-- English texts of the regional pack kalimdor_thunderbluff (content wave W01). The rules are in AzerothUnspoken_Kalimdor/ThunderBluff.lua.
local AU = AzerothUnspoken

AU:RegisterRegionalTexts("mulgore", "enUS", "kalimdor_thunderbluff", [==[
	["thb.journey.01"] = {
		"lifts off the bluff on the wind rider's back, and the city drops away beneath into rises, bridges and a long fall of stone.",
		"leaves the tower with a lurch, and Thunder Bluff turns below into a handful of mesas tied together with rope.",
		"rises from the bluff into the open wind, the tents of the city flattening into a scatter of pale shapes.",
	},
	["thb.journey.02"] = {
		"Already this high, and now we go higher. Wonderful.",
		"Start up here, end up somewhere lower. Can't be worse than the lift.",
		"Off the edge on purpose, for once.",
	},
	["thb.journey.03"] = {
		"The bluff falls behind, and with it the smell of the home fires. The wind rider doesn't look back. I do.",
		"From the air the rises look like the fingers of an open hand. I'll carry that picture down the road.",
	},
	["thb.journey.04"] = {
		"comes down from the wind rider's back onto the high tower, and for a moment the whole bluff seems to sway with the flight.",
		"lands on the bluff in a gust of wind, and the wind rider master is already reaching for the reins.",
		"steps off onto the top of the city, legs stiff, with the sweep of Mulgore spread out all around below.",
	},
	["thb.journey.05"] = {
		"Down from the sky onto a city that's half sky already. The difference is mostly the soup.",
		"Landed. On top of a cliff. I'm told that counts as solid ground here.",
	},
	["thb.journey.06"] = {
		"Thunder Bluff. High ground, friendly faces, and a wind that never sits still.",
		"Among friends, and well above the trouble. A fine place to land.",
	},
	["thb.memory_return.01"] = {
		"The bluffs haven't moved, the bridges still sway, and the stew smells the same. Some places keep their promises.",
		"Up the lift once more. The wind on top greets me the way it did the first time: rudely, and then not at all.",
	},
	["thb.muse.01"] = {
		"Up here the wind never quite stops. It just changes its mind about which way to push.",
		"The whole city stands on pillars of stone above the plains, and the wind treats it like one more cloud.",
		"From the edge of the bluff Mulgore lies below like a green sea, and the wind keeps trying to talk me into it.",
	},
	["thb.muse.02"] = {
		"No railings. Not one. The tauren must trust their feet more than I trust mine.",
		"Every edge in this city is a long way down, and every one of them is wide open.",
		"I've decided to walk in the middle of the bridge. Out of respect for the view.",
	},
	["thb.muse.03"] = {
		"stops beneath a tall carved totem, its painted faces worn by the wind into something calm and patient.",
		"watches the hide of a great tent swell and settle with the wind, as if the whole lodge were breathing in its sleep.",
		"looks across the rope bridges strung between the rises, swaying gently in the wind above the long drop.",
	},
	["thb.muse.04"] = {
		"Nobody hurries in Thunder Bluff. Even the merchants seem to weigh each word before spending it.",
		"A city with no walls, no gate, no crowd shoving. The height does all the guarding.",
	},
	["thb.muse.05"] = {
		"The lifts creak the whole way up. I've chosen to hear that as friendly.",
		"Ride a lift up a cliff, walk a rope bridge, ride another lift down. The tauren call this getting about town.",
	},
	["thb.muse.06"] = {
		"Close to the sky, and the Earth Mother still under every hoof. My people built well.",
		"The elders chose high ground to see far and remember long. Standing here, I think they chose right.",
	},
	["thb.muse.07"] = {
		"watches the fires of the city burn in the dark on every rise, like a handful of embers scattered across the sky.",
		"stands at the edge of the bluff in the night, the plains below gone black and silent, the stars almost close enough to touch.",
	},
	["thb.muse.08"] = {
		"Smoke, cured hide and sweetgrass. Thunder Bluff smells like a good fire after a long walk.",
		"Somebody up here is always cooking something slow over the coals. I can't find who, and I've tried.",
	},
	["thb.muse.09"] = {
		"Somewhere in this city an old chieftain keeps his people steady with few words. You can tell from how calmly everyone walks.",
		"Cairne's people. They carry their strength the way the bluffs carry the city: quietly, and without leaning on anyone.",
	},
	["thb.npc_meet.01"] = {
		"waits by the wind rider tower while the master murmurs to a restless beast, one big hand on its neck.",
		"nods to the wind rider master, who checks the straps of a saddle with slow, careful fingers and a steady hand.",
	},
	["thb.npc_meet.02"] = {
		"A Bluffwatcher, tall as a doorway and calm as the stone. Trouble would have to be very foolish up here.",
		"The guard watches without staring. Somehow that's more thorough.",
	},
	["thb.npc_meet.03"] = {
		"Good hides, fair price, no shouting. You'd do well in Orgrimmar. You'd hate it, but you'd do well.",
		"No haggling? Then I'll just pay. Strange city.",
	},
	["thb.quest_complete.01"] = {
		"Done. Up here even thanks come slowly, and mean more for it.",
		"Finished. The bluff won't notice, but someone living on it will.",
		"One more task off my shoulders. The wind can carry the rest.",
	},
	["thb.quest_complete.02"] = {
		"receives a deep, unhurried nod in thanks, the kind that seems to come from the whole rise at once.",
		"takes the reward and moves off along the rope bridge, minding the sway.",
		"accepts the reward with both hands, as the wind tugs at the hides overhead.",
	},
	["thb.quest_complete.03"] = {
		"All done, and not one bluff saw me go over the edge. Count that as two victories.",
		"Finished. Now, which bridge was the one that goes to food?",
	},
	["thb.rest_enter.01"] = {
		"comes in under the great tent of the inn and lets the warmth and the smell of stew close around like a blanket.",
		"settles onto a hide by the fire, where the wind outside is only a sound against the walls.",
		"sits down at last by the hearth, and the long sway of the bridges slowly leaves {g:his|her} legs.",
	},
	["thb.rest_enter.02"] = {
		"Thunder Bluff. High enough that the world's trouble has to climb to reach me, and it rarely bothers.",
		"Up the lift and into safety. The plains can keep their wolves for a while.",
	},
	["thb.subzone_enter.01"] = {
		"crosses onto Elder Rise, where the voices are lower and the totems stand taller than anywhere else in the city.",
		"steps off the bridge onto Elder Rise and slows a little, as one does in the presence of the very old.",
	},
	["thb.subzone_enter.02"] = {
		"{subzone}. The air feels thinner here, and not only because of the height.",
		"The shamans keep this rise. Even the wind seems to lower its voice crossing it.",
	},
	["thb.subzone_enter.03"] = {
		"Hunter Rise. Bows, blades and trophies. The kind of place that takes your measure at a glance.",
		"Smells of oiled leather and fresh-cut arrows. This rise suits me.",
	},
	["thb.subzone_enter.04"] = {
		"goes down into the hush beneath Spirit Rise, where still water glimmers in the half dark of the stone.",
		"walks among the pools under the rise; the water lies so still it seems to be listening.",
	},
	["thb.weather_change.01"] = {
		"Rain on the hide roofs, all over the bluff at once. The whole city sounds like a slow drum.",
		"I could see the rain crossing the plains long before it got here. Up here, weather is something you watch arrive.",
		"Rain. The rope bridges will be slick. I'll cross them like an old kodo: slowly, and in the middle.",
	},
	["thb.greet.w02.01"] = {
		"Greetings. The wind is strong up here; keep to the middle of the bridges.",
		"Well met, high above the grass.",
	},
	["thb.muse.w02.01"] = {
		"Hides stretched on frames in every corner of the rise, drying in the wind. Nothing the tauren take from the plains goes to waste.",
		"A leatherworker sits with a hide across her knees, working the needle slow and sure. The whole bluff seems to keep the pace of her hands.",
	},
	["thb.muse.w02.02"] = {
		"watches a bird of the plains hang motionless on the updraft beside the bluff, level with {g:his|her} own eyes.",
		"sees a wind rider bank around the tower far below, a strange thing to look at from above.",
		"notices a hawk riding the wind along the cliff face, and realizes {g:he|she} is looking down on its back.",
	},
	["thb.muse.w02.03"] = {
		"Magatha Grimtotem keeps her lodge on Elder Rise, among Cairne's own people. The tauren speak her name politely, and not often.",
		"On Elder Rise lives an elder of the Grimtotem, treated with great courtesy and very little warmth. I'd like to know that story.",
	},
	["thb.muse.w02.04"] = {
		"Somebody's drumming on the next rise. My feet have started keeping time without asking me.",
		"Drums from across the bridge. I can't see who's playing, but the whole bluff seems to know the rhythm.",
	},
	["thb.quest_complete.w02.01"] = {
		"It is done. May your hearth stay lit and your kodo stay fat.",
		"Finished, and gladly. The bluff has been a good host.",
	},
	["thb.quest_complete.w02.02"] = {
		"Done. The thanks came in a voice so deep it seemed to rise from the planks of the bridge.",
		"Finished. The tauren thank you as if they had the whole afternoon for it, and they mean every slow word.",
	},
	["thb.weather_change.w02.01"] = {
		"watches the sky clear over Mulgore from the edge of the bluff, the cloud shadows sliding off the grass far below.",
		"feels the wind shift and sees the haze lift from the plains, until the far mesas stand sharp against a clean blue sky.",
	},
	["thb.dawn.w05.001"] = {
		"watches dawn come up over the Barrens to the east, the light running across Mulgore's grass until it reaches the foot of the bluff.",
		"sees the first light of dawn catch the tops of the totems while the bridges below are still gray, the city waking from the top down.",
		"stands at the rim as the dawn spreads over the plains, while on the next rise someone lights a fire for the first stew of the day.",
	},
	["thb.dusk.w05.001"] = {
		"Dusk over Mulgore. The grass goes gold, then red, then gray, and the bluff lights its fires rise by rise.",
		"The sun drops behind the western hills at dusk and the whole city seems to slow down with it. Even the bridges creak more quietly.",
		"Dusk. The herds below drift off across the grass toward their resting grounds, and up here the drums start, low and unhurried.",
	},
	["thb.farewell.w05.001"] = {
		"Go well, and keep to solid ground where you can.",
		"Farewell. May the bridges hold for you.",
		"Until our paths cross again, on the bluff or below it.",
	},
	["thb.farewell.w05.002"] = {
		"Off I go. Take the lift down; it's quicker than the other way.",
		"Farewell! If you see me on a bridge later, don't wave. I'll need both hands.",
		"Safe travels. Mind the edge on your way out; it's everywhere.",
	},
	["thb.farewell.w05.003"] = {
		"Walk with the Earth Mother, wherever the road takes you.",
		"May the earth be kind under your feet until we meet again on the road.",
	},
	["thb.greet.w05.001"] = {
		"Hello! Good to meet someone on this rise who isn't a totem.",
		"Ah, a friendly face. Come, there's room by the fire.",
	},
	["thb.greet.w05.002"] = {
		"Peace on you, and on your road.",
		"Come and stand a while. The bluff is wide enough for the two of us.",
	},
	["thb.greet.w05.003"] = {
		"Hello there! Shake my hand quickly; I'm still holding the bridge rope with the other.",
		"Hello. Don't mind me, I'm still getting my legs back from the lift.",
	},
	["thb.jest.w05.001"] = {
		"Why are there no thieves in Thunder Bluff? Try running off with something across a rope bridge.",
		"I asked a tauren how far down the plains are. The answer was: one step. I've stopped asking.",
		"In Thunder Bluff the lifts take you up, the bridges take you across, and the wind rider takes you off the edge. Everything else is walking very carefully.",
	},
	["thb.journey.w05.001"] = {
		"banks out over the edge of the bluff, and the great lifts below shrink to two pale lines climbing the cliff from the grass.",
		"clears the rim of the mesa, and all at once the ground falls away a very long way, to the green plains below.",
		"swings away from the bluff, and the plains of Mulgore open out on every side, crossed by the slow brown lines of the herds.",
	},
	["thb.journey.w05.002"] = {
		"Every other tower I've flown from, the beast had to climb. Here it just leans forward and the ground lets go.",
		"Up here the wind rider barely flaps. It falls off the edge with me on it and calls that a departure.",
	},
	["thb.journey.w05.003"] = {
		"settles into the saddle while the wind rider master gives the beast a last word in its ear, and then the platform is gone.",
		"grips the saddle as the beast crouches at the edge of the tower, gathers itself, and throws itself and its rider into the open air.",
	},
	["thb.journey.w05.004"] = {
		"Down's the easy direction from here. Let's go sideways instead, please.",
		"Off we go. Mind the totems on the way out.",
		"Farewell, bluff. Keep the stew warm.",
	},
	["thb.journey.w05.005"] = {
		"From the air the three smaller rises look like they're kneeling around the big one. I never noticed that from the bridges.",
		"Seen from above, the bridges are thin as stitches holding the city together. It's a wonder anything up there stays put.",
	},
	["thb.journey.w05.006"] = {
		"takes off into the dawn, while far below the grass of Mulgore turns from gray to green in one long wave.",
		"rises off the bluff at dawn, the low places of the plains still full of blue shadow.",
	},
	["thb.journey.w05.007"] = {
		"A night departure. The bluff drops behind, and soon its fires are just more stars, only lower.",
		"Out into the night. I can't see the plains at all, only the shape of the wind rider's neck against the stars.",
	},
	["thb.journey.w05.008"] = {
		"Thunder Bluff will hear of this errand when it's done. Fly.",
		"Up, and to work. The bluff can manage without me for a while.",
	},
	["thb.journey.w05.009"] = {
		"lifts away past the top of a tall totem, close enough to look its carved face in the eye; the face does not look pleased.",
		"clears the edge of the tower with a lurch, and on the next rise a row of hides drying on their frames flaps a farewell.",
	},
	["thb.journey.w05.010"] = {
		"The bluff gives you a long look at the world before you go into it. From up here every road down there looks short.",
		"From this height the roads out of Mulgore all look easy. They aren't. It's still good to see them laid out like a promise.",
	},
	["thb.journey.w05.011"] = {
		"takes off into a gray rain, the bluff blurring behind until only the nearest totems can still be told apart.",
		"leaves the tower with rain streaming off the wind rider's wings, the plains below gone dim and silver.",
	},
	["thb.journey.w05.012"] = {
		"A guest's last look at the tauren's city: calm, high, and in no hurry either to see me go or to keep me.",
		"Every visit up here leaves me a little less of a stranger. That's more than most cities give.",
	},
	["thb.journey.w05.013"] = {
		"comes in low over the plains and watches the bluff rise ahead, sheer on every side, until the beast climbs and sets down on top of it.",
		"circles the central rise once, wide, past the bridges and the totems, before dropping onto the platform.",
		"lands on the tower and climbs down while the wind rider folds its great wings with a creak of leather and a snort.",
	},
	["thb.journey.w05.014"] = {
		"Down on the bluff, and the first thing I notice is the quiet. After the roar of the flight, a tent pole creaking sounds like news.",
		"Off the saddle at last. After the rush of the flight, even the bridges creak gently.",
	},
	["thb.journey.w05.015"] = {
		"Good landing. Now nobody move suddenly; it's a long way down from everywhere here.",
		"Down safe. Well, up safe. It's hard to tell in this city.",
		"Thanks for the ride. You can keep the view, I've had plenty.",
	},
	["thb.journey.w05.016"] = {
		"drops out of the night onto the tower, where a lantern swings on its hook and the wind rider master waits under a blanket.",
		"comes down through the dark toward the scattered lodge fires of the city, the only lights for leagues.",
	},
	["thb.journey.w05.017"] = {
		"Down at dawn. The bluff is still half asleep, and the only sound is a kodo complaining somewhere far below.",
		"A dawn arrival. Smoke from the first cookfires is going straight up, and the whole bluff smells of breakfast.",
	},
	["thb.journey.w05.018"] = {
		"climbs down at the end of the long flight and stands a moment with one hand on the beast's flank, waiting for the bluff to stop moving.",
		"slides from the saddle after the long flight, and the first steps across the platform are the careful steps of someone on a rope bridge.",
	},
	["thb.journey.w05.019"] = {
		"That flight went on long enough for me to learn every bone in the wind rider's back. Thunder Bluff, I could kiss your planks.",
		"Long flight, sore everything. If anyone needs me, I'll be lying flat in the nearest tent.",
	},
	["thb.journey.w05.020"] = {
		"Good to be up high again. The air tastes cleaner over the plains.",
		"Here we are. Nobody shouts in this city; I may finally hear myself think.",
	},
	["thb.journey.w05.021"] = {
		"touches down while a line of kodos far below plods along the road to the lifts, small as beetles from up here.",
		"lands and looks back the way the flight came, over the grass where the herds drift like cloud shadows.",
	},
	["thb.journey.w05.022"] = {
		"Down from the sky, and the bluff feels almost like a piece of it. I'm not sure I've quite landed.",
		"My feet are on the platform but my head is still up there with the hawks. It'll come down when it's ready.",
	},
	["thb.journey.w05.023"] = {
		"lands in the rain, slipping a little on the wet planks of the platform, and hurries for the shelter of the nearest tent.",
		"comes down through the rain, the bluff a dark shape in the gray until the very last moment.",
	},
	["thb.journey.w05.024"] = {
		"My thanks, beast. Next time, a little less diving at the end.",
		"Easy, easy. We're down. You can stop showing off for the master now.",
	},
	["thb.journey.w05.025"] = {
		"Landing in full sun. The hide tents glow almost white, and every totem lays a sharp dark shadow across the rise.",
		"Down under a high sun. The whole bluff smells of warm hide and dust, and the bridges creak in the heat.",
	},
	["thb.journey.w05.026"] = {
		"hands the reins to the wind rider master, who runs a palm along the beast's wing as if feeling for every sign of strain.",
		"dismounts while the master inspects the wind rider's claws and wings, nodding slowly, as if reading the flight off them.",
	},
	["thb.memory_return.w05.001"] = {
		"The bluff once more. Last time I left here in a worse state than I arrived. This time I mean to do it the other way round.",
		"Up here again. The last visit ended badly; the stone doesn't remember, and I'll try not to either.",
	},
	["thb.memory_return.w05.002"] = {
		"It's been a while. The totems haven't changed, the plains haven't changed. Only the faces at the inn are a little different.",
		"Weeks away, and the bluff looks exactly as I left it. Mesas are good at that. People, less so.",
		"So long since the last time that the creak of the lift sounds almost new. Almost.",
	},
	["thb.muse.w05.001"] = {
		"Sat on a tauren bench. My feet are dangling like a child's at the grown-ups' table.",
		"The mugs here are buckets with handles. I'm not complaining.",
		"Every doorway in Thunder Bluff is built for horns. I could walk through most of them with a ladder on my shoulder.",
	},
	["thb.muse.w05.002"] = {
		"Far below, a herd of kodo moves across Mulgore so slowly it might be the land itself shifting. From up here they look like boulders that decided to travel.",
		"I can count the kodo on the plain from the edge of the rise: gray shapes in the grass, grazing their way west without a care in the world.",
		"A herd crossing Mulgore leaves a darker path in the grass behind it, slow as a line drawn by a careful hand.",
	},
	["thb.muse.w05.003"] = {
		"spots a flock of plainstriders far below racing across the grass for no reason anyone could name, then stopping all at once, as if they had forgotten why.",
		"follows the tiny shapes of plainstriders scattering over Mulgore, comical even at this distance.",
		"laughs quietly at a pair of plainstriders far below, chasing each other in circles around a lone tree.",
	},
	["thb.muse.w05.004"] = {
		"The tauren druids of Elder Rise learned their craft from the night elves, and now the two peoples stand on opposite sides of a war. Nobody on this rise seems to enjoy that.",
		"Hamuul Runetotem keeps the druids of Elder Rise. Somewhere in his teaching are lessons first given by kaldorei hands, and he doesn't seem to mind saying so.",
	},
	["thb.muse.w05.005"] = {
		"The shamans of Spirit Rise do not command the elements; they ask. Watching one bow to a little fire before feeding it, I think of all the campfires I've stamped out without a word.",
		"A shaman is speaking to a stone on Spirit Rise, quietly, the way you'd speak to an elder. The stone, as far as I can tell, is listening.",
		"On Spirit Rise even the fires seem to burn more politely, as if they knew someone was talking to them.",
	},
	["thb.muse.w05.006"] = {
		"The hunters of Hunter Rise talk about the animals they've killed the way you'd talk about guests who did you a great honor. Not one trophy here is for showing off.",
		"On Hunter Rise they teach that you take what you need and thank what you take. The arrows here are fletched slowly, as if each one were a promise.",
		"Hunter Rise smells of fletching glue and fresh hide. Everyone there has the quiet eyes of people who watch for a living.",
	},
	["thb.muse.w05.007"] = {
		"Cairne Bloodhoof is old, and still the broadest back in the city. The years have taken his color, not his reach.",
		"Cairne led the tribes here out of a long, hunted wandering. Every tent on these mesas is, in a way, his work.",
		"When Cairne walks through the city, conversations don't stop; they just slow, the way grass bends when a big animal passes.",
	},
	["thb.muse.w05.008"] = {
		"When the centaur hunted the tauren across the plains, it was orcs who came to stand with them. The tauren have long memories for a kindness like that.",
		"The Horde's debt runs both ways here: Thrall's orcs helped the tauren win Mulgore, and the tauren gave the Horde a heart that isn't all fire.",
		"Orc and tauren: one people all fire, the other all patience. The Horde needed both, and Thrall seems to have known it.",
	},
	["thb.muse.w05.009"] = {
		"It was Cairne who argued for letting the Forsaken into the Horde. Watching a dead apothecary buy herbs from a tauren on this rise, I understand what he was hoping for.",
		"Undead in Thunder Bluff, haggling politely with the living. The old chieftain spoke for them once, and here is what came of it: a trade, a nod, a little less fear.",
	},
	["thb.muse.w05.010"] = {
		"An orc just tried to rush a tauren merchant. The tauren finished his sentence anyway. All of it.",
		"Watched a troll and a tauren haggle. One talks twice as fast; the other wins twice as often.",
		"A goblin tried to sell a tauren something urgent. The tauren is still considering it. The goblin looks older.",
	},
	["thb.muse.w05.011"] = {
		"Down in Mulgore the Venture Company is chewing at the hills. From up here you can't see the machines, only a smudge of smoke where there shouldn't be one.",
		"The goblins dig and saw at the edge of the plains as if the land were a pantry left unlocked. The tauren on this bluff watch with the patience of people choosing their moment.",
		"Every tree the goblins fell in Mulgore, the tauren seem to count. I wouldn't want to be standing nearby when they finish the sum.",
	},
	["thb.muse.w05.012"] = {
		"watches a tauren carver take a single thin curl from a tall log, look at it a long while, and take another.",
		"stops near a half-carved totem where a face is just beginning to come out of the wood, one eye open, the other still asleep in the grain.",
		"runs a hand over the base of a totem, where the wood has been rubbed smooth and dark by countless passing palms.",
	},
	["thb.muse.w05.013"] = {
		"watches a tauren woman braid a string of wooden beads into her mane without a mirror, quick and sure, talking all the while to a neighbor.",
		"notices two old tauren sitting knee to knee, one patiently plaiting feathers into the other's mane while both of them watch the plains.",
		"smiles at a young tauren trying to braid a feather into his own mane and getting it, by the look of things, mostly into his ear.",
	},
	["thb.muse.w05.014"] = {
		"Hooves on the planks of the bridges, all day long, heavy and even. The city has a footstep, and it's a slow one.",
		"You can tell a tauren is coming up behind you long before you see them: the boards of the bridge start to lean.",
		"The bridges answer every hoof with a creak, so the whole bluff talks in footsteps.",
	},
	["thb.muse.w05.015"] = {
		"The tauren speak of the Earth Mother the way farmers speak of the soil: with respect, without fuss, and as if she might overhear.",
		"Even the merchants here say a few words to the Earth Mother before they open their goods. Nobody makes a show of it. It's simply part of the work.",
		"On these mesas the land isn't scenery. Every tauren I pass seems to be on speaking terms with it.",
	},
	["thb.muse.w05.016"] = {
		"The tauren call the sun one of the Earth Mother's eyes. Up here, with nothing between me and the sky, it certainly feels like being looked at.",
		"The tauren say the Earth Mother keeps one eye open all day. Standing on top of the bluff at midday, I believe it.",
		"Midday light on the bluff, nothing to soften it. The tauren stand in it without squinting, as if being looked at by the sky were a pleasant thing.",
	},
	["thb.muse.w05.017"] = {
		"By night, the tauren say, the Earth Mother watches with her gentler eye. The moon hangs over Mulgore, and the whole plain lies under it like a sleeping herd.",
		"The moon over the mesas, pale and patient. If it's an eye, as the tauren say, it's one that has seen a great deal and forgiven most of it.",
	},
	["thb.muse.w05.018"] = {
		"watches the first light strike the tops of the mesas while the plains below still lie in blue shadow, as if the city had woken before the world.",
		"stands at the edge of the rise as dawn creeps up the cliff faces, band after band of red stone lighting up like coals stirred awake.",
		"sees the hide roofs go from gray to rose to gold as the morning finds them, one rise after another.",
	},
	["thb.muse.w05.019"] = {
		"At dusk the shadows of the bluffs stretch out across Mulgore for miles, long dark fingers laid over the grass. The plain seems to lean toward the night.",
		"The light goes gold, then copper, then gray, and the herds below fade before the hills do. Dusk takes its time on the plains, and so do I.",
		"Dusk turns the cliffs the color of embers. Fires start up on every rise, as if the bluff had decided to keep the sunset.",
	},
	["thb.muse.w05.020"] = {
		"Rain on Thunder Bluff, and the whole city smells of wet hide and wet earth. Somewhere a kodo is enjoying this. Nobody else is.",
		"Wet planks, dripping tents, a drenched tauren shaking out her mane like a dog after a swim. Rain makes everyone up here look a little less dignified.",
		"The rain finds every hole in every hide roof, and under each one a tauren sets out a bowl without even looking up.",
	},
	["thb.muse.w05.021"] = {
		"A storm over Mulgore, lightning walking across the plains at eye level, and the thunder rolling up the cliffs. Now I understand the name.",
		"The storm doesn't pass over Thunder Bluff; it goes around it, close enough to touch, booming off every mesa. The tauren don't even look up.",
		"Thunder off the mesas, so loud the bridges hum. Whoever named this city must have stood right here in weather like this.",
	},
	["thb.muse.w05.022"] = {
		"looks out from the edge of the rise over a white sea of fog, the other mesas standing up out of it like islands, the plains gone entirely.",
		"crosses a bridge with the mist so thick below that the ropes seem to hang over nothing at all.",
	},
	["thb.muse.w05.023"] = {
		"Dropped a copper off the edge. Still waiting to hear it land.",
		"Whatever falls off this city belongs to Mulgore now. Including, very nearly, my hat.",
		"Rule of the bluff: hold on to your coin, your hat and your dignity, in that order.",
	},
	["thb.muse.w05.024"] = {
		"The bank is a tent. The auction house is a tent. My entire fortune is protected by hide, rope and a very large tauren.",
		"The banker here counts my coins one by one, slowly, and then counts them again. I've never felt so thoroughly safe or so thoroughly late.",
		"My bank box sits in a tent on a cliff in the sky. Somehow it feels safer than a vault.",
	},
	["thb.muse.w05.025"] = {
		"Ask for a bowl of stew in Thunder Bluff and they hand you something you could bathe a gnome in. I'll finish it out of respect.",
		"Tauren bread is dense, warm, and roughly the size of a shield. One loaf would see me across the Barrens.",
		"Tauren portions: a bowl you need both hands for, and a cook who looks hurt if you leave any.",
	},
	["thb.muse.w05.026"] = {
		"To the south, past the grass and the low hills, lies Bloodhoof Village with its smoke and its fields. From up here the whole of Mulgore looks like one long, gentle slope.",
		"The road down from the lifts runs out across the grass toward Bloodhoof Village and the farms. Everything in Mulgore seems to be an easy day's walk away, and none of it in a hurry to be reached.",
	},
	["thb.muse.w05.027"] = {
		"East of the bluff the green of Mulgore thins and yellows, and beyond the ridge the Barrens begin, dry and wide. The tauren chose the softer side of the hills.",
		"Look one way and there's long grass and water; look east and there's dust rising over the ridge. Mulgore is a green cup held up against the Barrens.",
		"Green to the west, gold to the east. Thunder Bluff stands right where Mulgore makes up its mind.",
	},
	["thb.muse.w05.028"] = {
		"For generations the tauren followed the herds and slept wherever the grass was good. Thunder Bluff is what a wandering people builds when it finally decides to stay.",
		"The tents here are still tents. A people that walked for so long kept the habit of homes that fold, even after it found a place worth keeping.",
		"A wandering people with a city. The tauren seem to wear it lightly, like a cloak they could still take off.",
	},
	["thb.muse.w05.029"] = {
		"Best view in Kalimdor, and they don't even charge for it.",
		"I could sit on this edge all day and call it work.",
	},
	["thb.muse.w05.030"] = {
		"Sound carries strangely between the rises. I can hear two tauren on the far mesa arguing about a hide, word for word, and they have no idea.",
		"A laugh from across the gap, as clear as if the speaker stood beside me. Up here the air carries voices the way water carries leaves.",
		"Somebody on the next rise just dropped a pot. I heard it as if it were in my own hands.",
	},
	["thb.muse.w05.031"] = {
		"Bundles of herbs hang under every eave on Spirit Rise, drying gray-green in the open air. A shaman pinches one, smells it, and moves on to the next as if reading a stack of letters.",
		"Dried roots, bunches of leaves, a string of something like small bitter apples: the tents up here double as an herbalist's shop, and nobody labels anything.",
	},
	["thb.muse.w05.032"] = {
		"steps carefully over a hunter's wolf asleep across the middle of a rope bridge, which opens one eye, judges {g:him|her} harmless, and shuts it again.",
		"waits while a hunter coaxes a stubborn boar off the planks of the bridge, the whole span swaying with every grunt.",
	},
	["thb.muse.w05.033"] = {
		"A Forsaken sits at a tauren cookfire, holding out hands that can hardly feel the heat. Nobody tells him to move along. That may be the kindest thing in the whole Horde.",
		"The tauren offer the dead a place by the fire the same as anyone. I wonder whether the Forsaken feel the warmth, or only the welcome.",
		"A tauren healer is listening to an old Forsaken complain about his joints with exactly the same patience she gives the living.",
	},
	["thb.muse.w05.034"] = {
		"Orcs, trolls, even the Forsaken walk our bridges now. Strange company for the people of the plains. Good company, most days.",
		"When I hear the herds lowing far below, something in me stands a little straighter. Those are our plains. We bled to keep them.",
	},
	["thb.muse.w05.035"] = {
		"Walk with the Earth Mother, all of you. The bluff is glad of its guests.",
		"Thunder Bluff. Good grass below, good fires above. What more does a tauren need?",
	},
	["thb.muse.w05.036"] = {
		"Everybody here is a head and more taller than me and moves gently on purpose, the way you would around something small. I am the small thing.",
		"The tauren are careful with visitors the way big people are careful with furniture. I've had three apologies today from people who hadn't even touched me.",
	},
	["thb.muse.w05.037"] = {
		"Someone rode a kodo across the bridge. The bridge has opinions about that, and it's sharing them.",
		"Kodo on the bridge. Everybody else, please wait your turn and hold on.",
		"That kodo crossing the bridge has right of way. That kodo has right of way everywhere, I suspect.",
	},
	["thb.muse.w05.038"] = {
		"The tauren speak of their ancestors as if they were still up here, only a little further off, sitting just past the edge of the firelight. On this bluff it's easy to feel them leaning in.",
		"The shamans say the spirits of the old ones keep close to high places. I know nothing of spirits, but between one gust and the next there's a stillness up here that feels like someone listening.",
	},
	["thb.muse.w05.039"] = {
		"Woven blankets everywhere: over benches, in doorways, rolled under arms. Every pattern looks like a map of somewhere only the weaver has been.",
		"A tauren weaver at her frame doesn't look at her hands at all. She watches the plains and lets her fingers remember.",
	},
	["thb.muse.w05.040"] = {
		"The mesas are made of stone laid down in bands of red, tan and rust, like blankets folded and stacked by someone very patient and very old.",
		"Every cliff here shows its years in stripes. The bluff is a book of the land, and the tauren built their homes on the last page.",
		"The cliffs of the bluff are striped like an old blanket. Some of those stripes must be older than any people walking on Kalimdor.",
	},
	["thb.muse.w05.041"] = {
		"The centaur still raid the edges of the Barrens. The tauren didn't climb up here for the view; they climbed because the open plains were once a place where you could be run down.",
		"High ground was a choice made in hard years. Every tauren elder on this bluff remembers being hunted across open grass.",
	},
	["thb.muse.w05.042"] = {
		"Lovely city. Next time I'd like one I don't need a lift to leave.",
		"Fine people, the tauren. Shame they built their capital where only birds should live.",
	},
	["thb.muse.w05.043"] = {
		"Inside the lodge the light comes amber through the hides, and every sound from outside arrives softened, as if the city were speaking from under a blanket.",
		"Under the hide roof the air smells of old smoke and leather, and the floor is covered with rugs worn soft by hooves. It's the kind of room that tells you to sit down.",
	},
	["thb.muse.w05.044"] = {
		"sits down on the lip of the mesa with {g:his|her} legs over the drop, and for a long moment the only thing moving is the grass of Mulgore far below.",
		"stands at the edge of the rise until the dizziness passes and only the size of the plains remains.",
		"lies flat on the warm stone at the edge of the rise for a while, watching the clouds go by at what feels like arm's length.",
	},
	["thb.muse.w05.045"] = {
		"A big spotted cat bounded off a bridge onto the rise, and before I could reach for a weapon it stood up as an old druid, brushing grass from his robes. Elder Rise keeps its own customs.",
		"On Elder Rise the druids come and go on four legs as often as on two. You learn not to startle at a bear in the doorway.",
	},
	["thb.muse.w05.046"] = {
		"Even here, far above it all, word comes up the lifts: skirmishes in Ashenvale, raids in the Barrens, wounded headed home. Thunder Bluff is at peace; the Horde is not.",
		"The tauren are slow to anger and slower to forget. A warrior here is sharpening a blade for the Ashenvale front with the calm of someone mending a fence.",
	},
	["thb.muse.w05.047"] = {
		"Orcs who shout, trolls who laugh, Forsaken who whisper, and tauren who let all of them finish. The Horde sounds different on Thunder Bluff.",
		"On this bluff even an orc lowers his voice a little. Not out of fear; the place just seems to ask it.",
		"Every race of the Horde walks these bridges, and the bridges sway the same for all of them. Maybe that's the lesson.",
	},
	["thb.muse.w05.048"] = {
		"The tauren speak of the kodo with something close to reverence. They eat them, ride them, wear them, and grieve them, and see no contradiction in any of it.",
		"Kodo hide on the tents, kodo bone in the carvings, kodo stew in the pot. And still the tauren speak of the great beasts like elders of another tribe.",
	},
	["thb.muse.w05.049"] = {
		"lingers near a circle of old tauren by a fire, where one is telling a story so slowly that the listeners nod off and wake again without missing anything.",
		"hears an elder's deep voice rolling out a tale to a group of young tauren, every pause long enough to cross a bridge in.",
		"pauses where an old tauren is teaching a tune to a few young ones by humming it, phrase by phrase, until they hum it back.",
	},
	["thb.muse.w05.050"] = {
		"So much sky up here. It makes my troubles look small, which is kind of it, and then makes me look small too, which is less kind.",
		"On the bluff the world seems very large and very quiet, and I seem very far from everyone I've ever walked beside.",
	},
	["thb.muse.w05.051"] = {
		"Anyone who wants Mulgore will have to climb this bluff first. I'd like to watch them try.",
		"High ground, sharp eyes, long patience. Woe to whoever makes the tauren hurry.",
	},
	["thb.muse.w05.052"] = {
		"Everything in this city came up a lift at some point: every log, every pot, every sack of grain. I think of it whenever I see a tauren carry something heavy without complaint.",
		"Hunters coming up from the plains with game over their shoulders, farmers with baskets, travelers dusty to the knee. The city is fed from below, one lift load after another.",
		"Water, wood, grain, stone: none of it starts up here. Thunder Bluff is a city carried up the cliffs on many patient backs.",
	},
	["thb.muse.w05.053"] = {
		"I came up here to clear my head. It worked. There's no air left to think with.",
		"Thin air, steep drops and a lot of very calm people. I'm the only one breathing hard.",
	},
	["thb.muse.w05.054"] = {
		"is handed a cup of water by a passing tauren who offers it without a word, waits for it to be emptied, and takes it back with a nod.",
		"receives a curious, friendly look from an old tauren mending a basket, who lifts one hand from the work in greeting and goes on.",
	},
	["thb.muse.w05.055"] = {
		"Every totem on the bluff carries painted beasts and faces in a stack, eagle over bear over kodo. I can't read them, but I'm sure they are reading me.",
		"The totems mark something: a family, a story, a promise. I've asked twice what this one says, and got two different answers, both very long.",
		"The faces on the totems all look out toward the plains. Whatever they're guarding against, it comes from below.",
	},
	["thb.muse.w05.056"] = {
		"Noon on the mesas, and the only shade on offer is under a tent flap or behind a tauren. Both are popular.",
		"The sun sits right on top of the city at this hour, with nothing in between. Even the hides look sunburnt.",
	},
	["thb.muse.w05.057"] = {
		"Eat, sleep, mend the boots. The Barrens won't cross themselves.",
		"One more look at the plains, then down the lift and on to work.",
	},
	["thb.muse.w05.058"] = {
		"Baskets everywhere, woven so tight they hold water, stacked by doorways like loaves. Somebody on this bluff never stops weaving.",
		"The tauren make what they need with their hands and make it to last. A basket from here will outlive its owner, and very likely the owner's grandchildren.",
	},
	["thb.muse.w05.059"] = {
		"I keep my eyes on the far end of each bridge, never on the gap. The trick works until the bridge sways, and then nothing works.",
		"There's a moment halfway across every bridge when my body remembers how high we are, all at once. I've learned to keep walking through it.",
	},
	["thb.muse.w05.060"] = {
		"steps aside for a young tauren carrying two brimming buckets on a yoke across the bridge, not spilling a drop despite the sway.",
		"watches a tauren haul a bundle of firewood bigger than a dwarf up the path, humming under the weight.",
	},
	["thb.muse.w05.061"] = {
		"Not a single enemy in sight from up here. It's almost suspicious.",
		"Peace and quiet. I'll give it an hour before I go looking for trouble.",
		"Calm city, calm people. My hands are getting restless just standing here.",
	},
	["thb.muse.w05.062"] = {
		"The Bluffwatchers lean on their spears like herders on their staffs. Nobody up here is fooled into thinking that makes them slow.",
		"A guard on the bridge nods to everyone who passes, every single one, and remembers each face. You can see him doing it.",
	},
	["thb.muse.w05.063"] = {
		"A few hours among the tauren and I catch myself finishing tasks properly, tying knots twice, saying thank you more slowly. The bluff rubs off on you.",
		"Patience is catching up here. I came in at a trot and I'll leave at a walk, and the walk feels like an improvement.",
	},
	["thb.npc_meet.w05.001"] = {
		"is greeted by the innkeeper with a bowl already held out, as if the steps had been heard coming up from the lift.",
		"meets the innkeeper's eye across the tent and receives a slow nod toward an empty mat by the fire.",
		"stops before the innkeeper, whose welcome is a single deep word and a gesture at the pot hanging over the coals.",
	},
	["thb.npc_meet.w05.002"] = {
		"Whatever's in the pot, and a corner where the wind can't find me.",
		"A mat by the fire, if you have one. I'll pay for the snoring in advance.",
	},
	["thb.npc_meet.w05.003"] = {
		"The banker counts my coin with the patience of someone who has never once lost a copper and does not intend to start.",
		"A bank in a tent on a cliff. My savings have never been so high up, in any sense.",
	},
	["thb.npc_meet.w05.004"] = {
		"Put this with the rest, please. Away from the drop, if you can manage it.",
		"Just checking my things haven't blown off the bluff. Thank you, carry on.",
	},
	["thb.npc_meet.w05.005"] = {
		"stands before the trainer, who walks one slow circle around {g:him|her} and says nothing until the circle is closed.",
		"waits while the trainer finishes a lesson in a low, patient voice that never once rises, then steps forward.",
	},
	["thb.npc_meet.w05.006"] = {
		"Trainers here teach the way the elders talk: slowly, and only once. I'd better listen properly.",
		"The lesson will cost coin and patience. Up here, I suspect the patience is the dearer of the two.",
	},
	["thb.npc_meet.w05.007"] = {
		"Someone on the bluff has a problem, and I have the look of the solution. It's always the boots.",
		"A slow, grave greeting, the kind that comes before a long request. I settle my feet.",
		"Here it comes. Up here even a request for help arrives with ceremony.",
	},
	["thb.npc_meet.w05.008"] = {
		"You've work for me? Tell it plainly; I'll listen to all of it.",
		"I'm here. What needs doing?",
	},
	["thb.npc_meet.w05.009"] = {
		"passes a Bluffwatcher with a weapon resting against one shoulder, and gets a nod that is slow, thorough and final.",
		"steps aside on the bridge for a Bluffwatcher on patrol, who acknowledges the courtesy with a slight tilt of the horns.",
	},
	["thb.npc_meet.w05.010"] = {
		"Quiet day? Up here I imagine they all are.",
		"Lovely view from your post. I'd never get any watching done.",
	},
	["thb.npc_meet.w05.011"] = {
		"stops at a merchant's blanket where every piece of goods is laid out in straight rows, and nothing is touched until the merchant nods.",
		"watches the merchant wrap a purchase in soft leather and tie it off with careful hands, taking all the time the knot needs.",
	},
	["thb.npc_meet.w05.012"] = {
		"Hides, horn, bone needles, dried roots in clay jars. Half of it I can name; the other half I'll buy to find out.",
		"Everything on this blanket came off the plains below, one way or another. You can still smell the grass on it.",
	},
	["thb.npc_meet.w05.013"] = {
		"The wind rider master knows every beast on the perches by name. I'd ask which one is gentlest, but I suspect the answer is none.",
		"From the master's tower you can see half of Mulgore. I wonder if the beasts ever tire of the view.",
	},
	["thb.npc_meet.w05.014"] = {
		"Your steadiest beast, please. I've seen how far down the ground is from here.",
		"Is it true they like jumping off the edge? Never mind, don't tell me.",
	},
	["thb.npc_meet.w05.015"] = {
		"Cairne Bloodhoof. Old, broad, and still as a standing stone. When he speaks, the whole lodge leans in.",
		"The High Chieftain has the patience of the mesas themselves, and the stone of them too. I find myself standing straighter without deciding to.",
		"Cairne listens more than he speaks, steady as stone. With a people as calm as his, maybe that's what leading looks like.",
	},
	["thb.npcd_flightmaster_open.w05.001"] = {
		"The wind riders are rested and fed. Where shall the beasts carry you?",
		"Mind the claws, and step up when I say. The beasts know the way off the bluff better than any of us.",
	},
	["thb.npcd_guard_bye.w05.001"] = {
		"Walk in peace. And take the bridges slowly; we'd rather not fetch anyone out of the grass.",
		"Go on, then. The bluff will be here when you come back.",
	},
	["thb.npcd_guard_directions.w05.001"] = {
		"Druids train on Elder Rise, shamans on Spirit Rise, hunters and warriors on Hunter Rise. Follow the bridges.",
		"The bank, the inn and the wind rider master are all here on the central mesa. Cross back if you've wandered off.",
		"The High Chieftain's lodge stands on the central mesa. Go there with respect.",
	},
	["thb.npcd_guard_open.w05.001"] = {
		"Welcome to Thunder Bluff. Walk calmly, speak softly, and keep away from the edges.",
		"Peace is kept on the bluff. Help us keep it.",
	},
	["thb.npcd_guard_open.w05.002"] = {
		"You stand under Cairne's watch here. That is a safe place to stand.",
		"Every rise of this city answers to the High Chieftain. Mind that, and you'll have no trouble from us.",
	},
	["thb.npcd_innkeeper_bye.w05.001"] = {
		"Go gently. The fire will be lit when you come back up.",
		"Take some dried meat for the road. No, no, keep it. You can pay me by coming back.",
	},
	["thb.npcd_innkeeper_news.w05.001"] = {
		"The hunters of Hunter Rise came back from the plains with a story about a great white kodo. Nobody believes them, and everybody repeats it.",
		"Word from below is that the Venture Company's machines are still chewing at the hills of Mulgore. The braves are not pleased.",
	},
	["thb.npcd_innkeeper_open.w05.001"] = {
		"Come in out of the open air. Sit, warm yourself by the fire, eat. The questions can wait.",
		"There's a mat by the fire with no one on it. It's yours for as long as you need it.",
	},
	["thb.npcd_innkeeper_open.w05.002"] = {
		"You've the look of someone who crossed too many bridges today. The stew helps with that.",
		"Come into my lodge. Mind the tent pole; the tall ones always find it with their heads.",
	},
	["thb.npcd_merchant_bye.w05.001"] = {
		"Walk well. If the road wears through that leather, you know where I sit.",
		"Go in peace, and spend wisely on the road below. Nobody down there sells as fairly as we do up here.",
	},
	["thb.npcd_merchant_news.w05.001"] = {
		"Hides are plentiful just now; the hunters have been busy on the plains. Good time to buy.",
		"The lifts have been busy all week. Caravans from the Barrens, mostly, and they all want the same things.",
	},
	["thb.npcd_merchant_open.w05.001"] = {
		"Look as long as you like. Good leather doesn't mind being looked at.",
		"Everything here came up the lift on someone's back. Treat it gently, and the price stays gentle too.",
	},
	["thb.npcd_merchant_open.w05.002"] = {
		"Come closer. I don't shout my prices; I'll tell you once, and you'll find them fair.",
		"Come, come. Bone, hide, herbs from the plains below. Ask, and I'll tell you where each one came from.",
	},
	["thb.npcd_merchant_wares.w05.001"] = {
		"Kodo leather, cured slow, stitched with sinew. It will outlast your boots, and maybe you.",
		"Waterskins, rope, bone needles, plains herbs in little pouches. All you need for a long walk down there.",
	},
	["thb.npcd_trainer_open.w05.001"] = {
		"Sit. No, stand. Let me look at how you carry yourself before you tell me anything.",
		"You climbed all the way up here to learn. Good. Patience is the first lesson, and you've begun it already.",
	},
	["thb.pray.w05.001"] = {
		"Earth Mother, your children built this city close to the sky. Keep my steps sure on its bridges and on the roads below.",
		"Spirits of the high places, of earth and of sky: watch over this bluff, and over me when I leave it.",
		"Earth Mother, from this high place I ask little: a clear road, a steady hand, and a fire to come back to.",
	},
	["thb.quest_complete.w05.001"] = {
		"hands over what was asked, and the matter is settled in so few words that the quiet afterward seems to belong to the thanks.",
		"settles the business with a handful of low words, then lingers a moment, since nobody on the bluff seems in a rush to part.",
		"finishes the errand and is told it was well done, once, in a voice that sees no reason to say it twice.",
	},
	["thb.quest_complete.w05.002"] = {
		"Every task done here teaches me one more bridge. Soon I'll cross this city without stopping to look down.",
		"Another errand closed, another path between the rises that my feet will remember.",
		"I'm starting to know who lives on which rise. The city is slowly turning from a map into a neighborhood.",
	},
	["thb.quest_complete.w05.003"] = {
		"There. And I only took the long way across two bridges. Three, if you count the one I crossed twice.",
		"Delivered. I'd say it was nothing, but my knees climbed every rise of this city for it.",
		"Mission accomplished. Now I just need to remember which lift I came up on.",
	},
	["thb.quest_complete.w05.004"] = {
		"The shamans of Spirit Rise say the Earth Mother notices small work as well as great. I hope she was looking this way.",
		"They say on the bluff that the earth keeps count of every honest task. If so, it has one more of mine to carry.",
	},
	["thb.quest_complete.w05.005"] = {
		"is pressed to take a strip of dried meat along with the reward, for the road, and refusing is plainly not an option.",
		"receives the reward and, unasked, a flat cake of grain still warm from the coals, folded into a leaf.",
	},
	["thb.quest_complete.w05.006"] = {
		"It's done as you asked. If the bluff needs more hands, mine are free.",
		"Your request is answered. Send for me again, whenever the need comes.",
		"As promised. The bluff can count on me when it calls.",
	},
	["thb.quest_complete.w05.007"] = {
		"The work's handed in and the city goes back to its slow business. I'm the only one still carrying the road it took.",
		"Paid and thanked, and already the task feels far off, like the plains seen from the edge of the bluff.",
		"Thanks given, coin taken, and the moment is gone before I've finished noticing it.",
	},
	["thb.quest_complete.w05.008"] = {
		"pockets the reward under the eye of an old totem, whose carved face looks as if it has seen bigger deeds and kinder rewards.",
		"puts the reward away beneath a painted totem, which goes on staring past {g:him|her} at the plains, unimpressed.",
	},
	["thb.quest_complete.w05.009"] = {
		"That's settled, then. I'll be at the inn, if the stew hasn't gone.",
		"There, all squared. Now I've earned a seat by a fire and a bowl of whatever's in the pot.",
	},
	["thb.quest_complete.w05.010"] = {
		"Cairne's city keeps a long memory, the elders say. I'd like to be in it for something better than errands, one day. This is a start.",
		"Small deeds first. The tauren built this city one lodge after another; a name can be built the same way.",
	},
	["thb.quest_complete.w05.011"] = {
		"turns from the finished business toward the edge of the rise, where the grass of Mulgore rolls away below toward everything still left to do.",
		"concludes the matter and takes a moment at the rim of the mesa, the plains spread out green and gold beneath, already full of other tasks.",
		"pauses at the rim once the reward is stowed, looking out over the herds and the grass below as if counting what the errand was for.",
	},
	["thb.quest_complete.w05.012"] = {
		"A fair reward, given without a speech. Careful, or I'll start doing errands here for fun.",
		"Coin in hand and no one shouting. I keep waiting for the catch.",
		"Fair pay, no fuss. I don't trust it, but I'll spend it.",
	},
	["thb.quest_complete.w05.013"] = {
		"My part is done; what grows from it belongs to the bluff now. Good soil, I think.",
		"I set the task down here like a stone on a cairn. Others will add theirs, and the pile will grow.",
	},
	["thb.quest_complete.w05.014"] = {
		"receives the reward while a group of young hunters crossing the bridge stops to watch, curious about what earned it.",
		"takes the reward as a pair of braves passing along the rise glance over, weigh up the one receiving it, and give a short approving grunt.",
	},
	["thb.quest_complete.w05.015"] = {
		"The reward is fair, the thanks were long, and somebody mentioned soup. I may move here.",
		"I came up for one errand and I'm leaving with a full purse, a blessing and directions to three cooks.",
	},
	["thb.quest_complete.w05.016"] = {
		"Glad to have been of use. This city has treated me fairly.",
		"No need for more thanks. A fair word was enough.",
		"The pleasure was mine. Truly; the view alone paid for the climb.",
	},
	["thb.quest_complete.w05.017"] = {
		"loosens a strap of the pack once the errand is closed, as if the task had been riding in it all along.",
		"sits down on a bench right after, which says more about the errand than any report would.",
	},
	["thb.quest_complete.w05.018"] = {
		"This city pays what it promises and promises only what it can pay. I could get used to that.",
		"Fair work, fair coin, no tricks in the small print. Thunder Bluff keeps simple accounts.",
	},
	["thb.quest_complete.w05.019"] = {
		"accepts the reward as a thread of herb smoke drifts across from a nearby totem, as though the city had added its own word of thanks.",
		"receives the reward and the blessing that comes with it, spoken low over a bowl of smoldering herbs.",
	},
	["thb.quest_complete.w05.020"] = {
		"Easy enough. Next time, give me the one the others turned down.",
		"That one was light. Save the heavy ones for me.",
		"Another one done. Keep them coming, and make them harder.",
	},
	["thb.quest_complete.w05.021"] = {
		"Work done for my own people, on my own rise. It sits differently in the chest than work done for strangers.",
		"Here I don't need to be thanked. Helping the tribe is like tending a fire at home: you just do it.",
	},
	["thb.quest_complete.w05.022"] = {
		"closes the errand by firelight, the far rises only dark shapes against the stars.",
		"settles the business by lantern light, while above the bluff the night sky is vast and full of stars.",
	},
	["thb.quest_complete.w05.023"] = {
		"Settled with the sun still high over Mulgore. The rest of the day is mine, and the bluff is a fine place to waste it.",
		"The task is closed and there's still daylight on the plains. I'll sit at the edge a while and watch the herds move.",
	},
	["thb.quest_complete.w05.024"] = {
		"Settled. Next one, put it on this rise. I've walked enough rope for one day.",
		"Good. And if there's another, I'd like it not to involve the lift.",
	},
	["thb.quest_complete.w05.025"] = {
		"is walked to the head of the bridge after the reckoning, an escort of courtesy nobody asked for and nobody refuses.",
		"is seen off with a hand raised in farewell, held up until {g:he|she} is all the way across the bridge.",
	},
	["thb.quest_complete.w05.026"] = {
		"Handed in with rain dripping off my nose. The thanks were warm, at least; the rest of me is not.",
		"The task is closed in the rain, and the purse is the only part of me that's still dry.",
	},
	["thb.quest_complete.w05.027"] = {
		"The task is done. Walk with the Earth Mother.",
		"Earth Mother keep you. If the trouble comes back, send for me.",
	},
	["thb.reputation_change.w05.001"] = {
		"Someone up here speaks my name a little more warmly now. On the bluff, that kind of thing travels slowly and lasts.",
		"Trust grows slowly in this city, like the grass on the plains. A little more of it is mine now.",
	},
	["thb.rest_enter.w05.001"] = {
		"The city's calm gets into the bones after a while. I stop listening for footsteps behind me.",
		"Up here my hand drifts away from my weapon on its own. The bluff has that effect.",
		"Rest at last. Even my thoughts slow down to the pace of the people here.",
	},
	["thb.rest_enter.w05.002"] = {
		"lowers onto a pile of soft furs inside the inn, and the long day folds up behind half-closed eyes.",
		"pulls off the boots under the high roof of the inn's tent, and listens for a while to the poles creak overhead.",
	},
	["thb.rest_enter.w05.003"] = {
		"Nobody wake me unless the bluff falls over.",
		"I'm resting. If the lift breaks, tell me tomorrow.",
		"A whole city built for sitting still. My kind of place.",
	},
	["thb.rest_enter.w05.004"] = {
		"Night on the bluff. Someone across the bridge is humming low, and the lodge fires settle to embers one by one.",
		"Rest as the night comes on, high above Mulgore. The last voices fade, the fires burn down, and there's only the creak of ropes in the dark.",
	},
	["thb.rest_enter.w05.005"] = {
		"sits down with {g:his|her} back against a totem pole and lets the slow pace of the city take over.",
		"settles on a hide spread out at the edge of the rise, and lets the plains below do the moving for a while.",
		"finds a sheltered spot between two lodges and stretches out, the bustle of the bluff as soft as running water.",
	},
	["thb.rest_enter.w05.006"] = {
		"A bowl of stew, a fur blanket and a view that goes on for a day's walk. Rich folk elsewhere pay a fortune for less.",
		"Fur under me, a roof of hide over me, and nobody anywhere expecting anything. I could sleep for a season.",
	},
	["thb.rest_enter.w05.007"] = {
		"The shamans say the Earth Mother holds this bluff up in her hands. Resting here, I could almost believe I feel the palm.",
		"Lying still up here, I can feel the stone underneath, old and patient. The Earth Mother's back, the tauren call it, I'm told.",
	},
	["thb.subzone_enter.w05.001"] = {
		"Elder Rise, where the druids keep their lodges. The Arch Druid Hamuul Runetotem lives here, they say, among the oldest totems of the city.",
		"The druids' rise. Hard to say why, but the air up here smells a little more like a forest than the rest of the bluff.",
	},
	["thb.subzone_enter.w05.002"] = {
		"Elder Rise. I'll speak softly. Everyone here looks old enough to have names for the clouds.",
		"Quiet, quiet. This is the rise where the elders think. I'd hate to interrupt a century of it.",
	},
	["thb.subzone_enter.w05.003"] = {
		"crosses onto Spirit Rise, past totems hung with feathers and bone charms that click softly against the wood.",
		"steps onto {subzone}, where shamans sit cross-legged before small fires and speak to them in voices too low to follow.",
		"reaches Spirit Rise as a chant comes to its end, and the silence afterward seems to hang in the air a while.",
	},
	["thb.subzone_enter.w05.004"] = {
		"Spirit Rise. Shamans' ground. I'll keep my questions small and my voice smaller.",
		"Spirit Rise. The shamans' trainers keep their lodges here, and the totems outnumber the people.",
	},
	["thb.subzone_enter.w05.005"] = {
		"crosses to Hunter Rise, where pelts hang from frames and a row of practice targets stands bristling with arrows.",
		"steps onto {subzone}, among trainers of beasts and bows, where a tame cat pads past and an arrow thuds into a target somewhere close.",
	},
	["thb.subzone_enter.w05.006"] = {
		"The hunters and the warriors share this rise. You can tell which is which: the hunters watch the sky, the warriors watch each other.",
		"Hunter Rise. In one of these yards a trainer is telling someone they held the bow wrong. Possibly me, soon.",
	},
	["thb.subzone_enter.w05.007"] = {
		"The Pools of Vision. The shamans come down here to look into the water and see more than their own faces, they say.",
		"Dim, damp and very still. Whatever the water in these pools shows, it doesn't show it to passersby.",
	},
	["thb.subzone_enter.w05.008"] = {
		"I looked into the water. The water looked back. Neither of us learned much.",
		"Pools of Vision. All I see in the water is my own face, needing a wash.",
	},
	["thb.subzone_enter.w05.009"] = {
		"steps off a swaying bridge onto solid rock, and a new rise of the city opens up: other lodges, other totems, other fires.",
		"crosses into another quarter of the bluff, where the rhythm of the place changes as surely as if a gate had been passed.",
		"leaves the bridge behind, the boards stop moving underfoot, and for a moment the solid ground of the rise feels strange.",
	},
	["thb.subzone_enter.w05.010"] = {
		"Each rise of this city is its own small village. The bridges are just the paths between neighbors.",
		"New rise, new smells: tanning, herbs, a different stew. The bluff changes flavor with every bridge.",
		"The rises all look alike from the lift. Walking them, no two are the same.",
	},
	["thb.subzone_enter.w05.011"] = {
		"Made it across. That bridge and I have an understanding now.",
		"Another rise reached. My knees only wobbled twice on the way over.",
	},
	["thb.subzone_enter.w05.012"] = {
		"crosses to the rise in the dark, following the fires burning at the far end of the bridge.",
		"steps onto the rise as night lies over the bluff, the totems now only tall black shapes against the stars beside the fires.",
	},
	["thb.thanks.w05.001"] = {
		"Thank you. Up here even a small kindness feels like it comes from high places.",
		"My thanks. I'll pass the favor on before I reach the bottom of the lift.",
		"Thanks. You've the patience of the bluff, and I'm grateful for it.",
	},
	["thb.thanks.w05.002"] = {
		"You have my thanks, given slowly, the way they give it here.",
		"Thank you. The Earth Mother sees such things, they say on Spirit Rise.",
	},
	["thb.toast.w05.001"] = {
		"To the bluff, and to everyone who made it up the lift today!",
		"To the Earth Mother's children, and to their patient cooks!",
		"Raise them high. Higher than this, there's nowhere left to raise them.",
	},
	["thb.travel.w05.001"] = {
		"takes out the hearthstone at the edge of the rise, and the plains below begin to blur before the stone is even warm.",
		"closes a hand on the hearthstone between two totems, and the city of the tauren fades out like a drumbeat dying away.",
	},
	["thb.travel.w05.002"] = {
		"The quickest way off the bluff that doesn't involve a lift or a wind rider. I'll take the stone.",
		"One squeeze of the stone and I skip every bridge between here and the road. Sorry, bridges.",
	},
	["thb.weather_change.w05.001"] = {
		"watches the rain come in across the plains and reach the bluff, and the bright paint on the totems darkens in streaks.",
		"pulls up a hood as the rain starts, and the dust on the planks of the bridges turns to dark mud.",
		"stands under the eaves of a lodge while the rain hisses on the fires, and the smoke of the city turns white and heavy.",
	},
	["thb.weather_change.w05.002"] = {
		"Rain! Somebody take the hides in off the frames.",
		"Here comes the rain. Every bridge in this city is about to get exciting.",
	},
	["thb.weather_change.w05.003"] = {
		"A storm over Thunder Bluff. Now I understand the name: the thunder rolls between the mesas like a herd stampeding.",
		"Lightning to the west, close enough to count the forks. Up here the storm isn't overhead; it's beside me.",
		"The tents strain on their poles and the bridges swing in the storm. The tauren go about their business as if the sky always shouted.",
	},
	["thb.weather_change.w05.004"] = {
		"steps back from the edge of the rise as the storm breaks, the rope bridges bucking and the totems standing firm against it.",
		"watches lightning walk across the plains below in the storm, each flash lighting up Mulgore green and white for a heartbeat.",
	},
	["thb.weather_change.w05.005"] = {
		"The sky's cleared. From up here I can see all the way to the hills at the edge of Mulgore, every fold of them.",
		"Clear again, and the plains below look washed. Even the bridges seem to sway more cheerfully.",
		"Fair skies. The herds below have spread out across the grass again, and the whole bluff seems to breathe out.",
	},
	["thb.weather_change.w05.006"] = {
		"The clouds have gone and the night is enormous. Thunder Bluff sits in the middle of the stars like a lodge in an open field.",
		"The sky has cleared, and up here there's nothing between me and the stars but a bit of cold night air.",
	},
	["thb.weather_change.w05.007"] = {
		"The rain brings the smell of the plains up the cliffs: wet grass, wet earth, and kodo, faintly.",
		"Rain on Mulgore. Down there the grass is drinking, and the smell of it climbs all the way up here.",
	},
	["thb.journey.w24.alight.001"] = {
		"climbs down and flexes {g:his|her} fingers one by one; they are still curled to the shape of the reins.",
		"gets down from the beast and works {g:his|her} hands open and shut, stiff from gripping, until they remember how to be hands.",
	},
	["thb.journey.w24.alight.002"] = {
		"My ears are still full of rushing. The city comes in through it one piece after another: a ladle on a pot, somebody laughing low, a hide being beaten with a stick.",
		"After the flight every noise sounds far off. Then they come back one by one, close and ordinary: a hammer, a basket set down, two voices disagreeing slowly.",
		"The ringing in my ears fades and the rise fills in behind it: a kettle, a call across a bridge, beads clicking on someone's braid.",
	},
	["thb.journey.w24.alight.003"] = {
		"steps off the roost and shakes grass seed and grit out of {g:his|her} collar, the plain's last word on the matter.",
		"brushes down {g:his|her} sleeves after dismounting, and a fine dust drifts off them and away over the edge.",
	},
	["thb.journey.w24.alight.004"] = {
		"Whatever my hair looked like before, it now looks like a nest some hawk gave up on halfway.",
		"I'll need a comb, a few minutes and nobody looking. The flight has rearranged my hair to its own taste.",
	},
	["thb.journey.w24.alight.005"] = {
		"blinks hard after dismounting, eyes stung by the flight, and the lodges beyond the roost slowly come into focus.",
		"rubs {g:his|her} eyes, smarting from the rush of the flight, and lets the tents and poles of the rise settle back into their proper edges.",
	},
	["thb.journey.w24.alight.006"] = {
		"The planks don't move. After the wind rider, that's almost suspicious.",
		"A few steps in and I keep waiting for the floor to bank. It doesn't. Tauren build things that stay put.",
	},
	["thb.journey.w24.alight.007"] = {
		"steps off the platform past a tauren waiting to fly, who gives a single slow nod, the kind that seems to include the beast as well.",
		"passes a tauren sitting by the roost with a pack across the knees, who looks up, nods once without haste, and goes back to waiting.",
	},
	["thb.journey.w24.alight.008"] = {
		"Out of the wind, and the city has a smell again: leather oil, damp hide, something with corn in it bubbling on a fire nearby.",
		"The flight scours every smell away. Then I step off and they all come back at once: tanned leather, crushed grass, and a pot of something I'd follow anywhere.",
	},
	["thb.journey.w24.alight.009"] = {
		"Thank you. Same beast next time, if it's willing.",
		"My thanks to the both of you. I'll go and find my legs somewhere over there.",
	},
	["thb.journey.w24.alight.010"] = {
		"unbuckles the pack from behind the saddle, checks the straps with a quick tug, and slings it over a shoulder as {g:he|she} steps away.",
		"pulls {g:his|her} bag free of the saddle rings and pats it down twice, out of habit, to be sure the flight has kept nothing for itself.",
	},
	["thb.journey.w24.alight.011"] = {
		"Pockets checked. Every coin present. Mulgore will have to make its own fortune.",
		"First thing off the saddle: a hand on every pouch, one after another. All there. The plain gets nothing from me this flight.",
	},
	["thb.journey.w24.alight.012"] = {
		"takes three steps off the roost into the lee of a lodge, and the sudden hush of still hide all around is almost loud.",
		"ducks behind the first tent wall past the roost, and the world goes quiet and mild all at once, like stepping out of a river.",
	},
	["thb.journey.w24.alight.013"] = {
		"Everyone up here talks softly, but after the flight their voices sound right in my ear. I find myself whispering back.",
		"My ears are still tuned to the roar, so a tauren murmuring three paces off sounds like a shout. I nod too hard at nobody.",
	},
	["thb.journey.w24.alight.014"] = {
		"holds {g:his|her} hands over a fire pit near the roost, cold from the flight, and turns them over like bread on a hot stone.",
		"stops at the first fire past the roost to work the chill of the flight out of {g:his|her} fingers.",
	},
	["thb.journey.w24.alight.015"] = {
		"Somebody point me at food. Slowly. I'm still turning left.",
		"Which way to the nearest bench? Don't worry, I'll walk there. Mostly in a line.",
	},
	["thb.journey.w24.alight.016"] = {
		"The first footstep on the roost sounds enormous. Up there, nothing I did made any sound at all.",
		"Funny how loud a foot is on wood, once you've been a while where nothing touches anything.",
	},
	["thb.journey.w24.alight.017"] = {
		"walks away from the roost with the bow-legged dignity of someone who has just climbed off something very wide.",
		"sets off across the rise with a rider's rolling gait, which a passing tauren politely pretends not to notice.",
	},
	["thb.journey.w24.alight.018"] = {
		"dismounts while two young tauren at the edge of the roost watch the beast with the solemn attention of children who have been told not to touch.",
		"dismounts under the eyes of a pair of young tauren near the roost, who study the wind rider as if planning to ask for one.",
	},
	["thb.journey.w24.alight.019"] = {
		"steps down as a troll waits at the roost's edge for the next beast, and the two trade the small, knowing nod of people who share an opinion about saddles.",
		"passes an orc queuing for a flight on the way off the platform; neither says a word, but the orc's glance at {g:his|her} stiff walk says plenty.",
		"trades a look with a Forsaken waiting to fly, who studies the way {g:he|she} climbs down and seems to file it away for later.",
	},
	["thb.journey.w24.alight.020"] = {
		"A great hand closed under my elbow as I climbed down and let go the instant I had my footing. I never saw whose. That's how the tauren help, as far as I can tell.",
		"Someone steadied me as I came off the saddle, a hand the size of a shovel, gone before I could turn and say thanks.",
		"I stumbled off the beast and a huge palm caught my shoulder, set me upright, and was away. Up here kindness doesn't wait to be thanked.",
	},
	["thb.journey.w24.alight.021"] = {
		"meets a gust as {g:he|she} dismounts, carrying the sharp smell of the tanning racks, and {g:his|her} nose wrinkles before the rest of {g:him|her} has finished arriving.",
		"is met at the roost's edge by the smell of curing leather drifting over from Hunter Rise, strong enough to feel like a greeting.",
		"gets a whiff of tannin and wet hide from somewhere across the rises as {g:he|she} dismounts, the city's own particular welcome.",
	},
	["thb.journey.w24.alight.022"] = {
		"Good to be among people again. The sky's poor company; it never answers.",
		"Is that spice bread I smell? Never mind where it is, just point.",
		"Friends, a moment. I need to remember which way is down.",
	},
	["thb.journey.w24.approach.001"] = {
		"watches a dark smudge on the edge of the plain refuse to be a hill, then split, slowly, into separate rises as the wind rider closes on it.",
		"sees the bluff first as one dark shape on the grass, and only on the final approach does it come apart into rises with sky between them.",
		"picks out the city by its hard edges first, straight lines where the plain has none, and then by the faint haze of its fires.",
	},
	["thb.journey.w24.approach.002"] = {
		"Coming in from the side, the cliffs show their bands: red, buff, a stripe like rust, a stripe like bread crust. From the bridges you only ever see the city's floor, never its flanks.",
		"From the air the mesas show what they hide from anyone walking on them: their sides, banded red and pale like a cut loaf.",
	},
	["thb.journey.w24.approach.003"] = {
		"follows the wind rider's shadow as it slides across a rise, ripples over the tents, drops off the cliff and lands small and late on the grass far below.",
		"sees the beast's shadow run ahead over the lodges of a rise, vanish over the edge, and turn up again on the plain, tiny, still hurrying.",
	},
	["thb.journey.w24.approach.004"] = {
		"Some of the tent tops have patterns painted on their upper slopes that nobody walking the bridges could ever see. Either the tauren paint for the birds, or for whoever comes in by wind rider. I'll take it as a welcome.",
		"From up there I could see the painting on the tops of the tents, circles and zigzags meant for no one on the ground. I wonder who they're for.",
	},
	["thb.journey.w24.approach.005"] = {
		"passes low over a rope bridge where a tauren stops mid-crossing, looks up, and lifts one broad hand as if greeting a neighbor over a fence.",
		"skims a bridge close enough to see a tauren on it pause, tilt both horns upward, and raise a hand, unhurried, before walking on.",
	},
	["thb.journey.w24.approach.006"] = {
		"Hawks came off the cliff face as we passed, a dozen at once, and for a moment the wind rider was just the biggest bird in a flock.",
		"We went by the cliff so close that birds burst out of the cracks in it. The beast ignored them with great dignity.",
	},
	["thb.journey.w24.approach.007"] = {
		"spots, on a ledge just under one rise, a row of woven blankets laid out to air, bright as a strip of beadwork against the rock.",
		"notices from the air what the bridges hide: a narrow ledge below one rise where someone has spread blankets in red and ochre, out of everyone's way but the sky's.",
	},
	["thb.journey.w24.approach.008"] = {
		"The wind rider knew before I did. Its head came round toward the roost while I was still trying to tell one rise from another.",
		"Before I could even pick out the roost, the beast had turned its head that way and started to lose height.",
	},
	["thb.journey.w24.approach.009"] = {
		"looks down on the rises as the beast circles and sees the plan of a camp in them: lodges in loose rings, the fires at the middle, as if the tribes had pitched the plains up here and stayed.",
		"sees from above how the lodges sit in scattered rings around their fire pits, the way a camp is pitched on open grass, only lifted up into the sky.",
	},
	["thb.journey.w24.approach.010"] = {
		"Four rocks, a great deal of rope, and the calmest city in Kalimdor on top. Good to be standing in it.",
		"Seen from up there it's four pillars and some string. Seen from here, it's the steadiest place I know.",
	},
	["thb.journey.w24.approach.011"] = {
		"From the air each rise has its own smoke, thin threads leaning the same way, and the beast flew straight through one of them on the way in. I smell of someone's cooking now.",
		"We came in through a thread of cookfire smoke. Now my cloak smells of somebody else's meal, which is a kind of welcome.",
	},
	["thb.journey.w24.approach.012"] = {
		"comes over the rim and sees, between the lodges, the same green grass as the plain, as if a piece of Mulgore had been lifted up whole and the tauren had simply moved in.",
		"drops toward the roost over grass that grows on the mesa tops just as it does far below, short, tough, and crossed by hoof-worn paths.",
	},
	["thb.journey.w24.approach.013"] = {
		"From above I watched a whole queue waiting at the foot of the lifts. I'd wave, but that seems unkind.",
		"There's a line at the bottom of the lifts. I saw it on the way in and felt a small, unworthy satisfaction.",
	},
	["thb.journey.w24.approach.014"] = {
		"comes in level with an eagle riding the updraft off a cliff; for a few wingbeats the two fly side by side, and then the bird simply lets them have the roost.",
		"shares the last turn with a hawk hanging over the edge of a rise, which tips one wing, unimpressed, and slides out of the descending beast's way.",
	},
	["thb.journey.w24.approach.015"] = {
		"From the air the rises look like a herd that finally lay down to rest. The elders say our people walked for generations before they did the same.",
		"Coming in, I always think how the old wanderers would have laughed to see their lodges perched on stone, up where only the hawks go. Then I think how glad they'd be.",
	},
	["thb.journey.w24.approach.016"] = {
		"lets the wind rider thread the gap between two rises, a bridge sliding by overhead so close that its ropes hum, before it banks onto the roost.",
		"feels the beast slip between two rises on the way in, the cliffs on either side close enough to count the cracks, before it swings up onto the roost.",
	},
	["thb.journey.w24.approach.017"] = {
		"I'll say this for arriving by air: you see the whole city before it sees you.",
		"Best way in. You get the bluff laid out like a map, and nobody's hoof on your toe.",
	},
	["thb.journey.w24.approach.018"] = {
		"At dusk the lodges light up one by one as we drop toward them, each tent glowing from inside like a lantern of hide.",
		"A dusk arrival: the hides of the lodges turn amber from the fires within, and the whole city looks lit for my benefit. It isn't.",
	},
	["thb.journey.w24.approach.019"] = {
		"comes in over a plain going gold and green in broad patches, and the bluff stands out of it like an anvil, until the beast tilts and it becomes a city.",
		"sees the details arrive in order as the beast descends: first the shape of the rises, then the color of the tents, then poles, then a single figure on a bridge.",
		"drops toward the city and watches it fill in as if painted from the outside inward: outline, color, and then all the small moving things.",
	},
	["thb.journey.w24.approach.020"] = {
		"Every time, I try to pick out the roost before the beast does. Every time, I'm looking at the wrong rise.",
		"I've decided the trick to spotting the roost from the air is to stop trying and let the wind rider show off.",
		"From above all the rises look equally important. Only one of them has a crowd of wind riders lounging on it, and that's the one we wanted.",
	},
	["thb.journey.w24.approach.021"] = {
		"banks over the gaps between the rises, where the ground drops away into narrow shadowed clefts far below the planks people cross without a thought.",
		"looks straight down into one of the clefts between the mesas as the beast turns, a slot of shade and scrub so deep that it makes the bridge above it look brave.",
		"passes over a gap between two rises and glimpses, at the very bottom, a strip of green no one in the city ever looks down at.",
	},
	["thb.journey.w24.ascent.001"] = {
		"climbs until the edges of the bluff fall behind and the plain comes up on every side at once, green running into gold running into distance.",
		"gains height in a wide turn, and Mulgore spreads out under the wings patch after patch, as if someone were unrolling a blanket.",
		"climbs, and the plain opens to the eye on every side, wider with each wingbeat, as if it had been folded small around the city until now.",
	},
	["thb.journey.w24.ascent.002"] = {
		"Two wingbeats past the rim and the air turns a little colder, the way a stream does when you wade out deeper.",
		"Cooler already. The city's warmth stays down there with the cookfires; up here the air has its own ideas.",
		"The air bites at the fingers a little this high. The city kept its warmth; the sky keeps none.",
	},
	["thb.journey.w24.ascent.003"] = {
		"climbs, and the streams of Mulgore come into view below, thin pale threads laid loose across the grass.",
		"gains height until the creeks of the plain show themselves, winding and doubling back as if in no hurry at all.",
	},
	["thb.journey.w24.ascent.004"] = {
		"The first minute of a flight is the only quiet I ever get that nobody can interrupt. I try not to waste it on thinking.",
		"Nobody can reach me now, not a merchant, not a messenger, not a friend with a favor to ask. For a minute or so the sky is a locked door.",
		"For the first stretch of a flight nobody can find me. I sink into that like a warm bath.",
	},
	["thb.journey.w24.ascent.005"] = {
		"rises past the height where the city's sounds give out, and below a single cart creeps along a road across the plain, its dust trailing like a tail.",
		"climbs over the road that winds away from the foot of the lifts, where a lone cart goes about its business at the speed of whatever pulls it.",
	},
	["thb.journey.w24.ascent.006"] = {
		"From up here a quilboar camp is a few brown dots and a thread of smoke. It's the nicest they've ever looked.",
		"The quilboar on the edge of the plain look almost sweet from this height. Height is a terrible liar.",
	},
	["thb.journey.w24.ascent.007"] = {
		"turns once in the climb and sees Thunder Bluff whole, as no one inside it ever does: a cluster of stone pillars wearing a city on their heads.",
		"looks back as the beast climbs, and the bluff shows its true shape at last, sheer columns of banded rock rising out of the grass with tents perched on top like hats.",
		"glances behind from the climb, and only now does the bluff look as it is: a few towers of bare stone standing in the grass, with a whole people living on top.",
	},
	["thb.journey.w24.ascent.008"] = {
		"Little ponds lie scattered across the plain, each with a scrap of the sky in it. From up here Mulgore looks sewn with mirrors.",
		"Every pond on the grass below holds a piece of the sky, so the plain seems full of small holes going straight through.",
		"The little ponds of Mulgore wink up at the wind rider one after another, as if the plain were checking who was passing.",
	},
	["thb.journey.w24.ascent.009"] = {
		"Steady climb. That's it. No hurry.",
		"Higher, then. I want to see the whole plain before it goes.",
		"Nice and easy. The plain's not going anywhere.",
	},
	["thb.journey.w24.ascent.010"] = {
		"loosens {g:his|her} grip on the saddle one finger after another as the climb evens out and the bluff settles behind.",
		"unclenches both hands once the wind rider levels off, and only then seems to notice how tightly they were holding.",
	},
	["thb.journey.w24.ascent.011"] = {
		"In the city it took me ages to cross one span. The beast has crossed the whole bluff while I was adjusting a strap.",
		"All the ground I walked up there, every plank and every lift ride, the wind rider has just undone in a few wingbeats.",
	},
	["thb.journey.w24.ascent.012"] = {
		"climbs into a clear sky, and the plain below is laid open to its farthest hills, every road and stream as sharp as if drawn that very hour.",
		"rises into air so clear that the far rim of Mulgore stands out as plainly as the planks of the roost behind.",
	},
	["thb.journey.w24.ascent.013"] = {
		"Up there the tauren are the biggest thing around. From here they're specks, and the plain they walked across for generations is the size it always was.",
		"In the city everything was built to a tauren's size. Now the whole city is smaller than the wind rider's head in front of me.",
	},
	["thb.journey.w24.ascent.014"] = {
		"climbs into the dusk, and below, one after another, the lodges of the city begin to glow through their hides as fires are lit inside.",
		"rises from the bluff as the light goes, the plain below already blue while the tops of the rises still hold a last edge of red.",
	},
	["thb.journey.w24.ascent.015"] = {
		"leaves the roost straight into the fog, and within a few wingbeats the city behind is only a smell of smoke and a creak of rope.",
		"is swallowed by fog before the beast has cleared the roost, the nearest tent pole fading first, then the planks, then everything.",
	},
	["thb.journey.w24.ascent.016"] = {
		"The roost master studied the clouds a long time before letting the beast go. Up here in the storm, I understand why.",
		"Lightning somewhere over the plain, and the wind rider climbing right toward it. The roost master's silence at the edge said plenty.",
	},
	["thb.journey.w24.ascent.017"] = {
		"climbs into the dark, and the lanterns of the roost shrink behind until they are a single warm speck hung on nothing.",
		"lifts away into the night, the plain below gone entirely black, the city behind a cluster of small lights perched on darkness.",
	},
	["thb.journey.w24.ascent.018"] = {
		"After the first scramble the wingbeats find their rhythm, and the flight stops being an event and becomes a place to sit.",
		"A minute in and the lurching's done. Now there's just the long steady pull of the wings and whatever I care to think about.",
	},
	["thb.journey.w24.ascent.019"] = {
		"climbs high enough to see, off on the hills, a bare brown scar where the Venture Company has been cutting, ugly even at this distance.",
		"gains height, and from up here the raw clearing of the Venture Company shows plainly on the far slopes, a bald patch on the green.",
	},
	["thb.journey.w24.ascent.020"] = {
		"climbs until the plain, which looked flat from the city, begins to show its long gentle folds, like a hide not quite pulled tight.",
		"reaches enough height to see that Mulgore is not flat at all: it rolls, slow and wide, the way a sleeping animal's flank rises and falls.",
	},
	["thb.journey.w24.ascent.021"] = {
		"leans into the long turn away from the city, and the whole plain tips up on one side like a tray held by a careless hand.",
		"tilts with the beast as it banks away from the rises, and the horizon swings up, hangs a moment at a slant, then settles level.",
	},
	["thb.journey.w24.ascent.022"] = {
		"Whole plain at once. I'll never get tired of that.",
		"Look at all that grass. Somebody should mow it.",
		"Higher than the eagles now. Don't let them hear me say it.",
	},
	["thb.journey.w24.ascent.023"] = {
		"City behind, sky ahead. Hands, stay where you are.",
		"Plenty of air underneath now. Keep it that way, beast.",
	},
	["thb.journey.w24.farewell.001"] = {
		"The city never asked me to stay and never hurried me out. I'd like to be that kind of host someday.",
		"Nobody up there said goodbye in a hurry. I'm carrying that off with me like a warm stone in a pocket.",
		"Not one tauren in that city rushed me, fed me less than I could eat, or let me go without a word. I'd call that a rare place.",
	},
	["thb.journey.w24.farewell.002"] = {
		"I'm leaving Thunder Bluff a little slower than I came. Not my feet. Everything else.",
		"I've picked up the tauren habit of looking at a thing a while before speaking about it. I give it until the next noisy city.",
	},
	["thb.journey.w24.farewell.003"] = {
		"Walk gently, Thunder Bluff. I'll try to fly the same way.",
		"Peace on the rises, and on everyone who keeps them.",
		"Long life to the rises, and slow days to all who live on them.",
	},
	["thb.journey.w24.farewell.004"] = {
		"What stays with me from the city isn't the view. It's an old tauren shifting a stool aside to let me by, and the slow nod that went with it.",
		"Of everything up there, I'll remember a stranger's slow nod over a bowl. Odd, what the mind decides to pack.",
	},
	["thb.journey.w24.farewell.005"] = {
		"Every time I leave the bluff I tell myself the plain will feel like home too. It does, nearly. Nearly is the word that stays behind.",
		"The high lodges of my people grow small behind me. Wherever the wind rider carries me, part of me keeps a place by those fires.",
	},
	["thb.journey.w24.farewell.006"] = {
		"Even from the sky I can feel the Earth Mother under the grass down there. The bluff is only one of the places she holds me.",
		"The Earth Mother does not stay on the bluff when I leave it. She is the whole plain below, and every road after.",
	},
	["thb.journey.w24.farewell.007"] = {
		"I'll never have horns or hooves or that patience, but they let me sleep under their hides anyway. That's a kind of welcome you remember.",
		"A guest among giants for a while, fed and housed and never once made to feel my size, though I felt it. That deserves remembering.",
	},
	["thb.journey.w24.farewell.008"] = {
		"The tauren have every reason to keep the dead at arm's length, and they set out a mat for me all the same. I'll remember that longer than the view.",
		"A people of the living earth, and they let one of the dead walk their rises unbothered. Flying off, I find I owe them more than coin.",
	},
	["thb.journey.w24.farewell.009"] = {
		"I meant to buy one of those carved bone needles before I left. Now there's a long drop between me and changing my mind.",
		"A minute out over the plain and I remember the thing I meant to do in the city. Of course I do.",
		"There was one more thing I wanted to see on Spirit Rise. It can wait. The bluff isn't going anywhere.",
	},
	["thb.journey.w24.farewell.010"] = {
		"Thank you, city. You were patient with me.",
		"Farewell, rises. Keep your fires low and your ropes tight.",
	},
	["thb.journey.w24.farewell.011"] = {
		"The city won't notice I'm gone. That's no complaint. Some places are restful exactly because you don't matter much to them.",
		"Down there the cookfires go on and the elders keep talking, and not one of them will mark the gap where I was. I find that oddly comforting.",
	},
	["thb.journey.w24.farewell.012"] = {
		"looks back once as the rises fall behind, then turns forward in the saddle and keeps both eyes ahead after that.",
		"spares the shrinking city a long last look over one shoulder, then settles forward over the wind rider's neck.",
		"glances back past the wind rider's tail at the city, nods to it once as to an acquaintance, and faces forward.",
	},
	["thb.journey.w24.farewell.013"] = {
		"If I could take one thing out of the city it would be the patience. I'll settle for remembering what it looked like.",
		"I can't bottle the calm of that place, but I can try to remember how it sounded: slow voices, long pauses, nobody filling them.",
	},
	["thb.journey.w24.farewell.014"] = {
		"Tell the inn I paid. I did pay. Mostly.",
		"If anyone asks, I left on time. Tauren time, but still.",
	},
	["thb.journey.w24.farewell.015"] = {
		"The tauren were wanderers for generations before they settled on the bluff. Every time I fly off from their high camp, I think they'd understand the itch.",
		"A people who followed the herds for longer than anyone can count built that place to stay. Leaving it, I feel more like their ancestors than like them.",
	},
	["thb.journey.w24.farewell.016"] = {
		"lifts a hand toward the roost in farewell; the roost master, without looking up from a buckle, lifts one back.",
		"raises an arm to the shrinking roost, and far behind a great hand rises in reply, slow and unhurried, before going back to its work.",
	},
	["thb.journey.w24.farewell.017"] = {
		"pats the pack behind the saddle to be sure it is all there, the city's last small purchases bumping against {g:his|her} back.",
		"checks the straps of the pack once more as the roost falls behind, as if the city might have slipped something inside.",
	},
	["thb.journey.w24.farewell.018"] = {
		"Keep a seat by the fire for me, tauren. I'll be wanting it.",
		"Stay patient, all of you. Somebody has to be.",
	},
	["thb.journey.w24.harness.001"] = {
		"tests the harness with one last tug as the wind rider shifts its weight from paw to paw, and then the platform drops out from under them both.",
		"gives the chest strap a final pull, feels the whole beast tense against it like a drawn rope, and lets go of the post.",
		"pulls once on every strap within reach, and the wind rider takes that as its signal: one step, and there is nothing underneath.",
	},
	["thb.journey.w24.harness.002"] = {
		"Three straps, two buckles and a knot the roost master tied without looking. I'm choosing to trust the knot most.",
		"Cinched in without a word, and the pat went to the beast, not to me. I know whose safety matters up here.",
	},
	["thb.journey.w24.harness.003"] = {
		"feels the wind rider's tail swing up behind the saddle as it leaves the roost, the stinger passing a polite hand's width from {g:his|her} ear.",
		"goes out over the edge with the beast's barbed tail curling up over the saddle, close enough to part the hair and, mercifully, no closer.",
	},
	["thb.journey.w24.harness.004"] = {
		"If that strap was holding anything important, now's the moment to tell me.",
		"Is this buckle meant to rattle? Never mind. Too late to ask.",
	},
	["thb.journey.w24.harness.005"] = {
		"The reins are braided hide, worn smooth in two places where a thousand riders held on. My hands find the same two places without being told.",
		"Two shiny patches on the reins, polished by everyone who flew before me. That's where my fingers go too.",
	},
	["thb.journey.w24.harness.006"] = {
		"Feet in the loops, knees tight, reins short, and don't grab the mane. The roost master says it once, and once is plenty.",
		"Knees in, heels down, hands off the mane. That slow voice is still in my head as the platform falls behind.",
	},
	["thb.journey.w24.harness.007"] = {
		"hears the beads knotted into the harness click together at the first wingbeat, then go quiet as the flight smooths out.",
		"sets off to a small clatter of wooden beads on the harness, which settles into a steady rattle with the rhythm of the wings.",
	},
	["thb.journey.w24.harness.008"] = {
		"My knuckles always go pale on the reins for the first stretch. Then the beast settles, and slowly I give them back their color.",
		"First minute aloft, I hold the reins like they owe me money. Second minute, like a friend's hand.",
	},
	["thb.journey.w24.harness.009"] = {
		"takes to the air with rain beading on the oiled harness, the straps gone dark and slick under the fingers.",
		"quits the roost in the rain, the beast shaking water from its mane once, hard, before the first stroke.",
	},
	["thb.journey.w24.harness.010"] = {
		"Easy. You know the way out of here better than I do.",
		"All right, beast, your sky. I'm only luggage with opinions.",
		"Off you go, then, and I'll try not to help.",
	},
	["thb.journey.w24.harness.011"] = {
		"hears the beast give one sour grunt as it leaves the roost, the sound of a creature that agreed to this and wishes it had not.",
		"sets out with the wind rider muttering deep in its chest at the weight on its back, a complaint it keeps up for the whole first stretch.",
	},
	["thb.journey.w24.harness.012"] = {
		"works the saddle straps loose one by one, the leather stiff and cold from the height, and steps clear before the beast can shake.",
		"unhooks the last strap and slides down, and the beast at once gives a great shudder from mane to tail, like a dog out of a river.",
		"loosens the girth with a grunt of effort, and the wind rider, freed, stretches both wings wide enough to clear the platform of onlookers.",
	},
	["thb.journey.w24.harness.013"] = {
		"The harness comes off the beast in a minute. It comes off me, the feeling of it, somewhere around the bank.",
		"Out of the straps at last. My legs still think they're buckled in and walk accordingly.",
	},
	["thb.journey.w24.harness.014"] = {
		"watches the roost master lift the saddle off and hang it on a peg among a dozen others, each with its own stripes on the blanket.",
		"sees the harness come off the beast and go up on a wooden peg by the perch, still swinging, beads clicking, as the next one comes down.",
	},
	["thb.journey.w24.harness.015"] = {
		"My hands smell of oiled leather and wind rider. I'll notice it later, reaching for something at the inn, and be up there for a second.",
		"Leather and beast on my fingers. It's the part of the flight that comes with me into the city.",
	},
	["thb.journey.w24.harness.016"] = {
		"Straps held, beast held, I held. Good work all round.",
		"Every buckle did its job. Thank whoever stitched them.",
	},
	["thb.journey.w24.harness.017"] = {
		"unbuckles in the storm with numb fingers, the straps swollen and heavy with water, while the beast hunches its wings over its head like a cloak.",
		"drops onto the roost under a hard storm, water running off every strap, and two big hands take the reins and lead the beast under cover at once.",
	},
	["thb.journey.w24.harness.018"] = {
		"The Horde's roost, the Horde's beast, and a tauren to take the reins. Good to come down among allies.",
		"Wings of the Horde, set down on the tauren's high ground. My thanks.",
	},
	["thb.journey.w24.harness.019"] = {
		"The roost master says every harness here is knotted by the same few hands down on Hunter Rise, and mended by them too. I believe it: each knot on mine looked like a signature.",
		"According to the roost master, the harness leather is worked on Hunter Rise and tied off by people who never fly. Odd, to trust my life to someone who has never left the ground.",
	},
	["thb.journey.w24.homing.001"] = {
		"In most cities the wind rider brings you down to the ground. Here it leaves you at the top and puts the ground off for later.",
		"Elsewhere a flight ends at ground level. This one ends at the summit, and the ground is somebody else's problem.",
	},
	["thb.journey.w24.homing.002"] = {
		"The flight was all hurry. The city doesn't care: it was this calm before I came and it'll be this calm when I've gone. I like being outpaced by stillness.",
		"Everything up there was speed. Down here nobody has hurried since the lodges went up, and they're not about to start for me.",
	},
	["thb.journey.w24.homing.003"] = {
		"Peace to the roost and to all who keep it.",
		"May the planks hold and the fires keep. Good to be on the bluff.",
	},
	["thb.journey.w24.homing.004"] = {
		"A minute ago this rise was a coin-sized thing on the plain. Now it's a place with a smell and a crowd and a crooked plank I nearly tripped on. I prefer it this size.",
		"From above I could have covered the whole city with one hand. Standing in it, I can't even see across it for tents.",
	},
	["thb.journey.w24.homing.005"] = {
		"Feet down, list up: something warm to eat, a visit to the bank, and a sit somewhere nobody needs me to stand.",
		"Landed. Now the small things in their order: a meal, a counter, a bench. The city will wait while I do them; it always does.",
		"Down, and already my feet are choosing the way: the bank first, then food, then the quietest bench on the rise.",
	},
	["thb.journey.w24.homing.006"] = {
		"The beast set me down, and the first thing I felt underfoot was the old wood of the roost. Home is a sound before it is anything else.",
		"Earth Mother, I'm down among my own again. The lodges, the slow voices, the smell of the hides. I didn't know how much I'd missed them until I landed.",
	},
	["thb.journey.w24.homing.007"] = {
		"Whatever trouble the Horde has out there, it hasn't climbed these cliffs. Landing here feels like setting a heavy pack down in a friend's doorway.",
		"An ally's city, and the most patient one we have. I can be slow here without anybody thinking less of me.",
	},
	["thb.journey.w24.homing.008"] = {
		"Orgrimmar would have three people shouting at me by now. Here the roost master just nods, and that nod lasts longer than most orcish conversations.",
		"An orc gets used to noise. Landing here, the quiet is so thick I keep turning round to see who's sneaking up.",
	},
	["thb.journey.w24.homing.009"] = {
		"Cairne spoke for my kind when few would. I don't forget it when the wind rider sets me down here, among the people who listened to him.",
		"They let us into the Horde partly on the word of the tauren. I land on their bluff a little more carefully than anywhere else.",
	},
	["thb.journey.w24.homing.010"] = {
		"Nothing up here is like the islands: no surf, no vines, just grass and sky. But the tauren make room the way the Darkspear do, without fuss.",
		"Far from the sea, this bluff. Still, I land, and somebody nods, and that's enough to make a troll feel welcome.",
	},
	["thb.journey.w24.homing.011"] = {
		"Hello, bluff. Did I miss anything? No, of course not. Nothing here moves fast enough to be missed.",
		"On the rise once more. Somebody tell me nothing's changed; at this pace I'd hate to have missed it.",
	},
	["thb.journey.w24.homing.012"] = {
		"Nobody at the roost asked where I'd been or what I'd done. They just took the reins. There's a kindness in that I don't find everywhere.",
		"No questions on landing. A nod, a hand for the reins, and I'm free to be just someone walking off a platform.",
	},
	["thb.journey.w24.homing.013"] = {
		"looks up after dismounting at the empty sky {g:he|she} was part of a moment ago, and finds it already closed over, as if no one had ever passed.",
		"glances skyward from the roost; the path the beast cut through the air has left no mark at all, and the sky goes on being enormous without {g:him|her}.",
	},
	["thb.journey.w24.homing.014"] = {
		"After all that open grass on the way in, I understand the bluff better. On the plain you can be seen for miles. Up here, the tauren finally got to do the seeing.",
		"The plains are beautiful from a wind rider, and they're also wide open, nowhere to hide. Landing on the bluff, I think I know why a hunted people climbed.",
	},
	["thb.journey.w24.homing.015"] = {
		"I'll walk the rest. Bridges I can argue with; the sky never listens.",
		"Enough sky for one stretch. Planks from here on, thank you.",
	},
	["thb.journey.w24.homing.016"] = {
		"Came down through fog so thick the roost appeared under the beast's paws like a raft. Now I'm on it, and the rest of the city is only voices.",
		"The fog swallowed the plain on the way down and gave me the roost at the very last instant. Everything past it is murmurs and the shapes of tents.",
	},
	["thb.journey.w24.homing.017"] = {
		"comes down hard in the storm, the beast's wings snapping like wet canvas, and the roost master grabs the bridle with both hands before the next gust.",
		"drops onto the roost with the storm shoving from every side; somebody has already lashed the spare saddles down, and {g:he|she} slides off quickly and keeps low.",
	},
	["thb.journey.w24.homing.018"] = {
		"Clear all the way in. I could see the city from the far side of the plain, and it took its time getting bigger.",
		"Not a cloud on the way down. The bluff stood up out of the grass so sharp-edged it looked cut from paper.",
	},
	["thb.journey.w24.homing.019"] = {
		"climbs down into the hush of the night roost, where the only sounds are the beasts shifting and, somewhere across the rises, one low voice singing to itself.",
		"steps off the beast into the night, the planks cool and damp underfoot, the stars so near that the rise seems to lean toward them.",
	},
	["thb.journey.w24.homing.020"] = {
		"The beast brought me in with the dawn behind us, and the shadow of every pole on the rise is stretched out far enough to trip on.",
		"A dawn landing. Every lodge has its flap tied open and the hides are steaming faintly as the chill goes out of them.",
	},
	["thb.journey.w24.homing.021"] = {
		"I like that this city has no gate. You come up out of the grass or down out of the sky, and either way it simply lets you in.",
		"No walls, no gate, no one at the roost asking my business. Thunder Bluff takes arrivals the way grass takes hoofprints.",
		"Other capitals make you knock. This one only asks that you don't fall off on the way in.",
	},
	["thb.journey.w24.homing.022"] = {
		"Coming down out of so much empty sky, a crowded rise is a relief. I don't need anyone to speak to me. I just like that they're here.",
		"After the flight, the plain sound of other people going about their business is all the company I want.",
		"Up there it was me, the beast and nothing. Down here there are a hundred small lives within earshot, and I'm content to be one more.",
	},
	["thb.journey.w24.homing.023"] = {
		"stands on the roost a moment longer than needed, letting the slow pace of the city settle over everything like a blanket after the hurry of the flight.",
		"lingers at the roost's edge, watching the rises go about their unhurried business, and lets {g:his|her} own pace drop to match.",
		"waits by the roost until the flight's urgency has drained out of {g:his|her} shoulders, then walks into the city at the city's speed.",
	},
	["thb.journey.w24.homing.024"] = {
		"Three things I've learned about landing here: the beast knows the way, the roost master knows the beast, and neither of them needs my advice.",
		"My part in the landing was to hold on and say nothing. I managed one of those well.",
		"I flew in, I landed, nobody clapped. Tauren are a hard audience; they've seen a great many wind riders.",
	},
	["thb.journey.w24.liftoff.001"] = {
		"feels the roost's planks give one last time under the beast's claws, and then there is nothing under either of them but air.",
		"is pressed down into the saddle as the wind rider pushes off, and the planks of the roost knock once behind like a closing door.",
		"rocks back as the beast's hind legs shove against the platform, and the roost master's hand drops from the harness a moment late.",
	},
	["thb.journey.w24.liftoff.002"] = {
		"After walking all over the city at a tauren's pace, this sudden speed feels almost rude.",
		"The city taught me to slow down. The wind rider, apparently, missed that lesson.",
		"Everyone up there takes their time. The beast leaves like it owes somebody money.",
	},
	["thb.journey.w24.liftoff.003"] = {
		"Hold on to the city for me, would you? I'll want it where I left it.",
		"Off we go. Try not to clip a tent pole on the way.",
		"Easy. The tents don't need a closer look.",
	},
	["thb.journey.w24.liftoff.004"] = {
		"passes straight through the thin smoke of a cookfire on the way out, and comes out the far side smelling of it.",
		"is carried through a drifting ribbon of smoke from some lodge below, and for a moment the city is a smell rather than a sight.",
		"flies out through a thin gray drift of lodge smoke, and for the length of a wingbeat sees nothing of the city at all.",
	},
	["thb.journey.w24.liftoff.005"] = {
		"The moment the claws leave the planks the city goes quiet, as if someone had let a lodge flap fall over all of it.",
		"One push and the voices of the city are gone. Not fading. Gone, like a lid set on a pot.",
		"The roost was all voices and creaking. Two wingbeats later there's only the wings and the rush of air past my ears.",
	},
	["thb.journey.w24.liftoff.006"] = {
		"glances back once and sees the roost master already turned away, coaxing the next beast toward the edge.",
		"looks over a shoulder at the roost and finds nobody watching the departure; the master is already busy with another saddle.",
		"turns in the saddle to see the roost master already reaching for the next rider's reins, this departure finished and forgotten.",
	},
	["thb.journey.w24.liftoff.007"] = {
		"My ears go first. They always notice the height a moment before the rest of me does.",
		"A pop in both ears, a lurch somewhere under the ribs, and the city is behind me.",
		"Something in my ears gives way with a small click, and the city's last sounds come back thin and far, as if from the bottom of a well.",
	},
	["thb.journey.w24.liftoff.008"] = {
		"Up, beast. Gently, if you know the word.",
		"Wings out. Let's not give the roost a show.",
		"Mind the poles, then straight out.",
	},
	["thb.journey.w24.liftoff.009"] = {
		"rises over a tauren crossing the central rise with a basket, who does not so much as lift an ear.",
		"passes low over a pair of tauren deep in talk below the roost; neither of them turns a horn to watch.",
		"leaves behind a merchant who glances up, judges the departure unimportant, and goes on folding a blanket.",
	},
	["thb.journey.w24.liftoff.010"] = {
		"A young tauren on the planks below waves both arms at the wind rider. I wave back before I can think better of it.",
		"Somebody's calf is jumping and pointing down there. For that one small tauren, I'm the most exciting thing in the sky.",
		"Down on the planks a tauren child has stopped dead to stare. I sit up a little straighter. It seems only fair.",
	},
	["thb.journey.w24.liftoff.011"] = {
		"drops past the lip of the rise, and for a long moment the cliff face streams by close enough to count its bands of red and ochre.",
		"slides down along the side of the mesa before the wings catch, the striped rock rushing upward a few lengths from the stirrups.",
		"falls a short way along the mesa's face before the wings bite, near enough to see lichen and an old nest tucked into a crack.",
	},
	["thb.journey.w24.liftoff.012"] = {
		"For a moment the wind rider's shadow runs across the tent roofs beside me, then it slips off the edge of the rise and is gone into the drop.",
		"The beast's shadow climbs a lodge, crosses a walkway, and falls off the cliff. Better it than me.",
	},
	["thb.journey.w24.liftoff.013"] = {
		"Everyone else in this city takes the lift down. I'm told this is quicker.",
		"Some folk take the lift. Some folk are sensible.",
		"Quickest way off a mesa. Second quickest, to be fair.",
	},
	["thb.journey.w24.liftoff.014"] = {
		"pulls clear of the roost, and in a single wingbeat the city goes from all around to all beneath.",
		"is lifted off the roost, and the city that was walls and tent flaps a moment ago becomes, all at once, a map.",
	},
	["thb.journey.w24.liftoff.015"] = {
		"It took me a good while to say goodbye at the inn, the tauren way. The wind rider says it in one shove.",
		"Goodbyes up there are long and gentle. The wind rider's goodbye is a lurch.",
	},
	["thb.journey.w24.liftoff.016"] = {
		"The elders say a tauren who leaves the high place should look back once, no more. I look back once. It's harder than it sounds.",
		"Once, the elders say. A shu'halo leaving the bluff looks back once, and lets the plain have the rest.",
		"Look back one time only, the old herders taught. I do, and the bluff is already smaller than I'd like.",
	},
	["thb.journey.w24.liftoff.017"] = {
		"skims out low over a lodge beside the roost, close enough to hear someone humming inside it, and then the lodge is far below and the humming gone.",
		"passes so near the top of a tent on the way out that its smoke flap stirs in the beast's wake, and a startled voice within says something short.",
		"goes out over the nearest lodge at the height of its poles, and a tauren sitting in the doorway raises a bowl in slow salute.",
	},
	["thb.journey.w24.liftoff.018"] = {
		"Up! And if you sneeze, warn me first.",
		"Off the roost, then. Don't let the tauren see me flinch.",
	},
	["thb.journey.w24.liftoff.019"] = {
		"Feet off the planks. At last, a way across this city that doesn't sway.",
		"No rope, no lift, no ladder. Just air. I like this way out better.",
	},
	["thb.journey.w24.rimward.001"] = {
		"banks over the central rise, and the lodges show themselves as they never do from the ground: pale cones, each with a dark hole at its crown for the smoke.",
		"circles out past the roost, and from up here every tent in the city is a ring of poles meeting at a sooty point.",
		"drifts wide over the rooftops, and every lodge shows the same shape from above, a circle of hide gathered to a dark knot at its top.",
	},
	["thb.journey.w24.rimward.002"] = {
		"From the ground I only ever saw the bridges. From up here what I see is the gaps they cross, and the gaps are much bigger.",
		"Funny: walking the city I watch my feet on the planks. Flying over it, all I can look at is the empty space underneath them.",
		"Crossing the city I never looked at what was under the planks. Now that's all there is to look at: drop, and more drop.",
	},
	["thb.journey.w24.rimward.003"] = {
		"passes over Spirit Rise, where the dark mouth of the Pools of Vision opens in the rock, still and unbothered by anything in the sky.",
		"tilts past Spirit Rise and catches, among its lodges, the shadowed way down into the Pools of Vision, a dark notch in the stone.",
	},
	["thb.journey.w24.rimward.004"] = {
		"Over Hunter Rise the beast's head turns, and I can guess why: somebody down there is curing meat.",
		"The wind rider takes a long, interested look at Hunter Rise as it passes. I don't ask what it smells.",
		"The beast sniffs loudly as the flight clears Hunter Rise. Somebody there is working a fresh hide, and the wind rider has opinions.",
	},
	["thb.journey.w24.rimward.005"] = {
		"swings wide of Elder Rise and sees, small among the lodges, a bear walking unhurried toward a doorway, as if expected.",
		"passes high over Elder Rise, quiet as ever, where the only thing moving is a bear going from one lodge to the next at its own pace.",
	},
	["thb.journey.w24.rimward.006"] = {
		"Three rises and the big one. I count them every time I leave, as if one of them might have wandered off.",
		"From up here I can take the whole city in at once, every rise of it, which is something nobody standing in it can do.",
	},
	["thb.journey.w24.rimward.007"] = {
		"passes above the head of the lifts just as a platform arrives, crowded with travelers who step off without once looking up.",
		"looks down at the top of the great lifts, where a loaded platform is coming level with the rim and a kodo is being coaxed off it.",
		"watches the lifts as one platform sinks and the other rises, the ropes between them trembling, a trade of weights made without a word.",
	},
	["thb.journey.w24.rimward.008"] = {
		"There's the inn, there's the bank, there's the tent where I ate too much. From up here my whole stay looks like a few pebbles on a table.",
		"Every place I went in the city sits down there in a tidy cluster, much closer together than my feet believed.",
		"The inn, the bank, the bench where I sat and did nothing for a while: all of it now fits between two of the beast's wingbeats.",
	},
	["thb.journey.w24.rimward.009"] = {
		"sweeps past a Bluffwatcher on the rim, who follows the beast with an unhurried turn of the head and goes back to watching the plain.",
		"passes over a Bluffwatcher at the edge of the rise, who spares the wind rider one calm glance and returns to the more serious business of the horizon.",
		"is seen out of the city by a Bluffwatcher who doesn't trouble to raise a spear; whatever danger the sky may hold, it isn't this one.",
	},
	["thb.journey.w24.rimward.010"] = {
		"From this angle you can see how much each bridge sags in the middle. I'm glad nobody showed me this before I crossed them.",
		"Seen from the side, every span between the rises dips like a tired rope. Next time I cross them, I think, I'll do it faster.",
	},
	["thb.journey.w24.rimward.011"] = {
		"Somebody down there's waving. Or swatting a fly. Hard to say from here.",
		"Wave to the tents, beast. No? Fine. I'll do the waving.",
	},
	["thb.journey.w24.rimward.012"] = {
		"passes above the High Chieftain's great lodge, its hide roof broader than any other in the city, and from here smaller than a palm.",
		"looks down on the great lodge of the High Chieftain as the beast climbs, a wide pale roof among the others, with the plain already showing past its edge.",
	},
	["thb.journey.w24.rimward.013"] = {
		"A drum is still going somewhere on the rises behind me. I can't hear it anymore, but I can see the drummer's arms.",
		"I lose the sound of the city before I lose the sight of it. For a while it's like watching through thick glass.",
	},
	["thb.journey.w24.rimward.014"] = {
		"sees from above the paths worn pale across the tops of the rises, every one of them leading, sooner or later, to the edge.",
		"traces from above the pale tracks running from lodge to lodge on each rise, lines the feet of the city have drawn without meaning to.",
	},
	["thb.journey.w24.rimward.015"] = {
		"Higher than the tallest totem now. I feel I should apologize to someone.",
		"The totems spent my whole visit looking down at me. Now I'm looking down at them, and I'm too polite to enjoy it.",
		"Above the totems now, which feels a little like stepping over someone's legs.",
	},
	["thb.journey.w24.rimward.016"] = {
		"From this height the Horde down there is one crowd: tauren, orc, troll, Forsaken, all the same size, all going about their errands.",
		"Up here nobody below has a race. Just small shapes on the rises, every one of them ours.",
	},
	["thb.journey.w24.rimward.017"] = {
		"spots, laid flat on the ground of a rise below, a half-woven blanket pegged out in the open, a square of red and ochre no bigger than a fingernail from here.",
		"picks out the small colored squares of blankets spread on the rises below, bright among the pale hides like beads on a sleeve.",
	},
	["thb.journey.w24.rimward.018"] = {
		"flies over a tauren carrying two dripping waterskins along the rim, who sets them down to watch the wind rider pass and lifts them only when it is gone.",
		"passes an elder on a bench at the rim, who follows the beast across the whole sky with one slow turn of the head, never hurrying even that.",
	},
	["thb.journey.w24.rimward.019"] = {
		"There's the inn. Somebody's still eating. Of course somebody's still eating.",
		"Look, the lift's going down without me. Shame.",
	},
	["thb.journey.w24.roost.001"] = {
		"sees the roost master step back only once the beast's claws leave the boards, then turn at once to the next wind rider, as if the departure were already old news.",
		"glances back to find the roost master already brushing out another beast's mane; in that patient mind, this flight ended the moment it began.",
	},
	["thb.journey.w24.roost.002"] = {
		"The roost master spoke to the beast the way the elders speak to a calf: slow, low, sure it understood every word. I think it did.",
		"Before letting us go, the roost master looked a long while into the beast's eyes, the way a herder reads the sky. Apparently it read fine.",
	},
	["thb.journey.w24.roost.003"] = {
		"settles {g:his|her} great weight forward over the beast's shoulders as the roost falls behind, and the wind rider, used to tauren, does not even grunt.",
		"lies low along the beast's neck with horns tucked, as the roost master taught, to give the wings their room.",
	},
	["thb.journey.w24.roost.004"] = {
		"I said I was ready. The beast waited until it was ready, which was a different moment entirely.",
		"Somebody on this roost decides when we leave, and it isn't the one who paid.",
		"We go when the beast says so. All I contribute to the decision is the weight in the saddle.",
	},
	["thb.journey.w24.roost.005"] = {
		"pulls away to the low grumbling of the beasts still on their perches, every head turning to watch one of their own go out.",
		"goes out past a row of resting wind riders, who lift their heads in turn as the beast passes and then tuck them away.",
	},
	["thb.journey.w24.roost.006"] = {
		"I'll bring this one back in one piece. Or it'll bring me.",
		"Thanks for the loan of the beast. I'll return it with the same number of teeth.",
	},
	["thb.journey.w24.roost.007"] = {
		"Musk, old straw, oiled leather: the roost smell rides out with me for a while. It thins with every stroke until only the beast is left.",
		"Straw dust and animal musk cling to the saddle as we pull away. Up here it's the last of the city I'll smell.",
	},
	["thb.journey.w24.roost.008"] = {
		"leaves a small whirl of straw behind on the roost, and the roost master, without a word, reaches for the broom.",
		"lifts away in a scatter of straw from the perch, while a broom is already at work on the platform behind.",
		"kicks up a puff of straw and dust from the platform at the first stroke, and somebody behind sneezes.",
	},
	["thb.journey.w24.roost.009"] = {
		"As our elders do before a road, the roost master touched the beast's brow and then mine. I carry the warmth of that hand out over the edge.",
		"A touch on the beast's brow, a touch on mine, the old way. Then the planks are gone and only the hand's warmth stays.",
	},
	["thb.journey.w24.roost.010"] = {
		"rises under the gaze of a small tauren calf at the foot of the roost, who follows the beast's whole climb with an open mouth.",
		"climbs past a young tauren peering up from beside the roost, eyes wide, counting the wingbeats out loud.",
	},
	["thb.journey.w24.roost.011"] = {
		"No words at the roost, just a nod from the master and a nod back. In this city that counts as a long farewell.",
		"One nod as I took the reins, and that was all. Up here nobody spends words on what a nod can carry.",
	},
	["thb.journey.w24.roost.012"] = {
		"climbs down and watches the roost master work a wooden comb through the beast's mane, slowly, from the crown to the shoulders, without hurry.",
		"leaves the beast to the roost master, who has a bone comb out before the wings are even folded and begins on the tangles the sky put there.",
		"lingers by the perch as the beast's mane is combed out, the roost master humming low and easing each knot loose.",
	},
	["thb.journey.w24.roost.013"] = {
		"has hardly stepped down when the wind rider pulls toward the water trough at the edge of the roost and drinks with long, loud, unashamed laps.",
		"barely has both feet on the planks before the beast is at the trough, lapping like a great cat and spilling half of it over the boards.",
	},
	["thb.journey.w24.roost.014"] = {
		"The roost master counts the beasts home the way a herder counts kodo: by eye, without numbers. Mine is counted. So, I suppose, am I.",
		"One long look from the roost master takes in the beast, like a herder's at the end of a drive. We both pass, it seems.",
	},
	["thb.journey.w24.roost.015"] = {
		"Flew like a dream. Grumbled like a grandmother, but flew like a dream.",
		"Good beast, this one. Give it something nice.",
		"Not a single complaint about the flier. The flier may have a few about me.",
	},
	["thb.journey.w24.roost.016"] = {
		"steps off onto the roost among the resting wind riders, one of which opens a single heavy-lidded eye, judges the arrivals, and shuts it.",
		"touches down to a stir along the perches, the other beasts lifting their muzzles to sniff the air the flight brought in before settling back.",
	},
	["thb.journey.w24.roost.017"] = {
		"I know the spot behind a wind rider's ear that makes it lean in. Half a minute of scratching there, and we're friends till the next flight.",
		"A good scratch under the jaw after landing, and the beast leans its whole heavy head into my hand. Worth more than any tip.",
		"The beast pushes its nose against my shoulder as I step away. I'll call that a thank-you and not think too hard about the teeth.",
	},
	["thb.journey.w24.roost.018"] = {
		"stands aside as the roost master rubs a pungent salve into the joints of the beast's wings, working it in with both thumbs while the wind rider rumbles.",
		"smells the salve before seeing it: the roost master is already working a sharp-scented grease into the wing joints, and the beast half closes its eyes.",
	},
	["thb.journey.w24.roost.019"] = {
		"One look from the beast as I step clear: not fond, not hostile. The look a kodo gives a fence post.",
		"I'd like to think the beast will remember me. The way it turns its back on me says otherwise.",
	},
	["thb.journey.w24.roost.020"] = {
		"comes down onto boards scored by claws past counting, the newest scratches still pale where the beast just gripped.",
		"walks off across a landing floor gouged with claw marks, old ones gone dark and smooth, a fresh set bright beside them.",
		"crosses the roost on planks rubbed smooth in a path from the perches to the steps, worn there by every rider who ever climbed down.",
	},
	["thb.journey.w24.roost.021"] = {
		"comes down at dawn as the first light runs level across the plain and turns the edges of the beast's spread wings red.",
		"drops onto a roost still chill and damp at dawn, the planks dark and the claw prints left pale behind.",
	},
	["thb.journey.w24.roost.022"] = {
		"In our own tongue, low and plain, the roost master greets me, and the flight slides off my shoulders. I'm among my people.",
		"A word of welcome from the roost master in the shu'halo way, and the planks feel like the floor of my own lodge.",
	},
	["thb.journey.w24.roost.023"] = {
		"slides off as the beast lets out an enormous yawn, every tooth on show, and takes one prudent step to the side before saying thanks.",
		"gets down in time to catch the wind rider's yawn at close range: a long pink cave of teeth, offered without malice and declined with respect.",
	},
	["thb.journey.w24.roost.024"] = {
		"Here's your beast back. Treated it like family. Better, honestly.",
		"Returned with all its wings. Both of them. I checked.",
	},
	["thb.journey.w24.roost.025"] = {
		"Already the roost master is leading my beast to the perch, and someone else is waiting with a saddle. A flight ends up here the way a wave ends on a shore.",
		"By the time I reach the steps, my beast is someone else's. That's the way of a roost: nothing waits long for you.",
	},
	["thb.journey.w24.roost.026"] = {
		"climbs off the beast past a Forsaken waiting for the next flight, who studies the landing with the flat attention of someone weighing the odds.",
		"hands over the reins while an orc next in line eyes the beast's teeth with open suspicion and keeps a careful distance.",
	},
	["thb.journey.w24.saddle.001"] = {
		"rides out past the edge on a saddle blanket woven in tauren stripes, its fringe snapping as the beast finds the air.",
		"parts from the roost on a striped blanket of tauren weaving, folded thick under the saddle; its tassels stream back in the first rush of flight.",
	},
	["thb.journey.w24.saddle.002"] = {
		"This saddle was cut with a tauren in mind. I sit in the middle of it like a pea in a bowl and hope the straps understand the difference.",
		"Room in this saddle for me and a spare. Tauren saddles don't come any smaller, apparently, so I hold on harder.",
	},
	["thb.journey.w24.saddle.003"] = {
		"rocks gently to the creak of the saddle as the flight evens out, the leather complaining in time with the wings.",
		"settles into the saddle's long creak, one groan of leather for every stroke, as the city slides off behind.",
	},
	["thb.journey.w24.saddle.004"] = {
		"I always mean to leave looking dignified. Then the beast jumps, and dignity stays on the roost with my good intentions.",
		"My dignity is lying on that roost back there. I'll collect it next time I'm through.",
	},
	["thb.journey.w24.saddle.005"] = {
		"This saddle and I are going to have words.",
		"Somebody pad this saddle. Next time. Please.",
		"Ah. The saddle remembers me. Fondly, I hope.",
	},
	["thb.journey.w24.saddle.006"] = {
		"The beast is warm under the saddle and the air is not. I lean down closer to it, and it doesn't seem to mind.",
		"Cold on the face, warmth coming up through the saddle. I sit between the two and let the city go.",
	},
	["thb.journey.w24.saddle.007"] = {
		"straightens in the saddle once the beast has climbed clear of the roost, and lets go of the reins with one hand to feel the open air run through the fingers.",
		"sits up in the saddle as the climb levels out, one hand loose on the reins, the other held out flat into the rushing air.",
	},
	["thb.journey.w24.saddle.008"] = {
		"loses a stirrup in the first lurch off the roost, fishes for it with one boot over a very long drop, and finds it at last with great dignity.",
		"kicks about for a lost stirrup as the beast swings away from the platform, and hooks it again just as the roost master looks up.",
	},
	["thb.journey.w24.saddle.009"] = {
		"Saddlebags buckled, nothing loose, nothing dangling. Whatever slips off up here takes far too long to reach the bottom for my liking.",
		"I count the bags once more by touch as we pull away. Whatever I forgot is on the roost now, and it can stay there.",
	},
	["thb.journey.w24.saddle.010"] = {
		"gets down from the saddle after the long flight walking like someone who has just learned what legs are for, and has doubts.",
		"dismounts after the long flight and stands bow-legged on the planks, waiting for the shape of the saddle to leave {g:his|her} knees.",
	},
	["thb.journey.w24.saddle.011"] = {
		"A flight that long, and the saddle has printed its whole map on me. I'll be reading it for an hour.",
		"Long enough in the air that the saddle and I came to an arrangement. It won. I'll limp to the inn to discuss terms.",
	},
	["thb.journey.w24.saddle.012"] = {
		"swings a leg over the saddle to dismount, catches a boot in the stirrup, and completes the move in two stages, the second one hopping.",
		"slides down the beast's flank faster than intended and comes down in a crouch, then rises as though the crouch had been the plan.",
	},
	["thb.journey.w24.saddle.013"] = {
		"The saddle is still warm when I step away from it. For a moment I almost climb back up, just to keep being nowhere a little longer.",
		"I miss it as soon as my feet touch the planks: the saddle, the straps, the sky that asked nothing of me.",
		"The sky had me for a while, and now the planks have me back. I stand quite still a moment, not ready to be ordinary.",
	},
	["thb.journey.w24.saddle.014"] = {
		"I'll walk from here. Possibly forever.",
		"Somebody take this saddle off me. I mean off my memory.",
		"Feet down. Saddle, you and I are done for now.",
	},
	["thb.journey.w24.saddle.015"] = {
		"watches the striped saddle blanket come off the beast and get shaken out over the edge of the roost, a small cloud of hair and dust drifting off below.",
		"stands back as the roost master snaps the saddle blanket out over the drop, once, twice, sending a puff of shed hair away toward the plain.",
	},
	["thb.journey.w24.saddle.016"] = {
		"First thing off the saddle: count the bags. All there. The sky took nothing this time but a little of my composure.",
		"Bags, all of them, still buckled. Pockets, still full. The only thing I've lost up there is the feeling in my toes.",
	},
	["thb.journey.w24.saddle.017"] = {
		"gives the saddle a grateful pat on the way off, realizes it is patting the leather and not the beast, and pats the beast as well, to be fair.",
		"pats the empty saddle once on reaching the planks, then, catching the beast's look, pats the beast too.",
	},
	["thb.journey.w24.touchdown.001"] = {
		"feels the wind rider's claws find the planks of the roost with a dragging scrape, then a thump that travels all the way up {g:his|her} spine.",
		"comes down hard enough that {g:his|her} teeth click together, and the roost timbers grumble under the weight of beast and rider.",
		"lands with a jolt that rattles every buckle on the saddle at once, a small chorus of metal on the quiet roost.",
	},
	["thb.journey.w24.touchdown.002"] = {
		"The wind rider landed like a cat on a fence: all four feet, no fuss, and a look back at me as if to ask why I was holding on so tight.",
		"Four paws down at once, neat as anything. I'm the only one on this roost who flinched.",
	},
	["thb.journey.w24.touchdown.003"] = {
		"touches down among the resting wind riders, and one of them lifts its head, looks the pair over, and goes back to sleep.",
		"lands among the roost's other beasts; a few heads come up, a tail flicks, and one of them yawns wide enough to show every tooth.",
	},
	["thb.journey.w24.touchdown.004"] = {
		"The roost smells of wind rider, which is to say of wet dog, old leather and something I'd rather not name. The rest of the city smells better. I'm walking toward it.",
		"Like every roost, this one smells of beast, straw and leather. This one, at least, has cooking on the next gust.",
	},
	["thb.journey.w24.touchdown.005"] = {
		"lands in a little cloud of dust and loose straw, and the roost master, unhurried, waits for it to settle before saying a single word.",
		"sets down with a puff of grit off the planks; the keeper of the roost lets it drift past, blinks once, and only then steps forward.",
	},
	["thb.journey.w24.touchdown.006"] = {
		"Gently, gently. These planks are older than both of us.",
		"Easy on the roost, beast. Somebody had to carry those timbers up here.",
	},
	["thb.journey.w24.touchdown.007"] = {
		"is still in the saddle when the wind rider shakes itself from mane to tail like a dog out of a pond, and {g:he|she} has to ride that out too.",
		"gets one last jolt before dismounting: the beast shudders its whole hide, end to end, shedding the flight off itself with the rider still aboard.",
	},
	["thb.journey.w24.touchdown.008"] = {
		"There's a moment, just before the claws touch, when the whole city tilts up to meet us. I've decided to enjoy that moment instead of fearing it.",
		"In the last stretch the roost seems to rush up rather than us down. Then it stops, and so do we, and the city is just a city.",
	},
	["thb.journey.w24.touchdown.009"] = {
		"lands on the roost and feels the whole platform settle a finger's width under the weight, then hold, the way good timber does.",
		"comes down on planks that give a little, creak once, and take the weight without complaint.",
	},
	["thb.journey.w24.touchdown.010"] = {
		"Down, and all my pieces with me. Good.",
		"Landed. Nothing dropped, nothing lost, nothing broken.",
		"That'll do. Feet on the planks, everything where I left it.",
	},
	["thb.journey.w24.touchdown.011"] = {
		"I keep a hand on the beast's neck a moment after landing. It's warm, and it's tired, and it brought me here without a single complaint, which is more than I can say for myself.",
		"Before I climb down I rest my palm on the wind rider's neck. It's earned that much, and it doesn't seem to mind.",
	},
	["thb.journey.w24.touchdown.012"] = {
		"touches down at the end of the long flight and stays bent over the saddle horn for a while, as if the flight were not quite finished with {g:him|her}.",
		"sets down after the long haul across the sky and sits a moment longer than needed, reins slack, before swinging a stiff leg over.",
	},
	["thb.journey.w24.touchdown.013"] = {
		"A flight that long folds you into the shape of the saddle. It takes four or five steps across the roost to unfold.",
		"My knees have opinions about that flight, and they're sharing them all at once.",
	},
	["thb.journey.w24.touchdown.014"] = {
		"All that way and you never once stopped. I'd buy you a drink if they made cups your size.",
		"That long in the saddle, and my legs have stopped speaking to me.",
	},
	["thb.journey.w24.touchdown.015"] = {
		"feels the beast land hind feet first, then the forepaws, a rocking two-step that pitches {g:him|her} forward against the saddle.",
		"is rocked forward as the wind rider sets its back paws down and then its front, like someone stepping off a boat in two halves.",
		"rides out the double jolt of the landing, rear then front, and ends up with {g:his|her} chin nearly in the beast's mane.",
	},
	["thb.journey.w24.touchdown.016"] = {
		"I'd like to call that a dismount. It was more of a slide, with a small noise at the end.",
		"Graceful, I told myself. My feet, the saddle and the roost all had other plans.",
		"There's a way to climb off a wind rider with dignity. Nobody has shown it to me yet.",
	},
	["thb.journey.w24.touchdown.017"] = {
		"Lovely. Truly. Only one of us yelled, and it wasn't you.",
		"Neatly done. I'll tell everyone you only tried to throw me once.",
		"Down we are. Remind me to thank you properly when my knees stop shaking.",
	},
	["thb.journey.w24.touchdown.018"] = {
		"I always close my eyes for the last few wingbeats. I open them on planks, every time, and every time I'm a little surprised.",
		"The final drop is the part I never get used to: the city coming up too fast, the beast flaring at the last instant. Then the bump, and I can unclench.",
		"My hands only let go of the harness once the claws have touched. I've stopped being ashamed of that.",
	},
	["thb.journey.w24.wingbeat.001"] = {
		"feels the first downstroke press the saddle up hard into {g:him|her}, and the roost is a long way below before the second one comes.",
		"is shoved upward by the first great beat of the wings, the saddle rising like a step underfoot, and the planks are gone from view.",
		"rises in three hard heaves of the wings, each one pushing the saddle up like a shoulder from below.",
	},
	["thb.journey.w24.wingbeat.002"] = {
		"The wings settle into their stroke: down, a long glide, down again. After the third one my shoulders stop waiting for the fall.",
		"Down, glide, down. The rhythm finds me before I find it, and somewhere in the second minute I unclench.",
	},
	["thb.journey.w24.wingbeat.003"] = {
		"Flap, beast. That's it. Keep doing the thing with the wings.",
		"Lovely flapping. Really. Don't stop to take a bow.",
		"More wing, less wobble, if it's all the same to you.",
	},
	["thb.journey.w24.wingbeat.004"] = {
		"listens to the wings at work above the saddle, a sound like a heavy hide being shaken out, over and over.",
		"hears each wingbeat as a dull thump of leather on air, felt as much through the saddle as through the ears.",
	},
	["thb.journey.w24.wingbeat.005"] = {
		"The beast went up. Some part of me stayed on the roost a moment longer and is only now catching up.",
		"Up goes the wind rider, up go I, and my insides follow along at their own pace, protesting.",
		"There's always one stroke where the beast sinks a little before it climbs. My knees know it's coming. My knees never believe it.",
	},
	["thb.journey.w24.wingbeat.006"] = {
		"tilts with the beast as it banks away from the roost, one wing pointing down at the planks, the other at nothing at all.",
		"leans into the turn as the wind rider dips a wing over the platform's corner and swings out, the whole world tipping with it.",
	},
	["thb.journey.w24.wingbeat.007"] = {
		"For a beat between two wingstrokes nothing holds me but straps and an animal's will. It's the most honest moment of any flight.",
		"Between one stroke and the next there is a little drop, every time. I've stopped fearing it. I think I'd miss it.",
	},
	["thb.journey.w24.wingbeat.008"] = {
		"draws level with a hawk riding the air off the roost; the hawk looks at the wind rider, thinks better of it, and slides away.",
		"climbs past a hawk hanging still beside the roost, and the hawk, after one look at the beast's teeth, finds somewhere else to hang.",
	},
	["thb.journey.w24.wingbeat.009"] = {
		"goes out into the night with the roost lantern swinging behind, its little light caught for a moment in the wet gleam of the beast's eye.",
		"feels the beast climb through the night by touch alone: the stretch of its shoulders under the saddle, the pull of the straps, a cold rush past the ears.",
	},
	["thb.journey.w24.wingbeat.010"] = {
		"Into the fog, and the beast flies as if it could see straight through it. I decide to believe it can.",
		"White on every side the moment we clear the roost. The wings keep their beat, unbothered; one of us knows what it's doing.",
	},
	["thb.journey.w24.wingbeat.011"] = {
		"On the roost the beast was all grumble and claws. Out here it stretches every part of itself at once, and I understand: the perch was the waiting, and this is the living.",
		"A wind rider on a perch is a sulking thing. A wind rider leaving one is something else: long, loose, glad. I feel the change through the straps.",
	},
	["thb.journey.w24.wingbeat.012"] = {
		"Go on, then. Take us up.",
		"Higher, beast. Let's see what's above all this.",
		"Up! Up, and show me the sky.",
	},
	["thb.journey.w24.wingbeat.013"] = {
		"notes the wingbeats change on the way in, from long pulls to short hard cups of air, and then the claws find the planks.",
		"hears the beat of the wings go short and heavy at the end, each stroke holding the beast back, until the roost is solid underneath.",
		"is braked by three short, heavy strokes, each one rocking the saddle back, and then comes the jolt of claws on wood.",
	},
	["thb.journey.w24.wingbeat.014"] = {
		"Off the beast, and my body is still counting wingbeats. It'll be a while before it loses count.",
		"I'm standing still and something in me goes on rising and falling with the stroke. It fades slowly, like a tune after the drummer stops.",
	},
	["thb.journey.w24.wingbeat.015"] = {
		"That last bit, with the dropping? We'll discuss it.",
		"Lovely flight. The ending needs work.",
		"I've fallen out of bed more gently than that.",
	},
	["thb.journey.w24.wingbeat.016"] = {
		"steps down with {g:his|her} hair standing every way the sky pushed it, and makes a few passes at it with one hand, to no effect.",
		"climbs off looking thoroughly combed by the sky in the wrong direction, and tries to pat things flat before anyone looks.",
		"pulls a stray piece of straw from {g:his|her} collar after dismounting, and wonders at what point in the flight it got there.",
	},
	["thb.journey.w24.wingbeat.017"] = {
		"Down now, and the flight already feels like something told to me rather than done: the cold, the pull of the wings, the long lean into the turns.",
		"On the planks the whole flight shrinks to a few things my body kept: a lean, a lurch, the long pull of the wings under me.",
	},
	["thb.journey.w24.wingbeat.018"] = {
		"works a finger into one ear on reaching the planks, the roar of the flight still packed in there like wool.",
		"shakes {g:his|her} head on the roost to clear the hum the flight left in both ears, and the hum, stubborn, stays.",
		"tilts {g:his|her} head one way and then the other, trying to shake loose the deafness the flight stuffed into each ear.",
	},
	["thb.journey.w24.wingbeat.019"] = {
		"comes in on a long glide with the beast's wings held stiff and still, the roost growing under them without a single stroke until the very end.",
		"rides the last slope of air in with the wings locked wide and silent, and the planks of the roost rise to meet the claws.",
	},
	["thb.journey.w24.wingbeat.020"] = {
		"The moment before the claws touch is the one I never get used to: the roost rushing up, the beast trusting itself, and me trusting the beast.",
		"Every arrival, that last rush of planks toward my face. Then a thump, and I'm a person standing on a roost as if nothing happened.",
	},
	["thb.journey.w24.wingbeat.021"] = {
		"Coming in under a high sun, I watched our shadow race across the rise ahead and grow to meet us. Then we were standing on it.",
		"Our shadow climbed the side of the mesa ahead of us and was waiting on the roost. The beast came down right on top of it.",
	},
	["thb.journey.w24.wingbeat.022"] = {
		"watches the beast's tail come slowly down from its high arc once the claws are on the planks, the barb laid along the boards like a tool put away.",
		"notices how the wind rider's tail only lowers once all four paws are planted, uncurling from its flying arc to rest along the roost.",
	},
	["thb.journey.w24.wingbeat.023"] = {
		"We're down? We're down. I'll open my eyes now.",
		"Stopped? Good. Somebody tell my knees.",
		"You can stop flapping, beast. We're on the planks. Rest those wings.",
	},
	["thb.muse.w24.ancestor.001"] = {
		"The tauren name their dead in the middle of ordinary talk, between the price of a hide and the state of the lift ropes, as if the dead might have an opinion on both.",
		"A tauren just mentioned her great-grandmother in the same sentence as the price of salt. On this bluff the dead are part of the conversation.",
		"Ask a tauren what the sky will do and you may hear what a grandfather thought of it, forty winters gone. The dead keep their seat at the talk.",
	},
	["thb.muse.w24.ancestor.002"] = {
		"notices an old tauren fill a second, smaller bowl beside his own and leave it untouched through the whole meal, as if someone late were expected.",
		"sees an elder set the choicest morsel of his meal on the bench beside him, where nobody sits, and go on eating without a glance at it.",
		"pauses where an old tauren, finishing a meal, pushes an untouched portion a little further along the bench, toward nobody, and nods.",
	},
	["thb.muse.w24.ancestor.003"] = {
		"Beside me, a tauren retied a knot three times, muttering an apology each time to a grandfather who, I gather, was very particular about knots and has been dead for years.",
		"I heard a tauren say sorry to his late uncle for a crooked stitch. The uncle, I'm told, would have noticed. Apparently he still does.",
		"Somewhere on this rise a long-dead aunt is very disappointed in a basket. Her niece has told everyone, and is weaving it over.",
	},
	["thb.muse.w24.ancestor.004"] = {
		"Is that empty seat taken? By an ancestor, I mean. I'd hate to sit on anyone's grandmother.",
		"I'll stand, thanks. In this city an empty seat is rarely as empty as it looks.",
		"Mind if I sit? Living or otherwise, whoever's there, say so now.",
	},
	["thb.muse.w24.ancestor.005"] = {
		"An elder told me some of the tauren who fell to the centaur on the old plains were never found. Their names are spoken here instead, so they still have somewhere to come to.",
		"Not every ancestor has a resting place. The elders say a name said aloud is a resting place too, and they say a great many of them.",
		"Somewhere out in the Barrens lie tauren no one buried. On this bluff, I'm told, their names are kept warm instead, said beside the fire so they are never quite out in the cold.",
	},
	["thb.muse.w24.ancestor.006"] = {
		"A hunter told me the ancestors still follow the herds across Mulgore, out of old habit. When the kodo turn all at once for no reason, she says, someone very old is walking among them.",
		"The old ones never quite stopped wandering, according to the hunters. They walk with the herds still, which is why nobody up here would dream of hurrying a kodo.",
		"One hunter swears a kodo once turned its head toward nothing and bowed. 'Grandfather,' she said, as if that settled it. For her, it did.",
	},
	["thb.muse.w24.ancestor.007"] = {
		"catches a young tauren asking something of the empty air at the edge of the rise, waiting with head tilted, and nodding as if the answer had been fair.",
		"passes a calf speaking earnestly to nobody beside a lodge, then pausing, listening, and running off satisfied.",
		"smiles as a calf sets out two cups for a game of stones, one for itself and one for a player nobody else can see.",
	},
	["thb.muse.w24.ancestor.008"] = {
		"Those who came before me crossed the open plains with the centaur at their backs. I stand on stone they never saw, and I keep it for them.",
		"When I cross these bridges I cross them for the ancestors as well. They walked far enough. Let them be carried a while.",
	},
	["thb.muse.w24.ancestor.009"] = {
		"Two tauren are arguing over a hide, and both have called on the same dead elder as a witness. He seems to be taking his time deciding.",
		"Sooner or later in any quarrel up here, somebody calls on an ancestor. The other side always has one too. It ends in a draw and a long silence.",
		"I've learned that a tauren who starts a sentence with a dead grandfather's name has already won the argument, or thinks so.",
	},
	["thb.muse.w24.ancestor.010"] = {
		"Such tenderness when the tauren speak of their dead. I am dead, more or less, and nobody here talks to me in that voice. Still, nobody has looked away either.",
		"They honor the spirits of the dead up here and set food aside for them. I'm a corpse walking in plain sight, and they simply pass me the salt.",
	},
	["thb.muse.w24.ancestor.011"] = {
		"pauses near a ring of elders here on Elder Rise, where one place in the circle is left open, and nobody needs to explain to anyone why.",
		"comes upon elders seated in a loose ring with a gap in it the width of one tauren, and the talk carefully walks around the gap.",
		"slows near the elders' circle, where the open place is never filled and even the passing calves, without being told, step around it.",
	},
	["thb.muse.w24.ancestor.012"] = {
		"An old tauren leans on a staff worn dark at the grip by more hands than his. He calls it his grandmothers' staff, plural, and explains nothing further.",
		"So many hands held that old tauren's staff before his that the wood has a waist. He says he is only borrowing it from them.",
		"The staff he leans on belonged to someone, who had it from someone else. The old tauren names them all if you ask. I asked. It took a while.",
	},
	["thb.muse.w24.ancestor.013"] = {
		"I'll keep my voice down. I've been told the old ones listen from the edges.",
		"Quietly, please. I'm told the ancestors sit nearest at the rim of the rise.",
	},
	["thb.muse.w24.ancestor.014"] = {
		"I've yet to hear a tauren say plainly that someone died. The old woman 'went down to the Earth Mother', the young hunter 'was taken back'. It sounds less like losing and more like lending.",
		"The dead, as the tauren put it, go down into the earth that raised them, not away. It's a gentler direction than most peoples give their dead.",
		"'Taken back,' they say of their dead, as of a borrowed blanket. The grief is the same, I think. It just has somewhere to go.",
	},
	["thb.muse.w24.ancestor.015"] = {
		"hears a name spoken at a nearby fire, and every tauren within earshot lowers their eyes for the length of it before the talk goes on.",
		"notices that whenever an old name comes up among the tauren at the next fire, each of them brushes the ground with two fingers, never pausing a word.",
	},
	["thb.muse.w24.ancestor.016"] = {
		"If the tauren ancestors truly watch over this city, they've seen me lose an argument with a tent flap. I hope they have the manners not to mention it.",
		"The elders say the ancestors see everything that happens on the bluff. Somewhere a very old spirit has watched me count my coins twice and pretend I hadn't.",
	},
	["thb.muse.w24.ancestor.017"] = {
		"An old tauren is teaching a calf the names of their line, one name per finger. Both hands ran out some time ago; now they're counting on the beads of a blanket.",
		"A grandfather has been reciting forebears to a sleepy calf since before I sat down, and the names show no sign of ending. Neither, to be fair, does the calf's yawn.",
		"Names, names and more names, rolling out of an elder for a drowsy little tauren to keep. I've lost count. I doubt the calf ever had it.",
	},
	["thb.muse.w24.ancestor.018"] = {
		"Pardon me, whoever's sitting there. I can't see you, but it seems rude to assume.",
		"Excuse me, honored spirit. Only passing through. I'll be quick and very polite.",
		"Mind your feet, I tell myself. Somebody's elder may be stretched out right here.",
	},
	["thb.muse.w24.ancestor.019"] = {
		"A tauren told me, quite plainly, that her late grandfather came to her in a dream to complain about the state of her roof. She's up on a ladder now with a fresh hide, looking relieved.",
		"The ancestors visit in dreams, the tauren say, and their advice is mostly practical. Mend the roof. Mind the river. Eat something. It sounds very much like being alive.",
	},
	["thb.muse.w24.ancestor.020"] = {
		"Tell me about them, if you like. Your old ones. I've time.",
		"Who was he, the one whose name you just said? I'd like to know, if it's mine to know.",
		"Say the name again, slowly. I'd like to remember it too.",
	},
	["thb.muse.w24.braid.001"] = {
		"Every tauren braid I've looked at closely is tied off differently: sinew, a twist of leather, a bead, a knot I can't follow. I've started reading them like signatures.",
		"No two braids on this bluff end the same way. A wrap of red thread, a little bone ring, a plain knot pulled tight. Each one would tell me something, if I knew how to ask.",
	},
	["thb.muse.w24.braid.002"] = {
		"watches a tauren pull burrs one by one from a friend's tail, both of them deep in talk about something else entirely, the friend flicking the tail only when a burr is stubborn.",
		"turns to see a tauren combing out her own mane with a comb cut from horn, working through the tangles with the frown of someone untangling a fishing net.",
	},
	["thb.muse.w24.braid.003"] = {
		"Horns change everything. I just watched a tauren come out of a lodge, turn her head sideways without thinking, and slide through the door like a key into a lock.",
		"Tauren turn their heads before every doorway the way other people duck. They do it without looking, the way you'd step over a stair you know is there.",
		"A tauren carrying a long pole over one shoulder turned to greet me and swept the pole and her horns aside together, with the practice of a lifetime.",
	},
	["thb.muse.w24.braid.004"] = {
		"Beads clack when a tauren nods. The more beads, the slower the nod, I've noticed. Maybe that's the point.",
		"An old tauren with a whole curtain of beaded braids came up the path, and I heard her before I saw her, a soft dry rattle like seeds in a gourd.",
		"A tauren on the bench is counting her beads with a thumb, one braid after another, like someone checking a purse.",
	},
	["thb.muse.w24.braid.005"] = {
		"stops while a tauren sits down on the planks, takes one hoof in both hands and pries a pebble out of it with a little bone pick, with the air of someone doing it for the thousandth time.",
		"glimpses a tauren cleaning the edge of a hoof with a flat knife, the way another would clean nails, then knocking it twice on the path to test it.",
		"follows a clatter to a tauren at a water trough, carefully washing the mud from each hoof in turn, like a cat tending its paws.",
	},
	["thb.muse.w24.braid.006"] = {
		"A tauren just shed a tuft of fur the size of a small cat onto the bench and walked off. The tuft is still sitting there. I don't know the etiquette.",
		"Somebody's left a tuft of mane on the bench that could stuff a pillow. I'm sitting next to it, politely.",
	},
	["thb.muse.w24.braid.007"] = {
		"The first braid a calf ties into its own mane is always crooked, and we leave it. Our elders say a crooked first braid means the hands were eager.",
		"I still tie my braids the way I was shown, with the twist at the end before the knot. Every tauren has a way like that, handed down, and never quite the same twice.",
	},
	["thb.muse.w24.braid.008"] = {
		"lingers by a tauren rubbing oil into the base of a friend's horns with slow circles of the thumb, the friend's eyes closed like a cat by a hearth.",
		"pauses by a tauren tying a strip of painted leather around one horn, checking the knot by feel, then nudging a companion to ask how it looks.",
	},
	["thb.muse.w24.braid.009"] = {
		"I was asked to hold a bead while a tauren rebraided. I've been holding it for some time. I'm beginning to think she forgot about it. I'm beginning to think I'll keep it.",
		"Got handed a little carved bead to hold while a tauren redid a braid. Now I'm the keeper of a bead. Nobody's mentioned it since.",
		"Someone dropped a bead on the planks and four tauren stopped to look for it. It was found, handed back, admired, and everyone went their way, satisfied.",
	},
	["thb.muse.w24.braid.010"] = {
		"I passed a tauren with one braid cut short and left bare among all the others. A Bluffwatcher told me, quietly, that it is done for someone gone. I didn't ask who.",
		"A single braid cut ragged at the end, the rest neat and beaded. I've learned enough here to stop asking about those.",
	},
	["thb.muse.w24.braid.011"] = {
		"Nice beads. No, really. I'd ask where you got them, but I suspect the answer is 'made them' and I'd feel lazy.",
		"That's a fine set of braids. Mine look like I slept on them, because I did.",
	},
	["thb.muse.w24.braid.012"] = {
		"Some of the older tauren have little marks cut into their horns, rows of tiny notches. One told me each is something to remember, and then said nothing about what any of them were.",
		"I've noticed lines carved into the horns of a few elders, fine as scratches. When I asked about them I was given a long look and a short answer: 'Mine.'",
	},
	["thb.muse.w24.braid.013"] = {
		"observes a tauren's tail swat a fly off a neighbor's back without either of them pausing in their talk, as if this were an old, settled arrangement.",
		"notices two tauren standing side by side, each idly flicking flies off the other with a tail, deep in conversation and plainly unaware of it.",
		"catches a tauren's tail lifting and settling at every pause in a long speech, keeping time with the thinking.",
	},
	["thb.muse.w24.braid.014"] = {
		"Tauren ears say more than their faces. The face stays calm through any argument; the ears go flat, swivel, flick. I've started watching the ears.",
		"A tauren's face will give you nothing in a bargain. The ears, though. The ears are terrible liars.",
		"When a tauren is listening to you properly, both ears turn your way and stay there. It's a little like being looked at twice.",
	},
	["thb.muse.w24.braid.015"] = {
		"Down here by the still water a tauren is rebraiding her mane by feel, slowly, in the half-dark. She never once looks at her reflection, though it's right there.",
		"In the quiet of the Pools a tauren kneels at the edge and touches the water to each horn, then to the brow. I don't know what it means, and I won't break the silence to ask.",
	},
	["thb.muse.w24.braid.016"] = {
		"I'd ask how you sleep with those horns, but I'm fairly sure the answer is 'soundly, thank you.'",
		"Every tauren in this city knows exactly where their horns are. I'm impressed, and slightly relieved.",
	},
	["thb.muse.w24.braid.017"] = {
		"An old tauren's mane has gone white at the roots and the ends, and the beads in it are worn smooth as river pebbles.",
		"Somebody braids that elder's mane for her now; I've seen the helper's careful fingers at it. The braids are perfect. She sits for them like a queen.",
	},
	["thb.muse.w24.braid.018"] = {
		"The bigger the tauren, the smaller the bead they seem to favor. The largest brave I've seen wears exactly one, tiny and blue, tucked behind an ear.",
		"One Bluffwatcher, built like a lodge, wears a single bright blue bead hidden in the mane. I've decided never to ask about it, so it can stay perfect.",
	},
	["thb.muse.w24.braid.019"] = {
		"Is that bead bone or wood? Don't tell me. I'll guess wrong in peace.",
		"Lovely knot. If I tried that I'd tie my own fingers into it.",
	},
	["thb.muse.w24.brave.001"] = {
		"passes a Bluffwatcher eating a strip of dried meat on watch, chewing slowly, eyes never once leaving the far end of the bridge.",
		"notices a Bluffwatcher shift weight from one hoof to the other, very slowly, the only movement in an hour of standing.",
		"sees a guard roll one great shoulder and settle, the motion so slight it might have been a tent hide stirring.",
	},
	["thb.muse.w24.brave.002"] = {
		"I've been trying to catch a Bluffwatcher blinking. I've lost.",
		"Someone must have taught the Bluffwatchers to stand that still. I'd like a word with that teacher about my own fidgeting.",
		"The Bluffwatchers move so little that birds land on them. I saw one with a sparrow on the haft of her halberd, and she let it stay.",
	},
	["thb.muse.w24.brave.003"] = {
		"The Bluffwatcher at the head of the path let a calf stand beside her for a while, copying her stance exactly, and never once broke it to smile. I think she was smiling anyway.",
		"A small tauren has planted itself next to a guard, chin up, shoulders back, a stick held just like the guard's halberd. The guard pretends not to notice, which is the kindest kind of noticing.",
	},
	["thb.muse.w24.brave.004"] = {
		"sees, in the first gray light, a Bluffwatcher come off the long post and sit down on the planks right there, horns lowered, as if the legs had been waiting hours for permission.",
		"notices the Bluffwatchers on the far rise stand a little easier as the light comes up, the long watch of the dark behind them.",
	},
	["thb.muse.w24.brave.005"] = {
		"Here on Hunter Rise a hunter is talking to her cat in a low voice, explaining something at length. The cat yawns at the end, and she nods as if that settled it.",
		"A hunter on this rise is combing burrs out of his wolf's coat with his fingers, one by one, while the wolf pretends to be above it all.",
		"On Hunter Rise a hunter has fallen asleep sitting up, and her great cat has fallen asleep across her hooves. Neither is going to be the first to move.",
	},
	["thb.muse.w24.brave.006"] = {
		"Tauren hunters can sit still longer than anything they hunt. I watched one wait out a fly that had landed on his nose. The fly gave up first.",
		"By the path sits a hunter who has had a moth on one horn for a good while. She hasn't brushed it off. I suspect she's practicing.",
		"Tauren hunters tell a story the way they track: one small detail, then silence, then another, until you realize you've been led a long way off.",
	},
	["thb.muse.w24.brave.007"] = {
		"The shamans I've seen up close are ordinary at the edges: one had ash under every fingernail and a crumb of flatbread in her mane, and talked about the price of salt.",
		"I expected the shamans to be solemn all the time. The one I passed was laughing so hard at something a friend said that she had to lean on a tent pole.",
	},
	["thb.muse.w24.brave.008"] = {
		"notices a shaman here on Spirit Rise sitting with her hooves in a basin of water, eyes closed, the very picture of someone who has done enough for one stretch.",
		"passes an old shaman on Spirit Rise asleep against a lodge pole with his chin on his chest, a pipe gone cold in one hand and the other still lifted, as if halfway through a blessing.",
	},
	["thb.muse.w24.brave.009"] = {
		"A druid came up the path still half a bear in the way she walked: rolling shoulders, head low, a sniff at every doorway. It took her a few steps to remember she had hands.",
		"Druids keep a little of the beast after they change back. One just scratched behind his ear with the side of his hand, very much like a cat, and looked faintly embarrassed.",
		"A druid on her way to Elder Rise stopped mid-step to sniff, ears forward, then shook herself and went on. The bear hadn't quite left.",
	},
	["thb.muse.w24.brave.010"] = {
		"That Bluffwatcher just looked at me for a whole second. I've straightened my collar and my life.",
		"One look from a Bluffwatcher and I've remembered every rule I never knew.",
	},
	["thb.muse.w24.brave.011"] = {
		"Hunters come up from the plain with grass seed caught in the hair of their legs, and the first thing they do is sit down without speaking. The talking comes later, with food.",
		"You can tell a hunter fresh from the grass: burrs in the tail, a long quiet stare, and a way of sitting down that is mostly falling.",
		"A hunter just up from the plain sat down on the bench beside me, nodded, and was asleep against the tent pole before the nod was quite done.",
	},
	["thb.muse.w24.brave.012"] = {
		"A young brave is having a long cut on her forearm stitched by an older one. She stares at the plain the whole time without a sound, and the older one talks about nothing to give her somewhere to go.",
		"Two braves sit apart from the rest, one with a fresh bandage. They aren't talking about whatever happened out there. They're talking about a recipe, carefully, as if it mattered very much.",
	},
	["thb.muse.w24.brave.013"] = {
		"ends up in a polite standoff with two Bluffwatchers on patrol: everyone steps aside at once, everyone waits, until one guard rumbles a laugh and goes first.",
		"meets a Bluffwatcher at a narrow turn of the path, and each waits for the other with such courtesy that a calf finally squeezes past between them.",
		"shares a narrow stretch of path with a Bluffwatcher who simply stops, turns sideways and waits like a cliff face until the way is clear.",
	},
	["thb.muse.w24.brave.014"] = {
		"When the Bluffwatchers go down to the war in Ashenvale, they go without speeches. A nod to the ones staying, and that's all. I'd stand beside any of them.",
		"Our braves don't boast. The ones heading out for the front just check their straps a second time and go. The Horde could use more of that.",
	},
	["thb.muse.w24.brave.015"] = {
		"A hunter mending his bowstring by the path offered me the other end to hold without asking. We stood there a while, joined by a bit of gut, saying nothing.",
		"Held a hunter's cat still for her while she checked its paw. It will forgive me eventually, I think. The cat, I mean.",
	},
	["thb.muse.w24.brave.016"] = {
		"Before eating, the hunter at the next fire set a small piece aside on a flat stone. A friend of hers told me it's for the animal, so it knows it wasn't wasted.",
		"I saw a hunter press his palm to the ground before he cut into his catch. When I asked, he said only that the plains should know he was grateful.",
	},
	["thb.muse.w24.brave.017"] = {
		"I'd ask the guard how the watch is going, but I'm fairly sure the answer would last until the next watch.",
		"Don't mind me, I'm only admiring how still you stand. Carry on. Or don't move. Whichever.",
	},
	["thb.muse.w24.brave.018"] = {
		"In the fog a Bluffwatcher appears at the far end of the bridge a piece at a time: horns first, then shoulders, then the slow hooves, like a mesa coming out of the mist.",
		"The fog has swallowed the next rise, but I can hear the guard over there clearing his throat every so often, as if to tell the city he's still at his post.",
	},
	["thb.muse.w24.brave.019"] = {
		"Those Bluffwatchers could hold a bridge against a stampede. Probably have.",
		"If I ever need a door held shut, I know which rise to ask on.",
	},
	["thb.muse.w24.cairne.001"] = {
		"The High Chieftain's habits are all over this city. Tauren here end their arguments the way he is said to, by waiting until both sides run out of words.",
		"You can learn a leader from the people he leads. Up here everyone listens to the end of a sentence, and they tell me the High Chieftain started it.",
	},
	["thb.muse.w24.cairne.002"] = {
		"hears a tauren settle a quarrel between two calves with a single question, what the High Chieftain would say, and the quarrel simply stops.",
		"overhears an elder end a squabble among young tauren by mentioning the High Chieftain's name, gently, and nothing more.",
		"sees two grown tauren in the middle of an argument both fall silent when one mentions the Chieftain, then laugh and start over more gently.",
	},
	["thb.muse.w24.cairne.003"] = {
		"The story goes that Cairne met Thrall when the orcs were new to Kalimdor, and the old bull and the young Warchief understood each other at once. Half the Horde seems to rest on that friendship.",
		"An old tauren and a young orc, meeting on hard ground, and from that meeting a whole alliance. The tauren tell it plainly, the way you'd tell how a well was found.",
	},
	["thb.muse.w24.cairne.004"] = {
		"Ask a tauren about the High Chieftain and you get a long silence first. I think that's the respectful part.",
		"Asked about the old Chieftain. Got a nod, a pause, and a single word: old. Then a smile, as if that covered everything.",
		"Every tauren I ask about their chieftain answers the same way: slowly, and with pride.",
	},
	["thb.muse.w24.cairne.005"] = {
		"The High Chieftain united tribes that had wandered apart for generations. Getting tauren to agree on a campsite is hard enough; I can't picture talking them into a city.",
		"One old bull convinced every stubborn tribe on the plains to share a set of cliffs. Whatever else he is, he's the best negotiator in Kalimdor.",
	},
	["thb.muse.w24.cairne.006"] = {
		"Everyone knows the High Chieftain is old. Nobody says it twice. The city has a way of talking around the years he has left.",
		"Their chieftain's age is a thing the tauren step around, the way you step around a sleeping hound: carefully, and without ever pointing at it.",
		"No one here wants to count the High Chieftain's remaining winters. They count everything else instead.",
	},
	["thb.muse.w24.cairne.007"] = {
		"Tauren who walk past the High Chieftain's great lodge lower their voices without breaking stride. I've seen it more than once, and none of them seemed to know they did it.",
		"Near the Chieftain's lodge the talk drops by half, all by itself. Nobody is asked to be quiet. They just are.",
	},
	["thb.muse.w24.cairne.008"] = {
		"Our High Chieftain gave the tribes one place to stand together. Each time I look out from here I owe him a little more, and he would wave the debt away.",
		"My people stopped wandering because one old bull told them they could. I hope he knows what that meant to us.",
		"The Chieftain gave his word to the tribes, and the word turned to stone. I walk on it, and it holds.",
	},
	["thb.muse.w24.cairne.009"] = {
		"Even the Bluffwatchers stand a little taller when the High Chieftain's name comes up. I tested it twice. It works.",
		"Mention the old Chieftain within earshot of a guard and watch the spine straighten. It's better than a salute.",
	},
	["thb.muse.w24.cairne.010"] = {
		"In the city they say the High Chieftain still goes down to the plain now and then to walk in the grass with nobody beside him. I like a leader who keeps his hooves dirty.",
		"According to the tauren, their chieftain still likes the plain better than the bluff. A leader who misses the grass: that explains a great deal about this city.",
	},
	["thb.muse.w24.cairne.011"] = {
		"sees a young brave practicing a solemn stance, chin high, hooves planted, and an elder nearby muttering that the Chieftain never stood like that in his life.",
		"watches a young tauren imitate the High Chieftain's slow nod for a pair of friends, and an older one pass by and do it much better without trying.",
	},
	["thb.muse.w24.cairne.012"] = {
		"The elders say the High Chieftain fought centaur, demons and doubt to bring the tribes here, and that the doubt was the hardest of the three.",
		"Centaur behind them, demons in the forests, and a hundred tribal quarrels in between. Whatever the old Chieftain carried to these bluffs, it was heavy.",
	},
	["thb.muse.w24.cairne.013"] = {
		"May the High Chieftain keep his years and his patience, both.",
		"Long may the old Chieftain stand, and long may he keep everyone else waiting.",
		"To the High Chieftain, and to many more slow years.",
	},
	["thb.muse.w24.cairne.014"] = {
		"The High Chieftain's own name is on a village down on the plain, Bloodhoof, and the tauren say the city never made him forget it. A leader with one hoof on the bluff and one in the grass.",
		"A chieftain with a capital in the sky and a village in the grass. From what the tauren say, he has never quite chosen between them, and doesn't intend to.",
	},
	["thb.muse.w24.cairne.015"] = {
		"notices that the tauren pause, very briefly, whenever they speak the High Chieftain's name, as if setting it down somewhere careful before going on.",
		"watches an old tauren touch two fingers to the brow before mentioning the Chieftain, a small gesture made without any fuss.",
		"notices a small carving of a great horned figure on a lodge post, and a tauren who sees {g:him|her} looking explain, briefly and proudly, who it is meant to be.",
	},
	["thb.muse.w24.cairne.016"] = {
		"Leading the tauren must be like steering a herd: no shouting, no hurry, and a great deal of walking at the front where everyone can see you tire.",
		"A chieftain of a patient people has to be the most patient of all. I wouldn't want the job. I'm not sure the old bull wanted it either.",
	},
	["thb.muse.w24.cairne.017"] = {
		"I'd like to hear the High Chieftain tell the founding of this city himself. I'd need a free week.",
		"Someday somebody will write down how this city was founded. It'll take a tauren to read it aloud, and a week to finish.",
	},
	["thb.muse.w24.calf.001"] = {
		"watches two young tauren butting heads in play, horns barely more than nubs, both pushing so hard that neither moves at all.",
		"smiles at a pair of calves locked forehead to forehead in the middle of the path, grunting, hooves scrabbling, utterly stuck and utterly delighted.",
		"steps around two calves shoving at each other head to head, a contest that seems to have one rule: whoever laughs first has lost.",
	},
	["thb.muse.w24.calf.002"] = {
		"A calf has been sent somewhere with a message. She runs the first part, remembers, and walks the rest with enormous dignity, ears twitching to break into a run.",
		"I watched a young tauren run an errand: a sprint to the turn, then the slow, solemn walk of someone very important as soon as an adult came into view.",
		"The calf who carries messages between the lodges has learned to deliver them word for word, pauses and all, in a voice dropped as low as it will go.",
	},
	["thb.muse.w24.calf.003"] = {
		"A calf has been studying me from behind a tent pole. Every time I look, it's gone. Every time I look away, there it is, a little closer.",
		"That little one is staring at my ears as if they were the strangest thing on the bluff. To be fair, around here they might be.",
	},
	["thb.muse.w24.calf.004"] = {
		"sees a calf fall asleep mid-meal against an adult's flank, a bit of bread still in one hand, and the adult go on eating with great care not to move.",
		"notices a young tauren asleep in a heap of blankets by a doorway, one ear still flicking at every sound, as if half of it had stayed on watch.",
		"spots a calf asleep across the doorway of a lodge, and the adults stepping over it one after another, without a word and without waking it.",
	},
	["thb.muse.w24.calf.005"] = {
		"A calf tried to carry a basket nearly as big as itself across the path. Three adults watched and did nothing. It made it. They nodded. That, apparently, is how lessons go here.",
		"The young ones here are given loads just too heavy for them, and nobody helps until they ask. I've seen one grunt and wobble and refuse to ask, and get there.",
		"Half the kindling a calf was carrying just tumbled onto the path. An adult walking past picked up exactly one stick, handed it back, and kept walking.",
	},
	["thb.muse.w24.calf.006"] = {
		"That calf just beat me in a staring contest. I wasn't even aware we were having one.",
		"Lost a staring match to someone with horn nubs. I demand a rematch.",
	},
	["thb.muse.w24.calf.007"] = {
		"An adult is teaching a young tauren to sit still. That's the whole lesson. Sit. Be still. Look at the plain. The calf lasts about as long as I would.",
		"There seems to be a lesson here for the young that is simply waiting. I watched a calf try it beside an elder: a groan, a wriggle, a long look at the elder, and then, slowly, the real thing.",
	},
	["thb.muse.w24.calf.008"] = {
		"steps around a young tauren sweeping the path with a broom twice its height, mostly moving the dust from one end to the other and back.",
		"stops to let a calf drag a bundle of kindling past, the sticks bumping along behind like a reluctant tail.",
		"waits as a small tauren hurries by with a clay jar held in both arms, tongue out in concentration, every step placed like a promise.",
	},
	["thb.muse.w24.calf.009"] = {
		"As the light goes, voices start calling names across the rises, long and low, and one by one small shapes break off from their games and trot back to the lodges.",
		"Dusk, and the calling begins: a deep voice from one lodge, another answering from across the gap, and young tauren reluctantly leaving the game exactly where it stood.",
	},
	["thb.muse.w24.calf.010"] = {
		"The calves on this bluff have never been hunted across open grass. They play at the very edge of the mesa without a thought for who might be coming. That is what our elders bought for them.",
		"Watching our young ones race along the rise, careless and loud, I think this is the city's real work. Everything else just keeps it standing.",
	},
	["thb.muse.w24.calf.011"] = {
		"I was told a long story by a calf, with a great many gestures. I nodded in the right places, I think. At the end it looked at me very seriously and walked off satisfied.",
		"I've just been told a very important secret by a very small tauren. I didn't catch a word of it, but I've promised to keep it.",
	},
	["thb.muse.w24.calf.012"] = {
		"pauses beside a young tauren counting beads into a bowl under an elder's eye, lips moving, starting over every time a bead rolls away.",
		"follows a calf practicing a hunter's stalk across an empty stretch of rise, belly low, each hoof placed with exaggerated care, toward an unsuspecting basket.",
		"spies a calf rehearsing a grown-up greeting on a tent pole, head dipped just so, then glancing around to see whether anyone saw.",
	},
	["thb.muse.w24.calf.013"] = {
		"A big tauren carried two sleeping calves up the path, one over each shoulder like sacks of grain, and nodded to me as he passed without waking either.",
		"Saw a calf riding on an adult's shoulders, holding on by the horns as if steering. The adult went wherever the steering suggested, very slowly.",
	},
	["thb.muse.w24.calf.014"] = {
		"Young tauren run like boulders that just learned how. Mind your toes.",
		"Careful, little one. If you run into me at that speed, one of us is going over the edge, and it won't be you.",
	},
	["thb.muse.w24.calf.015"] = {
		"Here on Elder Rise a druid is letting a cluster of calves stroke the fur of her bear form, one careful hand after another, while she lies there as patient as a hill.",
		"On this rise the young ones learn the beasts up close. A druid in the shape of a great cat lies very still while three calves count her whiskers, out loud, and disagree.",
	},
	["thb.muse.w24.calf.016"] = {
		"The rain has sent every adult under a hide and left every calf out in it, stamping in the puddles on the path and bellowing as if they'd invented water.",
		"A little tauren is standing in the rain with her mouth open to the sky, perfectly content, while someone in a lodge calls her name with fading hope.",
	},
	["thb.muse.w24.calf.017"] = {
		"hears a young tauren reciting a long list of names to an elder, ancestors perhaps, stumbling at the same place each time, and the elder supplying the word each time without impatience.",
		"lingers as a calf repeats a long chain of names back to an old tauren, stumbling at the same link every time, and the old one offering it every time as if for the first.",
	},
	["thb.muse.w24.calf.018"] = {
		"One calf plays alone at the end of the rise, very carefully, the way children play when they are waiting for someone. A Bluffwatcher keeps glancing over. Nobody says anything to me, and I don't ask.",
		"There's a young tauren who sits at the head of the lift each time I pass, watching every load come up. I hope whoever it's waiting for is on the next one.",
	},
	["thb.muse.w24.calf.019"] = {
		"Run, run, but not toward the edge, little one. Toward the bread.",
		"Hey! Slow down near the drop. Your elders will blame me.",
	},
	["thb.muse.w24.calf.020"] = {
		"Yes, I'm watching. Yes, that was a very good jump. Yes, do it once more, but further from me.",
		"No, I don't know any good games. Show me yours, and go easy.",
	},
	["thb.muse.w24.carving.001"] = {
		"watches a carver scrape out the inside of a horn with a hooked knife, shaving by shaving, until it is thin enough for light to show through.",
		"stops by a carver hollowing a horn into a drinking cup, the hooked knife working inside it with small, patient turns of the wrist.",
		"studies a row of horn spoons laid out to cure, each one bent to a slightly different curve, as though made for one particular hand.",
	},
	["thb.muse.w24.carving.002"] = {
		"A tray of bone toggles on a merchant's blanket, and no two alike: a tiny kodo, a crescent, a knot, a face with its tongue out. I bought the face.",
		"Bone buttons, bone combs, bone beads strung by size. A carver up here can find twenty small things inside one big bone.",
		"I bought a bone toggle carved like a tiny sleeping kodo. It holds my cloak shut and makes me smile every time it does.",
	},
	["thb.muse.w24.carving.003"] = {
		"The carvers' shavings don't go to waste: they're swept into a basket and fed to a cookfire, so the smell of a new totem ends up in somebody's supper.",
		"Cedar shavings in the fire, and for a while the whole rise smells like the carver's bench.",
	},
	["thb.muse.w24.carving.004"] = {
		"The carver asked me to stand still because my face is 'interesting'. I've decided that's a compliment.",
		"A carver keeps glancing at me and then at a block of wood. I'm either a model or a warning.",
		"If a little wooden version of me turns up on a stall next week, I want a share.",
	},
	["thb.muse.w24.carving.005"] = {
		"A painter is renewing an old totem, grinding red earth with fat in a stone dish and laying the new color exactly over the faded one. Not a stroke strays. The first painter, she says, is still the one deciding.",
		"The paint for the totems is earth, mostly: red clay, white chalk, black from the fire, worked into fat with a thumb. When it fades, someone paints the same face again, right on top of itself.",
		"Watching a totem repainted is like hearing someone retell a story word for word. The colors come back; nothing new is added.",
	},
	["thb.muse.w24.carving.006"] = {
		"smiles at a huge tauren whittling a tiny wooden kodo for a calf who waits at his knee, the toy no bigger than one of his knuckles.",
		"looks on as enormous hands carve a toy kodo smaller than a thumb, and the young tauren waiting for it holds out both palms long before it is ready.",
	},
	["thb.muse.w24.carving.007"] = {
		"A carver hones a knife on a flat wet stone, then tests the edge on the hair of his forearm. Half his arm is bare in neat patches. He clearly does this often.",
		"The carving knives get more care than the carvings: honed, oiled, wrapped in hide, laid in a row. A dull edge, one carver told me, tears the wood and insults the tree.",
		"Before he touches the wood, the carver spends a long while on the knife. The wood waits. It is used to waiting.",
	},
	["thb.muse.w24.carving.008"] = {
		"A carver softens a ram's horn in a pot of hot water, then bends it straight between two pegs and leaves it to set. It looks like a cruelty and is, apparently, a kindness: the horn would crack otherwise.",
		"Horn, I've learned, can be boiled soft and pressed flat. A carver here is making a comb out of what was, last season, very much a ram.",
	},
	["thb.muse.w24.carving.009"] = {
		"Here on Elder Rise the carvers work only wood that fell on its own, one of them tells me. The druids would not have it otherwise, and the carvers don't seem to mind leaving the felling to the years.",
		"The druids of Elder Rise, I'm told, won't see a living tree cut, so the carvers up here wait for deadfall. Every log on this rise arrived by its own decision, more or less.",
		"On Elder Rise even the carving has rules. Fallen wood only, the druids ask, or so the carvers say, and they keep to it without a grumble I can hear.",
	},
	["thb.muse.w24.carving.010"] = {
		"The carver handed me a stick and told me to find what's inside it. So far I've found more stick.",
		"I've been whittling for an hour. It was going to be a kodo. It's now a respectable toothpick.",
		"I asked to try carving. I was given the softest wood on the bluff and the bluntest knife. Fair.",
	},
	["thb.muse.w24.carving.011"] = {
		"A new totem lies on its side across three trestles, its half-finished faces staring at the sky. The carvers work it lying down and raise it only when it's done. I'd like to be here for that.",
		"The unfinished totem rests on its trestles like a sleeper, and the carvers move around it quietly, as if not to wake it before it is ready to stand.",
	},
	["thb.muse.w24.carving.012"] = {
		"Mulgore grows grass far better than it grows trees, so the carvers treat every good log as news from far away. One of them ran a hand down a trunk and asked it where it had been.",
		"Wood is precious on these plains. A carver measures a log three times, walks around it, sleeps on it, and only then makes the first cut.",
		"For a long while a carver turned a short log over in his hands, then set it aside for later. Later, I gathered, might mean next year.",
	},
	["thb.muse.w24.carving.013"] = {
		"picks up a carving from a stall, a hawk with folded wings, and finds the carver has finished even the underside nobody will ever see.",
		"turns a small bone figure over in {g:his|her} fingers and finds the back as carefully worked as the front, every feather cut.",
	},
	["thb.muse.w24.carving.014"] = {
		"The carving knives here are sized for tauren hands. In mine, the smallest looks like a cleaver.",
		"I picked up a carver's mallet to admire it and needed both hands. The carver uses it for the delicate work.",
		"Tauren tools are made for tauren hands. Holding a carver's smallest knife, I feel as if I've been let into the workshop to play with the grown-ups' things.",
	},
	["thb.muse.w24.carving.015"] = {
		"The old carvings are small and light, a merchant told me, made to ride in a pack across the Barrens. The new ones are tall and heavy. You can read the end of the wandering in the size of things.",
		"The oldest pieces on the carvers' shelves would fit in a palm. They were made for people who walked, a carver said, and everything they owned had to be light.",
	},
	["thb.muse.w24.carving.016"] = {
		"That carving is looking at me. I think I'm buying it.",
		"This little bone kodo has more character than half the folk I know. Wrap it up, would you?",
	},
	["thb.muse.w24.carving.017"] = {
		"Is that a spoon or a sculpture? Both? Then I'm paying for both.",
		"Even the spoons here have faces carved on them. I'll be eating my soup under supervision.",
	},
	["thb.muse.w24.carving.018"] = {
		"On Hunter Rise the bone carvers sit close to the hunters, and tusks and antlers pass straight from one to the other, a little plain grass still caught in them.",
		"On Hunter Rise a carver turns a boar's tusk in the light, deciding. A hunter waits nearby, as if the tusk's future were also his business.",
	},
	["thb.muse.w24.carving.019"] = {
		"The carver's hands are a map of small old nicks, pale lines in the fur. Every one of them, I suspect, came with a lesson attached.",
		"Scars on a carver's fingers, dozens of them, fine as hairs. The newest belong to the youngest carver. The oldest carver has stopped collecting them.",
	},
	["thb.muse.w24.centaur.001"] = {
		"The centaur never met the tauren in open battle, the elders say. They harried: a camp struck, a herd scattered, the stragglers ridden down. A war of tired legs.",
		"From what the old tauren tell, the centaur had a cruel kind of patience: follow the tribe, wait for it to tire, take the slowest.",
		"The worst of the centaur years, an elder told me, was never the raids. It was the waiting between them.",
	},
	["thb.muse.w24.centaur.002"] = {
		"notices a long, pale scar across an old tauren's shoulder, the kind a lance leaves, and the way the elder rubs it without seeming to know.",
		"spots a tauren elder with a notched horn, and a younger tauren nearby who glances at the notch whenever the talk turns to the Barrens.",
		"spots an old tauren whose left ear is half gone, listening to the young ones' chatter with the good one turned toward them.",
	},
	["thb.muse.w24.centaur.003"] = {
		"Someone came running across the planks just now, quick and hard, and every older tauren in earshot looked up at once. Then they laughed at themselves, a little. An old fear, from the centaur years.",
		"A sudden clatter of hooves nearby, and the elders all lift their heads together before they remember where they are. Some alarms never get unlearned.",
	},
	["thb.muse.w24.centaur.004"] = {
		"The centaur could outrun the tauren on the plains. Nobody has yet seen a centaur climb a cliff. The elders have clearly given this a great deal of thought.",
		"Four legs are wonderful on grass and useless on a sheer wall of rock. Somewhere in the founding of this city, I suspect, a tauren smiled about that.",
	},
	["thb.muse.w24.centaur.005"] = {
		"News of centaur in the Barrens still makes the elders put down whatever they're holding. Not fear, exactly. More the way you set down a cup before a hard story.",
		"When a hunter brings word of centaur riders, the old tauren go very still and very polite. The young ones get loud. You can tell who remembers.",
	},
	["thb.muse.w24.centaur.006"] = {
		"The talk by the lifts is centaur. Sooner or later, the talk here is always centaur.",
		"Mention the centaur up here and watch a whole row of tauren ears go flat.",
		"Say centaur on this rise and even the cook stops stirring.",
	},
	["thb.muse.w24.centaur.007"] = {
		"Someone came up from the plain with sawdust caught in the fur of their shins. Nobody needed to ask which hills they'd crossed. The Venture Company marks everything that passes near it.",
		"A brave just tipped a handful of goblin screws and rivets onto a hide in front of the elders, picked up somewhere in the hills. They looked at them a long time without touching them.",
		"Bits of the Venture Company keep arriving in the city: a snapped saw tooth, a grease-stained rag, a crumpled tally sheet. The tauren pass them hand to hand like evidence.",
	},
	["thb.muse.w24.centaur.008"] = {
		"The quilboar have dug in at the edges of Mulgore, the talk goes. The tauren speak of them with a frown more tired than angry, like a farmer speaking of weeds.",
		"Quilboar in the brambles, again and always. The hunters up here mention them the way you mention a leaking roof: not urgent, never quite fixed.",
	},
	["thb.muse.w24.centaur.009"] = {
		"Hides taken back from the gnolls come up to the city sometimes, and the tanners handle them with extra care, as if to apologize to the beast.",
		"A hunter brought up a bundle of skins recovered from a gnoll camp. Nobody here would use them for anything ordinary. They're being kept apart, like the belongings of the dead.",
	},
	["thb.muse.w24.centaur.010"] = {
		"watches two Bluffwatchers trade a few low words about the plain below, one of them tilting a pair of horns toward the hills where the goblins work.",
		"catches a scrap of talk between passing braves: quilboar, a burned camp, a count of something, and then the voices move out of earshot.",
		"hears a Bluffwatcher repeat a hunter's report to another, word for word, in the slow careful way of people who will repeat it again to someone else.",
	},
	["thb.muse.w24.centaur.011"] = {
		"The tauren won Mulgore at a price, and the price was paid in the Barrens. Nobody up here forgets that the green plain below was bought with dry miles.",
		"Every blade of grass in Mulgore, an elder told me, stands on a mile of dust walked by someone who didn't get here.",
	},
	["thb.muse.w24.centaur.012"] = {
		"A splinter in the hoof: that's how the tauren handle the Venture Company. Slowly, thoroughly, and with a look that says it will not happen twice.",
		"Goblins are cutting down Mulgore and the tauren are deciding what to do about it. The goblins should hope they take their time.",
		"Venture Company crews in Mulgore. Brave of them. Not clever, but brave.",
	},
	["thb.muse.w24.centaur.013"] = {
		"Here on Hunter Rise the talk is all of what's wrong with the plain: less game where the goblins cut, gnoll snares where there were none.",
		"The hunters of this rise trade news like trail signs. A hillside cleared, a spring fouled, a herd moved off: each one said once and remembered.",
		"On Hunter Rise they keep the plain's troubles the way others keep accounts. Nothing written; nothing forgotten either.",
	},
	["thb.muse.w24.centaur.014"] = {
		"notices an old tauren turn away from the eastern edge whenever dust rises over the far ridge, as if that view had been used up long ago.",
		"sees an elder stand at the rim facing east, toward the Barrens, for a long while, and then turn deliberately toward the green side of the plain.",
		"pauses to watch a tauren elder point east for a younger one and say a single word, and the younger one stop smiling.",
	},
	["thb.muse.w24.centaur.015"] = {
		"watches the fires of a far camp on the plain, and an elder at the edge watching them too, until a Bluffwatcher murmurs that they are only herders.",
		"stands at the dark edge of the rise while an old tauren counts the campfires on the plain below, the way, the elders say, the tribes once counted the centaur's.",
	},
	["thb.muse.w24.centaur.016"] = {
		"There is a tauren word, I'm told, for the sound of many hooves coming from far off, and nobody likes to say it aloud. The centaur taught them that word.",
		"There's a way the elders go quiet when the young ones gallop for fun. Nobody scolds them. Nobody joins in, either.",
	},
	["thb.muse.w24.centaur.017"] = {
		"The goblins of the Venture Company sell timber by the board. The tauren count the same trees by the century. The two will never agree on a price.",
		"A goblin would call it clearing land. The tauren call it something slower and much less polite, and only among themselves.",
	},
	["thb.muse.w24.centaur.018"] = {
		"takes in a broken centaur lance hung on a lodge pole, point to the ground, and the fact that the tauren passing it never look at it.",
		"spots a faded pattern of war paint on an old tauren's arm, nearly gone, and the care the elder takes to keep it covered.",
		"stops to watch a tauren child gallop about on all fours whooping like a centaur, and an elder call the child back, not angrily, but at once.",
	},
	["thb.muse.w24.centaur.019"] = {
		"If I were a centaur, I'd stay well clear of this cliff. These people have long memories and longer patience.",
		"Whatever the centaur did to these people, I hope they're sorry. The tauren certainly haven't forgotten.",
	},
	["thb.muse.w24.cookfire.001"] = {
		"sits down at a cookfire and is handed a skewer of roasted meat before managing a single word, the cook already turning back to the coals.",
		"lowers onto a log by a cookfire, and a skewer finds {g:his|her} hand before the greeting is even finished.",
	},
	["thb.muse.w24.cookfire.002"] = {
		"I asked for a little. The cook nodded wisely and gave me what a tauren means by a little.",
		"Portions here come in two sizes: tauren, and slightly more than tauren, for guests.",
		"The skewer I was handed is as long as my arm, and the meat on it would feed a camp in the Barrens. I'm told it's a snack.",
	},
	["thb.muse.w24.cookfire.003"] = {
		"I'll need a second plate. Not for more food. To hold up the first one.",
		"Thank you. I'll eat what I can and carry the rest around for a week.",
		"This is one portion? I'd like to meet whoever orders two.",
	},
	["thb.muse.w24.cookfire.004"] = {
		"Nobody at the fire asks where I'm from or what I've done. They pass the bowl and talk about the price of salt. I'd forgotten how restful that is.",
		"At a fire of strangers up here, I'm asked nothing at all. Only whether I want more, and that one keeps coming round.",
	},
	["thb.muse.w24.cookfire.005"] = {
		"listens as a troll at the fire explains to the cook how the Darkspear would spice the same meat; the cook nods slowly and changes nothing at all.",
		"shares a cookfire with a young orc who eats in quick hungry bites, while the tauren around the coals take one slow mouthful each and watch with mild interest.",
	},
	["thb.muse.w24.cookfire.006"] = {
		"What is this? No, don't tell me. It's good, and I'd like to keep it that way.",
		"Whatever this is, I want the recipe. Or the cook. Mostly the recipe.",
	},
	["thb.muse.w24.cookfire.007"] = {
		"My spoon has a little carved face on the handle. It watched me eat the whole bowl. I think it approved.",
		"Someone carved a tiny face into the handle of the spoon I was given. It's very hard to eat greedily while it looks at you.",
	},
	["thb.muse.w24.cookfire.008"] = {
		"tries to hand the bowl back and finds it refilled instead, the ladle already moving on to the next guest.",
		"sets down an empty bowl for a moment and turns to find it full, with no one nearby looking the least bit guilty.",
	},
	["thb.muse.w24.cookfire.009"] = {
		"I said aloud at the fire that my pack strap was fraying. A moment later a large hand held out a needle and a length of sinew, and went straight back to its bowl.",
		"A tauren at the cookfire is restitching a strap of mine that I never asked anyone to touch. I only mentioned it was loose. Up here that seems to count as asking.",
	},
	["thb.muse.w24.cookfire.010"] = {
		"My compliments to whoever cooked this. And my apologies to whoever has to carry me off afterward.",
		"Best thing I've eaten in weeks. Possibly ever. Don't tell the other cooks.",
	},
	["thb.muse.w24.cookfire.011"] = {
		"joins a cookfire as the dusk comes on, and someone slides along the log without a word to make room.",
		"sits down by a fire just being lit for the dusk, and is handed a fan of stiff hide and shown, without words, where the coals want air.",
	},
	["thb.muse.w24.cookfire.012"] = {
		"There is exactly one thing tauren do quickly, and it's notice an empty bowl.",
		"Slow in everything, the tauren, except one: an empty bowl in a guest's hands lasts about as long as a spark.",
	},
	["thb.muse.w24.cookfire.013"] = {
		"Is there salt? Ah, it's already in. Everything's already in. I'll stop asking and eat.",
		"Is there any more of that dark bread? No? Then I'll take a little more of everything else.",
	},
	["thb.muse.w24.cookfire.014"] = {
		"warms cold fingers over the coals of a cookfire, turning them slowly like meat on a spit, while the cook hums.",
		"holds both hands out to the coals for a long, quiet while, and the cook, without breaking off a tune, nudges a flat stone closer to sit on.",
	},
	["thb.muse.w24.cookfire.015"] = {
		"My cloak keeps the cookfire for days. In some far camp I'll catch a whiff of it and be back on this log.",
		"One meal at a tauren fire and my cloak carries it around like a keepsake: smoke, fat, and something green I couldn't name.",
	},
	["thb.muse.w24.cookfire.016"] = {
		"Lovely silence at this fire. I'd say so, but that would ruin it.",
		"Nobody's spoken at this fire in a long while. Best conversation I've had all week.",
	},
	["thb.muse.w24.cookfire.017"] = {
		"Guests at the fire always eat too fast the first time. By the third bowl they slow down, and that's when I know the welcome has reached them.",
		"An orc at my fire eats as if someone might take the plate away. I set another piece in front of the orc and say nothing. After a few meals, guests learn that nobody will.",
	},
	["thb.muse.w24.cookfire.018"] = {
		"burns a finger on the first bite, too polite to wait, and draws a deep rumbling chuckle from the far side of the fire.",
		"takes a bite too soon, scalds {g:his|her} tongue, and pretends very hard that nothing happened while a tauren across the coals looks politely elsewhere.",
	},
	["thb.muse.w24.cookfire.019"] = {
		"The roots they roast in the ashes here come out black as coal and sweet inside. I've asked their name twice and lost it both times somewhere in the middle.",
		"Blackened roots straight from the ashes, split open with a thumb. Nobody here would call it a feast. I'd call it the best thing on the rise.",
	},
	["thb.muse.w24.cookfire.020"] = {
		"is shown by a patient tauren, with gestures and no words, how to tear the flatbread and fold it around the meat, and gets it almost right.",
		"watches the tauren across the fire wrap meat in flatbread with three neat folds, tries it, and produces something closer to a small disaster.",
	},
	["thb.muse.w24.cookfire.021"] = {
		"Can I help? I can stir. I'm a very good stirrer.",
		"Let me fetch the water at least. No? Then I'll sit here and feel guilty. It's no trouble.",
		"Put me to work. Peeling, carrying, anything. I've eaten enough for three of me.",
	},
	["thb.muse.w24.cookfire.022"] = {
		"Somebody's cookfire is already going at dawn, and I've drifted toward it like a moth.",
		"Dawn, and the first cook up is setting out bowls. I'm the second one awake. I'll take whatever is first in the pot.",
	},
	["thb.muse.w24.cookfire.023"] = {
		"Thank you, truly. No, I can't. No, really. ...All right, a little.",
		"I said I was full. You heard me say it. And still the ladle comes.",
	},
	["thb.muse.w24.crossing.001"] = {
		"Halfway over the span I meet a tauren with a basket on each arm, coming the other way. Somebody has to back up, and it's plain which of the two weighs less.",
		"Two can't pass on these planks when one of them is a tauren with firewood. I walk backward to the start, and get a very gracious nod for it.",
	},
	["thb.muse.w24.crossing.002"] = {
		"reaches the lift just as it starts down without {g:him|her}, and settles in to wait with the air of someone who meant to all along.",
		"arrives at the platform in time to watch the lift sink away, empty, and folds {g:his|her} arms to wait.",
	},
	["thb.muse.w24.crossing.003"] = {
		"Missed the lift by a step. It didn't even slow down to apologize.",
		"The lift waits for no one. Except the tauren. It always seems to wait for the tauren.",
		"Lift's gone. Fine. I'll stand here and look patient, like a local.",
	},
	["thb.muse.w24.crossing.004"] = {
		"I count the planks when I cross. It isn't fear. It's just something for my mind to do while my feet handle the brave part.",
		"There's one plank on the way to the far rise that gives a little more than the others. I step over it every time, and I suspect I'm not the first.",
		"Every crossing, I pick a knot on the far post and walk toward it as if it owed me money. It works better than looking anywhere else.",
	},
	["thb.muse.w24.crossing.005"] = {
		"follows an orc across the span, both of the orc's fists locked on the ropes and a low growl of complaint going the whole way over.",
		"crosses behind a troll who strolls the planks with both hands in the air, laughing, while everyone else holds on a little tighter.",
	},
	["thb.muse.w24.crossing.006"] = {
		"Took the wrong crossing and ended up back on the rise I'd just left, from the other side. The tauren who watched me do it said nothing, very kindly.",
		"I keep taking the wrong span. The city is only a few rises tied together, and I still manage to visit each of them twice.",
	},
	["thb.muse.w24.crossing.007"] = {
		"After you. Truly. I'll take my turn once the planks stop moving.",
		"Go on ahead, I'm in no hurry. I've noticed that's the polite thing to say here.",
	},
	["thb.muse.w24.crossing.008"] = {
		"kneels at the head of the span to double-knot a bootlace before setting off; nothing crosses loose here.",
		"stops before the crossing to tuck in a loose strap and tighten the pack, the small rites of someone about to walk over air.",
	},
	["thb.muse.w24.crossing.009"] = {
		"I carried a full cup from one end of the span to the other without spilling a drop. Nobody saw. It's still my proudest moment in this city.",
		"A bowl in both hands and a crossing ahead. I took it the way you'd carry the last ember of a fire, and arrived with every drop.",
	},
	["thb.muse.w24.crossing.010"] = {
		"Lift's full: two tauren, a sack of grain and me. If anything goes over the side to lighten it, I can tell it's me.",
		"Four on the lift, and I'm the only one holding the rope.",
	},
	["thb.muse.w24.crossing.011"] = {
		"crosses between the rises by the glow of the fires at either end, feeling for each plank before trusting it.",
		"walks the ropes in the dark with one hand sliding along the line, the far rise marked only by a lantern.",
	},
	["thb.muse.w24.crossing.012"] = {
		"Halfway over I stop to admire the knots. I'm not frightened. These are simply very interesting knots.",
		"Whenever the span dips I take a sudden scholarly interest in the ropework. The tauren behind me waits, politely, for my studies to end.",
	},
	["thb.muse.w24.crossing.013"] = {
		"steps back as the lift comes up loaded with firewood, a crate of clay pots and one dozing tauren, who wakes at the top as if summoned.",
		"waits while the lift unloads sacks of meal and a pair of dusty travelers, then steps on alone and has the whole platform for the ride.",
	},
	["thb.muse.w24.crossing.014"] = {
		"Excuse me, is this the way to the inn, or the way to falling off? Ah, the inn. Thank you.",
		"Is this the crossing for the trainers? Never mind. I'll just follow whoever looks most sure.",
	},
	["thb.muse.w24.crossing.015"] = {
		"Every tauren I pass on the span murmurs something low and kind. I nod back and hope it wasn't a question.",
		"On the crossings the tauren greet each other with a word I don't know. To me they give a nod instead, carefully, the way you'd hand a guest the good cup.",
	},
	["thb.muse.w24.crossing.016"] = {
		"freezes mid-crossing when the span gives a lurch, finds it was only a tauren stepping on at the far end, and walks on with great dignity.",
		"pauses halfway over as the planks dip, finds nothing wrong but a heavy step far behind, and resumes with a dignity that fools no one.",
	},
	["thb.muse.w24.crossing.017"] = {
		"I slow down on the crossings when a guest is ahead of me. Nothing is worse than a big shadow hurrying you along over a drop.",
		"An orc ahead of me on the span keeps glancing back. I stop and look at the plains until the orc is across. Hospitality starts with not looming.",
	},
	["thb.muse.w24.crossing.018"] = {
		"My knees have opinions about this crossing. I've asked them to keep those until the far side.",
		"Knees, please. Opinions at the other end.",
	},
	["thb.muse.w24.crossing.019"] = {
		"crosses with a new purchase held tight against {g:his|her} chest, eyes fixed on the far post, and only loosens the grip on the other side.",
		"makes the crossing with a parcel clutched in both arms, the way one carries something that cost a great deal and would fall a very long way.",
	},
	["thb.muse.w24.crossing.020"] = {
		"Lift going down? Hold it, please. Please! Thank you, I'll wait for the next one.",
		"Is that lift coming or going? Either way, I'm late for it.",
	},
	["thb.muse.w24.drop.001"] = {
		"Lean out far enough and the cliff doesn't go straight down at all: it bellies outward, so the foot of the mesa hides under it like toes under a robe.",
		"I tried to see the bottom of the cliff from the edge. The rock bulges out halfway and keeps it from me. Probably for the best.",
	},
	["thb.muse.w24.drop.002"] = {
		"stops where the rock at the rim has been polished pale by everyone who ever paused to look down, and adds {g:his|her} own share to the polish.",
		"notices that the stone at the very lip of the rise is worn smooth and lighter than the rest, a lookout made by nothing but feet.",
		"pauses at a spot on the rim where the stone dips in a shallow, pale hollow, as if the rise itself had leaned there a long time to look down.",
	},
	["thb.muse.w24.drop.003"] = {
		"There's a ledge a long way below this one, no wider than a bench, with a nest of sticks on it. Something lives there with the whole of Mulgore for a doorstep.",
		"Far down the cliff face a shelf of rock holds a ragged nest. Whoever built it chose the one address in the city nobody can visit.",
		"Below the rim, out of reach of any rope, a bird has made a home in a crack of the stone. It is the only house in Thunder Bluff that never gets a caller.",
	},
	["thb.muse.w24.drop.004"] = {
		"I keep wanting to know exactly how far down it is. I keep deciding not to find out.",
		"How high up is this? No, don't tell me. I'd only start doing sums.",
	},
	["thb.muse.w24.drop.005"] = {
		"Trees seen from straight above are a different thing: round dark tufts with no trunks at all, set down on the grass like pincushions.",
		"The few trees of the plain, seen from the rim, have lost their trunks. Only the crowns are left, little dark knots tied into the green.",
		"Seen from the top, a lone tree shrinks to a dark round blot on the grass, and its trunk is something to take on trust.",
	},
	["thb.muse.w24.drop.006"] = {
		"spots a young tauren sitting on the very lip of the rise to mend a strap, hooves swinging over nothing, as unconcerned as on a doorstep.",
		"sees a tauren child lie on her belly at the edge and peer down, while an elder nearby keeps talking and keeps one hand on the back of her tunic.",
	},
	["thb.muse.w24.drop.007"] = {
		"Near the edge everyone holds things a little tighter: a cup, a pipe, a child. I've started doing it with my own hands, which aren't going anywhere.",
		"Watch any tauren pass something to a friend near the rim: both hands, every time, and a pause before letting go.",
	},
	["thb.muse.w24.drop.008"] = {
		"The drop doesn't threaten. It waits at the end of every path, patient as everything else in this city, and lets you choose not to.",
		"Every edge here makes the same quiet offer, and the whole city turns it down a thousand times over without a thought.",
	},
	["thb.muse.w24.drop.009"] = {
		"considers spitting over the edge to see where it lands, catches the eye of a nearby Bluffwatcher, and thinks better of it.",
		"leans out over the drop with a pebble in hand, meets the flat stare of a passing elder, and puts the pebble quietly back where it was.",
	},
	["thb.muse.w24.drop.010"] = {
		"At the foot of the mesa there's a skirt of fallen rock, boulders the size of lodges, every one tumbled down at some moment nobody saw.",
		"Down where the cliff meets the grass lies a long heap of broken stone. Every piece of it was once up here. I try not to take that personally.",
		"The boulders heaped at the cliff's foot look like pebbles from the rim. Then a traveler walks past one, and the pebble is taller than the traveler.",
	},
	["thb.muse.w24.drop.011"] = {
		"Straight down, at the foot of the lifts, a little crowd of dots waits its turn. Nobody there seems to be in a hurry, though that may only be the distance.",
		"The bottom of the lift is a scrap of trodden earth with dots gathered around it. One of the dots is waving. I wave back, just in case.",
	},
	["thb.muse.w24.drop.012"] = {
		"Every city has a high part and a low part. This one is all high part, with the low part left outside.",
		"Most places, you climb to see the view. Here you'd have to go down to stop seeing it.",
	},
	["thb.muse.w24.drop.013"] = {
		"For generations beyond counting the tauren slept on open grass with one ear listening. The cliff under this city is the first wall my people ever had, and the deepest.",
		"Down there is where the tauren were hunted. Up here is where the hunting stopped. The drop between the two is the whole of my people's peace.",
	},
	["thb.muse.w24.drop.014"] = {
		"kneels at the rim, sets both palms flat on the stone, and looks down for a long, steady while, as if introducing {g:himself|herself} to the height.",
		"crouches near the edge with one hand on the rock and stays there, unhurried, until the distance below stops being news.",
	},
	["thb.muse.w24.drop.015"] = {
		"I've worked out the only shortcut in Thunder Bluff. It is very quick, it goes straight to Mulgore, and nobody takes it twice.",
		"There's a fast way down from any rise. The tauren built lifts precisely so nobody would use it.",
	},
	["thb.muse.w24.drop.016"] = {
		"Call out over the edge and nothing comes back. The plain takes the voice and keeps it, like a letter sent with no address.",
		"No echo from the plain. Whatever is said over the rim simply goes out across the grass and stays there.",
	},
	["thb.muse.w24.drop.017"] = {
		"Here on Hunter Rise the hunters' beasts lie right at the edge, chins on their paws, watching the plain below like dogs at a window.",
		"The pets on Hunter Rise all choose the rim to nap on. A wolf lies with its nose over the drop, twitching at smells that come all the way up from the grass.",
	},
	["thb.muse.w24.drop.018"] = {
		"Lovely edge. It looks just as good from back here.",
		"Nobody needs to stand that close to the drop. I'm saying this to my own feet.",
		"Fine. I've looked down. Can I have my knees back now?",
	},
	["thb.muse.w24.drop.019"] = {
		"Lean out over the rim and the city goes quiet behind you, all at once, as if the noise stopped at the edge and refused to follow.",
		"Two steps from the tents it's busy and loud. One more step, to the lip of the rise, and every sound of the city is suddenly at my back and very small.",
	},
	["thb.muse.w24.drop.020"] = {
		"Somebody built a whole city on the one spot where tripping over is a serious decision.",
		"Trip anywhere else and you get a bruise. Trip here and you become a story nobody tells.",
	},
	["thb.muse.w24.drop.021"] = {
		"Everything in this city is a short walk and a long fall from everything else.",
		"Mind the step. Every step. There's always one that isn't there.",
	},
	["thb.muse.w24.eagle.001"] = {
		"A hawk holds itself still in the air off the rim, and the only part of it working is the very tip of each wing: one feather, then another, trimming and trimming.",
		"Watching a hawk hover close by the cliff, I can see the small corrections it makes, a single wingtip feather lifting and settling, like someone steadying a cup.",
		"The hawk off the rim isn't resting, though it looks it. Its tail keeps fanning and closing, small and quick, like fingers counting coins in a pocket.",
	},
	["thb.muse.w24.eagle.002"] = {
		"watches small quick birds dart in and out beneath a rope bridge, flicking through the gaps between its boards as if it had been built for them.",
		"follows a pair of swifts that skim the cliff face, vanish into a crack in the stone, and burst out a moment later from another.",
	},
	["thb.muse.w24.eagle.003"] = {
		"There's an eagle that sits on top of the same tent pole every time I pass. It no longer bothers to look at me. I've become furniture.",
		"Up here the birds don't scatter when someone walks past. They glance, they judge, they go back to preening. The city has spoiled them.",
	},
	["thb.muse.w24.eagle.004"] = {
		"On the plain a hawk's cry comes from above. Up here it comes from the side, level with my ear, like a neighbor calling across a lane.",
		"Strange, to hear an eagle scream and turn my head sideways instead of up. In this city the creatures of the sky live at eye height, and so does their racket.",
		"The hawks' calls bounce between the rises, so one bird sounds like three, and the city seems full of hawks that aren't there.",
	},
	["thb.muse.w24.eagle.005"] = {
		"meets the gaze of an eagle perched on a jut of rock a few strides away, and for a long, level moment neither of them looks away first.",
		"stands very still while an eagle on a nearby ledge studies {g:him|her}, head tilting one way and then the other, as if reading small print.",
	},
	["thb.muse.w24.eagle.006"] = {
		"Birds line the lift ropes like beads on a string, and whenever the platform moves they lift off together, complain, and settle back in the same order.",
		"The lift ropes are the best perch in town, apparently. A row of little brown birds rides them up and down all day and never pays a copper.",
	},
	["thb.muse.w24.eagle.007"] = {
		"A hunter told me she reads the plain by its birds: where they circle, something has died; where they all rise at once, something is coming. From this height the whole page is open.",
		"The hunters watch the hawks over Mulgore the way merchants watch prices. A sudden spiral far out, and two of them stop talking and look at each other.",
	},
	["thb.muse.w24.eagle.008"] = {
		"That bird has been circling at my height for a while now. Either it's curious or it's measuring me.",
		"Hello, bird. No, I'm not going to fly. Stop waiting.",
		"Eagles at eye level. Somebody tell them they're not supposed to be this close.",
	},
	["thb.muse.w24.eagle.009"] = {
		"On a ledge below the rim lies a small pile of bones and fur, picked clean. Something up here eats very well, and does it with a view.",
		"On a shelf just under the edge are the leavings of some hawk's meal: a few tiny bones, a scrap of fur. Even the high, calm places have their hunting.",
	},
	["thb.muse.w24.eagle.010"] = {
		"takes a distant dark shape over the plain for a bird, until it banks and grows and turns out to be a wind rider with someone on its back, coming in from very far off.",
		"keeps an eye on a speck over Mulgore that looks like a hawk for a long time and then, much nearer, is plainly a wind rider making for the city.",
	},
	["thb.muse.w24.eagle.011"] = {
		"Here on Elder Rise a druid sits with an eagle on the post beside her, the two of them watching the plain together without a word, like old sentries sharing a watch.",
		"On Elder Rise the birds land closer than anywhere else in the city. A druid told me they know who will not reach for them.",
	},
	["thb.muse.w24.eagle.012"] = {
		"Far below, a flock of small birds turns over the grass all together, and every turn shows a different side: dark, then pale, then dark, like a cloth shaken out.",
		"A cloud of tiny birds wheels low over Mulgore, flashing light and dark as it turns. Seen from the rim, it looks as if the plain were blinking.",
		"A flock below rises off the grass, turns all at once and settles a little further on, like a handful of seed thrown and gathered by the same hand.",
	},
	["thb.muse.w24.eagle.013"] = {
		"holds a crust out at the rim on a whim, and a bird snatches it in passing so neatly that {g:he|she} is left holding nothing but the idea.",
		"breaks off a bit of bread near the edge and has it whisked from {g:his|her} fingers by a darting bird before deciding to offer it.",
	},
	["thb.muse.w24.eagle.014"] = {
		"One hawk, very high, alone in all that sky. I watch it longer than I mean to. Nobody up here would think less of me for it.",
		"A single eagle is out past the rise, circling with nothing near it for miles. It doesn't look lonely. I may be the one who does.",
	},
	["thb.muse.w24.eagle.015"] = {
		"An elder said the eagles nested on these mesas long before the first tauren climbed them, and that the city still pays them rent in scraps. I believe the part about the scraps.",
		"One old herder swears the birds of the bluffs were the first tenants here, and the tribes only asked to share. The birds seem to remember the arrangement.",
	},
	["thb.muse.w24.eagle.016"] = {
		"At dusk the swifts come home to the cracks in the cliffs all at once, a dark stream pouring into the stone just below my feet.",
		"Dusk, and the small cliff birds are pouring back into their crevices, a whole loud neighborhood going to bed beneath the city.",
	},
	["thb.muse.w24.eagle.017"] = {
		"I've been up here long enough that the birds have stopped flinching. I'm not sure that's a compliment.",
		"If one more hawk looks at me like that, I'm going to start charging it for the show.",
	},
	["thb.muse.w24.eagle.018"] = {
		"Look at that hawk. Not a single flap. I want whatever it's having.",
		"That eagle hasn't moved a feather in ages. I name it the laziest hunter in Mulgore.",
	},
	["thb.muse.w24.eagle.019"] = {
		"Up here the birds look me straight in the eye. It's less flattering than it sounds.",
		"Nice of the hawks to fly at my level. Most cities make you crane your neck.",
	},
	["thb.muse.w24.earthsong.001"] = {
		"observes a druid here on Elder Rise hold a long, low conversation with a hawk perched on her arm, pausing often, as if the hawk had a good deal to say.",
		"sees an old druid offer a wounded hawk his forearm and wait, unmoving, until the bird decides to step onto it.",
	},
	["thb.muse.w24.earthsong.002"] = {
		"A druid of Elder Rise told me taking the bear's shape is like borrowing a coat from a friend: you keep it clean, you give it back, and you never pretend it was yours.",
		"I asked a druid what it's like to be a great cat for an afternoon. 'Polite,' he said. 'You're a guest in someone else's legs.'",
		"Druids speak of their beast shapes like borrowed tools: cleaned, mended, and returned with thanks to whoever lent them.",
	},
	["thb.muse.w24.earthsong.003"] = {
		"The druids of the city never say a beast obeys them. A beast 'agrees', they say, and sometimes it doesn't, and that's its right.",
		"Ask a tauren druid whether the wolves of the plain listen to her, and she'll say no: only that sometimes they choose to walk the same way.",
	},
	["thb.muse.w24.earthsong.004"] = {
		"notices an old druid kneel beside a wilting plant in a clay pot by a lodge, murmur to it, and get up with a grunt, apparently satisfied with its promises.",
		"pauses beside a druid running a thumb along a sickly vine on a lodge frame, frowning like a healer at a stubborn patient.",
	},
	["thb.muse.w24.earthsong.005"] = {
		"I lay my palm on the stone before I cross the long bridge. Not for luck. Only to tell the Earth Mother where I'm going, the way you'd tell your mother.",
		"Up this high, some think the Earth Mother is far off. She isn't. She is the whole bluff under me, and she has carried heavier than me without a word.",
	},
	["thb.muse.w24.earthsong.006"] = {
		"A clay jug slipped from a tauren's hands and shattered on the planks. He looked at the pieces and said, without heat, that the Earth Mother must have wanted it back. Then he swept her share off the edge.",
		"Small losses go to the Earth Mother, up here. A broken bowl went back to her; a torn hide went back to her. I've started trying it with my own mishaps. It helps more than swearing.",
	},
	["thb.muse.w24.earthsong.007"] = {
		"comes upon an old tauren lying with one ear pressed to the bare rock, eyes closed, like someone listening to a neighbor through a wall.",
		"spots a tauren stop in the middle of a bridge, close her eyes and stand with hooves planted wide, as if feeling for something far below the planks.",
	},
	["thb.muse.w24.earthsong.008"] = {
		"A shaman told me the mesas hum, very low, all the time, and that you hear it only when you stop expecting to. I've been trying not to expect it. It's harder than it sounds.",
		"The tauren say the earth sings beneath Thunder Bluff, too deep for most ears. I sat still a long while and heard nothing but my knees creak. Perhaps that counts.",
	},
	["thb.muse.w24.earthsong.009"] = {
		"Hello, ground. A tauren tells me you're listening, so: thank you for staying put.",
		"I'm told the earth up here has ears. Good. Then plainly: thanks for every plank that held.",
	},
	["thb.muse.w24.earthsong.010"] = {
		"The elders speak of places out on the old plains where their dead were laid, far behind them now in centaur country. They can't go there, so they name them slowly, one by one, like stops on a road they can't walk.",
		"Some of the ground the tauren honor lies far out where the centaur roam. An elder told me she visits it in her sleep instead, and wakes tired from the walk.",
	},
	["thb.muse.w24.earthsong.011"] = {
		"follows an elder who takes a calf's hand and presses it to the rock, saying a few slow words the calf repeats, badly, and then once more, better.",
		"lingers near a grandmother showing a small tauren how to stand still and listen to the ground, the two of them side by side like a pair of stones, one fidgeting.",
	},
	["thb.muse.w24.earthsong.012"] = {
		"The Earth Mother isn't mine to call on. Still, after a while up here I catch myself stepping more gently, as if I'd been told someone was sleeping under the floor.",
		"She's the tauren's, not mine, this Earth Mother. But it's hard to stand on her for long and not want to wipe your feet.",
	},
	["thb.muse.w24.earthsong.013"] = {
		"A crow landed beside an old druid and the two of them looked at me for a while. Then the crow left, and the druid said I'd do. I don't know what I was being considered for.",
		"On Elder Rise an owl watched me from a lodge pole the whole time I talked with a druid. When the owl blinked, the druid ended the talk. I suspect I know who was in charge.",
	},
	["thb.muse.w24.earthsong.014"] = {
		"Is that bear one of yours, or one of you? I'd like to know how polite to be.",
		"Excuse me. Is the owl with you, or are you with the owl?",
	},
	["thb.muse.w24.earthsong.015"] = {
		"Now and then the druids of Elder Rise walk a long way north, a Bluffwatcher told me, to a glade they share with the night elves, and they come home saying nothing about the war.",
		"There's a place, the druids say, a valley far to the north, where tauren and night elf still sit at one fire. They speak of it rarely and always quietly, like a secret too good to wear out.",
	},
	["thb.muse.w24.earthsong.016"] = {
		"A druid carried a dead hawk up from the plains in both hands, wrapped in a scrap of blanket, and sat with it a long time before taking it to the edge. Nobody hurried her.",
		"I watched a tauren druid close the eyes of a dead bird of the plains someone had brought up for the pot, say a few words over it, and only then hand it to the cook.",
	},
	["thb.muse.w24.earthsong.017"] = {
		"notices a druid sitting cross-legged among a scatter of seeds, letting small birds hop up and pick them from her open palms.",
		"sees sparrows gather around a motionless druid like old friends at a market, perching on knees, shoulders and once, briefly, a horn.",
	},
	["thb.muse.w24.earthsong.018"] = {
		"sees a few elders at the edge of the rise turn their faces up to the moon and speak a low word to it, as one greets a relative across a room.",
		"stands near an old shaman who lifts a hand to the moon over Mulgore and holds it there, palm out, for a long while.",
	},
	["thb.muse.w24.earthsong.019"] = {
		"The shamans stand out in the rain with their faces up and eyes shut, perfectly content. One told me it was the sky coming down to visit the earth. I'm visiting the nearest awning.",
		"A shaman tells me the rain is the sky paying its respects to the ground. The ground looks pleased. Everyone who isn't a shaman is under the eaves.",
	},
	["thb.muse.w24.earthsong.020"] = {
		"Earth Mother, watch over the Horde's sons and daughters out in Ashenvale. I say it here, where they tell me you listen best.",
		"For the ones fighting far from these mesas: may the tauren's spirits keep an eye on them too. We need every friend we have.",
	},
	["thb.muse.w24.earthsong.021"] = {
		"An elder told me the bluffs are young, as the Earth Mother counts things, and the tauren younger still. She said it kindly, the way you'd remind a proud calf how small its horns are.",
		"'Before the mesas, she was. After them, she will be,' an old tauren said of the Earth Mother, and went back to shelling beans as if he'd remarked on the beans.",
	},
	["thb.muse.w24.earthsong.022"] = {
		"If the spirits are listening: I'd like a sign. A small one. A dry blanket would do.",
		"Spirits of this place, I'm told you hear everything. Sorry about the grumbling on the lift.",
	},
	["thb.muse.w24.elder.001"] = {
		"An elder on the bench by the path has been getting up for some time now. First the hands, then a long think, then the knees. I've decided not to offer help; it would only slow her down.",
		"Watching a tauren elder rise from sitting is like watching a mesa decide to move. It happens in stages, and every stage gets its own grunt.",
		"Old tauren have a way of sitting down, too: a long lean, a hand on the bench, a pause halfway, and then the arrival, like a heavy pack set down by careful hands.",
	},
	["thb.muse.w24.elder.002"] = {
		"stops to watch an elder undo a young tauren's knot on a bundle and tie it again, without a word, slowly, so the young one can follow every turn of the cord.",
		"notices an old tauren reach over and quietly retie the cord on a young hunter's quiver, then go back to looking at nothing in particular.",
	},
	["thb.muse.w24.elder.003"] = {
		"I asked an elder how old she was. She thought about it so long the question began to feel rude, then said she had stopped counting summers and started counting herds.",
		"One elder measures his age in the herds he has followed, not in years, or so he told me. He lost count somewhere past forty and seemed pleased about it.",
		"An elder told me she was born in the year the herds came late. When I asked which year that was, she looked at me with real pity.",
	},
	["thb.muse.w24.elder.004"] = {
		"There's an old tauren who sits in the same spot each time I pass, eyes half closed. I thought he was asleep until he lifted a finger to point out a hawk I hadn't seen.",
		"That elder with the half-shut eyes isn't dozing. I went by too quickly once and got a low 'slower' without him moving at all.",
	},
	["thb.muse.w24.elder.005"] = {
		"I asked an elder a quick question. I've had the first half of the answer. I'll come back for the rest.",
		"Never ask a tauren elder for directions if you're in a hurry. You'll get the way, and the history of the way.",
		"Asked an elder whether the path ahead was steep. The answer began with her grandfather.",
	},
	["thb.muse.w24.elder.006"] = {
		"notices the tips of an old tauren's horns, worn blunt and pale, polished by a lifetime of ducking under lodge poles.",
		"looks at an elder's horns: one chipped and bound with a thin band of copper, the other whole, both gone the color of old bone.",
		"sees a pair of old horns hung with tiny bone charms that knock together softly whenever the elder turns to look at something.",
	},
	["thb.muse.w24.elder.007"] = {
		"Some of the oldest tauren up here walk with a limp they never mention. I've stopped wondering which raid on the plains gave it to them.",
		"By the path, an elder keeps one hand pressed to an old scar on his flank when he stands. Nobody asks about it, and neither will I.",
	},
	["thb.muse.w24.elder.008"] = {
		"Two elders are arguing on the next bench. Each speaks, then there's a silence long enough to plant something in, then the other answers. They may finish next season.",
		"I've found the slowest argument in Kalimdor: two old tauren disagreeing about where a river used to run. Neither has raised a voice, and neither will give an inch.",
		"Tauren elders argue the way water wears down a plain: no noise, no hurry, and in the end someone's position is simply gone.",
	},
	["thb.muse.w24.elder.009"] = {
		"waits at the edge of a circle of elders here on Elder Rise. The one speaking has stopped mid-sentence, and nobody fills the gap; the pause, it seems, is part of the speech.",
		"lingers near the elders gathered on Elder Rise, close enough to hear the low voices and no closer, and catches the sound of their talk without any of its sense.",
	},
	["thb.muse.w24.elder.010"] = {
		"Our elders never tell you you're wrong. They ask you a question, and wait while you find it out yourself.",
		"When our elders go quiet at something you've said, that is the whole reproach. It is enough. It was always enough.",
	},
	["thb.muse.w24.elder.011"] = {
		"Take your time, elder. I'll hold the flap until you're through.",
		"No hurry. The door isn't going anywhere, and neither am I.",
	},
	["thb.muse.w24.elder.012"] = {
		"An elder I pass sometimes sets down whatever she's carrying, halfway along, just to look at the plain. Then she picks it up and goes on. I've started stopping too.",
		"There's a habit among the old ones I've caught: setting the load down halfway, for no reason, for a look. Nothing is lost by it. I'm not sure why it took me so long.",
	},
	["thb.muse.w24.elder.013"] = {
		"The oldest tauren in sight has been watching me tie a strap for a while. He hasn't said anything. He doesn't need to. I'm doing it over, properly.",
		"A white-muzzled tauren looked at my pack, then at me, then back at the pack, and walked on. I've repacked it twice since.",
		"Somebody's grandfather corrected the way I was holding a cup by turning my hand a little, saying nothing, and walking on. The cup does sit better now.",
	},
	["thb.muse.w24.elder.014"] = {
		"sees an old tauren hand a small carved charm to a passing calf, who holds it up, turns it over, and runs off forgetting to say thanks. The elder doesn't seem to mind.",
		"spots a white-muzzled elder slip a strip of dried meat to a hunter's cat lying by the path, then glance around as if nobody should know.",
		"catches an elder stopping a running calf with one raised finger, bending down to straighten the little one's beads, and letting it go off at full speed.",
	},
	["thb.muse.w24.elder.015"] = {
		"Elders here sometimes look out over the plain for a long while and then shake their heads, very slightly. Whatever they're seeing, it isn't what's down there now.",
		"There's a look the old tauren get when they stand at the rim: not at the grass, but past it, at something that used to be there.",
		"Once in a while an elder stops talking in the middle of a story and simply sits. The others let the silence keep the absent company.",
	},
	["thb.muse.w24.elder.016"] = {
		"I've seen tauren elders nap standing up. I can't decide if it's wisdom or a very good trick.",
		"That old one has been asleep on her feet for a while now, and nobody's knocked her over. Impressive.",
	},
	["thb.muse.w24.elder.017"] = {
		"Late, with the city mostly quiet, a few elders are still awake, sitting apart, each with a blanket around the shoulders. They don't talk. Keeping watch with nothing to watch for, as old people do.",
		"At this hour only the elders seem to be up, a handful of humped shapes on the benches, blankets up to the horns. I like knowing they're there.",
	},
	["thb.muse.w24.elder.018"] = {
		"An elder's laugh arrives late. The joke is told, everyone else has finished, and then it comes up out of him slowly, like water from a deep well, and sets everyone off once more.",
		"Old tauren laugh last and longest. By the time it reaches the surface, the joke has been forgotten by everyone else, and somehow it's funnier.",
		"I made an old tauren laugh once. It took a while to arrive, but when it did the bench shook, and I felt I'd been handed something.",
	},
	["thb.muse.w24.elder.019"] = {
		"Slowly, elder, slowly. I'll match your pace; I need the practice.",
		"If I walk any slower beside you, I'll start going backward. Lead on.",
	},
	["thb.muse.w24.elder.020"] = {
		"I'd like to be that calm at that age. I'd like to be that calm now, honestly.",
		"There's more patience on that one bench than in all of Orgrimmar.",
	},
	["thb.muse.w24.errand.001"] = {
		"Walked to the bank to fetch one thing. Stood at the counter rearranging everything else instead. Left without the one thing.",
		"My bank box is a museum of things I might need someday. Someday keeps not arriving.",
	},
	["thb.muse.w24.errand.002"] = {
		"leans over the auction list, runs a finger down the bids, and makes the small sound of someone outbid by a single copper.",
		"checks the auctions for the third time in a short while, as if the bids might have grown out of politeness.",
	},
	["thb.muse.w24.errand.003"] = {
		"Nobody's bought my wolf pelts. Fine. They'll be worth more when they're antiques.",
		"Three days on the auction block and not one bid. I'm starting to take it personally.",
		"If anyone wants a slightly chewed pair of boots, the auctioneer has them. Make an offer. Any offer.",
	},
	["thb.muse.w24.errand.004"] = {
		"Coin counted, questions rehearsed. The trainer listens to all of them and answers a different one, which turns out to be the one that mattered.",
		"Every visit to a trainer up here costs two things: the price, and the time it takes me to stop fidgeting long enough to learn.",
	},
	["thb.muse.w24.errand.005"] = {
		"empties a pack of odds and ends onto a merchant's blanket, and the tauren sorts through them one by one without comment, which somehow makes them look worse.",
		"sells off a heap of cracked teeth and torn pelts, and pockets the coins with the look of someone who had hoped for a little more for the teeth.",
	},
	["thb.muse.w24.errand.006"] = {
		"Can you mend these boots? I'd like to walk out of here on both of them.",
		"My gear is held together with hope and a bit of string. The string's giving out first.",
		"Stitch it, patch it, glue it. I'm not proud. I just don't want to lose a sole halfway across.",
	},
	["thb.muse.w24.errand.007"] = {
		"Every bag full, and still I picked up that feather. Some lessons don't take.",
		"Nine pockets, four pouches and a pack, and not one of them has room for the thing I just bought.",
	},
	["thb.muse.w24.errand.008"] = {
		"I asked the innkeeper to make this the place I come back to. One word and a nod, and the little stone in my pocket feels heavier, as if it knows.",
		"With a word, my hearthstone is tied to this place. Wherever I go next, a small part of me will know the way back up the cliff.",
	},
	["thb.muse.w24.errand.009"] = {
		"waits behind a tauren at the bank who is depositing a single item with the care of someone burying a friend.",
		"stands in line at the bank while the tauren ahead explains, at length and with pauses, exactly why that particular hide must go on the left.",
	},
	["thb.muse.w24.errand.010"] = {
		"Is there a corner free? I don't need much. I'll fold up small.",
		"Somewhere to sit and something to eat. In that order, or the other one. I'm not fussy.",
	},
	["thb.muse.w24.errand.011"] = {
		"I crossed all the way to Hunter Rise for a single strap. Two hunters were debating feathers by the stall. I now know a great deal about feathers. I have no strap.",
		"Hunter Rise, errand number three. Everyone here looks at my boots before my face. I should have cleaned the boots.",
	},
	["thb.muse.w24.errand.012"] = {
		"Bank, trainer, food, mending. Four errands, three rises. This city was laid out by someone with very long legs.",
		"My list says buy thread. The thread is on the far rise. The list didn't mention that.",
		"Every errand here comes with a crossing attached. I'm getting very good at errands and very tired of crossings.",
	},
	["thb.muse.w24.errand.013"] = {
		"Trainer paid, boots mended, pack sorted. What's left of my coin fits in one hand, and the hand still feels richer than it did on the way up.",
		"Money moves faster in this city than anything else does. Everything else here takes its time.",
	},
	["thb.muse.w24.errand.014"] = {
		"steps away from the trainer flexing {g:his|her} fingers, the way one does after being shown, very patiently, that one has been doing it wrong for a long while.",
		"leaves the trainer with a new trick and a faint frown, already doubting {g:he|she} could do it twice.",
	},
	["thb.muse.w24.errand.015"] = {
		"In line at the bank behind an orc, a troll and a Forsaken. Nobody pushes. The tauren behind the counter has that effect, even on orcs.",
		"The bank line up here is the most peaceful gathering of the Horde I've ever seen. Nobody wants to be the one who hurries the counting.",
		"An orc at the bank tapped the counter once, impatiently. The tauren looked at the finger until it stopped. That was the whole conversation.",
	},
	["thb.muse.w24.errand.016"] = {
		"tucks a fresh bundle of dried meat into the pack, then takes it out again to check it really is as large as it looked at the stall.",
		"pays for a small bag of dried berries and is handed what is plainly a large one, with a look that dares {g:him|her} to argue.",
	},
	["thb.muse.w24.errand.017"] = {
		"Down here in the Pools of Vision a Forsaken sells me what I need and counts out my change in the damp half dark, as calm as if this cave were a market square.",
		"Shopping in the Pools of Vision: still water, cold stone, and a Forsaken vendor who seems to find the gloom restful. Of the two of them, only the vendor looks at ease.",
	},
	["thb.muse.w24.errand.018"] = {
		"Teach me whatever comes next. Slowly, please. I've noticed nobody here does anything fast.",
		"I've brought the coin and the patience. Mostly the coin.",
	},
	["thb.muse.w24.errand.019"] = {
		"I've never seen where the bank keeps things. I hand them over, they vanish behind a hide curtain, and they come back exactly as they left. I've decided not to ask.",
		"Whatever I leave at the bank comes back folded. I didn't fold it.",
		"Somewhere behind the banker's curtain lies everything I own that I can't carry. I picture it in neat stacks, being kept company.",
	},
	["thb.muse.w24.errand.020"] = {
		"watches a tauren at the auction house take so long over a bid that someone else wins it, and the tauren nods as if that had been the plan all along.",
		"lingers by the auctioneer long enough to hear a Forsaken and an orc bid against each other for a single bolt of cloth, neither willing to lose to the other.",
	},
	["thb.muse.w24.errand.021"] = {
		"Is this bowl part of the room, or a gift? With tauren I can never tell where the price stops.",
		"How much for the room? Oh. And the food? Oh. You'll have to let me pay for something.",
		"I came to settle my bill and somehow I owe less than when I arrived. Explain that, please. Slowly.",
	},
	["thb.muse.w24.errand.022"] = {
		"Waiting for the trainer to finish with the student before me. The student is a tauren. This may take some time.",
		"A queue at the trainer: two tauren and an orc. The orc keeps shifting from foot to foot. The tauren haven't moved since I got here.",
	},
	["thb.muse.w24.errand.023"] = {
		"Coin in the bank, a lesson learned, a hot meal down. Good visit.",
		"Everything's done: banked, trained, fed, mended. I don't know what to do with my hands now.",
	},
	["thb.muse.w24.errand.024"] = {
		"Storm on the bluff, so everyone's crowded under the eaves by the auction house, suddenly fascinated by the bids.",
		"Nothing like a storm to fill the bank. Suddenly everyone has urgent business with their savings.",
	},
	["thb.muse.w24.farsight.001"] = {
		"The roads of Mulgore are pale threads seen from the rim, and you can tell where each one gives up and becomes a path, then a trail, then just a kinder line in the grass.",
		"The trails across the plain look drawn by a hand that kept lifting the pen: firm near the lifts, fainter and fainter until the grass takes them back.",
	},
	["thb.muse.w24.farsight.002"] = {
		"I picked out a single traveler on the road below and watched for what felt like an hour. They hadn't moved. Or the plain had moved with them.",
		"A dot sits on the long road toward the lifts. I've been watching it a while, and as far as I can tell it's walking in place.",
	},
	["thb.muse.w24.farsight.003"] = {
		"You can find the streams of Mulgore from the rim even where the water doesn't show: the grass runs darker and greener along them, like a vein under skin.",
		"The creeks themselves are hidden from this height, only the green they leave behind, a deeper thread winding through the paler plain toward somewhere I can't see.",
		"Willows, or something like them, mark where the water runs: a crooked line of darker crowns wandering across the grass.",
	},
	["thb.muse.w24.farsight.004"] = {
		"Stonebull Lake shows from here as a pale patch the shape of a hoofprint, the only flat thing in all that rolling green.",
		"Find the place where the plain dips and holds something flat and pale: that's Stonebull Lake, small as a spoon from this far up.",
	},
	["thb.muse.w24.farsight.005"] = {
		"picks out a single thread of smoke far out on the plain and stays watching it, trying to guess whose fire it is and what is cooking on it.",
		"follows a thin line of smoke rising from a camp somewhere in the far grass, the only sign for leagues that anyone is out there at all.",
	},
	["thb.muse.w24.farsight.006"] = {
		"Out past the farms there's a patch of plain where the grass is trampled flat and brown. A Bluffwatcher pointed at it and said one word: gnolls. The story needed nothing more.",
		"Some of the brown on the plain isn't the season. A brave beside me named the patches one by one: quilboar there, gnolls there. She didn't raise her voice for any of them.",
	},
	["thb.muse.w24.farsight.007"] = {
		"On the far edge of everything, past the last of the green, the hills go blue and then bluer, and behind them stand peaks that must be Stonetalon. They never come closer, however long I stare.",
		"The farthest thing in view is a row of mountains to the northwest, gone pale with distance. A tauren beside me called them Stonetalon, as if naming an old friend's house.",
		"Look north and west long enough and the land climbs in steps, green, darker green, blue, and the last step is mountains so faint they could be a trick of the eye.",
	},
	["thb.muse.w24.farsight.008"] = {
		"Each time I come up here the plain is a different green: fresh and almost yellow, then deep, then going to straw at the edges. The city stays the same; the view below keeps changing its clothes.",
		"The grass below never holds one color for long. I've seen it the green of new peas, the green of old moss, and a tired gold, and each time it looked as if it had always been so.",
	},
	["thb.muse.w24.farsight.009"] = {
		"Mulgore looks exactly like a map from the rim, except that nobody has bothered to write the names on, and the paper keeps rippling.",
		"I can see the whole plain at once and still couldn't tell you which hill is which. It's a map with every label scraped off.",
	},
	["thb.muse.w24.farsight.010"] = {
		"watches a tiny cart crawl along the road toward the lifts, so slowly that it seems painted on the plain, until a glance away and back finds it a little further on.",
		"picks out a little file of travelers and pack beasts creeping across the plain, each of them no bigger than a grain of rice at this distance.",
		"observes two travelers meet on the road below, stop, and stand together a long while, small as ants, then part, each going on the way the other came.",
	},
	["thb.muse.w24.farsight.011"] = {
		"Away across the plain there's a reddish huddle of stone. The Red Rocks, a tauren beside me said, and lowered her eyes a little. I didn't ask more.",
		"Even from this height the Red Rocks stand out, a rust-colored knot in the green. The tauren glance toward them the way one glances toward a grave on a hill: briefly, and often.",
	},
	["thb.muse.w24.farsight.012"] = {
		"Where the herds have grazed, the plain is shorn paler, in big uneven patches, like a head cut by someone who kept getting distracted.",
		"The grass below is all patchwork: long and dark where nothing has eaten it, cropped and light where something has. Mulgore wears its meals.",
		"A darker square of green below marks somebody's field, the only straight edge on the whole plain. It looks almost rude.",
	},
	["thb.muse.w24.farsight.013"] = {
		"A whole day's walk out there fits between my thumb and finger.",
		"Hold up a hand and one thumb covers a village. Very satisfying. Very rude.",
	},
	["thb.muse.w24.farsight.014"] = {
		"Everything I can see on the plain is moving, grass and birds and a far cart, and not a sound of it reaches the rim. Mulgore from here is a story told in mime.",
		"All that life down there, and not one noise of it climbs this high. It's like watching the world through a closed window.",
	},
	["thb.muse.w24.farsight.015"] = {
		"In the dark the plain is gone, all of it, except a few small fires scattered far apart. I count them like a herder counting heads, and feel better when the number holds.",
		"Night has taken Mulgore away and left only its fires, five or six, very small and very far. Each one is someone keeping watch, or someone keeping warm.",
	},
	["thb.muse.w24.farsight.016"] = {
		"From the rim I saw this rain coming across Mulgore long before it got here: a gray curtain dragging over the grass, darkening it stripe by stripe.",
		"The rain walked across the plain toward the city like a slow gray herd, and I could watch the grass go dark under every step of it.",
	},
	["thb.muse.w24.farsight.017"] = {
		"The air is so clear that the far side of the plain has come up close: single trees, a white stone, the ring of a well, each one sharp as a stitch.",
		"Nothing hazes the distance. I can pick out a lone tree on a ridge so far off it ought to be a rumor.",
	},
	["thb.muse.w24.farsight.018"] = {
		"narrows {g:his|her} eyes at the far plain, tracing a ridge line from one end of the view to the other as if committing it to memory.",
		"stays at the edge running a slow gaze along the horizon, from the farthest hill on one side to the farthest on the other, without hurrying any of it.",
	},
	["thb.muse.w24.farsight.019"] = {
		"Down on the plain a tiny figure is creeping up on an even tinier beast. From the rim I can see what the hunter can't: the beast has noticed, and is creeping away at the same speed.",
		"I've been watching someone far below stalk something through the grass for ages. Neither of them has any idea I'm rooting for both.",
	},
	["thb.muse.w24.farsight.020"] = {
		"Even now the eye can trace, from the rim, the old routes the herds followed, the ones my people walked behind for generations. They are still there in the grass, if you know how to look, like the lines of an old palm.",
		"The whole of the land my people wandered for so long fits inside one look from up here. It took them lifetimes to cross what my eyes cross in a moment.",
	},
	["thb.muse.w24.farsight.021"] = {
		"The horizon is so long and so level from here that I keep imagining I can see it curve at the ends, like the rim of a bowl.",
		"Look far enough in any direction and the land and the sky stop arguing about where one ends. Out at the very edge they simply agree to blur.",
	},
	["thb.muse.w24.farsight.022"] = {
		"listens while an old tauren beside {g:him|her} points across the plain with a long finger, naming hills one after another in a slow voice, as if introducing relatives.",
		"is shown the plain by a tauren who happens to be standing nearby: a nod toward a ridge, a nod toward a dip, a name for each, and then a satisfied silence.",
	},
	["thb.muse.w24.farsight.023"] = {
		"Is that smoke out there a camp or a grass fire? I'll say camp. It's the nicer thought.",
		"Someone's cooking out on the plain. Can't see who, but that smoke has the look of a meal.",
	},
	["thb.muse.w24.farsight.024"] = {
		"All that green and not a soul in sight. Mulgore is very good at hiding people.",
		"There must be hundreds of folk down there. Seen from the rim it's grass, grass, a tree, more grass.",
	},
	["thb.muse.w24.farsight.025"] = {
		"There's too much sky here. Someone should fold some of it up and put it away.",
		"So much sky over this city. It's like living under an upturned lake.",
	},
	["thb.muse.w24.greeting.001"] = {
		"Tauren greet without hurry. One I passed stopped, faced me square, lowered her head a little so the horns turned aside, and only then said hello. It took a moment. It felt like being properly seen.",
		"When a tauren greets you, the horns tip aside first, away from you. Somebody explained it to me once: you show a stranger the side of your head that isn't for fighting.",
	},
	["thb.muse.w24.greeting.002"] = {
		"watches two tauren meet on the path and press foreheads briefly, horn beside horn, before stepping apart and talking about nothing much.",
		"sees two old friends greet each other with a slow touch of brow to brow, eyes closed, as though comparing the years without a word.",
	},
	["thb.muse.w24.greeting.003"] = {
		"I said a quick hello to a tauren in passing. He stopped, turned, and gave it back in full, with my name, the weather and a question about my road. I'm learning not to throw greetings around lightly.",
		"A greeting here is a whole exchange, not a word tossed over the shoulder. Toss one anyway and you'll be standing there a while, catching what comes back.",
		"After the greeting, a tauren asked after my health and then waited for a real answer. I had to think about it.",
	},
	["thb.muse.w24.greeting.004"] = {
		"And to you. Take all the time you like.",
		"Greetings. No, no hurry, set down what you're carrying first.",
		"Hello to you too. Tell me the rest slowly; I'm listening.",
	},
	["thb.muse.w24.greeting.005"] = {
		"I've been trying the tauren way of saying hello, the stop and the tilt of the head, and I keep forgetting I've no horns to tilt. They're kind enough to answer anyway.",
		"My greeting came back from a tauren with the little sideways dip of the horns, and I answered by dipping my head the same way. It looked odd without horns. She smiled all the same.",
	},
	["thb.muse.w24.greeting.006"] = {
		"is listened to by a tauren with such complete attention, ears turned forward and head still, that {g:he|she} loses the thread of what {g:he|she} was saying.",
		"finds {g:himself|herself} talking more slowly to the tauren in front of {g:him|her}, who simply waits, unhurried, until every word has arrived.",
	},
	["thb.muse.w24.greeting.007"] = {
		"Tauren laughter is something you feel through the planks before you hear it. Somebody nearby just found something very funny, and my feet know about it.",
		"A big tauren laugh starts low in the chest and takes the whole body with it. Three of them laughing together, and the nearest tent pole starts to hum.",
	},
	["thb.muse.w24.greeting.008"] = {
		"Tauren eat slowly, and they eat together. I've yet to see one eat walking. Even a strip of jerky gets a seat, a look at the plain, and a word to whoever's near.",
		"Nobody up here eats on the move. A tauren with a bit of bread will stop, sit, offer half to whoever's closest, and only then begin.",
		"Alone on a bench, a tauren eating kept glancing up at each passerby, half a loaf held ready, in case anyone wanted company.",
	},
	["thb.muse.w24.greeting.009"] = {
		"makes way for a tauren carrying a whole boar across both shoulders, who stops to chat with a neighbor for some while without setting it down, then moves on.",
		"spots a tauren with a rolled hide over one shoulder, a basket on the other arm and a calf on the back pause to greet someone and somehow find a hand free to wave.",
	},
	["thb.muse.w24.greeting.010"] = {
		"When a tauren says your name, it comes out slower than you've ever heard it, as if each sound were being set down carefully on a table.",
		"I didn't know how fast I talk until a tauren repeated my question back to me at their own pace. It sounded wiser. It wasn't.",
	},
	["thb.muse.w24.greeting.011"] = {
		"Guests always rush their greetings. I don't mind; I give mine slowly anyway, all of it, and watch them slow down to catch it. The bluff teaches without lessons.",
		"A stranger's quick hello deserves a full answer. That's how our elders did it, and on this bluff it's how I'll keep doing it.",
	},
	["thb.muse.w24.greeting.012"] = {
		"Two tauren met on the path and spent so long greeting each other that a third came along and was included. I think the third was only trying to get past.",
		"A greeting started between two tauren by the path has grown. There are five of them now, plus a calf, and nobody can leave without starting the round over.",
	},
	["thb.muse.w24.greeting.013"] = {
		"receives a tauren's greeting in the form of a broad hand laid briefly on {g:his|her} shoulder, heavy and solid, the way one might steady a post.",
		"is greeted by a passing tauren with a hand laid flat on the chest and a slow nod, and returns it before {g:he|she} quite knows how.",
	},
	["thb.muse.w24.greeting.014"] = {
		"I said 'excuse me' and the tauren said 'of course' and we've now been apologizing at each other long enough to count as friends.",
		"Tauren manners are contagious. I just thanked a tent pole for holding still.",
	},
	["thb.muse.w24.greeting.015"] = {
		"Taking leave of a friend by the lift, a tauren used the same slow care as in greeting, every word in its place. If they never meet again, nothing will have been left unsaid.",
		"Tauren goodbyes take as long as their hellos. It seems slow, until I think of how many partings on the plains, as the elders tell it, had no time at all.",
	},
	["thb.muse.w24.greeting.016"] = {
		"Here on Hunter Rise greetings are shorter: a lift of the chin, a hand raised from the work. Hunters save their words the way they save their steps.",
		"On this rise the hunters greet each other with a glance and a grunt, and somehow nothing is missing from it.",
	},
	["thb.muse.w24.greeting.017"] = {
		"sits a while beside a tauren at the rim, neither of them speaking, the plain spread out below, until the tauren rises, touches {g:his|her} shoulder once, and goes, which seems to have been a conversation.",
		"shares the edge of the mesa with a silent tauren for a long spell, and when the tauren leaves, there is a nod that says the company was good.",
	},
	["thb.muse.w24.greeting.018"] = {
		"You let me finish the whole story. Nobody lets me finish. I like this city.",
		"Thanks for hearing all of that. Truly all of it. It doesn't happen to me often.",
	},
	["thb.muse.w24.greeting.019"] = {
		"Greetings, and the long version, since I've learned.",
		"I'm told the slow version is the polite one, so: greetings... to... you.",
	},
	["thb.muse.w24.greeting.020"] = {
		"Nobody's interrupted me since I got up here. It's unsettling. Somebody say something rude, please.",
		"A whole conversation and not one person talked over me. Careful, I could get used to this.",
	},
	["thb.muse.w24.grimtotem.001"] = {
		"Here on Elder Rise the elders speak of the High Chieftain fondly and of the Grimtotem carefully, and the gap between the two tones is wide enough to fall into.",
		"This rise holds the oldest voices in the city, and the most careful ones. Every mention of the Grimtotem here comes wrapped in courtesy, like something sharp.",
	},
	["thb.muse.w24.grimtotem.002"] = {
		"The Grimtotem are proud, the tauren say, in the tone people use for a cliff edge somebody keeps walking too close to.",
		"Proud is the word every tauren uses for the Grimtotem. It's never quite a compliment, and never quite anything else.",
	},
	["thb.muse.w24.grimtotem.003"] = {
		"notices the tauren beside {g:him|her} drop their voice to say the word Grimtotem, then glance toward Elder Rise as if the name might carry.",
		"sees a tauren merchant stop mid-sentence at the mention of the Grimtotem, look about, and pick the sentence up again a little more quietly.",
	},
	["thb.muse.w24.grimtotem.004"] = {
		"Of Magatha Grimtotem the tauren say only that she is very old and very wise. They say the wise part a little too carefully.",
		"Everyone here agrees Magatha is a great elder. They agree so quickly that it sounds rehearsed.",
	},
	["thb.muse.w24.grimtotem.005"] = {
		"I asked about the Grimtotem. The tauren started talking about the price of leather. Quite suddenly.",
		"Mention the Grimtotem and a whole circle of elders finds something fascinating about its own hooves.",
		"Funny. Nobody up here has an opinion about the Grimtotem. Not one. Loudly.",
	},
	["thb.muse.w24.grimtotem.006"] = {
		"Travelers say the Grimtotem out in Stonetalon are not friendly to strangers, Horde or not. The tauren here hear that news and say nothing, which says plenty.",
		"A hunter came up with a story about Grimtotem warriors turning travelers away in the far hills. The elders listened, nodded once, and asked how the road had been.",
	},
	["thb.muse.w24.grimtotem.007"] = {
		"Some tribes came to the city gladly, the elders say, and some came because the alternative was the centaur. Some, I gather, still remember which they were.",
		"Not every tribe climbed these bluffs with the same heart. Ask carefully and you'll hear it: those who came for the High Chieftain, and those who came for the cliffs.",
	},
	["thb.muse.w24.grimtotem.008"] = {
		"watches two elders fall silent as someone from Magatha's lodge passes, and take up the talk again only once the other is well out of hearing.",
		"sees a group of tauren on a bench make room, politely and at once, for a passing Grimtotem elder, and close the gap again just as quickly.",
	},
	["thb.muse.w24.grimtotem.009"] = {
		"There's an old rule among the tauren, I'm told: an elder's lodge is never questioned. The Grimtotem lodge seems to make a few of them wish otherwise.",
		"Every elder's lodge is honored here, no matter whose. Honoring one and trusting it, I'm starting to see, are two different things.",
	},
	["thb.muse.w24.grimtotem.010"] = {
		"Kin are not chosen, and the Grimtotem are our kin. I hold my tongue about them, as the elders do, and I watch.",
		"Every tribe on these bluffs is family of a sort, the Grimtotem too. That's what makes it hard to say what I think of them.",
	},
	["thb.muse.w24.grimtotem.011"] = {
		"Someone from Magatha's lodge just passed a Bluffwatcher on the planks. Both nodded. Neither nodded first.",
		"A Grimtotem and a guard, crossing paths: two perfect nods, timed to the instant. That's not friendship. That's diplomacy.",
	},
	["thb.muse.w24.grimtotem.012"] = {
		"The Grimtotem, the murmur goes, think the other tribes have gone soft beside their new friends. Watching a tauren carefully pour water for a Forsaken, I see what they mean, and I like it.",
		"Soft, the Grimtotem call the rest of the tauren, or so the talk says. If soft means sharing bread with orcs and the dead, this city could use more of it.",
	},
	["thb.muse.w24.grimtotem.013"] = {
		"hears an elder say, of nobody in particular, that some roots grow toward water and some toward stone, and sees every listener look toward Elder Rise.",
		"catches an old tauren's remark that a proud tree catches the most wind, and the small silence that follows it around the fire.",
		"hears an old shaman remark that pride is a heavy totem to carry up a cliff, and nobody ask whom the shaman means.",
	},
	["thb.muse.w24.grimtotem.014"] = {
		"Proud people, the Grimtotem. I'll keep my distance and my manners.",
		"Whatever goes on in that lodge on Elder Rise, it's tauren business. I'll mind mine.",
		"The Grimtotem? Not my lodge, not my quarrel.",
	},
	["thb.muse.w24.grimtotem.015"] = {
		"Nobody in this city will say a word against Magatha Grimtotem. That's the thing I keep noticing: how carefully nobody says it.",
		"Silence about someone can be a kind of respect. Up here, about the Grimtotem, it feels more like a held door that nobody wants to walk through.",
	},
	["thb.muse.w24.grimtotem.016"] = {
		"I've heard the Grimtotem kept to the old ways longer than most, and they seem to think that makes them the truest tauren. The other tribes don't argue. They just don't agree.",
		"There are tauren who believe the wandering made them strong and the city will make them weak. You hear it only in murmurs, and never near the High Chieftain's lodge.",
	},
	["thb.muse.w24.grimtotem.017"] = {
		"Every city has one family everyone is polite to. In this one it's the Grimtotem.",
		"Polite nods for the Grimtotem, warm ones for everybody else. I'm learning the difference.",
	},
	["thb.muse.w24.kiln.001"] = {
		"watches a potter build a jar from coils of clay laid one on another, then smooth the ridges away with a wet thumb until the coils vanish.",
		"crouches by a potter rolling ropes of red clay between two broad palms and winding them, round upon round, into the wall of a jar.",
		"follows a potter's thumb around the rim of a coiled pot, again and again, until the seam between the last two coils is gone.",
	},
	["thb.muse.w24.kiln.002"] = {
		"There's no great kiln up here, only a pit. The pots go in on a bed of bark and dried dung, more of it heaped over them, and the fire is left to sulk. They come out mottled black wherever the flame touched them.",
		"The potters bury their pots in a smoldering heap and leave them. A day later they dig them out, and every jar wears its own dark clouds where the fire leaned on it.",
		"A firing pit is a patient thing. The potter covers it, walks away, comes back, listens, walks away again. I've watched it a while and nothing has visibly happened, which I'm told is correct.",
	},
	["thb.muse.w24.kiln.003"] = {
		"admires the patience of a potter rubbing a dry jar with a smooth river pebble, round and round, until the dull clay takes on the gleam of polished horn.",
		"listens to the faint squeak of a stone worked over unfired clay, the potter's hand never pausing until the whole jar shines.",
	},
	["thb.muse.w24.kiln.004"] = {
		"Bought a pot. Carried it across a rope bridge. I've never held anything so carefully in my life.",
		"This jar is taller than some gnomes and it's for salt. Just salt.",
		"Don't touch the drying pots. I've now been told three times, each more politely than the last.",
	},
	["thb.muse.w24.kiln.005"] = {
		"The potters grind old broken jars into powder and knead it into the new clay. It keeps the walls from cracking in the fire, one says; another says it keeps the old pots in the family. Both, I suspect.",
		"Nothing broken is thrown out by the potters. The shards are pounded fine and worked into the next batch, so every jar up here has a bit of an older one inside it.",
	},
	["thb.muse.w24.kiln.006"] = {
		"stops at a trough where long reeds are soaking, and sees a basket maker pull one out, split it lengthwise with a thumbnail, and set the halves aside in perfect pairs.",
		"looks on while a tauren draws a soaked reed through a notch in a bone tool, shaving it to an even width, then reaches for the next without looking.",
		"crouches to look at the base of a half-made basket, a spiral of split reeds tighter than anything {g:he|she} could weave in twice the time.",
	},
	["thb.muse.w24.kiln.007"] = {
		"The big carrying baskets here have a strap that goes across the brow, not the shoulders. A tauren just walked past me with a stack of pots hanging from her forehead, chatting the whole way.",
		"Burden baskets with a band across the brow: the tauren carry half their goods with their necks. I tried one, empty. My neck has filed a complaint.",
		"A basket maker weaves a carrying band thick and soft as a folded blanket. Whoever wears this one, she says, will be carrying all day and should not be sorry for it.",
	},
	["thb.muse.w24.kiln.008"] = {
		"The red clay, a potter says, comes from the banks of a stream far below, carried up in baskets. Every jar on the bluff started as a muddy walk.",
		"Clay doesn't grow on mesas. Someone dug this from a streambank on the plain, hauled it up the cliffs, and is now very calmly turning it into a soup pot.",
		"Every bowl in this city was once mud at the bottom of Mulgore, hauled up the cliffs in a basket by somebody with strong shoulders.",
	},
	["thb.muse.w24.kiln.009"] = {
		"Every potter presses a mark into the base of a jar before it dries: a thumbprint, a row of dots made with a twig, a twist of cord rolled into the wet clay. Turn any pot over and you can tell whose hands it came from, if you know the marks.",
		"I turned a bowl over at a stall and found a small spiral pressed into the bottom. The merchant named the potter at once, and smiled, as if I'd asked after a friend.",
	},
	["thb.muse.w24.kiln.010"] = {
		"waits as a potter unhurriedly draws a hide over a row of unfired jars while the first drops fall, tucking the edges under like a blanket over sleepers.",
		"sees the potters cover their drying jars against the rain without any hurry, as though the clay and the weather came to an arrangement long ago.",
	},
	["thb.muse.w24.kiln.011"] = {
		"Freshly fired pots ping and tick as they cool, small bright sounds like a fingernail against a cup. The potter sits among them, listening. A cracked one, she says, sounds wrong.",
		"Beside a heap of cooling jars I listened to them click and chime. One went dull. The potter lifted it out without a word and set it apart.",
	},
	["thb.muse.w24.kiln.012"] = {
		"Grain in clay jars sealed with wax and a lid of hide. Somewhere nearby, a very disappointed mouse.",
		"The storage jars here are sealed so well that, I'm told, a mouse once lived beside one for a whole season and never found out what was inside.",
	},
	["thb.muse.w24.kiln.013"] = {
		"pauses near an old basket maker who has set down a half-woven basket to argue happily with a neighbor, and whose fingers keep weaving the air out of habit.",
		"notices an elder's cracked, enormous fingers splitting willow faster than {g:he|she} can follow, while the elder looks the other way, talking.",
	},
	["thb.muse.w24.kiln.014"] = {
		"Tauren pots turn up in Orgrimmar too, in the corner of every orc kitchen that cares about its water. Our allies make things that last, and trade them to us at fair prices. A Horde could do worse.",
		"Half the water jars in the Horde's camps came down these cliffs in a tauren's basket. An ally who sends pots instead of speeches is one worth keeping.",
	},
	["thb.muse.w24.kiln.015"] = {
		"A potter told me the clay listens to the mood of the hands. On a bad day she doesn't work at all. I can't think of anything I do that is that honest about me.",
		"The potters don't work clay when they're angry, one says. The jar would remember. I think of everything I've done in anger, and wonder what remembers that.",
	},
	["thb.muse.w24.kiln.016"] = {
		"A pot this good shouldn't be used for beans. I'm going to use it for beans.",
		"How long does a jar like this last, I wondered aloud. The potter answered with a shrug that went on for several generations.",
	},
	["thb.muse.w24.kiln.017"] = {
		"A finished basket is tested by being sat on, apparently. The basket maker sat on this one, and it held, and so did my opinion of tauren basketry.",
		"The basket maker's test is simple: she sets the basket down and stands on it. Since she is a tauren, that's quite a test.",
	},
	["thb.muse.w24.kiln.018"] = {
		"waits while a potter scrapes clean a set of shaping tools, a rib of bone, a shell, a smooth paddle, and lays them out in the order they were used.",
		"notices the potter's tools drying in a row on a cloth: a shell, a flat stick, a bone rib, each worn to fit one particular grip.",
	},
	["thb.muse.w24.lashing.001"] = {
		"watches a tauren wet a strip of rawhide in a bowl, bind it tight around the joint of two poles, and leave it to shrink as it dries, harder than any nail.",
		"stops beside a tauren binding a crossbar with a long strip of soaked hide, wrapping it around and around and tucking the end under with a thumb.",
		"looks on as a tauren ties off a lashing and then pours a little water over the knot from a gourd, like someone watering a plant.",
	},
	["thb.muse.w24.lashing.002"] = {
		"No nails anywhere in this city, as far as I can find. Everything is bound, pegged or wedged. If something works loose, you can see exactly where, and fix it with your hands.",
		"I went looking for a nail in Thunder Bluff and found none. Knots, pegs, wedges. A city you could take apart with patience and put back the same.",
		"Every joint of every frame up here is a knot someone could untie. I find that oddly comforting, like a lock with the key left in it.",
	},
	["thb.muse.w24.lashing.003"] = {
		"The knots here all look alike until you stare at them long enough. Then you start to see hands: one tauren finishes with a double turn, another tucks the tail under, a third leaves it long.",
		"Each lashing on this rise ends a little differently. I think you could tell who tied it, if you knew the hands.",
		"I watched a tauren retie a lashing someone else had made, and tie it exactly the same way, as if out of respect for the first hands.",
	},
	["thb.muse.w24.lashing.004"] = {
		"I trust that knot. I don't know why. It's bigger than my head.",
		"If that rope ever snaps, I want it known that I never said a rude word about it.",
		"That rope has held through more gusts than I've had hot meals. I salute it.",
	},
	["thb.muse.w24.lashing.005"] = {
		"sees a Bluffwatcher stop midway across, run one hand down a guide rope the way a herder feels a kodo's leg for heat, and walk on without a word.",
		"notices a passing tauren give one tug to a rope where it meets its post, listen to it, and nod.",
	},
	["thb.muse.w24.lashing.006"] = {
		"Somebody in this city must do nothing but rope: make it, check it, replace it. I'd like to shake that hand, very respectfully.",
		"There must be more rope on these mesas than in every port of Kalimdor put together, and not one sailor to boast about it.",
	},
	["thb.muse.w24.lashing.007"] = {
		"The rope here isn't hemp. It's twisted from long grass and strips of hide, three strands, and it smells faintly of the plain it came from.",
		"Pull a strand loose from an old rope and it's grass, plain grass from Mulgore, twisted so hard it has forgotten it ever bent in a breeze.",
		"New rope is pale and smells green. Old rope is brown and smells of smoke. Between the two lie a few seasons in the open.",
	},
	["thb.muse.w24.lashing.008"] = {
		"steps around two tauren splicing a rope across their knees, one holding, one working the strands in, neither of them speaking.",
		"pauses where an old rope lies stretched along the path while a tauren works a fresh length into it, strand under strand.",
		"watches a frayed end being whipped with fine sinew, wound so close and even that the rope seems to grow a neat little cap.",
	},
	["thb.muse.w24.lashing.009"] = {
		"The lashings here on Elder Rise are dark with age and smoke, gone hard as horn. Nobody has replaced them because nobody has needed to.",
		"On Elder Rise even the knots look old: black, glossy, shrunk into the wood until you can't tell where the rope ends and the pole begins.",
	},
	["thb.muse.w24.lashing.010"] = {
		"In the rain every rawhide lashing in the city goes slack and dark at once. The tauren leave them be. They'll tighten as they dry, and the whole city will creak while they do.",
		"Wet rawhide stretches, dry rawhide shrinks. In this rain the lashings are all loosening a little, and nobody seems worried.",
	},
	["thb.muse.w24.lashing.011"] = {
		"Look at that lashing. Not a single loose turn. I couldn't lace my boots that neatly.",
		"Whoever bound that post knew what they were about. I'd let those hands tie my pack.",
		"Three turns, a tuck and a pull. I watched that done twice and I still couldn't tell you how.",
	},
	["thb.muse.w24.lashing.012"] = {
		"I never think about rope until I'm standing on some. Then I think about nothing else: how many strands, how old, who tied it, and whether they were in a good mood that day.",
		"Halfway across, my mind always goes to the knots at the far end. Whoever tied them, I hope they'd had a good breakfast first.",
	},
	["thb.muse.w24.lashing.013"] = {
		"notices a small bird tugging at the frayed end of a tent rope, pulling out fibers for a nest while whoever strung the rope pretends not to see.",
		"follows a bird as it works a loose strand out of a lashing and flies off with it, one city's repair becoming another's roof.",
		"spots a tuft of rope fiber woven into a nest wedged under a crossbar: the bird has taken its share of the city's mending.",
	},
	["thb.muse.w24.lashing.014"] = {
		"A tauren told me the knots on the tent ropes are the old traveling knots, the ones that held when the tribes moved with the herds. They go on in a moment and come off with one pull.",
		"The tent ropes still use the knots of the road, I'm told: quick to tie, quick to free, made for a people who might follow the herds before the fire had gone cold.",
		"One knot on the tents is called the herd knot, a tauren told me, because it holds firm while it's pulled and lets go the moment you ask it kindly.",
	},
	["thb.muse.w24.lashing.015"] = {
		"I finally watched the lifts properly. As one platform climbs, the other sinks, like the two pans of a scale. The tauren didn't build a lift so much as a balance.",
		"Riding up, you pass the other platform coming down, halfway along the cliff, close enough to nod to whoever's on it. Each one pulls the other.",
		"High over the lifts a great wooden wheel takes the ropes. From the bottom you only see it twitch; from the top you can hear it grumble.",
	},
	["thb.muse.w24.lashing.016"] = {
		"watches the lift operator at the top lean on a long wooden lever, and far below a platform shudders and begins to move.",
		"spots a tauren at the head of the lift checking the ropes hand over hand, one long pass before the next load goes down.",
		"watches a tauren at the top of the lift lay a palm flat on the moving rope, feeling for something only hands can tell, then nod for the next load.",
	},
	["thb.muse.w24.lashing.017"] = {
		"I've worked out how the lift works. Someone heavier than me is going down. Thank you, stranger.",
		"So the lift goes up because the other one goes down. Somebody down there is doing me a favor and doesn't know it.",
		"Every time the lift starts I hear the ropes take the weight. Like the cliff clearing its throat.",
	},
	["thb.muse.w24.lashing.018"] = {
		"Ropes as thick as my wrist run up the cliff beside the lift, and they don't hang slack: they thrum a little, taut as a fiddle string, whenever a platform moves.",
		"Stand close to the lift ropes when a load goes up and you can feel them through the rock, a low hum, as if the cliff itself were doing the work.",
		"The lift ropes are greased dark where they run over the top beam, and pale and fuzzy where they hang free. Even rope has a working side.",
	},
	["thb.muse.w24.ledge.001"] = {
		"peers over the lip of the rise at a narrow ledge a little way down the cliff, where a few stubborn tufts of grass grow and a bird has made a home of a hollow.",
		"leans out just far enough to see a shelf of rock below the rim, littered with feathers and small bones, the leavings of some bird that lives there.",
	},
	["thb.muse.w24.ledge.002"] = {
		"The rim of the rise isn't a clean edge. It's rounded, worn, crumbly, and for the last few steps it slopes a little toward the drop. The tauren keep well back of that slope. So do I.",
		"Near the drop the rock tilts outward, gently, as if the mesa were shrugging. I've noticed nobody stands on the tilted part.",
	},
	["thb.muse.w24.ledge.003"] = {
		"That ledge down there has a nest on it. Nobody built that bird a lift.",
		"Look, a shelf in the cliff with a little tree on it. Finest seat in the city, and no way to reach it.",
		"Somebody's lost a basket on that ledge below. It's been there long enough to grow grass.",
	},
	["thb.muse.w24.ledge.004"] = {
		"Where the path runs nearest the drop, the rock has been roughened with chisel strokes across it, so a hoof or a boot won't slide.",
		"Someone has cut shallow steps into the slope where the path dips toward the rim. Small, careful steps, the kind you cut after you've seen what a slip does.",
	},
	["thb.muse.w24.ledge.005"] = {
		"sits on a block of stone near the rim, worn into two shallow hollows by the many who sat in that exact place before.",
		"finds a seat at the edge of the rise on a ledge polished by long use, the stone dipped slightly where countless others have rested.",
	},
	["thb.muse.w24.ledge.006"] = {
		"The lodges near the edge are pegged twice as often as the ones in the middle. The builders didn't argue with the drop; they just tied everything tighter near it.",
		"Toward the rim the guy ropes double up and the stakes stand closer together. You can tell how near the drop is by counting pegs.",
	},
	["thb.muse.w24.ledge.007"] = {
		"Under the lip of the rock there's an overhang, and under the overhang, impossibly, someone has stacked firewood. Either the tauren climb down there, or they have very long arms.",
		"There's a coil of rope tied off to a peg at the very edge, hanging down out of sight. I'm not going to pull it up to see what's on the end. I respect a mystery.",
	},
	["thb.muse.w24.ledge.008"] = {
		"notices how the grass at the rim of the rise grows short and flattened, combed all one way, while a step back from the edge it stands up soft and tall.",
		"kneels at the edge, where tough little plants grow pressed flat against the rock, every leaf turned the same way.",
	},
	["thb.muse.w24.ledge.009"] = {
		"The shelves of rock down here by the Pools of Vision are slick with damp, and the path between the pools is so narrow you set each foot as if the water might take offense.",
		"In the Pools of Vision the rock shelves step down into the water like a stair nobody finished.",
	},
	["thb.muse.w24.ledge.010"] = {
		"A fresh scar marks the rim where a chunk of stone has broken away, the rock inside paler than the rest. The tauren have already moved a tent back from it.",
		"A piece of the edge has come away not long since, and the break is raw and pale. The bluff isn't going anywhere, and yet, very slowly, it is.",
	},
	["thb.muse.w24.ledge.011"] = {
		"Step back from there. That rock's been leaning out longer than any of us has been around, and it's getting tired.",
		"Not that bit of the edge. That bit's cracked. Stand over here, where the rock is still on speaking terms with the rest.",
		"Mind the edge there. It's softer than it looks, and it looks like a biscuit.",
	},
	["thb.muse.w24.ledge.012"] = {
		"The way up to the higher ledges of a rise is often just a ramp of packed earth and stone, edged with logs pinned by stakes. The tauren don't build stairs when a slope will do.",
		"Most paths here climb on ramps, not steps: earth and rubble held in place by logs staked across them. Easier on hooves, I suppose, and on anyone carrying a load.",
		"Where the rock steps up from one level of a rise to the next, there's a log laid crosswise and pinned with stakes, and behind it packed earth. Small engineering, everywhere you look.",
	},
	["thb.muse.w24.ledge.013"] = {
		"kicks a pebble by accident toward the edge, watches it roll, wobble at the very lip, and stop, as if it too had thought better of it.",
		"nudges a loose stone back from the rim with the side of a boot, a small, tidy courtesy to whoever walks below.",
	},
	["thb.muse.w24.ledge.014"] = {
		"The elders say the bluffs were chosen because their edges are honest: a cliff tells you plainly where it ends. Out on the open plain, the danger never did.",
		"A cliff hides nothing. Its edge is right there, plain as a line drawn in the dirt. I think that's part of why a hunted people felt safe on top of one.",
	},
	["thb.muse.w24.ledge.015"] = {
		"In the full sun the stone at the edge is hot to the touch, and the little lizards that live in its cracks lie flat on it like spilled coins.",
		"With the sun right overhead the ledges give no shade at all, and every crack in the rim has a lizard in it, waiting for the stone to cool.",
	},
	["thb.muse.w24.ledge.016"] = {
		"Some of the lodges sit so close to the rim that their back poles stand on the last hand's width of rock. Whoever pitched them either knew that stone very well or slept very soundly.",
		"One lodge has its back right against the drop, pegged into the very lip. I'd want a good reason to sleep in that one, and a better one to sleepwalk.",
	},
	["thb.muse.w24.ledge.017"] = {
		"lingers as a tauren sweeps loose grit off a ledge with the side of a hoof before setting a heavy basket down there, careful as anyone laying a table.",
		"sees a tauren test the edge of a ledge with one hoof, pressing down, before trusting it with a load of firewood.",
	},
	["thb.muse.w24.ledge.018"] = {
		"There's more city under the rim than you'd think. Ropes, ledges, little shelves. The bluff has a cellar.",
		"Lean out and look under the edge. Pegs, rope, a whole lower floor nobody ever mentions.",
	},
	["thb.muse.w24.loom.001"] = {
		"keeps half an eye on a weaver pressing each new row down with a flat comb of bone: three taps, a glance, never a fourth.",
		"follows the rhythm of a weaver at an upright frame, the bone comb coming down on each row with the same soft knock.",
		"stands near a weaver's frame long enough to learn its pattern of sounds: thread, thread, knock; thread, thread, knock.",
	},
	["thb.muse.w24.loom.002"] = {
		"The dyer's arms are stained to the elbow in a red that will never wash out. Roots for that red, she says, a yellow from a lichen off the cliffs, and a gray from wood ash.",
		"Dye pots in a row, each a different murk: one of boiled roots, one of crushed bark, one of something the dyer wouldn't name. The skeins come out in the colors the plain wears from season to season.",
		"Ask a dyer what makes that deep red and you'll get a root, a pot, and a long look that says the rest is not for sale.",
	},
	["thb.muse.w24.loom.003"] = {
		"What's this color called? 'Late grass,' says the weaver. I'll take two blankets of late grass.",
		"This blanket is the exact brown of a kodo's ear. The weaver says that was the whole idea.",
		"Blankets dyed 'river after the thaw' and 'kodo in the shade'. The names are half the price, I think.",
	},
	["thb.muse.w24.loom.004"] = {
		"A weaver counts the threads half aloud in her own tongue, a soft rolling count I can't follow past the first few. Interrupted, she starts the row over without a word of complaint.",
		"The weavers count in their own language, low and steady, so a row of looms sounds like a slow conversation between numbers.",
		"I've picked up two words of the tauren tongue from watching a weaver count. I think they mean 'one' and 'start over'.",
	},
	["thb.muse.w24.loom.005"] = {
		"steps carefully over a long warp stretched low between two stakes, while the weaver walks its length checking every thread.",
		"nearly trips on a line of warp threads pegged out along the planks, and the weaver lifts them clear with one hand without looking up.",
	},
	["thb.muse.w24.loom.006"] = {
		"An old tauren spins thread as she walks, the spindle dropping and turning at her knee, and never seems to look at it. She has crossed half the rise and made a hand's length of yarn.",
		"A spindle twirling at the end of a thread, a big hand pinching and drawing out the fiber: some of the city's blankets begin like this, with one slow pull after another.",
		"The spinners here talk, laugh, cross bridges and haggle, and the spindle goes on turning the whole while, as if it had an errand of its own.",
	},
	["thb.muse.w24.loom.007"] = {
		"I tried a row on the loom. The weaver unpicked it so kindly I almost didn't notice I'd been corrected.",
		"The weaver let me add one thread. It's in there somewhere. Nobody will ever find it, and I'm told that's a compliment.",
		"Took a turn at the loom. Result: one crooked row and a very patient tauren.",
	},
	["thb.muse.w24.loom.008"] = {
		"passes under a pole hung with skeins of new-dyed yarn, dripping blue onto planks already stained every color the dyers know.",
		"ducks beneath a line of wet skeins, and a drop of red lands on {g:his|her} sleeve like a small claim of ownership.",
		"notices that the planks below the dyers' poles are mottled red, blue and gold, a record of every batch that ever dripped.",
	},
	["thb.muse.w24.loom.009"] = {
		"A small tauren is weaving on a frame no bigger than a plate, every row crooked. Her teacher looks it over, says something warm, and doesn't straighten a single thread.",
		"Somebody's first little mat hangs beside a tent flap, lopsided and proud. Nobody seems to think it belongs anywhere else.",
		"The elder at the big loom keeps a tiny one beside it, strung for whichever calf wanders up. Three have wandered up while I watched.",
	},
	["thb.muse.w24.loom.010"] = {
		"After dark the cold comes up off the stone, and suddenly every tauren on the rise has a blanket around the shoulders. Now I understand why the weavers never stop.",
		"In the dark the blankets come out: around shoulders, over knees, folded under the elders on the benches. The day's weaving is the night's warmth.",
	},
	["thb.muse.w24.loom.011"] = {
		"I've seen these blanket patterns rolled behind a passing orc's saddle and folded under a troll's pack. Tauren weaving gets around more than the tauren do.",
		"A Forsaken trader has a tauren blanket over one arm and holds it as if it were fragile. I suspect the blanket will outlast the trader.",
		"The weavers' work leaves the bluff in every pack that goes down the cliffs. Many a bedroll on the roads of Kalimdor began on a loom up here.",
	},
	["thb.muse.w24.loom.012"] = {
		"lingers by a weaver who stops, finds a mistake six rows back, and begins without any sign of temper to undo all six.",
		"sees a weaver frown at a finished blanket, find one wrong thread near the middle, and set to unpicking half a day's work.",
	},
	["thb.muse.w24.loom.013"] = {
		"There is no word for 'quick' in any price a weaver gives me. Everything takes as long as it takes, and costs about the same.",
		"I asked when a blanket would be ready. The weaver looked at the frame, then out at the plain, and said 'when it is'. I'll come back.",
	},
	["thb.muse.w24.loom.014"] = {
		"Not every thread up here comes from an animal. Some is beaten out of tall plain grass and twisted by hand into a cord that smells faintly of summer.",
		"A tauren sits pounding grass stems flat with a wooden mallet, then rolls the fibers along her thigh into twine. By the end there is enough to tie shut a tent flap.",
	},
	["thb.muse.w24.loom.015"] = {
		"Every blanket in this city is warmer than it looks, and it looks very warm.",
		"Came for one blanket, leaving with two and a rug. The weaver didn't even try to sell me the rug.",
	},
	["thb.muse.w24.loom.016"] = {
		"My fingers are blue. I touched one skein. One.",
		"Note to self: the wet yarn is wet on purpose.",
	},
	["thb.muse.w24.loom.017"] = {
		"When a blanket is made as a gift, a weaver told me, it is handed over folded with the pattern hidden inside, so the one who receives it has to unfold it to see. I like a people who make you open a gift slowly.",
		"Gift blankets are given folded small, I'm told, pattern inward. The unfolding is part of the giving.",
	},
	["thb.muse.w24.offering.001"] = {
		"sees a hunter lay a strip of dried meat on a flat stone at the rim of the rise, step back, and wait until a hawk takes it before going back to work.",
		"notices a small strip of meat left on a ledge at the edge of the mesa, and a tauren who passes it again and again without once touching it.",
	},
	["thb.muse.w24.offering.002"] = {
		"The old tauren on the next bench breaks off the first corner of every flatbread and lets it fall to the planks. The birds know it. So, by the look on her face, does the Earth Mother.",
		"Before she eats, a tauren grandmother crumbles a pinch of bread onto the ground. 'Hers first,' she told me, without saying whose. She didn't need to.",
		"First crumb to the ground, then the rest to the mouth. The tauren do it without thinking, the way others knock mud off their boots at a door.",
	},
	["thb.muse.w24.offering.003"] = {
		"I wanted to leave something on the ledge where the tauren leave theirs. All I had was a copper and half a biscuit. A shaman said either would do, and eyed the biscuit with interest.",
		"I asked a shaman what a proper offering is. 'Something you'd rather keep,' she said. I've been holding the same apple for a while now, unable to decide.",
	},
	["thb.muse.w24.offering.004"] = {
		"stands aside while a tauren pours a thin line of water around the foot of a lodge's door post, slowly, a full circle, and walks off with the empty jug without looking back.",
		"comes across a dark ring of damp earth around the base of a door post, freshly poured, and a small clay cup set upside down beside it.",
	},
	["thb.muse.w24.offering.005"] = {
		"Someone tucks feathers into the cracks of the rock at the head of a bridge. Whenever the old ones blow away, new ones appear. Nobody admits to it.",
		"There's a crack in the rock where a bridge meets the rise, and it's always full of small things: a feather, a bead, a twist of grass. An offering, or a joke the whole city is in on.",
		"I tucked a hawk feather into the crack by the bridge. When I looked back from the far side, someone had already straightened it.",
	},
	["thb.muse.w24.offering.006"] = {
		"Don't mind me. I'll look the other way; that isn't meant for me.",
		"Shall I leave something too? I've a button, a bit of string and a great deal of goodwill.",
	},
	["thb.muse.w24.offering.007"] = {
		"A tauren told me the best offering is a task done well and never mentioned. By that measure the leatherworkers of this bluff are the most devout people I've met.",
		"'Not everything you give the Earth Mother goes in a bowl,' an elder said. 'A straight furrow. A patient answer. A knot tied right.' Then she retied mine.",
	},
	["thb.muse.w24.offering.008"] = {
		"Fresh strips of dyed hide hang from the post at the head of one bridge, a Bluffwatcher told me: one for each brave who didn't come back up from Ashenvale.",
		"When word comes up that someone has fallen far away, the tauren don't wail, an elder told me. They go quiet, somebody cooks the fallen one's favorite dish, and everybody eats a little of it.",
	},
	["thb.muse.w24.offering.009"] = {
		"catches a calf stretching up to set a smooth pebble on the carved ledge of a totem, while a nearby adult studies the sky with great attention so as not to have seen.",
		"spots a row of tiny pebbles lined up along the base of a totem, at exactly the height a calf could reach.",
	},
	["thb.muse.w24.offering.010"] = {
		"I've wondered who eats the offerings afterward. A shaman told me: 'The birds, the ants and the Earth Mother. Usually in that order.'",
		"Where do all those little offerings end up? I asked. 'Back,' a shaman said, and that was the whole answer.",
		"'What happens to the offerings?' I asked. A shaman pointed at a fat crow and said nothing more.",
	},
	["thb.muse.w24.offering.011"] = {
		"Tauren offerings are small and quiet. The loa back home like theirs loud and bloody. Different spirits, different manners. Up here I mind mine.",
		"A pinch of grain, a cup of water, a nod. Tauren spirits must be easy to please, or very patient. The loa would call it an insult.",
	},
	["thb.muse.w24.offering.012"] = {
		"For whoever watches over this place: not much, but freely given.",
		"Here. It isn't grand. Take it as it's meant.",
		"A small thing, left with thanks. That's all I have, and all I'm asked.",
	},
	["thb.muse.w24.offering.013"] = {
		"steps over a braid of dried grass laid across the path to a lodge door, as the tauren do, careful not to touch it.",
		"spies a small woven ring of grass hung on a peg by a lodge door, fresh and green among the faded ones beneath it.",
	},
	["thb.muse.w24.offering.014"] = {
		"I thought the offerings were payment, the way some peoples bargain with their spirits. A shaman corrected me, kindly: 'You don't pay your grandmother for supper. You bring her something because you came.'",
		"Offerings up here aren't bargains. An elder put it this way: nobody keeps a tally with the Earth Mother; you simply never arrive with empty hands.",
	},
	["thb.muse.w24.offering.015"] = {
		"watches an old tauren knot a single bead onto a cord already heavy with them, tie it off with great care, and hang the whole cord back on its peg without a word of explanation.",
		"notices a weathered cord of beads hanging by a lodge entrance, each bead a different color, and a tauren who touches the newest one on the way past.",
	},
	["thb.muse.w24.pact.001"] = {
		"An orc and a tauren elder sat together just now without a word for a long while. Old allies, I think, from the centaur years. Some debts need no talk.",
		"Two old soldiers, one tusked and one horned, sharing a bench and a silence. The tauren say the orcs earned their place here before there was a here.",
	},
	["thb.muse.w24.pact.002"] = {
		"watches a tauren hunter clasp an orc's forearm in greeting, the way the Horde does, and then add a slow bow of the horns, the way the tauren do.",
		"spots an orc grunt arrive at a cookfire and be handed a bowl before any word is spoken, as though the seat had been kept for years.",
		"hears an old orc and an old tauren greet each other by name from opposite ends of the planks, loud and slow, like two people repeating the same joke.",
	},
	["thb.muse.w24.pact.003"] = {
		"The orcs came over the sea with nothing, the story goes, and the tauren gave them directions, grain and a friend. The orcs gave them an army. Fair trade.",
		"A lost people with axes met a hunted people with patience. The tauren tell it like a good bargain, and they don't often brag about bargains.",
	},
	["thb.muse.w24.pact.004"] = {
		"Our Warchief and the High Chieftain hold each other up like two poles of the same lodge. The Horde lives under that hide.",
		"Whatever the Alliance thinks of us, they never reckoned on the tauren. Thrall did. Our Horde stands taller for it, horns and all.",
	},
	["thb.muse.w24.pact.005"] = {
		"The Forsaken came into the Horde on the High Chieftain's word, and some tauren still watch them the way you watch a guest who kept their boots on. Watching, not refusing.",
		"The old Chieftain spoke for the dead before the Horde, the tauren say, and not every tauren agreed. They keep the disagreement the way they keep everything: quietly, and for a long time.",
	},
	["thb.muse.w24.pact.006"] = {
		"notices a Forsaken apothecary and a tauren herbalist bent over the same bundle of roots, disagreeing very politely about its name.",
		"watches a tauren child offer a Forsaken a dried flower, solemnly, and the Forsaken accept it with a bow so stiff it creaks.",
		"stops to watch an orc and a Forsaken wait side by side for a tauren trader to finish counting, both of them equally resigned.",
	},
	["thb.muse.w24.pact.007"] = {
		"The tauren didn't have to let the rest of us up here. A pair of lifts is an easy thing to stop running.",
		"This is someone else's refuge, built after a long hunt. That they share it with outsiders at all says more than any treaty.",
	},
	["thb.muse.w24.pact.008"] = {
		"Every lift brings someone up with a story from somewhere else: Stonetalon, Ashenvale, the Barrens. The tauren take each one the same way, by sitting down to hear it properly.",
		"News reaches this city late and slowly, carried up the cliffs by tired travelers. By the time it arrives it has been told so often it sounds like history.",
		"Up here the war is mostly a matter of voices: a name from Ashenvale, a rumor from the Barrens, a hunter's shrug.",
	},
	["thb.muse.w24.pact.009"] = {
		"glimpses a tauren come in from the lifts with an arm bound in clean hide, and an elder rise without a word to make room by the fire.",
		"turns to watch a tired warrior sit down heavily among the tauren, and the talk nearby turn at once to easier things.",
	},
	["thb.muse.w24.pact.010"] = {
		"The braves are all talking Ashenvale. Whatever's happening out there, it's reached the cookfires up here.",
		"Stonetalon, Ashenvale, the Barrens. You hear more of the war on this quiet cliff than at the front.",
		"Everyone up here has a cousin at the Ashenvale front. Or a friend. Or a debt.",
	},
	["thb.muse.w24.pact.011"] = {
		"Orcs and tauren both know what it is to have no place: one people torn from its world, the other hunted across its own. Maybe that's what they recognized in each other.",
		"The orcs had lost a world and the tauren had never been let to keep one. Two homeless peoples, and somehow between them a city.",
	},
	["thb.muse.w24.pact.012"] = {
		"When we had nothing on this continent but our hunger, the tauren stood with us. I walk their city softly. It's the least an orc can do.",
		"Every orc in Kalimdor owes these people a debt we'll never finish paying. I lower my voice here. They'd never ask, which is why I do.",
	},
	["thb.muse.w24.pact.013"] = {
		"A tauren chieftain spoke for us when nobody else would. I don't have much left to be grateful with, but I find I have this.",
		"The living of this city made room for us on an old bull's word. I don't trust easily anymore. I'm making an exception, slowly.",
	},
	["thb.muse.w24.pact.014"] = {
		"When the orcs first brought it to Kalimdor, the Horde was the name of a war. Up here it sounds more like the name of a meal shared with strangers.",
		"The Horde means axes in Durotar and raids in Ashenvale. On this cliff, for some reason, it mostly means somebody passing you bread.",
	},
	["thb.muse.w24.pact.015"] = {
		"Without the orcs the tauren would still be walking. Without the tauren the orcs would still be lost. Good deal for everybody.",
		"Orcs bring the noise, tauren bring the patience, and the Forsaken bring the paperwork. Somehow it works.",
		"An orc, a troll, a tauren and a Forsaken around one fire. Anywhere else that would be the start of a brawl.",
	},
	["thb.muse.w24.pact.016"] = {
		"Hunters coming up from Stonetalon don't talk about it much. They just sit closer to the fire than usual, and the tauren let them.",
		"Whoever has been out where the Horde is fighting comes up here quieter than they went down. The city seems built to hold that kind of quiet.",
	},
	["thb.muse.w24.pact.017"] = {
		"listens to a young troll ask an old tauren how the tribes and the orcs first met, and stays to listen, because the answer is clearly going to be long.",
		"glimpses an orc child sit down at an elder's hooves to hear about the centaur years, chin in hands, a fierce frown of attention on the small green face.",
		"lingers to watch a tauren elder draw the old trails of the tribes in the dust with one finger for a Forsaken, who studies them with great seriousness.",
	},
	["thb.muse.w24.pact.018"] = {
		"catches sight of a runner coming up from the lifts and going straight to a Bluffwatcher, who listens without moving at all.",
		"pauses to watch a tauren elder unroll a painted hide map of the Barrens for a group of braves, the centaur camps marked in soot, the Horde's in ochre.",
		"notices that a fresh name has been added to a list painted on a lodge hide, and that the tauren passing it slow down.",
	},
	["thb.muse.w24.pact.019"] = {
		"Forsaken in Thunder Bluff. Who'd have believed it? The High Chieftain, apparently.",
		"Dead folk buying herbs from tauren. The Horde is a stranger and kinder thing than its enemies think.",
	},
	["thb.muse.w24.pact.020"] = {
		"Any word from Ashenvale? Up here, that's how people say hello.",
		"News from the Barrens climbs this cliff slower than a tauren, and twice as worried.",
	},
	["thb.muse.w24.plank.001"] = {
		"The planks of the crossings aren't all the same age. Pale new ones sit between old gray ones, and you can read the repairs like patches on a cloak.",
		"Crossing a span, I count the boards: dark, dark, dark, then a pale one with fresh tool marks, then dark again. Someone was out here not long ago, fixing that one.",
		"Some boards are worn hollow in the middle where feet have landed for years. The new ones still have their edges.",
	},
	["thb.muse.w24.plank.002"] = {
		"waits at the head of a crossing while a tauren kneels halfway along it, prying out a split plank and fitting a new one into its place.",
		"edges past a gap in the walkway where a single board is missing, a fresh one already lying beside it, waiting to be fitted.",
	},
	["thb.muse.w24.plank.003"] = {
		"There's a gap in that board big enough to lose a boot through. Keep your boots on, everyone.",
		"I can see the ground between the planks. I'd prefer the planks were closer friends.",
		"Careful, the third board from the end has opinions.",
	},
	["thb.muse.w24.plank.004"] = {
		"Between the boards of the crossing there are thin bright gaps, and through each one the plain, very far down. I've stopped looking at the gaps and started looking at the boards.",
		"Light comes up between the planks underfoot. It's a strange thing, to walk on a floor that lets the sky in from below.",
	},
	["thb.muse.w24.plank.005"] = {
		"notices that the planks of the span are laid with a finger's width of give between them, so the whole walkway can flex like a spine instead of cracking.",
		"studies how the boards of the crossing are threaded onto the ropes, each one notched at the ends and bound, free to tilt a little on its own.",
	},
	["thb.muse.w24.plank.006"] = {
		"The crossing sways. It's meant to, I'm told: a stiff span would snap, a loose one survives. I'm told a lot of comforting things up here.",
		"Apparently the sway is deliberate. Builders who mean for a walkway to wobble are either very wise or very funny, and up here I can't tell which.",
	},
	["thb.muse.w24.plank.007"] = {
		"The boards are split, not sawn: the grain runs unbroken from end to end. Split wood holds; sawn wood cracks where the saw cut across it.",
		"Every plank I look at was split from the log along the grain and smoothed with a knife, not a saw. More work, and it shows in how long they last.",
	},
	["thb.muse.w24.plank.008"] = {
		"steps onto a board that answers with a loud crack, freezes, and then sees the tauren behind {g:him|her} walk over the very same board without a glance.",
		"hears one plank give a sharp complaint underfoot and stops dead, while a passing tauren pats the rope as if to say it always does that.",
	},
	["thb.muse.w24.plank.009"] = {
		"On one of the old planks someone has carved a small mark, a circle with a line through it, worn almost smooth. A builder's sign, maybe. Or someone who wanted the wood to remember them.",
		"There are marks scratched into some of the boards near the ends: little signs, a notch, a hoofprint shape. I don't know what they mean, and I suspect the boards don't either.",
	},
	["thb.muse.w24.plank.010"] = {
		"Here on Spirit Rise the walkways by the lodges are laid with boards scrubbed pale, as if someone sweeps and washes them more often than anywhere else in the city.",
		"On Spirit Rise the planks near the lodges are scrubbed almost white. Someone here takes the floor as seriously as the chanting.",
	},
	["thb.muse.w24.plank.011"] = {
		"Whoever fixed this board, thank you. I'd tell you in person, but I'd have to stop walking.",
		"New plank. You can still smell the sap. I'll step on it gently.",
		"Good, solid board. I'd shake its hand if it had one.",
	},
	["thb.muse.w24.plank.012"] = {
		"Rain turns the old planks dark and slick, while the new ones stay pale a while longer, and the crossing goes striped like the cliffs.",
		"Wet boards underfoot, and I can feel which ones are old: they give a little, soft as moss, while the new ones stay hard and loud.",
	},
	["thb.muse.w24.plank.013"] = {
		"Somebody carried that plank across three rises to fit it here. No one will notice it now. That seems to be the whole point of a good repair.",
		"Nobody thanks whoever replaced a board. They just don't put a foot through it. A quiet sort of gift.",
	},
	["thb.muse.w24.plank.014"] = {
		"watches an empty lift platform come up the cliff, its thick planks flexing slightly at the center as it settles against the top.",
		"takes in the floor of the lift, thick planks bound to a frame with rawhide, the bindings dark and polished by countless boots and hooves.",
	},
	["thb.muse.w24.plank.015"] = {
		"Planks, ropes, poles, pegs. The tauren built a capital out of what a carpenter keeps in one shed, plus a great deal of nerve.",
		"A city of wood and rope on top of a cliff. Anywhere else that would be a dare. Here it's simply how the street goes.",
	},
	["thb.muse.w24.plank.016"] = {
		"Orc boots, troll feet, Forsaken bones, tauren hooves: the same planks carry all of us. Somebody up here keeps them sound for a whole Horde that rarely says thanks.",
		"Our allies mend their walkways for every one of us who passes, orc or troll or dead. That's a kind of hospitality you walk on.",
	},
	["thb.muse.w24.plank.017"] = {
		"This board's loose. No, wait. They're all a bit loose. That's the design.",
		"Is it meant to bounce like that? Don't answer. I've decided it is.",
		"Every plank here creaks in a different voice. I think this one just insulted me.",
	},
	["thb.muse.w24.plank.018"] = {
		"The oldest boards have gone silver and hard as bone. Wood that spends so many years in the open stops being wood and becomes something nearer to stone.",
		"Old planks up here weather to the color of ash and the hardness of horn. You could believe the bluff is slowly turning its crossings back into rock.",
	},
	["thb.muse.w24.pole.001"] = {
		"The lodge poles are all near enough the same length, and straight as spear shafts. Somebody walked a long way to find trees that grow like that.",
		"Straight poles, every one, peeled clean and rubbed with fat. Whoever chose them was fussier about timber than most people are about friends.",
		"Each pole carries the marks of the hand that shaped it: long flat knife strokes down its length, never quite the same twice.",
	},
	["thb.muse.w24.pole.002"] = {
		"looks up at the top of a lodge where the poles cross, their tips blackened by years of smoke rising between them.",
		"tips {g:his|her} head back to see where a lodge's poles meet high overhead, bound in a bunch and stained dark by the smoke that slips out through the gap.",
		"notices that the poles of each lodge lean in to the same point and lock there, so the harder the frame is pressed, the tighter it grips.",
	},
	["thb.muse.w24.pole.003"] = {
		"The poles of the lodges don't sit on the rock; they sit in it. Each foot is set in a socket cut into the stone, so the wind can lean on the tent all it likes.",
		"Look at the foot of any lodge pole and you'll find it seated in a shallow hole chiseled into the rock. The city isn't pitched on the bluff. It's plugged into it.",
		"Where the rock is too hard to cut, the poles stand in rings of piled stones instead, packed tight and chinked with mud.",
	},
	["thb.muse.w24.pole.004"] = {
		"watches three tauren raise a new pole, two walking it upright hand over hand while the third steadies the foot with a hoof.",
		"stands back as a long pole tips upright between two tauren and drops into its socket with a dull knock.",
		"sees a tauren lean a whole shoulder into a fresh pole to settle it, then step back and study it for a long while, head tilted.",
	},
	["thb.muse.w24.pole.005"] = {
		"A lodge here is a cone of poles with a hide thrown over it. Said like that, it sounds flimsy. Then you try to push one, and it pushes back.",
		"I put my back against the side of a tent to rest, expecting it to give. It didn't. I've leaned on castle walls that were less sure of themselves.",
		"'Only a tent,' you'd say. Then you look at the frame under the hide, pole lashed to pole, and it's more like the ribs of a ship.",
	},
	["thb.muse.w24.pole.006"] = {
		"Every big tent is held by a skirt of ropes running out to stakes, and the stakes are driven into cracks in the rock, wedged tight with chips of stone. Nothing up here is merely set down.",
		"The guy ropes run out from each lodge like the legs of a spider, every one ending at a peg hammered into a seam of the stone.",
		"I counted the ropes holding down one big lodge and gave up at twenty. Nothing on this mesa trusts its luck.",
	},
	["thb.muse.w24.pole.007"] = {
		"Mind the peg. Mind the other peg. This city is mostly pegs.",
		"I've stubbed my foot on three tent stakes since I left the lift. Very well driven, I'll grant them that.",
		"Pegs. Everywhere. If this city ever floats off, it won't be for lack of pegs.",
	},
	["thb.muse.w24.pole.008"] = {
		"A pole by the path has been patched: a split in it bound with three tight collars of rawhide, the old wood showing pale between them. Not replaced. Mended, and trusted again.",
		"Someone has mended a cracked pole rather than throw it out, splinting it with a short length of wood and binding the lot. Up here a thing earns a second chance.",
		"Half the poles in this city have been mended at least once, and the mends are the neatest part of them.",
	},
	["thb.muse.w24.pole.009"] = {
		"runs a hand along an old post here on Hunter Rise, scarred with notches cut in uneven rows, a tally of something the wood is not telling.",
		"lingers by a weathered post on Hunter Rise, its grain split and silvered, still holding up its corner of a lodge without complaint.",
	},
	["thb.muse.w24.pole.010"] = {
		"At night the poles of the city tick and settle as they cool, a dry sound from every lodge at once, like a great many old joints.",
		"After dark you can hear the timber of the lodges giving up the warmth of the day, small cracks and ticks all over the rise.",
	},
	["thb.muse.w24.pole.011"] = {
		"The lodges all turn their backs the same way, low side to the edge, door away from it. The tauren have argued with the wind a long time and learned where it pushes.",
		"I haven't found a door on this rise that faces the drop. The tents sit like a herd with their rumps to the edge and their heads together.",
		"Round lodges give the gusts nothing flat to push against. A sensible shape, when you think about it, and the tauren thought about it long ago.",
	},
	["thb.muse.w24.pole.012"] = {
		"We choose a lodge pole the way others choose a weapon: by its weight, its grain, the sound it makes when you knock it with a knuckle.",
		"A good pole rings when you rap it; a bad one thuds. The elders like to say every tauren calf learns that before learning to bargain.",
	},
	["thb.muse.w24.pole.013"] = {
		"ducks under a guy rope, steps over another, and ducks again, as if crossing the rise were a dance with too many partners.",
		"picks a way through a thicket of tent ropes and stakes, ducking and stepping like someone crossing a line of snares.",
		"trips on a guy rope, catches {g:himself|herself} on another, and stands very still while the nearest tent shivers its disapproval.",
	},
	["thb.muse.w24.pole.014"] = {
		"The hide over a lodge is laced to its frame, not tied in one place but stitched all down the seam with thong, so a tear in one place stays a tear in one place.",
		"Lacing all down the seam of every tent, thong through holes, a little cross of rawhide every hand's width. Patient work, and the whole city is wearing it.",
		"Where two hides meet on a lodge they overlap by a full hand and are laced through both, so no seam ever faces the open side alone.",
	},
	["thb.muse.w24.pole.015"] = {
		"That pole's older than half the people walking past it, and straighter than most of them.",
		"Every pole in this place has been rubbed with fat until it shines. You could check your face in some of them.",
		"Somebody's tied a feather to the top of that pole. Decoration, or a way to tell where the gusts come from. Probably both.",
	},
	["thb.muse.w24.pole.016"] = {
		"One lodge stands empty, its poles bare, the hide taken down and folded at its foot. Nobody has moved the poles. I didn't ask why; it didn't feel like my question.",
		"Among the lodges a bare frame of poles stands with no hide on it, just the bones of a home. The tauren walk around it carefully, the way you would around someone asleep.",
		"Between two lodges stands a single pole with nothing on it, worn smooth, too short for a frame. I've no idea what it's for, and nobody has offered to say.",
	},
	["thb.muse.w24.pole.017"] = {
		"Fog has swallowed the far lodges; only their pole tips show, a scatter of dark crosses in the white.",
		"Fog all round, and the nearest lodge is just a gray cone with its poles poking out on top, crossed like fingers.",
		"The fog beads on every guy rope, and the ropes drip in a steady patter onto the stone, as if each tent had its own small shower.",
	},
	["thb.muse.w24.pole.018"] = {
		"The pegs here are the size of my forearm, and the mallet leaning beside them I can barely lift. Tauren don't tap a stake in. They tell it where to go.",
		"A tauren drove a stake into a crack in the rock with three strokes of a mallet I couldn't have raised once. The stake looked relieved it was over.",
		"Lifting one of their tent pegs is a workout. Driving one, apparently, is a chat between friends.",
	},
	["thb.muse.w24.quip.001"] = {
		"Ask a tauren for directions and you get the way, the history of the way, and a pause long enough to walk it.",
		"I've stopped asking for directions. Every answer starts with over the span and ends with a very long silence.",
	},
	["thb.muse.w24.quip.002"] = {
		"Nobody in this city has ever been late. Nobody has ever been on time, either. Time just isn't invited.",
		"I told a tauren I was in a hurry. The tauren nodded slowly and asked what that was like.",
	},
	["thb.muse.w24.quip.003"] = {
		"Orgrimmar has walls. Thunder Bluff has a very long way down. Both work.",
		"Undercity keeps you in. Thunder Bluff keeps you up. I'm not sure which is harder on the knees.",
	},
	["thb.muse.w24.quip.004"] = {
		"Bowed to, nodded at and fed twice, and I haven't done a single useful thing. I may never leave.",
		"Fed, greeted and offered a seat three times on one walk to the bank. Hospitality here is a hazard.",
	},
	["thb.muse.w24.quip.005"] = {
		"If I stand still long enough up here, somebody will drape a blanket over me and call it furniture.",
		"Stood in one place too long and a tauren hung a bundle of herbs on me to dry.",
	},
	["thb.muse.w24.quip.006"] = {
		"Some orcs call this place soft. I'd like to hear them say it in the middle of a span when it dips.",
		"Some say tauren are slow. Those people have never tried to win an argument with one.",
	},
	["thb.muse.w24.quip.007"] = {
		"I've learned two words of Taur-ahe. I'm told one of them is a greeting and the other is a kind of cheese.",
		"Learned a word of greeting from a tauren. I've been using it all over the city, and the smiles are getting suspiciously wide.",
	},
	["thb.muse.w24.quip.008"] = {
		"Sat down on what I took for a rolled-up hide. The hide stood up, apologized, and walked off.",
		"Leaned on a post for a rest and the post wished me well. Tauren are very still when they listen.",
	},
	["thb.muse.w24.quip.009"] = {
		"Hurrying in Thunder Bluff is like shouting in a library. Nobody stops you. Everyone just looks.",
		"I crossed the main rise at a brisk walk and three tauren asked if something was wrong. Something was: I was walking briskly.",
	},
	["thb.muse.w24.quip.010"] = {
		"A troll bet me I couldn't cross without holding the rope. The troll was right, and now owns my lunch.",
		"Never bet a troll on anything involving balance. I learned that one the expensive way.",
	},
	["thb.muse.w24.quip.011"] = {
		"Thunder Bluff: where the floor is optional and the soup is not.",
		"The city of patience. I've been patient for nearly an hour. It's exhausting.",
	},
	["thb.muse.w24.quip.012"] = {
		"I left the innkeeper a tip. It came back to me along with a bowl of something. I think I lost that exchange.",
		"Tried to overpay at a stall. The merchant counted out my change and added a dried apple. There's no winning here.",
	},
	["thb.muse.w24.quip.013"] = {
		"A tauren on the lift asked how I was. I said going up. It got the longest, slowest laugh I've ever earned.",
		"I tell the same joke on every lift ride. The tauren laugh every time, slowly, as if it were new. I suspect pity.",
	},
	["thb.muse.w24.quip.014"] = {
		"Good to see the whole Horde in one place with nobody shouting. Thrall should hold his councils up here.",
		"Orc, troll, Forsaken, tauren, all on one span. The Horde's an odd company, and this is its quietest corner.",
	},
	["thb.muse.w24.quip.015"] = {
		"I've caught myself nodding slowly before I answer people. Thunder Bluff is getting into me.",
		"I answered a question with a long silence and a nod. The tauren looked impressed. I'd only forgotten the question.",
	},
	["thb.muse.w24.quip.016"] = {
		"My pack is full of gifts I never asked for: a dried root, a bead, half a flatbread. I came up here to sell things.",
		"Every stall I stop at sends me off with something extra. At this rate I'll leave richer in odds and ends than in coin.",
	},
	["thb.muse.w24.quip.017"] = {
		"A tauren asked me to hold a basket for a moment. That was some time ago. I'm still holding it. I think I live here now.",
		"Agreed to mind a stall for a moment while its keeper fetched something. The moment is running long, and I've sold two blankets.",
	},
	["thb.muse.w24.quip.018"] = {
		"Quietest capital in the Horde. I keep talking to fill it, and then apologizing.",
		"I could get used to a city where the loudest sound is somebody's spoon against a pot.",
	},
	["thb.muse.w24.quip.019"] = {
		"I asked a tauren what hour it was. A long look at the plains, then: later than before.",
		"Asked how far the inn was. Not far, said the tauren. Three crossings later I understand that tauren measure distance in patience.",
	},
	["thb.muse.w24.respite.001"] = {
		"dozes off sitting up against a lodge pole and wakes to find a folded blanket tucked under {g:his|her} head by someone already gone.",
		"nods off on a pile of hides at the edge of the rise and wakes with a woven blanket over {g:his|her} knees and no idea who put it there.",
	},
	["thb.muse.w24.respite.002"] = {
		"For once nobody needs anything from me. I sit on a log, I watch people carry things, and I let the carrying be theirs.",
		"I've sat here so long doing nothing that my thoughts have stopped arguing with each other.",
	},
	["thb.muse.w24.respite.003"] = {
		"empties the whole pack onto a hide and repacks it with great care, heaviest at the bottom, which takes most of an hour and achieves nothing at all.",
		"sits cross-legged on a hide sorting the contents of the pack into neat piles, and a passing tauren stops to watch with approval, as if this were a craft.",
	},
	["thb.muse.w24.respite.004"] = {
		"I came up here to rest my feet. My feet have now walked every rise twice looking for the right place to rest.",
		"Finding a place to sit in this city is easy. Choosing one, with every view on offer, takes ages.",
	},
	["thb.muse.w24.respite.005"] = {
		"I'm not asleep. I'm resting my eyes the tauren way, which is slowly.",
		"Five more minutes on this hide. Then I'll be useful. Probably.",
	},
	["thb.muse.w24.respite.006"] = {
		"pulls off one boot, shakes a pebble out of it, inspects the pebble at length, and sets it on the ground with something like respect.",
		"tugs off both boots and rubs {g:his|her} feet in plain view, which nobody on the rise seems to find the least bit strange.",
	},
	["thb.muse.w24.respite.007"] = {
		"On the bench beside me an old tauren is darning a sock the size of my pack. Not a word has passed in either direction. Fine company all the same.",
		"Shared a bench with a tauren for a long while, neither one speaking. When the tauren left, there was a nod. I think that was a whole friendship.",
	},
	["thb.muse.w24.respite.008"] = {
		"Sitting out the rain under a tent flap with two strangers and a wet wolf that must belong to some hunter. Nobody minds. It'll stop when it stops.",
		"Rain, so I'm under a hide awning with my boots off, watching drops come off the edge in a slow row.",
	},
	["thb.muse.w24.respite.009"] = {
		"This is a good spot. Anyone mind if I sit here and do nothing for a while?",
		"Room on this log for me? I promise to be very boring company.",
	},
	["thb.muse.w24.respite.010"] = {
		"The tauren treat my rot the way they'd treat a limp: noticed, not mentioned.",
		"In Undercity nobody looks at me twice. Here they look once, kindly, and then not again. I prefer it.",
	},
	["thb.muse.w24.respite.011"] = {
		"In most cities, sit still too long and a guard asks what you want. Here a Bluffwatcher walks past twice, and the second time nods as if I'd passed a test.",
		"Nobody moves me along up here. I've sat in one spot long enough to see a Bluffwatcher's whole round twice, and got only a nod for it.",
	},
	["thb.muse.w24.respite.012"] = {
		"lies back on a hide spread over the rock of the main rise, one arm behind {g:his|her} head, and counts stars until the counting falls apart.",
		"settles on a folded blanket out in the open as the fires burn low, watching the stars and thinking of nothing in particular.",
	},
	["thb.muse.w24.respite.013"] = {
		"I washed my face in a basin a tauren had left out. I've since learned it was for soaking a hide. My face has never been so supple.",
		"Borrowed a basin of water to wash in. It turned out to be someone's hides, soaking. I smell faintly of tannery and great embarrassment.",
	},
	["thb.muse.w24.respite.014"] = {
		"Sit, stitch, sit some more. Best work I've done in a long while.",
		"Don't mind me. Just sewing a button back on and being very proud of it.",
	},
	["thb.muse.w24.respite.015"] = {
		"sits on an upturned basket near the bank and watches the comings and goings: an orc with a sack, a troll with a grin, a Forsaken with a ledger of its own.",
		"rests on a crate near the auction house, following the Horde's traffic in and out as if it were a slow river.",
	},
	["thb.muse.w24.respite.016"] = {
		"I sat down on Elder Rise meaning to rest a moment, and an elder nearby nodded, as if resting were the right answer to something.",
		"Here on Elder Rise I found a bench with nothing to do but face the other rises. For a while I let it do that for me.",
	},
	["thb.muse.w24.respite.017"] = {
		"On Spirit Rise a Forsaken trainer and a tauren shaman are sharing a patch of shade and disagreeing about something with enormous politeness. I'll wait my turn and enjoy it.",
		"I came to Spirit Rise for a lesson and found the Forsaken teacher deep in a long, courteous dispute with a shaman. Happy to wait; it's better than the lesson.",
	},
	["thb.muse.w24.respite.018"] = {
		"Sitting here watching the tauren work. Someone has to supervise.",
		"I'm resting. From what, I couldn't say, but I'm very committed to it.",
	},
	["thb.muse.w24.respite.019"] = {
		"Somebody lent me a blanket to sit on. It weighs about as much as I do, and it's the most comfortable thing I've touched in weeks.",
		"The blankets here are so thick you could sleep on bare stone and never know it.",
		"Three different people have handed me a blanket to sit on. I'm now sitting on all three, like a very small chieftain.",
	},
	["thb.muse.w24.respite.020"] = {
		"rests on a bench here on Hunter Rise, where a hunter's cat has also chosen to rest, and the two of them consider each other with polite suspicion.",
		"sits down on Hunter Rise for a rest, and a tame boar ambles over at once to sniff both boots, judges them of no interest, and wanders off.",
	},
	["thb.muse.w24.respite.021"] = {
		"sits with a blanket around {g:his|her} shoulders beside a lodge while the fog swallows the rises, the next tent only a soft shape, and seems in no hurry to go anywhere.",
		"waits out the fog on a bench with both hands around a cup, listening to the city go on talking without being seen.",
	},
	["thb.muse.w24.spiritward.001"] = {
		"A young shaman here on Spirit Rise has held her hands over a cold fire pit for as long as I've been watching. Her teacher sits beside her chewing a root, in no hurry for the fire to decide.",
		"On this rise the apprentices learn to wait first. One has spent the whole time I've stood here asking a heap of kindling for permission, and the kindling is still thinking it over.",
		"Patience is the first lesson of the shamans, I gather. The student nearest me has been at it so long a beetle has climbed his knee and back down.",
	},
	["thb.muse.w24.spiritward.002"] = {
		"watches a shaman cup water from a skin in both hands and murmur to it before drinking, the way one might thank a friend for walking a long way.",
		"sees an old shaman tip a little water from a cup onto the planks before drinking the rest, without looking down.",
		"waits as a shaman lifts a water skin, says a quiet word into its open neck, and only then drinks.",
	},
	["thb.muse.w24.spiritward.003"] = {
		"Just now a shaman scolded a fire pit for spitting an ember onto a blanket. Not angrily: the way you'd speak to a dog who knows better. The fire, to be fair, has behaved since.",
		"I watched a fire throw a spark onto a shaman's sleeve. She told it, quite firmly, that guests don't behave like that. It has burned very quietly ever since.",
		"Fires up here get spoken to like unruly nephews. They seem to take it better than nephews do.",
	},
	["thb.muse.w24.spiritward.004"] = {
		"A totem isn't a statue of a spirit, I've learned from the shamans. It's a question carved in wood and left standing, so the asking goes on after the carver has gone home.",
		"To the shamans, a totem holds a request the way a bowl holds water: it keeps it there, patiently, long after the hand that filled it has let go.",
		"Every totem on the bluff is asking something, I'm told. That explains the faces. Nobody looks that patient unless they're waiting for an answer.",
	},
	["thb.muse.w24.spiritward.005"] = {
		"Of the hills where the goblins dig, the shamans speak as of a wound that won't close. One of them pressed a palm to the rock and said she could feel it from this far off.",
		"Ask a shaman about the Venture Company and you get no anger, only a long look toward the hills and the words 'the earth is sore there'. Somehow that's worse.",
		"Every shaman on this bluff seems to know which hills the goblins are cutting without going near them. They wince at the same moments, someone told me.",
	},
	["thb.muse.w24.spiritward.006"] = {
		"watches a shaman on Spirit Rise shake a dried gourd beside one ear, frown, shake it again, and set it down as if it had given a poor answer.",
		"listens to the dry rattle of seeds in a shaman's gourd, slow and uneven, until the shaman stops and nods once at whatever it said.",
	},
	["thb.muse.w24.spiritward.007"] = {
		"May I ask what the fire told you? Or is that like reading someone else's letters?",
		"I won't interrupt. I only wondered whether the stone ever says no.",
	},
	["thb.muse.w24.spiritward.008"] = {
		"An orc shaman and a tauren shaman are sitting together at the rim of the rise, comparing what the elements told each of them. It's mostly silence, a word now and then, and both seem to find it a lively talk.",
		"I saw an orc shaman come over from Orgrimmar and sit down beside a tauren elder of the same calling. Neither spoke for so long I thought they'd fallen out. Then both laughed at the same moment.",
		"Orc shamans come to this bluff to listen, I'm told, the way smiths visit a famous forge. They leave with fewer words and more patience.",
	},
	["thb.muse.w24.spiritward.009"] = {
		"A shaman leaned on a lodge pole, straightened, laid a hand on the wood and told the owner the pole was tired. They're replacing it. Nobody found that odd but me.",
		"On this bluff, I'm told, even timber has a temper. A shaman listened to a creaking pole for a while and advised that it be thanked and retired.",
		"Wood remembers the tree, a shaman said, laying an ear to a lodge pole. This one, she decided, remembered it fondly.",
	},
	["thb.muse.w24.spiritward.010"] = {
		"Politely, the shamans ask the elements and get answers. I've asked the sky nicely to behave more than once, and it has never replied.",
		"Shamans speak with fire, water, earth and air. I can barely get a word out of a stubborn campfire, and it's usually a rude one.",
	},
	["thb.muse.w24.spiritward.011"] = {
		"halts near a shaman at the very lip of the rise, arms open to the air, so still that a hawk drifts past at arm's length without minding.",
		"keeps a respectful distance from a shaman standing at the brink of the mesa with eyes closed and palms turned out to the open sky, listening to something beneath the noise of the city.",
		"gives a wide berth to a shaman at the edge of the drop, who stands facing the empty air like a guest at a door, waiting to be let in.",
	},
	["thb.muse.w24.spiritward.012"] = {
		"'Water isn't mine,' a shaman told me, filling a jar. 'It visits, and I keep the jar clean so it will want to come again.' I've never thought of a water jar as a guest room.",
		"To a tauren shaman, calling on the elements seems less like giving orders and more like inviting an old friend who may be busy.",
		"Shamans speak of fire, water, earth and air as you'd speak of neighbors: who's in a mood, who needs a visit, who's owed an apology.",
	},
	["thb.muse.w24.spiritward.013"] = {
		"I don't know what you're holding up there, totem, but you're holding it very well.",
		"Good totem. Steady totem. Whatever you're keeping, keep it.",
	},
	["thb.muse.w24.spiritward.014"] = {
		"When the shamans speak with the earth, I hear only the ordinary noises of the rise. Still, I lower my head. The earth that bore my people deserves at least that from those who can't hear her.",
		"I have no gift for the elements. But any tauren can thank the ground under the hooves, and up here the ground has earned it many times over.",
	},
	["thb.muse.w24.spiritward.015"] = {
		"glimpses a Forsaken priest and a tauren shaman pass each other on the planks, each giving the other a small, careful nod, like two cooks from rival kitchens.",
		"finds a Forsaken in dark robes stopping to watch a shaman feed a fire, before moving on without a word, head slightly bowed.",
		"takes note of how the Forsaken on the bridges give the shamans' fires a wide, polite berth, like guests unsure of a host's dog.",
	},
	["thb.muse.w24.spiritward.016"] = {
		"The shamans say the air around the bluffs is the busiest place in Mulgore, full of spirits coming and going like traders on a road. To me it just feels like the wind. Perhaps that's what a crowd of spirits feels like to the deaf.",
		"According to the shamans, the open sky over these mesas is crowded. I see nothing but hawks and the wind tugging at a tent flap. They see a marketplace.",
	},
	["thb.muse.w24.spiritward.017"] = {
		"A young brave touches the same totem every time he passes, low down, where the paint is gone. A promise, a Bluffwatcher told me, and what kind is his own business.",
		"A Bluffwatcher said the youngsters each choose a totem to make their promises to, and never tell which. I've caught three of them guiltily touching the same one.",
	},
	["thb.muse.w24.spiritward.018"] = {
		"Next time you speak to the water, thank it for me too. I've drunk plenty and never said a word.",
		"If you're talking to the earth, put in a good word for my knees. They've climbed a lot of it.",
		"Tell the fire I'm grateful. It warmed me and asked nothing back, which is more than the innkeeper did.",
	},
	["thb.muse.w24.spiritward.019"] = {
		"kneels to watch a shaman here on Spirit Rise set a small stone totem into a hollow of earth, press the soil around it with both palms, and hum to it until the humming stops on its own.",
		"stops where a shaman is bedding a squat stone totem into a patch of earth, packing it in like a seedling and patting it twice when done.",
	},
	["thb.muse.w24.spiritward.020"] = {
		"No whistling on this rise. Someone said it calls the spirits, and I've nothing to offer them.",
		"No whistling, I'm told. Fine. I'll hum. Nobody's said anything about humming.",
	},
	["thb.muse.w24.spiritward.021"] = {
		"May the elements answer when you call.",
		"Kind words to you from the fire, and from the stone.",
		"Fair answers to your asking, shaman. Few questions are owed that much.",
	},
	["thb.muse.w24.stewpot.001"] = {
		"Bargaining with a tauren works like this: the merchant names a price, then says nothing at all. Whoever speaks next loses. It's never the tauren.",
		"The tauren haggle with silence. You make an offer; they look at it the way you'd look at the sky changing, and wait. I've raised my own price three times without hearing a counteroffer.",
		"I've learned the tauren way of bargaining: you say a number and then you hold still. It's harder than it sounds. I lasted about as long as a plainstrider standing in one place.",
	},
	["thb.muse.w24.stewpot.002"] = {
		"I offered half. The merchant considered it for so long I raised my own offer. Twice.",
		"Tip for haggling here: don't. Just pay, and enjoy the nod.",
		"Made my best offer, got a slow blink. I think that's a no. It might be a nap.",
	},
	["thb.muse.w24.stewpot.003"] = {
		"Coin is welcome at the stalls, but I've seen more trades done without it: a hide for two pots, a pot for a bundle of roots, a favor promised for later. The tauren keep the accounts in their heads, and nobody seems to forget.",
		"A potter and a tanner just traded without a single coin changing hands, only a long look at each other's work and a nod. I suspect a running account that goes back years.",
	},
	["thb.muse.w24.stewpot.004"] = {
		"sees two tauren close a trade with a long, unhurried handclasp, neither letting go until something unspoken has been settled.",
		"witnesses a deal at a stall end not with coin but with two huge hands clasped a long moment, and both traders turning back to their work as if nothing had happened.",
	},
	["thb.muse.w24.stewpot.005"] = {
		"A tauren healer grinds roots in a stone bowl with a stone pestle worn to a perfect fit. Bowl and pestle have been grinding each other so long they've become one tool in two pieces.",
		"The mortar this herbalist uses is hollowed so deep by use that the pestle sits in it like an egg in a nest.",
		"The herbalist's pestle has a thumb-shaped hollow worn into its top. Not her thumb, she says. The one before hers.",
	},
	["thb.muse.w24.stewpot.006"] = {
		"Spice bread baked flat on a hot stone at the edge of a fire, flipped with bare fingers. The cook doesn't flinch. I flinch for both of us.",
		"Someone is baking flatbread on a stone beside the coals, slapping each round down and turning it with bare fingers. The smell crosses three rises before the bread is done.",
		"Mulgore spice bread, warm, torn in half by the baker and handed over without asking. Some cities greet you with guards. This one greets you with bread.",
	},
	["thb.muse.w24.stewpot.007"] = {
		"The cook at one big pot told me it hasn't been empty since before the city had its lifts. Something is always added, something always taken out. I asked what the first thing in it was. The cook only stirred.",
		"A cookpot that's never allowed to run empty, only topped up: the cook says it's the same meal it was when her teacher stood over it. I had a bowl of a very old supper, and it was excellent.",
	},
	["thb.muse.w24.stewpot.008"] = {
		"passes a rack of thin meat strips curing over a low, smoky fire, a young tauren posted beside it to wave off the birds with a feathered stick.",
		"eyes a rack of drying kodo meat, dark and stiff, turning slowly in the smoke while someone flips each strip with two fingers.",
	},
	["thb.muse.w24.stewpot.009"] = {
		"The stalls sell things the plain can't grow: salt from the south, spices that came up from the coast with a goblin trader, a little iron. The tauren buy them slowly, as if every foreign good had to be introduced first.",
		"Among the hides and the pots at one stall sits a single pouch of salt, priced higher than everything else. Some things have to come a long way to reach the top of a mesa.",
		"A goblin's spices beside a tauren's roots on the same blanket, each priced in its own way: one loudly, one not at all until you ask.",
	},
	["thb.muse.w24.stewpot.010"] = {
		"studies a grain seller measuring out grain with a carved wooden bowl, leveling each scoop with the edge of one great hand, never a kernel over.",
		"notices that the grain merchant's scoop is a carved bowl worn smooth, and that each measure is struck level with a palm and poured as slowly as a gift.",
	},
	["thb.muse.w24.stewpot.011"] = {
		"At first light the cooks rake the banked coals out from under the ash, and the fires come back without anyone having to start them. A good cook up here, I'm told, hasn't lit a fire from nothing in years.",
		"Dawn, and the cooks are already fanning yesterday's coals awake under the pots with a fan of feathers.",
	},
	["thb.muse.w24.stewpot.012"] = {
		"Last of all, the cooks bury their coals under a blanket of ash and lay a flat stone across the pit. In the dark the whole rise smells of banked fire, warm and low.",
		"The cookfires go under the ash for the night one by one, and the rise grows quieter with each. Only the coals keep talking, very softly, under their gray covers.",
	},
	["thb.muse.w24.stewpot.013"] = {
		"The cook asked if I liked it. I said yes with my mouth full. That seems to be the right answer in any language.",
		"I've been handed a strip of dried kodo to chew on while I wait. I'll be chewing it, I think, until well after I leave.",
	},
	["thb.muse.w24.stewpot.014"] = {
		"Our cooks still make the trail bread the wanderers carried, hard enough to keep for a season's walk. Nobody needs it to keep anymore. We make it anyway, and dip it in broth, and remember.",
		"Bread, broth and a place at the fire for anyone who comes up the path: that is our way, and I'm glad every time I see a stranger handed a bowl without being asked a name.",
	},
	["thb.muse.w24.stewpot.015"] = {
		"I taste very little these days. The tauren cook doesn't know, or doesn't mind, and watches me eat as though my enjoyment were the whole point. So I eat slowly, and let it be.",
		"Food is mostly texture to me now. Still, a tauren handed me a bowl and waited to see me smile, and I found the smile was the part I could still give.",
	},
	["thb.muse.w24.stewpot.016"] = {
		"follows the even fall of a cook's stone knife on a slab of wood scored with a thousand old cuts, the roots beneath it coming apart in equal pieces.",
		"lingers at a cook's board, a thick round of wood hollowed in the middle by countless choppings, the roots on it cut into pieces exactly the same size.",
	},
	["thb.muse.w24.stewpot.017"] = {
		"Here on Spirit Rise an herb seller lets each buyer smell a pinch before paying, and watches the buyer's face rather than the buyer's purse. Some, I noticed, are sent off with a different herb than they asked for.",
		"The herbalists of Spirit Rise sell by nose. You smell, they watch, and sometimes they quietly hand you something else. I asked for one root and was given another, and I'm still not sure which of us was right.",
	},
	["thb.muse.w24.stewpot.018"] = {
		"Every blanket I unfold at the stall, the merchant folds again behind me, perfectly, without comment. I've stopped touching things. That may have been the plan.",
		"I picked up four things at a stall and put them down slightly wrong. The merchant spent the whole conversation setting them right, one by one, and still sold me the fifth.",
	},
	["thb.muse.w24.stewpot.019"] = {
		"Whatever that cook is stirring, I want it, and I want the recipe, and I know I'm getting only one of those.",
		"I'd haggle, but the merchant has more patience than I have years.",
	},
	["thb.muse.w24.stewpot.020"] = {
		"Smells like roots, smoke and somebody's grandmother's secret. I'll have a bowl.",
		"Don't ask what's in it. Just hold out the bowl and say thank you. Slowly.",
	},
	["thb.muse.w24.stewpot.021"] = {
		"An elder at the cookfire eats slowly and leaves the bowl perfectly clean. 'We were hungry once, on the long walk,' she said, when she saw me notice. That was all.",
		"The old tauren never waste a scrap at the cookfire. Some of them, a cook told me quietly, remember the lean seasons of the wandering, when the herds moved faster than the tribes could follow.",
	},
	["thb.muse.w24.strata.001"] = {
		"Close up, the bands in the cliff aren't neat at all. They thicken, thin out, swallow each other, and one pale stripe simply stops, as if the rock lost its train of thought.",
		"From across the gap the cliff looks ruled with a straightedge. Up close the stripes wander, pinch and fade like a story told by several people.",
		"One band in the cliff is no thicker than a finger and runs the whole width of the rise without a break. It's the thick ones that wander off.",
	},
	["thb.muse.w24.strata.002"] = {
		"rubs a thumb along a band of soft yellow rock at the side of the path, and it comes away dusted like a baker's.",
		"presses a fingertip into a pale seam of the cliff; a little of it crumbles off and drifts away as fine as flour.",
		"scrapes at a reddish seam with a fingernail and leaves a pale line in it, then rubs the line out with a thumb, a little guiltily.",
	},
	["thb.muse.w24.strata.003"] = {
		"Swallows nest in a crack just under the lip of the rise, little mud cups pressed into the red stone. I'd wager they were here before the first pole came up the cliff.",
		"Under an overhang of the rock there's a row of small mud nests, and the birds dart in and out as if the whole city were a passing inconvenience.",
		"The swallows under the rim scold anyone who leans out too far. Fair enough. That's their side of the edge.",
	},
	["thb.muse.w24.strata.004"] = {
		"Near the rim the rock is split into slabs as big as lodges, with dark gaps between them a hand wide. The tents are all pitched well back from those gaps. Nobody needed telling.",
		"The edge of the mesa is not one edge but a row of loose-looking blocks, each with a crack behind it. Nobody pitches a tent on the wrong side of a crack.",
		"The cracks near the edge run parallel to it, every one of them. The bluff is peeling away from itself in slow slices, and the tauren have learned to read the slices.",
	},
	["thb.muse.w24.strata.005"] = {
		"crouches to look at a patch of orange lichen on a boulder, crusted flat like spilled paint that has had a few hundred years to dry.",
		"kneels by a rock blotched with lichen in three colors, orange, pale green and a gray almost black, each patch keeping politely to its own ground.",
		"bends over a gray-green crust of lichen on the rock, the kind that grows so slowly a patch the size of a palm might be older than the city.",
	},
	["thb.muse.w24.strata.006"] = {
		"The rock up here is soft enough to scratch with a fingernail and has stood for longer than anyone can count. I'm trying not to take it personally.",
		"Sandstone, I think. It crumbles in my fingers and outlasts kingdoms. There's a lesson in there that I refuse to learn.",
		"I could scratch my name into this cliff with a spoon, and it would outlast me. Some bargains are hard to argue with.",
	},
	["thb.muse.w24.strata.007"] = {
		"A dark stain runs down the cliff below the path, with a fringe of moss at its foot. Somewhere inside the mesa, water is finding its way out, very slowly.",
		"A seep in the rock face: a damp black streak with a few ferns clinging to it. The bluff is dry on top and quietly wet inside.",
	},
	["thb.muse.w24.strata.008"] = {
		"This whole city is standing on a pile of very patient sand.",
		"Lovely stone. Crumbles if you look at it. I'll look at it less.",
		"Don't lean on the cliff. It comes off on your coat.",
	},
	["thb.muse.w24.strata.009"] = {
		"Here on Elder Rise the path is worn into the rock itself, a shallow trough polished by hooves. Stone this soft keeps every passing, and it has kept a great many.",
		"On Elder Rise the paths are grooves, sunk a finger deep into the stone. You don't walk them so much as follow them.",
	},
	["thb.muse.w24.strata.010"] = {
		"looks down the face of the mesa at the long apron of fallen rock piled at its foot, every boulder down there once a piece of the edge.",
		"follows the cliff down with {g:his|her} eyes to the slope of broken stone at its base, where the bluff has been shedding pieces of itself, unhurried, for ages.",
		"looks at a boulder far below at the foot of the cliff, then up at a raw notch in the rim above it, and does the arithmetic.",
	},
	["thb.muse.w24.strata.011"] = {
		"Under the rise, by the Pools of Vision, the stone is beaded with cold drops. Each one gathers for a long while before it lets go.",
		"Down here the walls are the same banded rock as the cliffs outside, only wet and dark, the stripes running into the water and on beneath it.",
	},
	["thb.muse.w24.strata.012"] = {
		"Red dust in the creases of my boots, red dust on my sleeves. The bluff doesn't let you leave without a little of itself.",
		"By the time I leave this city I'll be the same color as its cliffs, from the knees down.",
	},
	["thb.muse.w24.strata.013"] = {
		"Our builders read this rock before they trusted it: which bands will hold a peg, which ones crumble. That knowledge came up the cliffs with them, older than the city.",
		"The stone of the bluff is good stone, the old builders used to say, if you listen to it first. My people listened a long while before they drove the first stake.",
	},
	["thb.muse.w24.strata.014"] = {
		"That crack in the rock goes down further than my arm. I checked. Don't ask why.",
		"Somebody's wedged a flat stone into that crack to keep it from widening. An optimist.",
		"There's a lizard in that crack. It's been watching me longer than the guards have.",
	},
	["thb.muse.w24.strata.015"] = {
		"A twisted little tree grows out of a crack in the cliff face, roots splayed over the rock like fingers holding on. Of everything on this mesa, it chose the hardest place to stand.",
		"Some shrub has wedged its roots into a split in the stone just below the rim and refuses to leave. I admire that in a plant.",
		"Halfway down the cliff a single bush grows straight out sideways and then bends upward, stubborn, toward the open sky.",
	},
	["thb.muse.w24.strata.016"] = {
		"studies the cliff of the next rise across the gap, where a single white band runs level through the red, matched exactly by the same band in the stone underfoot.",
		"notices that the pale stripe in the cliff opposite lines up perfectly with one in the rock below {g:his|her} own feet, as if the two mesas had once been one.",
		"traces a dark band across the gap with one finger held out at arm's length, from the rock opposite back to the rock underfoot.",
	},
	["thb.muse.w24.strata.017"] = {
		"Rain darkens the cliffs band by band, the soft stripes soaking it up first. Wet, the bluff looks striped like the flank of some great beast.",
		"The rain brings out the colors in the rock: rust, ochre, a red like brick, a yellow almost gold. Dry, the cliffs are only dusty.",
		"The cliffs drink the rain and go a deeper red by the minute, until the whole bluff looks freshly painted.",
	},
	["thb.muse.w24.strata.018"] = {
		"Pressed into one slab by the path is the shape of a shell, ribbed and perfect, a long way from any sea. I've no idea how it got there, and the rock isn't saying.",
		"I keep finding small odd shapes in the stone: a spiral, a ribbed curl. Whatever they are, they were here before any of the people walking past them.",
	},
	["thb.muse.w24.tannery.001"] = {
		"draws near a tanner running a bone scraper down the inside of a stretched hide in long, even strokes, stopping now and then to test the surface with a thumb.",
		"stops beside a tauren at work on a kodo hide, the bone scraper going down and back, down and back, with no hurry in it at all.",
		"keeps a respectful distance from a tanner scraping a fresh hide, each stroke followed by a pause and a slow look along the grain.",
	},
	["thb.muse.w24.tannery.002"] = {
		"A tanner told me a hide is cured with the beast's own brains, worked in by hand. I asked if that was a joke. It was the longest silence of my visit.",
		"Brains, smoke and many days of rubbing: that's how good leather was explained to me up here. I've stopped asking what went into my boots.",
	},
	["thb.muse.w24.tannery.003"] = {
		"lingers while a young tauren works a damp hide back and forth over a smooth wooden post, pulling until the stiff skin goes soft as cloth.",
		"pauses where two tauren see-saw a hide across a rounded pole between them, softening it in a slow tug of war that neither is trying to win.",
		"notices a hide being worked over a post by someone who has plainly done it a thousand times, the leather loosening with every pull.",
	},
	["thb.muse.w24.tannery.004"] = {
		"Over a low fire of punk wood the hides hang until they go the color of honey. Smoked leather, the tanners say, dries soft after a soaking instead of stiff as bark.",
		"Someone keeps a sulking little fire under a tent of hides, never letting it flare. It isn't for warmth. It's for color, and for leather that forgives water.",
		"Honey-brown hides turning slowly in a thin haze. The tanner minding them looks as if it would be rude to rush a color.",
	},
	["thb.muse.w24.tannery.005"] = {
		"A good hide takes the better part of a month, from the plain to the frame to the needle. Nobody here tries to make it take less. It would be like pulling on grass to make it grow.",
		"The tanner I watched won't be hurried. 'A hide remembers being rushed,' she said, and turned back to the scraping as though that settled it.",
		"Leather on this bluff is measured in weeks of work, not in coins. The coin comes at the end, almost as an afterthought.",
	},
	["thb.muse.w24.tannery.006"] = {
		"A tanner just sniffed my boots and sighed. I didn't know leather could be disappointed in me.",
		"Apparently my boots were tanned by someone with no respect for the animal. I've been told so gently, twice.",
		"I asked a tanner to look at my gloves. The tanner looked at them, then at me, then said nothing for a very long while.",
	},
	["thb.muse.w24.tannery.007"] = {
		"Here on Hunter Rise the hides come up fresh from the plain and are sorted before anything else is done: this one for a saddle, this for a drum, this too thin for anything but lacing.",
		"On Hunter Rise a hunter and a tanner stand over a fresh hide arguing about a single hole. The hunter is ashamed of it. The tanner is already planning around it.",
		"Every hide brought onto Hunter Rise is read like a letter first: where the beast was struck, how old it was, what the skin can still become.",
	},
	["thb.muse.w24.tannery.008"] = {
		"One hide, followed all the way: the best of it goes to a tent wall, the offcuts become lacing, the lacing scraps tie up bundles of roots, and the last shavings are boiled down for glue. I lost track of it before it ran out.",
		"I tried to find what the tanners throw away. There's a basket of scraps, and every so often a weaver or a carver comes by and takes a handful out of it.",
		"Even the glue up here was a kodo once. So were the laces, the bindings and the little pouch the glue is kept in.",
	},
	["thb.muse.w24.tannery.009"] = {
		"leans close to a finished jerkin laid out on a bench, the stitches along its seam so small and even they look like a single line.",
		"runs a thumb along the edge of a hide pouch on a merchant's blanket, and finds no stitch out of place.",
	},
	["thb.muse.w24.tannery.010"] = {
		"The awl in the leatherworker's hand is older than she is. It was her teacher's, she said, and someone else's before that. The handle has worn to the shape of other hands.",
		"A tanner keeps her tools rolled in a strip of her own oldest leather, each in its pocket. When she unrolls them it looks less like work than like a greeting.",
		"The bone awls here are oiled, wrapped and put away at the end of every job, even if the next job begins a moment later. A tool is treated like a guest who might leave.",
	},
	["thb.muse.w24.tannery.011"] = {
		"The smell of a tanning pit doesn't so much reach you as introduce itself, and then stay for the whole conversation.",
		"I can find the tanners without asking anyone. I simply follow the smell until my nose gives up, then turn left.",
		"A tanning vat has just been uncovered somewhere on the bluff. I know it the way I'd know a kodo had sat on me.",
	},
	["thb.muse.w24.tannery.012"] = {
		"I wear the plain on my back: kodo leather, worked slow by a tanner of this bluff. Our tanners still thank each hide in the old words. I find I do it too, when I fasten a strap.",
		"Leather from our own tanners has a smell no trader's goods ever have. Smoke, earth and patience. It smells like home.",
	},
	["thb.muse.w24.tannery.013"] = {
		"watches a tanner lace a wet hide into a wooden frame, then come back a while later to tighten each thong a little, like someone tuning an instrument.",
		"steps around a frame where a hide is being laced tight, the tanner working along its edge knot by knot and pulling each one a finger tighter.",
		"sees a tanner walk slowly around a framed hide, giving each lace a small tug as it dries, listening to the skin as much as looking at it.",
	},
	["thb.muse.w24.tannery.014"] = {
		"Kodo leather: stops a boar's tusk, sleeps soft, and lasts longer than the buyer. I'll take two.",
		"Tauren leather. Heavy as a promise and twice as hard to break.",
		"If I ever wear this jerkin out, I'll come back and apologize to the tanner in person.",
	},
	["thb.muse.w24.tannery.015"] = {
		"An elder's robe of soft hide has been patched so often it is more mending than robe. The leather comes from a beast nobody alive remembers seeing. The elder wears it like a name.",
		"Patch upon patch, each a slightly different brown: that old robe has outlived the hands that first stitched it, and the ones that stitched it after.",
	},
	["thb.muse.w24.tannery.016"] = {
		"Smells like a tannery. Which is fair. It is one.",
		"Good leather, honest stitching, and a tanner who looks at me as if I'm the piece being appraised.",
		"Whoever made this belt expected it to outlive me. Rude, but probably right.",
	},
	["thb.muse.w24.tannery.017"] = {
		"That tanner has oiled the same awl three times while we've been talking. I've been talking too long.",
		"The tauren look after their tools better than most folk look after their friends.",
	},
	["thb.muse.w24.tannery.018"] = {
		"In the full sun the tanners keep turning the framed hides so no side dries faster than the other. They go from frame to frame like herders checking a flock.",
		"The sun is hard on a hide, the tanners say, so at midday they tilt the frames edge-on to it and wait in the shade beside them.",
	},
	["thb.muse.w24.updraft.001"] = {
		"drops a loose feather over the rim and watches it rise instead, turning slowly, until it is higher than {g:his|her} head and still climbing.",
		"lets go of a stray tuft of down at the edge; it does not fall at all, but goes up past {g:his|her} face as if returning something.",
	},
	["thb.muse.w24.updraft.002"] = {
		"Grass seed on my sleeve, a long way above any grass. The plain sends things up the cliffs on the rising air, and the city never asked for any of them.",
		"A seed head on my collar, on top of a mesa. Mulgore is determined to plant itself everywhere, including on me.",
		"Thistledown drifts between the tents, though no thistle grows on this bare rock. It came up from the plain the easy way.",
	},
	["thb.muse.w24.updraft.003"] = {
		"An elder smokes a pipe at the rim, and the smoke doesn't drift out over the plain; the air lifts it straight back past the horns, like a thought that refuses to leave.",
		"Near the edge even pipe smoke climbs. It never goes out toward Mulgore; it rolls back up the cliff and over the smoker's head.",
	},
	["thb.muse.w24.updraft.004"] = {
		"loses hold of a scrap of paper at the edge and watches it hover just out of reach, rising and dipping, clearly enjoying itself.",
		"makes a grab for a note snatched off the rim, and the note hangs in the air a pace beyond the drop, bobbing, as if daring {g:him|her} to follow.",
	},
	["thb.muse.w24.updraft.005"] = {
		"At the rim the air comes up the cliff instead of across it. Everything loose on me lifts at once and stays lifted, like a hand under the elbow.",
		"Stand at the very edge and the push comes from below, steady and mild, like standing over a hearth the size of half Kalimdor.",
	},
	["thb.muse.w24.updraft.006"] = {
		"A white moth went past me at the edge, traveling upward without once moving its wings. It came from somewhere in the grass and is going somewhere above, and seems content to let the air decide.",
		"Small pale moths ride up the cliff face on the rising air and spill over the rim, blundering about between the tents as if surprised to have arrived.",
	},
	["thb.muse.w24.updraft.007"] = {
		"Some smells arrive from below, not from beside: damp soil by a stream, crushed grass, once a whiff of something dead. The cliff hands up whatever the plain is doing.",
		"Mulgore's news comes up by the nose: grass, earth, a far-off dung fire, all carried straight up the face of the stone.",
		"Some hours the plain smells of cut hay all the way up here, so strongly that I look around for a field that isn't there.",
	},
	["thb.muse.w24.updraft.008"] = {
		"watches a tauren shake a blanket out over the rim; the dust doesn't fall, it flies back up into her face, and she sneezes with great dignity.",
		"sees someone empty a basket of chaff off the edge, only for the rising air to return most of it, politely, all over the planks.",
	},
	["thb.muse.w24.updraft.009"] = {
		"Heat climbs off the cliff faces and makes the far rises wobble as if seen through water. Even the view up here won't keep still.",
		"In the hot hours the air over the edge ripples like a pane of bad glass, and the tents on the next mesa seem to sway though nothing is moving them.",
	},
	["thb.muse.w24.updraft.010"] = {
		"Even the air here refuses to go down. I'm starting to see why the tauren built so high.",
		"Things don't fall off this city so much as get sent back. Mostly.",
	},
	["thb.muse.w24.updraft.011"] = {
		"One of the elders says the air that climbs the cliffs carries the plain's prayers up to the ancestors. Standing in it, I can't argue: something is certainly being carried.",
		"The tauren have a word for the air that comes up the cliff face, a shaman told me; it means something like the plain remembering the sky. The word itself I never caught.",
	},
	["thb.muse.w24.updraft.012"] = {
		"stops to watch a young tauren lean out over the rim with a scrap of hide on a long cord, letting the rising air lift it, reeling it in, letting it climb once more, utterly absorbed.",
		"spots a tauren youngster at the edge flying a square of painted hide on a string, which goes straight up the cliff face and hangs above the city like a small, proud flag.",
	},
	["thb.muse.w24.updraft.013"] = {
		"Standing in the lift of the air at the rim, I seem to weigh a few pounds less. It's a lie, of course, but a kind one.",
		"The rising air at the edge takes a little of my weight, the way a friend takes an elbow on a steep path. I don't trust it, and I'm grateful anyway.",
	},
	["thb.muse.w24.updraft.014"] = {
		"No bird here works for its height. They tip a wing into the air coming off the cliff and simply go up, like someone stepping onto a lift.",
		"Watch the big birds near the cliffs: not a single flap between the plain and the rim. They lean, and let the air do the climbing.",
	},
	["thb.muse.w24.updraft.015"] = {
		"The rain here doesn't only fall. At the rim it comes up the cliff as well, a fine spray thrown back from below, so it soaks from both directions.",
		"In this rain, drops come rising past my face from beneath the edge, blown back off the stone. Even the rain here would rather go up.",
	},
	["thb.muse.w24.updraft.016"] = {
		"turns as a dry leaf comes up over the rim from nowhere, spins once between two tents, and settles on the planks at {g:his|her} feet.",
		"sees a leaf from some tree far down on the plain sail up over the edge and land beside a sleeping wolf, which does not wake for so little.",
		"notices a few blades of dry grass caught in a lashing at the edge of the rise, carried up from far below and tied there by nothing but chance.",
	},
	["thb.muse.w24.updraft.017"] = {
		"A dog barking at some farm far below comes up the cliff thin and late, like a word from the other end of a long house.",
		"Sounds from the plain do climb, but they lose most of themselves on the way: a dog becomes a squeak, a shout becomes a sigh, a cart becomes nothing at all.",
	},
	["thb.muse.w24.updraft.018"] = {
		"Someone on the next rise is hammering a peg, and every blow comes twice: once from the hammer and once, a beat later, from the cliff across the gap.",
		"Knock, and the far cliff knocks back. Somebody over there is driving pegs, and the rock keeps a careful, slightly late count.",
	},
	["thb.muse.w24.updraft.019"] = {
		"Hear that? Somebody down on the plain just whistled. All that way, and it still got up here.",
		"Listen. That's from the grass, way down. The cliff carries the odd sound up like a gift.",
	},
	["thb.muse.w24.updraft.020"] = {
		"Feel that? The air's coming up from underneath. This whole city is standing on a sigh.",
		"Put a hand out over the edge. See? It pushes back.",
	},
	["thb.muse.w24.vertigo.001"] = {
		"When the height gets into my knees I put a hand on the nearest pole and wait. Wood driven into stone has stood up here longer than I have, and it lends a little of that.",
		"My own cure for the drop: find something rooted, a post, a tent peg, the upright of a frame, and lean on it until I remember I'm rooted too.",
		"When the edge starts to pull, I put my back to a tent frame and look at the hide instead of the plain. Hide doesn't go anywhere.",
	},
	["thb.muse.w24.vertigo.002"] = {
		"A Bluffwatcher told me the trick is never to look at the drop, only at the far hills: they don't move, so neither do you. It works better than I expected and worse than she promised.",
		"Advice from a guard on a bridge: eyes on the horizon, never on the boards, and trust that the boards are where they were a moment ago.",
	},
	["thb.muse.w24.vertigo.003"] = {
		"takes one look over the edge, steps back without meaning to, and laughs quietly at {g:his|her} own feet for having opinions.",
		"finds {g:himself|herself} leaning back from the rim before deciding to, the body making its own arrangements with the height.",
	},
	["thb.muse.w24.vertigo.004"] = {
		"Odd thing: the drop doesn't bother me much. It's looking up that does it. There's so much sky above this city that it feels like falling the other way.",
		"Lie on your back up here and the giddiness comes from above. No roof, no branches, just sky going on and on, until the planks under me feel like the only thing holding me down.",
	},
	["thb.muse.w24.vertigo.005"] = {
		"Spend long enough on the bluff and the plain becomes the strange place. Down there my eyes keep dropping to my feet, waiting for an edge that never comes.",
		"After a while up here my body starts expecting the edge. On flat ground later I'll still be feeling for it at every step.",
	},
	["thb.muse.w24.vertigo.006"] = {
		"I'm fine. I'm just going to stand very still and be fine for a moment.",
		"Nobody talk to me until the plain stops tilting.",
		"Give me a moment. My knees and I are discussing the view.",
	},
	["thb.muse.w24.vertigo.007"] = {
		"stands at the edge counting slowly in a murmur until the ground below agrees to stay put.",
		"hums something tuneless near the rim, low and steady, the way one might soothe a skittish animal; only this time the animal is inside.",
	},
	["thb.muse.w24.vertigo.008"] = {
		"An elder watched me wobble at the rim and said, kindly, that the dizziness is only the body bowing to the height. Bow, then, and keep walking. I'm practicing.",
		"The way one old tauren put it: the giddy feeling at the edge isn't fear, it's good manners. The height is very old, and you are being introduced.",
		"A shaman told me not to fight the dizzy spell but to let it finish its sentence, like an elder. It did, eventually. It had a lot to say.",
	},
	["thb.muse.w24.vertigo.009"] = {
		"Down here in the Pools of Vision there's rock above, rock around and still water below, and not a single edge to fall off. My knees have never liked this city more.",
		"The only place in the whole city where I can't see down. In the Pools of Vision the floor ends in water, and water I can manage.",
	},
	["thb.muse.w24.vertigo.010"] = {
		"Every time I stand at the rim my hands go cold first, before anything else. They seem to know about heights on their own, and want no part of them.",
		"It starts in my fingers, at the edge: a chill, a tingle, a wish to hold something. The rest of me catches up a moment later.",
	},
	["thb.muse.w24.vertigo.011"] = {
		"catches a broad orc striding confidently to the edge, looking down once, and striding as confidently back, as if he had meant to all along.",
		"notices a troll at the rim leaning out with great interest, then leaning back with greater interest, tusks working as if chewing over the view.",
	},
	["thb.muse.w24.vertigo.012"] = {
		"With the fog this thick there's no drop at all, only white past the edge, and my knees have stopped complaining. A city you can't see down from is just a city.",
		"Fog fills the gap below every edge, and for once I can walk right to the rim without a flutter. What you can't see can't make you dizzy. Mostly.",
	},
	["thb.muse.w24.vertigo.013"] = {
		"Sleep up here long enough and you will dream of falling, the gentle kind where you never land. A Bluffwatcher told me everyone does, tauren included, and that it passes.",
		"According to a tauren who keeps the beds, every guest up here dreams of falling sooner or later. Slow falls, never a landing. I'm told it's the city's way of saying welcome.",
	},
	["thb.muse.w24.vertigo.014"] = {
		"The surest cure for heights is to sit down. Nobody falls off a city sitting down. I've checked this with no one, but I'd stake my purse on it.",
		"When the drop starts pulling, I sit. It's undignified and nobody here minds; half the tauren on this rise are sitting already.",
	},
	["thb.muse.w24.vertigo.015"] = {
		"The tauren stroll to the edge the way I'd walk up to a fence. I'd ask how they do it, but I suspect the answer would be a long silence and a kind look.",
		"A tauren beside me leaned out over the drop to see what I was looking at, as casually as leaning over a cookpot. Rarely have I felt so much like a guest.",
	},
	["thb.muse.w24.vertigo.016"] = {
		"Step back a little, would you? You're making my knees nervous.",
		"Do you have to stand right on the lip like that? I have an imagination, you know.",
	},
	["thb.muse.w24.vertigo.017"] = {
		"There's a moment at the rim when the whole length of the fall is plain to see, and after it everything ordinary, a cup, a voice, a creaking pole, looks a little more precious.",
		"Standing near the drop sharpens things. Bread tastes better afterward. I don't recommend it as a method, but I don't deny it either.",
	},
	["thb.muse.w24.vertigo.018"] = {
		"On a wind rider's back I've crossed this drop without a second thought. On my own two feet at the rim, the same distance turns my knees to string.",
		"Strange: in the saddle, high over Mulgore, I never feel it. Stand me at the edge of a rise with nothing under my feet but stone, and the plain starts swaying.",
	},
	["thb.muse.w24.vertigo.019"] = {
		"I'm not afraid of heights. I'm afraid of the bit at the bottom.",
		"Heights don't scare me. It's how suddenly they stop.",
	},
	["thb.muse.w24.vision.001"] = {
		"Here in the Pools of Vision a tauren knelt at the water's edge for so long I forgot she was there. When she stood, she only nodded to the pool, the way you nod to someone who has told you something hard.",
		"One young tauren came down to these pools, looked into one, and went back up the path without a word. He climbed more slowly than he came down.",
		"An old shaman sat beside me by the pools, said nothing, saw something, and patted my shoulder on the way out. I'll be wondering about that for days.",
	},
	["thb.muse.w24.vision.002"] = {
		"stands among the pools and listens to a single drop fall somewhere in the dark, then the long wait for the next, as if the cave were counting slowly.",
		"lingers by the still water under the rise, where the only sound is a slow drip from the stone and the faint ring it leaves on the surface.",
		"crouches beside the nearest pool until the drip from the stone above has measured out a long, unhurried silence.",
	},
	["thb.muse.w24.vision.003"] = {
		"Never look into these pools for an answer you've already settled on, the shamans warn. I haven't decided anything. Maybe that's why the water is so dull with me.",
		"These pools show you what you need, not what you want, or so the shamans say. Judging by how plain the water stays, I need a great deal less than I thought.",
	},
	["thb.muse.w24.vision.004"] = {
		"Mention a dream to a tauren elder and be ready: she'll want all of it, the dull parts too, and she'll thank you as if you'd brought news from far off.",
		"The tauren treat a dream like a letter: you don't throw it away unread, and you don't read it alone. An elder will sit with you over even the silliest one.",
		"Up here nobody laughs at a dream. They lean in, ask what color the river was, and nod as if the answer mattered.",
	},
	["thb.muse.w24.vision.005"] = {
		"The druids up on Elder Rise speak of a dream that isn't theirs: a green one, older than the world's waking face, where every forest still stands as it was meant to. They talk of it the way travelers talk of a country they once crossed.",
		"Some druids of Elder Rise, I'm told, sleep and walk somewhere green and vast, the world as it was dreamed. They wake with the look of people who've been very far and can't describe the road.",
	},
	["thb.muse.w24.vision.006"] = {
		"overhears a calf telling a dream to an old tauren in great and solemn detail, every word of it about a very large beetle, while the elder nods gravely throughout.",
		"smiles at a young tauren describing a dream to a patient grandmother, who asks careful questions about the beetle as if a great deal depended on it.",
	},
	["thb.muse.w24.vision.007"] = {
		"'A vision isn't a picture,' a shaman told me. 'A picture you hang up. A vision gets up and walks, and you follow it or you don't.'",
		"The shamans don't speak of seeing the future. They speak of being shown a way, as someone who has crossed a river shows you the ford.",
		"What the tauren call a vision sounds less like a window and more like a hand on the shoulder, turning you a little to the left.",
	},
	["thb.muse.w24.vision.008"] = {
		"The young of Mulgore, the elders say, go out on their rites before they're counted grown: strength, wisdom, vision. Some come up to the bluff afterward looking taller, some looking quieter.",
		"A young tauren fresh from the rites of the plains crossed the rise as if the planks might not hold what he now carried. Nobody asked what he had seen. Everybody made room.",
	},
	["thb.muse.w24.vision.009"] = {
		"I asked the pool a simple question. It answered with a drip. I'm choosing to take that as yes.",
		"Lovely water. Very still. Very wise, no doubt. Not much of a talker.",
	},
	["thb.muse.w24.vision.010"] = {
		"The Forsaken who teach down by the pools stand very still beside the water, and the water stays very still beside them. I can't tell which learned it from the other.",
		"A Forsaken priest keeps to the cool dark near the Pools of Vision. Two kinds of patience side by side: one that waits for a vision, one that has nothing left to wait for.",
		"Two silences live near those pools: the water's and the Forsaken's. A tauren elder told me the water's is the warmer one.",
	},
	["thb.muse.w24.vision.011"] = {
		"steps softly past an old shaman asleep on a blanket in the open, as the tauren nearby are doing, nobody wanting to be the one who wakes a dreamer in the middle of something.",
		"notices that passersby lower their voices around a sleeping elder, as if a dream were a fragile thing carried in both hands.",
		"picks a quieter way around a lodge where someone is dreaming, judging by how everyone else is tiptoeing past it.",
	},
	["thb.muse.w24.vision.012"] = {
		"At dawn the tauren at the next fire swap dreams the way other folk swap news, and argue gently about what each one meant.",
		"First light, and the old tauren nearby are comparing dreams over their bowls. One of them dreamed of a white kodo; the others are taking that very seriously.",
	},
	["thb.muse.w24.vision.013"] = {
		"Something about this bluff makes me want to remember my dreams, if only to have an answer when a tauren asks.",
		"In most cities nobody asks what you dreamed. Here it's a fair question over a bowl of porridge, and I find I'd like to have something worth telling.",
	},
	["thb.muse.w24.vision.014"] = {
		"watches a shaman lean over a pool and let a single feather settle on the water, then study the slow rings as though reading a page.",
		"sees a shaman touch the surface of a pool with one fingertip and stay bent over the spreading ripples long after they have gone.",
	},
	["thb.muse.w24.vision.015"] = {
		"A Bluffwatcher told me an elder once dreamed of a burning tent and sent a runner down to a camp on the plain. The runner found nothing wrong. The elder sent another the next week anyway. On this bluff a dream doesn't expire.",
		"Nobody here waves off a bad dream. You tell it to someone, then go and check on whoever was in it. I've seen a hunter take the lift down on the strength of a grandmother's dream.",
	},
	["thb.muse.w24.vision.016"] = {
		"I dreamed of nothing at all. Is that good or bad? Everyone here seems to have an opinion.",
		"No dreams worth telling, I'm afraid. I'll try harder.",
	},
	["thb.muse.w24.vision.017"] = {
		"Visions rarely come to the one who stares hardest, a shaman told me. They come sideways, while you're mending something, like a bird landing on a fence you'd stopped watching.",
		"The visions the tauren speak of never seem to arrive on time. They come late, half-heard, in the middle of chores, and the seer spends a season working out what they meant.",
	},
	["thb.muse.w24.wandering.001"] = {
		"The elders measure the wandering years in herds, not seasons: the herd their parents followed, the herd that thinned, the herd that led them to Mulgore.",
		"Ask an old tauren how long the tribes walked and you get no number, only a list of herds, each of them a lifetime.",
		"Nobody up here counts the wandering in years. They count it in herds, and the list is long.",
	},
	["thb.muse.w24.wandering.002"] = {
		"notices an old tauren fold a blanket the way travelers do, tight and quick, as if the lodge might have to move before supper.",
		"watches an elder roll a sleeping mat into a bundle small enough for a back, out of a habit older than the city around it.",
		"stops to watch a tauren pack a few belongings into a sling with practiced hands, then remember there is nowhere to go and slowly unpack them.",
	},
	["thb.muse.w24.wandering.003"] = {
		"A wandering people leaves its dead along the way. The elders here can name burial places scattered across half of Kalimdor, and visit almost none of them.",
		"Generations on the move meant a grave behind every hill. Some of the old tauren still turn toward a certain horizon when they speak of the dead.",
		"Every tribe that walked left someone under the grass of a place it never saw again. The tauren carry those places in their speech instead.",
	},
	["thb.muse.w24.wandering.004"] = {
		"Generations spent walking behind the herds, and now the herds are a long way down and the walking is mostly lifts. Progress.",
		"The tauren followed the herds across half a continent, then settled somewhere the herds can only look up at. Bold choice.",
		"They gave up the open road for a city in the sky, these tauren. I'd have picked somewhere with stairs.",
	},
	["thb.muse.w24.wandering.005"] = {
		"The old herd trails are still in the tauren's speech: they give directions by where the grass used to be good, not by where the roads go.",
		"A tauren gave me directions to the Barrens by the old herd trails. Half the landmarks were water holes that dried up generations ago.",
		"Ask the way here and you may get it in grazing: two good meadows east, then the spring that used to be sweet.",
	},
	["thb.muse.w24.wandering.006"] = {
		"The elders say the herds thinned in the wandering years, and the tribes thinned with them. When the tauren speak of plenty, they speak quietly, as if it might overhear and leave.",
		"Lean years, the old tauren call them: fewer herds, longer walks, smaller fires. They say it without bitterness, which is somehow worse.",
	},
	["thb.muse.w24.wandering.007"] = {
		"overhears an elder reciting the names of old camping grounds to a young tauren, one after another, the way other peoples recite their kings.",
		"listens as an old tauren names, slowly and in order, every place the tribe once pitched its tents, while a youngster tries to keep count on thick fingers.",
		"catches a list being taught by an elder to two calves: a ford, a hill, a dry wash, a ford again, the whole road of a tribe in plain names.",
	},
	["thb.muse.w24.wandering.008"] = {
		"Watch where the tauren sit by a fire: always where they can see past it, out to the open plain. Old wanderers' manners, I'd guess.",
		"High as they built, the tauren still sit facing outward. A people that walked for so long never quite turns its back on the horizon.",
		"Every circle around a fire here leaves a gap toward the edge. Nobody explains it. The habit looks older than the city.",
	},
	["thb.muse.w24.wandering.009"] = {
		"Our people walked, the elders say, until the land told them to stop. The land has never said a word to me, but I believe it said that.",
		"We were a long time on the move before the bluffs. Some days the old road still pulls at me, as if nobody told it we had stopped.",
		"My people carried everything for generations. Standing on stone that will not need carrying, I feel lighter than I can explain.",
	},
	["thb.muse.w24.wandering.010"] = {
		"In the wandering years, the elders say, a tauren owned only what a tauren could carry. Given the size of a tauren, that was still quite a lot.",
		"A tauren once owned only what one could carry, the old ones tell me. I've seen what a tauren can carry. That doesn't sound like much of a hardship.",
	},
	["thb.muse.w24.wandering.011"] = {
		"pauses by a rack of walking staffs outside a lodge, their grips worn thin by hands long gone, kept well past the end of the walking.",
		"notices an old walking staff hung over a lodge entrance like a trophy, its foot worn to a blunt stub by roads the city has never seen.",
		"sees an elder lean a long walking staff by a lodge entrance as if ready to set off, though that staff has not left the city in years.",
	},
	["thb.muse.w24.wandering.012"] = {
		"Someone told me the tribes used to meet only when the herds crossed paths, a few days in a long year. Now they live a rope span apart and still greet each other as if a season had passed.",
		"Before the city, the elders say, two tribes might see each other once a year where the herds met. Old habits: up here every greeting still sounds like a reunion.",
	},
	["thb.muse.w24.wandering.013"] = {
		"Ask an elder about the wandering years, then sit down. Then get comfortable. Then cancel your plans.",
		"An elder just started telling me about the long wandering. I suspect the story will take as long as the walk did.",
		"Never ask a tauren elder where the tribes came from unless you've eaten first.",
	},
	["thb.muse.w24.wandering.014"] = {
		"Not every tribe that wandered came to the bluffs. The tauren mention the ones that went their own way with the care you keep for a name that still hurts.",
		"The tribes that took other roads come up in conversation rarely, and always gently, the way you speak of a relative who stopped writing.",
	},
	["thb.muse.w24.wandering.015"] = {
		"Here on Elder Rise the oldest tauren sit and talk of the wandering as though it ended last season. For them, I suppose, it nearly did.",
		"On this rise the elders speak of open grass and moving camps with no distance in their voices at all. The city is young; their memories are not.",
		"On Elder Rise the past is close enough to touch. An old tauren beside me just described a river crossing as if the water were still on her fur.",
	},
	["thb.muse.w24.wandering.016"] = {
		"Thunder Bluff is younger than most of the tauren walking in it. Nearly every grown tauren here can remember sleeping on open grass.",
		"For all its old totems, this is a young city. The tauren who raised its first lodges still carry water past them.",
		"Strange to think of it: the city is newer than the cracks in the elders' hooves.",
	},
	["thb.muse.w24.wandering.017"] = {
		"Thunder over the plain. The elders say a storm on open grass, in the wandering years, meant a long cold walk and no shelter. Up here they listen to it like a story they lived through.",
		"Lightning walking across Mulgore, and an old tauren beside me says that once the tribes simply kept going under it, heads down. Now the old tauren just watches.",
	},
	["thb.muse.w24.wandering.018"] = {
		"Rain on the hides, and the tauren next to me remarks that in the wandering years the tribes walked through weather like this without stopping. It sounds a little like a boast.",
		"The rain drums on the lodges and an elder says, to nobody in particular, that a roof is a fine thing for a people who went so long without one.",
	},
	["thb.muse.w24.wandering.019"] = {
		"watches an old tauren crumble a pinch of soil from a pot by the lodge between two fingers and smell it, the way herders once judged a new pasture.",
		"sees an elder press a palm flat to the bare stone of the rise and hold it there, as a traveler tests whether a camp is good ground.",
		"stays to watch an old tauren stop at the edge, sniff the air rising from the plain, and nod, the way herders once did before choosing where to walk.",
	},
	["thb.muse.w24.wandering.020"] = {
		"lingers to watch a tauren mend an old hauling harness that nobody has pulled in years, oiling the leather anyway.",
		"spots a pair of worn travel poles lashed under a lodge's eaves, kept the way other peoples keep a grandparent's ring.",
		"happens to hear a youngster ask what a battered drag frame by the lodge was for, and an elder answer with a story instead of a word.",
	},
	["thb.muse.w24.wandering.021"] = {
		"Tauren tents come down in no time. Tauren conversations, never.",
		"Generations on the move, and not once, I'd bet, did they rush a goodbye.",
	},
	["thb.npc_meet.w24.asker.001"] = {
		"is invited to sit before anything is asked, and finds that the asking waits until {g:he|she} has actually settled.",
		"is shown a place on the ground with an open hand; the request, it seems, cannot be made to someone standing.",
		"lowers {g:himself|herself} onto the offered mat, and only then does the tauren lean forward to speak.",
	},
	["thb.npc_meet.w24.asker.002"] = {
		"A look at me, then at the ground between us, then at me once more. Whatever is coming, it has been carried a long while.",
		"Before the asking, a long gaze past my shoulder at nothing I can see. Some requests have to be lifted before they can be handed over.",
	},
	["thb.npc_meet.w24.asker.003"] = {
		"I'm listening. Take the long way round if you need to; I'll follow.",
		"You've a weight on you. Set it down here, and I'll see what I can carry.",
		"{other}. You were looking for me, I think. Here I am.",
	},
	["thb.npc_meet.w24.asker.004"] = {
		"is studied at length by a tauren with something to ask, the look moving from {g:his|her} boots to {g:his|her} pack to {g:his|her} face, and resting there.",
		"bears a long, frank appraisal before the request is spoken, the kind a herder gives a beast before a long road.",
	},
	["thb.npc_meet.w24.asker.005"] = {
		"The tauren apologizes before asking, a deep, formal apology for the trouble of the asking itself. I haven't even heard the trouble yet.",
		"An apology first, slow and grave, for burdening a guest. Then, and only then, the burden.",
	},
	["thb.npc_meet.w24.asker.006"] = {
		"No rush. I'll be here. Clearly, so will you.",
		"Go on, I've found a spot. Tell it from the beginning; I can see you want to.",
		"Before you begin: is this a sitting-down sort of request?",
	},
	["thb.npc_meet.w24.asker.007"] = {
		"receives the request with {g:his|her} hand closed between two huge ones, a grip that waits for an answer before letting go.",
		"finds {g:his|her} hand taken in a much larger one as the asking begins, held gently and firmly, the way a promise is held.",
	},
	["thb.npc_meet.w24.asker.008"] = {
		"I'm asked as one asks an ally, not a hired hand. It's the kind of trust the Horde runs on, and I mean to deserve it.",
		"No coin on the table first, no bargaining. Just the Horde asking the Horde. I find I don't need more than that.",
	},
	["thb.npc_meet.w24.asker.009"] = {
		"hears the asking begin, stop, and begin again in other words, as if looking for a way to ask that will shame neither of them.",
		"waits while each word of the request is chosen with visible care, set down, picked up, and replaced by another.",
	},
	["thb.npc_meet.w24.asker.010"] = {
		"There's a tiredness in the way the tauren asks, as though this was asked of others before me, and not all of them came back.",
		"The tauren is very calm about it. Too calm, the way people are when they have been disappointed once already.",
		"Whatever it is, it isn't new. The asking has the smooth edges of something carried for a long time.",
	},
	["thb.npc_meet.w24.asker.011"] = {
		"sees the shoulders settle and the hooves plant themselves before the asking, braced for a long request, and prepares accordingly.",
		"watches a large hand smooth an already smooth patch of hide, twice, before the asking begins.",
	},
	["thb.npc_meet.w24.asker.012"] = {
		"People here don't ask for help so much as offer you the chance to give it. It's a subtle difference, and it works on me every time.",
		"Here the asking is made to sound like an honor being extended. I know the trick perfectly well, and I'm going to fall for it.",
	},
	["thb.npc_meet.w24.hearth.001"] = {
		"is asked a name by the innkeeper, says it, and hears it said back once, carefully, as if being put away somewhere safe.",
		"gives {g:his|her} name at the innkeeper's question and listens to it repeated slowly, every sound of it weighed and kept.",
		"answers the innkeeper's first question, which is not about coin but about what to call {g:him|her}.",
	},
	["thb.npc_meet.w24.hearth.002"] = {
		"The innkeeper says I may make this my hearth if I like. Said that way, slow and plain, it sounds less like a service and more like an offer.",
		"Bind my hearthstone here? The innkeeper asks it as though it were a real question with a real answer, and waits for it.",
		"Setting a hearth with a tauren innkeeper, it turns out, involves a pause long enough to change your mind twice. I didn't.",
	},
	["thb.npc_meet.w24.hearth.003"] = {
		"A bed, please, and whatever you'd give a guest who's tired of talking.",
		"Room for one more? I'm quiet, I'm tidy, and I'll be gone before you notice.",
	},
	["thb.npc_meet.w24.hearth.004"] = {
		"accepts a cup from the innkeeper, filled from a waterskin that seems to have been waiting by the door for exactly this.",
		"is handed a horn cup of cool water before a single word of business, and the innkeeper waits for it to be drunk.",
		"takes the water the innkeeper pours without being asked, and notices the cup has been chosen small, for a guest's hand.",
	},
	["thb.npc_meet.w24.hearth.005"] = {
		"Crushed leaves and tallow: that's what the innkeeper's hands smell of. Whatever they were doing before I came, they were doing it well.",
		"There's root dust in the creases of the innkeeper's palms. Behind the hangings, something is being ground for later.",
	},
	["thb.npc_meet.w24.hearth.006"] = {
		"Somewhere quiet to set my pack down, and nothing else. I'm easy to please.",
		"Which side is quieter? I'd like to hear myself think for once.",
		"{other}, I'll take whatever's free and be grateful for it.",
	},
	["thb.npc_meet.w24.hearth.007"] = {
		"is told by the innkeeper which sleeping mats sit out of the draft, which ones creak, and which belong to a guest who always comes back.",
		"listens as the innkeeper lays out the place in a few slow words: where to sleep, where to wash, where not to step.",
	},
	["thb.npc_meet.w24.hearth.008"] = {
		"I offered coin first. The innkeeper looked at it, then at me, as if I'd answered a question nobody asked.",
		"Payment comes later, apparently. First comes sitting. I'm still learning which way round things go in this city.",
		"The innkeeper hasn't mentioned a price. I'm starting to suspect the price is that I slow down.",
	},
	["thb.npc_meet.w24.hearth.009"] = {
		"has the dust brushed from one shoulder by a broad hand, a gesture the innkeeper makes without comment and does not explain.",
		"feels the innkeeper's palm rest a moment on {g:his|her} shoulder, heavy and brief, before the talk turns to blankets.",
	},
	["thb.npc_meet.w24.hearth.010"] = {
		"The innkeeper greets me the way our people greet a traveler back from the plains: no questions, a blanket first.",
		"Home is where someone sets out a blanket before you ask. The innkeeper has already done it.",
		"Among our own once more. The innkeeper's welcome asks nothing of me, and that is the whole of it.",
	},
	["thb.npc_meet.w24.hearth.011"] = {
		"is handed a folded blanket of woven wool, banded in rust and ochre, and invited to choose another if this one is not liked.",
		"is shown two blankets and asked to pick, and the innkeeper waits through the choosing as if it mattered a great deal.",
	},
	["thb.npc_meet.w24.hearth.012"] = {
		"Thank you. No, truly, the water was enough. All right, a little of whatever that is.",
		"You keep a good house, {other}. Quiet, and nobody rushing me out.",
		"I'll be back before long. Keep the corner by the post for me, if it's no trouble.",
	},
	["thb.npc_meet.w24.hearth.013"] = {
		"Mending a hide while we talk, the innkeeper doesn't stop. Somehow the stitches take nothing away from the listening.",
		"Mid-welcome, the innkeeper goes on sorting dried roots into two baskets, and tells me all I need without a single root going astray.",
		"Every question I ask gets a full answer, and the innkeeper's hands never stop working. Clerks in other cities manage neither.",
	},
	["thb.npc_meet.w24.roostkeep.001"] = {
		"finds the wind rider master scratching a beast beneath the jaw in slow circles, and is greeted only once the beast has had enough.",
		"waits while the roost master runs a thumb along the edge of a wind rider's wing, feeling the membrane for tears, inch by inch.",
		"is kept waiting while a sulking wind rider is coaxed round with a long low hum and a strip of meat.",
	},
	["thb.npc_meet.w24.roostkeep.002"] = {
		"The roost master talks to the wind riders in full sentences and to me in single words. I know where I stand.",
		"I asked the master a question. The nearest wind rider got the answer, at length, and I got a nod.",
	},
	["thb.npc_meet.w24.roostkeep.003"] = {
		"Which of these is in a good mood? ...None of them? Ever? All right.",
		"Hello to you, and hello to the one glaring at me. Mostly to the one glaring.",
		"{other}, does that one always look at me like that, or am I special?",
	},
	["thb.npc_meet.w24.roostkeep.004"] = {
		"notices the roost master's forearms crossed with old pale scratches, and the easy way they rest on a wind rider's neck all the same.",
		"steps around fresh straw being spread beneath the perches, laid down as carefully as embers are banked.",
	},
	["thb.npc_meet.w24.roostkeep.005"] = {
		"The beasts quiet down as the master walks past, one after another, like a row of lamps being turned low.",
		"Every wind rider on the perches turns an ear toward the master's voice. I've never seen anything listened to so completely.",
		"The master hums a phrase, low, and the restless beast at the end of the row settles. I'd like to learn that, and suspect I can't.",
	},
	["thb.npc_meet.w24.roostkeep.006"] = {
		"is looked over by the roost master as carefully as any beast: shoulders, hands, the grip of {g:his|her} boots, and then a nod toward the perches.",
		"submits to a short inspection, straps and buckles checked by the same thick fingers that work the harnesses.",
	},
	["thb.npc_meet.w24.roostkeep.007"] = {
		"There's a tally scratched into a post by the perches, marks in rows. I don't ask what it counts. I decide it's landings, and that it's long.",
		"Scored into the post beside the perches: notches, dozens of them. Flights, I hope. I prefer that to the alternatives.",
	},
	["thb.npc_meet.w24.roostkeep.008"] = {
		"Good beasts, all of them. You can tell they're cared for.",
		"I'll be gentle with whichever you give me. Tell it I said so.",
	},
	["thb.npc_meet.w24.roostkeep.009"] = {
		"pauses while the roost master leans close to a wind rider's ear and says something too low to hear; the beast blinks slowly in reply.",
		"watches the master pick a burr from a wind rider's mane and flick it away without looking.",
		"sees the master rest a forehead briefly against a beast's broad skull before turning, at last, to the one waiting.",
	},
	["thb.npc_meet.w24.tutor.001"] = {
		"is made to stand still before the trainer for a long moment, then to walk ten paces and back, before a word of the lesson is spoken.",
		"begins the lesson by being watched: how {g:he|she} stands, how {g:he|she} sets {g:his|her} feet, how long {g:he|she} can bear the silence.",
		"submits to the trainer's first test, which is simply to wait, unmoving, until told otherwise.",
	},
	["thb.npc_meet.w24.tutor.002"] = {
		"The trainer corrected me with one fingertip on the shoulder, pressing down a hair. Nothing else. It was exactly right.",
		"No lecture. A single touch to the elbow, a small push, and suddenly the whole thing sits differently. I hate how well that works.",
		"The correction was so small I almost missed it. My body didn't.",
	},
	["thb.npc_meet.w24.tutor.003"] = {
		"I'm ready. Mostly. Show me, and I'll keep up.",
		"Teach me what you think I can carry, {other}. I'll ask for more after.",
		"Take it slowly. I'd rather learn it once than learn it badly.",
	},
	["thb.npc_meet.w24.tutor.004"] = {
		"is asked to show what {g:he|she} already knows first, and does so under the trainer's gaze, which misses nothing and praises nothing.",
		"performs all {g:he|she} knows for the trainer, start to finish, and is met by a long silence that seems to be the good kind.",
	},
	["thb.npc_meet.w24.tutor.005"] = {
		"I asked whether I'd done it right. The trainer said yes after so long that I'd already started doing it differently.",
		"Praise from a tauren trainer is a slow blink. I got one. I'm choosing to be very proud of it.",
		"One nod from the trainer. I've decided that's applause.",
	},
	["thb.npc_meet.w24.tutor.006"] = {
		"meets a Forsaken trainer in the lee of a tauren tent, a gaunt figure whose dry voice carries the lesson as patiently as any of its hosts.",
		"finds a Forsaken trainer among the tauren, oddly at ease, and gets a lesson as unhurried as the city that took the teacher in.",
	},
	["thb.npc_meet.w24.tutor.007"] = {
		"The trainer has me repeat the movement until it stops being something I do and becomes something my feet already know.",
		"Ten times. Twenty. Never a word that it's wrong, only a nod for the next. Somewhere around the thirtieth, the movement is mine.",
	},
	["thb.npc_meet.w24.tutor.008"] = {
		"Same as last time? I'll pretend I remember last time perfectly.",
		"You could tell me if I'm getting worse. I'd prefer a hint to a long, meaningful silence.",
		"That silence. Good silence or bad silence? I'm still learning to tell them apart.",
	},
	["thb.npc_meet.w24.tutor.009"] = {
		"is told to set a hand flat on the planks and feel how the city moves before the lesson begins, and does, feeling faintly foolish.",
		"presses a palm to the ground at the trainer's word and holds it there, no reason given, until the trainer seems satisfied.",
	},
	["thb.npc_meet.w24.tutor.010"] = {
		"The trainer teaches as our elders teach: show, wait, show, wait, and trust the learner to come the rest of the way.",
		"Among our own, a lesson is a gift between equals. The trainer hands it over that way, and I take it that way.",
	},
	["thb.npc_meet.w24.tutor.011"] = {
		"pays the trainer, who takes the coin without looking at it and keeps looking at {g:him|her} instead.",
		"hands over the fee and sees it vanish into a pouch while the trainer's attention stays, unbroken, on {g:his|her} stance.",
		"settles the cost of the lesson, and the trainer accepts it like a formality, eyes elsewhere, on {g:his|her} hands.",
	},
	["thb.npc_meet.w24.tutor.012"] = {
		"Whatever the trainer teaches, the first lesson is always the same: stop fidgeting. I'm getting better at that one.",
		"Before anything else, the trainer waited for my hands to go still. It took longer than I'd like to admit.",
		"I've learned more from where the trainer told me to stand than from anything said aloud.",
	},
	["thb.npc_meet.w24.tutor.013"] = {
		"Thank you. I'll practice it until it's dull.",
		"I'll come back when it's in my hands, not just my head.",
		"{other}, I won't waste it. Whatever it cost you to teach me.",
	},
	["thb.npc_meet.w24.vault.001"] = {
		"watches the banker mark the deposit in a ledger of stitched hide, the stylus pressed so slowly that each figure looks carved.",
		"sees {g:his|her} belongings entered one by one in a heavy book bound in leather, each line ruled before it is written.",
		"waits as the banker writes, reads the line back half aloud, and only then writes the next.",
	},
	["thb.npc_meet.w24.vault.002"] = {
		"I handed over a cracked buckle. The banker examined it from every side, then wrote it down as though it were a crown.",
		"The banker treats my odds and ends with grave respect. I almost want to apologize to the bent spoon.",
		"My entire fortune, laid out on the banker's board, is a handful of coin and some string. It was received like tribute.",
	},
	["thb.npc_meet.w24.vault.003"] = {
		"Everything I left is still there? Of course it is. I just like hearing it.",
		"Deposit, please. And maybe don't look too closely at that last bit.",
		"{other}, you remember what I left last time? ...Exactly? That's unsettling.",
	},
	["thb.npc_meet.w24.vault.004"] = {
		"sees a chest opened for {g:his|her} things, its rawhide straps undone one by one and fastened again in the same order.",
		"hands over a bundle that the banker accepts with both palms up, as if weighing not the goods but the trust that came with them.",
	},
	["thb.npc_meet.w24.vault.005"] = {
		"The banker doesn't hurry, and so neither do my thoughts. For the length of a deposit, I have nowhere at all to be.",
		"Something about watching a careful hand put my things away makes me feel, for once, that they're worth keeping.",
		"The banker's quiet is catching. I meant only to drop off some clutter, and I find myself thinking.",
	},
	["thb.npc_meet.w24.vault.006"] = {
		"receives back the single item asked for, and with it the banker's slow, wordless glance at everything else not asked for.",
		"retrieves a stored bundle and is reminded, by a careful finger on the ledger, of three others left untouched for some time.",
		"asks for something in storage and waits while the banker searches without haste, lifting each bundle and setting it down in exactly its place.",
	},
	["thb.npc_meet.w24.vault.007"] = {
		"In this city even the bank keeps the elders' pace. My gold has never been so calm.",
		"The banker gives my coin the same patient regard an elder gives a story. It must be the most respected copper in Kalimdor.",
	},
	["thb.npc_meet.w24.vault.008"] = {
		"Thank you for keeping it safe. I know it isn't much.",
		"Just the small pouch, please. The rest can stay with you a while longer.",
		"You keep better track of my things than I do. That's no compliment to me.",
	},
	["thb.npc_meet.w24.vault.009"] = {
		"is asked by the banker to touch the closed chest once, lightly, before it is carried back among the others.",
		"watches the banker press a thumb to the lid of the chest as it closes, as if sealing it with something more than a latch.",
	},
	["thb.npc_meet.w24.wares.001"] = {
		"sets down coin at a tauren stall, where an open palm weighs the pile first and counts it only afterward, as if checking the hand.",
		"watches {g:his|her} coins tipped into a shallow clay dish and looked at there, untouched, before the merchant nods.",
		"pays, and sees the coins slid one by one into a pouch of soft hide by fingers far too large for the work and perfectly good at it.",
	},
	["thb.npc_meet.w24.wares.002"] = {
		"Before selling me the knife, the merchant asks what it's for. I say cutting rope. Apparently that's the right answer.",
		"The merchant wants to know what the needle will mend. I wasn't expecting to have to explain my socks.",
	},
	["thb.npc_meet.w24.wares.003"] = {
		"And the price? ...Said once, and that's the price. I see. Done.",
		"Do you have this smaller? No, smaller than that. Smaller still. There, perfect.",
		"I was going to bargain. Then you looked at me. I'll pay what you said.",
	},
	["thb.npc_meet.w24.wares.004"] = {
		"is shown each clay jar at the merchant's stall in turn: lid lifted, contents named, lid set back, and only then the next.",
		"learns where every root in the merchant's baskets was dug, the hill named for each, though {g:he|she} asked about only one.",
	},
	["thb.npc_meet.w24.wares.005"] = {
		"A goblin trader would have sold me three things by now. The tauren merchant is still telling me about the first, and I'm somehow enjoying it.",
		"The pitch, if this counts as one, is a long quiet account of where the leather came from. I'm buying, and I'm not sure why.",
	},
	["thb.npc_meet.w24.wares.006"] = {
		"is offered a strip of dried meat from the merchant's own pouch, a taste before trade, and the price is not mentioned until it is eaten.",
		"accepts a pinch of something sharp and dried from the merchant's palm, and the haggling, such as it is, waits politely.",
	},
	["thb.npc_meet.w24.wares.007"] = {
		"What's this one for? Go on, the long version. I've nowhere to be.",
		"{other}, I'll take the bundle of thread and whatever story comes with it.",
		"Fair price. I won't insult you by arguing.",
	},
	["thb.npc_meet.w24.wares.008"] = {
		"Horn spoons, bone awls, a comb carved from something I'd rather not identify. Everything here was alive once, and none of it was wasted.",
		"Not one scrap goes to waste on this stall: the horn is a cup, the bone a needle, the sinew a thread. The whole beast is for sale, piece by careful piece.",
	},
	["thb.npc_meet.w24.wares.009"] = {
		"reaches for something on the stall and stops, because the merchant has raised one finger, very slowly, and has not yet lowered it.",
		"is gently refused a piece of goods: not ready, the merchant says, and sets it back to finish drying.",
	},
	["thb.npc_meet.w24.wares.010"] = {
		"Everything on this stall is sized for tauren. I'm holding a pair of gloves like two empty sacks, and the merchant says they'll shrink.",
		"The merchant assures me the boots will fit. They'd fit me and a friend, comfortably, both at once.",
	},
	["thb.npc_meet.w24.wares.011"] = {
		"completes a purchase and receives it in both of the merchant's hands, held out together, the way one hands over something that matters.",
		"is given the goods with a small bow of the horns, as though the sale were a gift that happened to cost something.",
	},
	["thb.npc_meet.w24.wares.012"] = {
		"Thick fingers, lips moving: the merchant counts, and arrives at a number nobody here would dream of questioning. Least of all me.",
		"Prices up here aren't shouted. They're arrived at, slowly, aloud, and then they're simply true.",
		"I named a lower price. The merchant thought about it for so long that I withdrew it out of embarrassment.",
	},
	["thb.npc_meet.w24.wares.013"] = {
		"Is this for wearing or for hanging on a pole? I honestly can't tell.",
		"I'll take it. No, don't wrap it. Fine, wrap it. Take your time, then.",
	},
	["thb.npc_meet.w24.wares.014"] = {
		"waits while the merchant finishes threading a string of beads for the customer ahead, every bead chosen, held up, studied, kept or put back.",
		"finds the merchant's stall laid out by color rather than by kind: all the reds together, horn and leather and clay alike.",
		"lingers at a stall where each thing carries a scrap of knotted cord, and the merchant reads the knots aloud like prices.",
	},
	["thb.npc_meet.w24.wares.015"] = {
		"The merchant glances at my old pack and quietly sets a strap and an awl beside the goods, not offering, just making them available.",
		"Without a word, a coil of new lacing appears next to what I came for. The state of my boots has not gone unnoticed.",
		"I came for one thing. The merchant saw what I'll need next and put it within reach, saying nothing. It worked, too.",
	},
	["thb.npc_meet.w24.wares.016"] = {
		"I'll take the herbs. No, not the soothing ones. Nothing left in me to soothe, I'm afraid.",
		"No need to stand back. I don't bite, and I've stopped smelling worse than the tannery.",
	},
	["thb.npc_meet.w24.watch.001"] = {
		"slows near a Bluffwatcher whose eyes move once, from {g:his|her} face to {g:his|her} hands, and settle back on the crossing.",
		"draws a single look from the guard at the post: face, hands, belt, then away, the whole inspection done without a turn of the head.",
		"passes under the gaze of a Bluffwatcher who reads {g:him|her} from boots to brow and finds nothing worth a second look.",
	},
	["thb.npc_meet.w24.watch.002"] = {
		"I asked the Bluffwatcher the way to the bank. The answer was a turn of the head so slow I had time to doubt the question.",
		"Directions from a Bluffwatcher come as a single tilt of the horns. You learn to follow the horns.",
		"The guard pointed with the chin. On someone that size a chin covers a lot of ground, and I found the place anyway.",
	},
	["thb.npc_meet.w24.watch.003"] = {
		"The auction house? Past you, and then which way? ...That's all of it? Thank you.",
		"No need to walk me there. Point once more, slower, and I'll manage.",
		"Do you ever sit down up here, or is that against the rules?",
	},
	["thb.npc_meet.w24.watch.004"] = {
		"lingers while a Bluffwatcher reties a loose strap at the wrist without ever looking down, eyes on the crossing the whole time.",
		"stands aside as the guard rebinds a fraying grip on the haft, fingers working by feel while the gaze stays on the road.",
	},
	["thb.npc_meet.w24.watch.005"] = {
		"The guard's arms are marked with old ochre, worn pale where the strap of the weapon rubs. Long years at the same post, if I had to guess.",
		"Paint on the Bluffwatcher's forearms, faded to rust except under the bracer. Somebody renews it, but not often.",
		"Faded lines of red earth on the guard's face. I can't read them, and I'd rather not guess aloud.",
	},
	["thb.npc_meet.w24.watch.006"] = {
		"sees a Bluffwatcher step aside for a bent elder, then step back to the very same board, as if the post were measured to the inch.",
		"notices the guard yield the path to an old tauren with a cane and return to the post exactly, not a hand's width off.",
	},
	["thb.npc_meet.w24.watch.007"] = {
		"Two Bluffwatchers at one post, one of them humming low, the other pointedly silent. I think it's an argument, and I think it has run for years.",
		"One guard hums, the other doesn't, and neither looks at the other. I seem to have walked into a quarrel older than I am.",
	},
	["thb.npc_meet.w24.watch.008"] = {
		"Anything I ought to know before I go wandering, Bluffwatcher?",
		"Quiet on your side? Good. I'll try to keep it that way.",
		"{other}, is there a rule up here I'm about to break without knowing it?",
	},
	["thb.npc_meet.w24.watch.009"] = {
		"hears a small clicking from the guard's weapon: a cord of beads and bone tied below the head, stirring each time the Bluffwatcher shifts.",
		"spots the feathers bound under the blade of the guard's weapon, trimmed short and even, kept with the same care as the edge.",
	},
	["thb.npc_meet.w24.watch.010"] = {
		"The Bluffwatcher's nostrils widen as I pass, and narrow again. Polite of the guard to say nothing about what I smell of.",
		"I've been weighed by living eyes in every city of the Horde. The tauren do it with the nose as well, and still let me by.",
		"The guard looks at me the way one looks at a cut that is healing badly. Then nods. Cairne's word holds, it seems.",
	},
	["thb.npc_meet.w24.watch.011"] = {
		"catches the guard counting the people on the far walkway with small movements of the eyes, and is counted too, in passing.",
		"realizes the Bluffwatcher has been tracking every figure on the crossing, one after another, and that {g:he|she} was simply next.",
		"is noted by the guard the way a herder notes one more head in the herd: a glance, a count, nothing further.",
	},
	["thb.npc_meet.w24.watch.012"] = {
		"The Bluffwatcher doesn't grip the weapon. It just rests there, held the way you hold something you have never needed to reach for quickly.",
		"No hand on the haft, no frown. Whatever this guard has seen, it was enough to make calm look like the stronger choice.",
		"The weapon leans on the guard's shoulder like a walking stick at rest. Nobody up here seems to have given it reason to be anything else.",
	},
	["thb.npc_meet.w24.watch.013"] = {
		"I was told to ask a guard if I got lost. I'm not lost yet; I'm just getting ahead of it.",
		"You've seen me pass four times now, haven't you. I'm sightseeing. Thoroughly.",
		"Good watching to you. If someone goes by in circles, that's me.",
	},
	["thb.npc_meet.w24.watch.014"] = {
		"receives the Bluffwatcher's greeting: two fingers raised to the base of a horn, held a moment, lowered.",
		"is answered by the guard with a touch of the fingertips to the brow, unhurried, the gesture of someone with nowhere else to be.",
		"returns a Bluffwatcher's slow salute, a broad hand lifted to the brow and brought down to rest on the chest.",
	},
	["thb.npc_meet.w24.watch.015"] = {
		"Weight on one leg, then on the other, back and forth like a slow tide. A Bluffwatcher could stand like that for a season.",
		"The guard sways a little, side to side, so little you'd miss it. It must be how they last a whole watch without stiffening.",
	},
	["thb.npc_meet.w24.watch.016"] = {
		"A Bluffwatcher on post, and I feel safer for it than behind any wall in Orgrimmar. Good to have the tauren on our side.",
		"These are the braves who stand between the Horde and whatever comes up from the plain. I give the guard the nod an ally owes.",
		"The guard's look eases a little when it reaches me. Allies, then. It's a good thing to be, up here.",
	},
	["thb.npc_meet.w24.watch.017"] = {
		"asks the guard a question and gets the answer only after the Bluffwatcher has repeated it back, slowly, to be sure of every word.",
		"puts a question to a Bluffwatcher, who considers it in full silence before answering in exactly four words.",
		"waits out the guard's pause, long and attentive, and gets back an answer that leaves nothing to ask after.",
	},
	["thb.quest_complete.w24.afterward.001"] = {
		"steps back once the business is closed and finds that nobody expects a goodbye; the tauren is already bent over the next small task.",
		"moves off a few paces, and behind {g:him|her} a conversation that had been politely set aside picks up exactly where it stopped.",
	},
	["thb.quest_complete.w24.afterward.002"] = {
		"With nothing left to deliver, my own footsteps sound twice as loud on the planks.",
		"Empty-handed now, and the walk away is suddenly very quiet.",
		"Nothing to hand over anymore. I hadn't noticed how much noise purpose makes until it stopped.",
	},
	["thb.quest_complete.w24.afterward.003"] = {
		"pauses where an old tauren sits mending a basket, and is offered, without a word, the free end of the log beside the work.",
		"lingers near an elder bent over a split basket and is waved, silently, to share the same log.",
	},
	["thb.quest_complete.w24.afterward.004"] = {
		"That's it? No speech? I had a whole modest reply ready.",
		"Thanked in four words. I'd rehearsed at least twenty in return.",
		"A nod and we're done? I was halfway through being humble.",
	},
	["thb.quest_complete.w24.afterward.005"] = {
		"Nobody looks up as I go. It isn't coldness; on this rise a finished thing simply stops needing attention.",
		"No one watches me leave. Up here, I think, a job that's done just rejoins the furniture.",
	},
	["thb.quest_complete.w24.afterward.006"] = {
		"walks away slowly, and a small brown bird hops along the guide rope beside {g:him|her} for a few lengths before losing interest.",
		"leaves the business behind at an easy pace, in the company for a moment of a sparrow that bounces along the rope.",
	},
	["thb.quest_complete.w24.afterward.007"] = {
		"I'll go before someone thanks me again. My neck can't take another round of nodding.",
		"Better leave while I can still nod. One more thank-you and I'll be bowing for an hour.",
		"Leaving now, before the thanks start up a second time.",
	},
	["thb.quest_complete.w24.afterward.008"] = {
		"flexes stiff fingers once it is over, and a passing tauren, without breaking stride, nods as if that too were understood.",
		"works the stiffness out of {g:his|her} shoulders when the matter is closed, under the mild eye of a Bluffwatcher leaning on a spear.",
	},
	["thb.quest_complete.w24.afterward.009"] = {
		"A small silence follows a finished task. Here nobody hurries to fill it, and it turns out I like that.",
		"The hush after the hand-over isn't awkward on this bluff. They let it be, and after a moment, so do I.",
	},
	["thb.quest_complete.w24.afterward.010"] = {
		"is trailed for a few steps by a tauren calf who seems to have decided that whoever just got paid is worth following.",
		"picks up a small, curious escort, a young tauren padding behind, until a call from a doorway turns the little one back.",
		"notices a calf following at a respectful distance, matching each step, until someone older clears a throat and the game ends.",
	},
	["thb.quest_complete.w24.afterward.011"] = {
		"I go to the edge once it's handed in and look down at the grass, not to see anything, only to give my eyes somewhere far to rest.",
		"Afterward I find the lip of the mesa and let my eyes drop into Mulgore. Nothing to look for. Just distance, for a moment.",
	},
	["thb.quest_complete.w24.afterward.012"] = {
		"Off I go, then. If I'm needed, I'll be near the bank, counting.",
		"I'll be around. Look for whoever's walking fastest; that'll be me.",
		"Call if you need me. I'll be at a cookfire, pretending not to be hungry.",
	},
	["thb.quest_complete.w24.afterward.013"] = {
		"passes a shaman tending a small fire on the way off and, without quite knowing why, slows until the flame is behind {g:him|her}.",
		"walks by a shaman crouched over a little fire and finds {g:his|her} own steps going softer until it is passed.",
	},
	["thb.quest_complete.w24.afterward.014"] = {
		"The purse is heavier and somehow I'm walking taller. Not tall enough to matter here, but taller.",
		"Coin in the pouch, a little swagger in the step. On this rise nobody notices swagger; they're all too busy being patient.",
	},
	["thb.quest_complete.w24.afterward.015"] = {
		"steps aside after the hand-over for a tauren carrying two dripping water skins, and gets a grave nod for the courtesy.",
		"makes room for someone hauling water up the path, and the small kindness is returned with a slow dip of horns.",
	},
	["thb.quest_complete.w24.afterward.016"] = {
		"It always seems smaller once it's handed over. All that mattering, folded into a word of thanks and a nod.",
		"Funny how a task shrinks the moment it leaves my hands. Here it becomes one more quiet thing in a quiet city.",
	},
	["thb.quest_complete.w24.afterward.017"] = {
		"Thank you for the patience. I know I talk fast.",
		"Sorry for rushing the telling. I'm working on it.",
		"You listened to all of it. Not many would, at my speed.",
	},
	["thb.quest_complete.w24.afterward.018"] = {
		"sets off and has to stop at once: a line of young tauren is filing past with baskets on their heads, and nobody cuts a line like that.",
		"starts away and waits, almost at once, for a row of young tauren to pass with loaded baskets balanced on their heads.",
	},
	["thb.quest_complete.w24.afterward.019"] = {
		"Didn't trip once on the way off. Personal best.",
		"Nobody saw me stumble leaving. I'm counting that as a second reward.",
		"Paid, thanked, and still upright. A clean sweep.",
	},
	["thb.quest_complete.w24.afterward.020"] = {
		"The work is handed in and the fog has swallowed the far rises. For once I can't see the next thing waiting, and I don't mind.",
		"Fog hides everything past the next rope. Good. Let the rest of the world wait out there, unseen, a while.",
	},
	["thb.quest_complete.w24.afterward.021"] = {
		"I stand there nodding long after the thanks have ended. Someone ought to teach me how a tauren conversation closes.",
		"There must be a signal that the talk is over. Everyone on this rise knows it except me.",
	},
	["thb.quest_complete.w24.afterward.022"] = {
		"I walk off about a hand's width lighter. Not the purse; the purse is heavier. Something else.",
		"Lighter on the way out, and not in the pouch. The pouch disagrees.",
	},
	["thb.quest_complete.w24.afterward.023"] = {
		"I'll walk slowly away now, out of respect for local custom.",
		"Leaving at a dignified pace. Watch, I'm getting better at it.",
	},
	["thb.quest_complete.w24.blessing.001"] = {
		"is sent off with a blessing in the tauren's own tongue, low and rolling, of which {g:he|she} catches only the Earth Mother's name and the warmth around it.",
		"hears the blessing given in the tauren's own language, the words unknown, the meaning plain enough in the slow, settled voice.",
		"stands for a blessing spoken in a language of long vowels, of which only one word, the Earth Mother's name, is clear.",
	},
	["thb.quest_complete.w24.blessing.002"] = {
		"'May the ground know your step.' That's what the tauren said, handing it over. I don't know if the ground listens, but the words did me good.",
		"I was told the earth would remember my feet kindly. A tauren saying, I think. I'll walk a little more carefully to deserve it.",
		"My steps were what it blessed, that the ground should know them and hold them. It's the tauren's word, not mine, but I'll gladly borrow it.",
	},
	["thb.quest_complete.w24.blessing.003"] = {
		"And on you, and on your fire.",
		"The same to you, and to all under your roof.",
	},
	["thb.quest_complete.w24.blessing.004"] = {
		"The tauren asked the ancestors to walk behind me. Not beside, not ahead: behind, where they can see what I do. That's a blessing with a warning folded in.",
		"'The ancestors at your back,' I was told. I'm still deciding whether that is comfort or supervision.",
	},
	["thb.quest_complete.w24.blessing.005"] = {
		"I'll carry your blessing, though I don't know the words to give one back. Will a thank you do?",
		"I've no blessing of my own to return, so take my thanks in its place.",
		"I can't answer that in your tongue. Thank you, in mine.",
	},
	["thb.quest_complete.w24.blessing.006"] = {
		"A broad thumb pressed once to my brow with the blessing, firm, then gone. I can still feel where it was.",
		"The blessing came with a thumb set to my forehead, as steady as a seal on wax. I didn't move until it lifted.",
		"For the blessing, a fingertip on my brow, a word I didn't know, and a long look. Then the ordinary world came back.",
	},
	["thb.quest_complete.w24.blessing.007"] = {
		"Blessed and paid. If someone feeds me as well, I'll never leave.",
		"A blessing as well? Careful, I'll start to think I'm somebody.",
	},
	["thb.quest_complete.w24.blessing.008"] = {
		"A practical blessing, mine: may you always find water, and shade, and someone who'll share both. Plains people know what matters.",
		"Water, shade and good company: that's what the tauren wished on me. Not glory, not fortune. Somehow it sounds richer.",
	},
	["thb.quest_complete.w24.blessing.009"] = {
		"'Rest where the grass is good.' The tauren said it the way it must have been said for generations, back when no camp stood longer than a season.",
		"It's an old wanderers' blessing, I think: may you lie down where the grass is good. It sounds like it was made by people who never knew where they'd sleep.",
	},
	["thb.quest_complete.w24.blessing.010"] = {
		"May the Earth Mother hear you, then, since you ask her for me.",
		"I'll trust the Earth Mother to keep that promise for me.",
		"If she listens to anyone, it's to you. Thank you for asking.",
	},
	["thb.quest_complete.w24.blessing.011"] = {
		"watches the tauren touch the planks, then the brow, then reach out toward {g:him|her}: earth, then thought, then the one who is being blessed.",
		"is blessed in three slow touches: the tauren's palm on the ground, on the tauren's own heart, and lightly on {g:his|her} shoulder.",
		"stands still while a broad hand goes from the floor of the rise to the air between them, the blessing passed along like a cup.",
	},
	["thb.quest_complete.w24.blessing.012"] = {
		"I've been blessed more in this city than anywhere else I've worked. I'm not sure I've earned the half of it, but the tauren don't seem to keep that kind of count.",
		"A blessing for every errand, up here. If they work, I must be the best-protected errand-runner in Kalimdor.",
	},
	["thb.quest_complete.w24.blessing.013"] = {
		"Forgive me: what does that blessing mean, word for word? I'd like to carry it properly.",
		"Say it again, slower? I want to remember how it goes.",
	},
	["thb.quest_complete.w24.blessing.014"] = {
		"An elders' blessing, in the old words, and the Earth Mother named as ours. Some things you hear with your bones before your ears.",
		"The blessing was the one every calf on these rises grows up hearing. It still lands, every time.",
		"Blessed in the old words, by one of our elders. The Earth Mother sounds closer when it's one of us asking.",
	},
	["thb.quest_complete.w24.blessing.015"] = {
		"is blessed under the night sky, the tauren's horns a dark curve against the stars as the old words are spoken.",
		"hears the blessing given by firelight, the words rising toward a sky thick with stars.",
	},
	["thb.quest_complete.w24.blessing.016"] = {
		"A hunter's blessing asked the spirits of the beasts to forgive me in advance. I liked that it was so honest.",
		"The patience of the eagle and the stubbornness of the kodo: that's what I was wished. I'll accept both, though I suspect the second was a comment.",
		"A hunter blessed me in the name of the beasts of the plain. I didn't know they had a say. Up here, apparently, they do.",
	},
	["thb.quest_complete.w24.blessing.017"] = {
		"Your blessing on me, and the Horde's strength on you. Fair trade.",
		"Keep the spirits close. The Horde will keep the rest.",
	},
	["thb.quest_complete.w24.blessing.018"] = {
		"Blessed in the rain, the tauren not even bothering to step under the eaves. Water from the sky is apparently also from the Earth Mother.",
		"The rain ran off those horns the whole time the blessing lasted, and the words didn't hurry by a single beat.",
	},
	["thb.quest_complete.w24.blessing.019"] = {
		"I'll keep that blessing close. It's the kindest thing I've been handed in a while.",
		"Thank you for the blessing. It travels lighter than the reward and lasts longer.",
		"I'll remember those words long after the reward is spent.",
	},
	["thb.quest_complete.w24.blessing.020"] = {
		"The shaman's blessing named the four elements one after another, asking each to be patient with me. I hope they heard; I can be trying.",
		"Earth, fire, water, air: the blessing went round them in a slow circle, asking each a small favor on my behalf.",
		"A shaman's thanks comes with the elements in it. I was commended to each in turn, like a guest being introduced around a fire.",
	},
	["thb.quest_complete.w24.blessing.021"] = {
		"I'll try to deserve that. No promises about the ancestors' opinion.",
		"Much obliged. If your ancestors come asking about me, be kind.",
	},
	["thb.quest_complete.w24.blessing.022"] = {
		"Part of the blessing was spoken to the reward itself, I think, as if it should behave well in my hands. Tauren don't leave much out.",
		"I heard the blessing address me, then, more softly, the thing I'd been given. Even objects get a word of advice here.",
	},
	["thb.quest_complete.w24.blessing.023"] = {
		"May your ancestors be proud of how you keep their city.",
		"Spirits keep your lodge standing and your fire fed.",
	},
	["thb.quest_complete.w24.blessing.024"] = {
		"I don't know what that blessing will do. Probably nothing I can see. But I've stopped minding being looked after by things I can't see.",
		"Whether the blessing works or not, it was given with full attention. That alone is rare enough to be worth something.",
		"Maybe the spirits listened, maybe not. The tauren who asked them certainly meant it, and I'll count that.",
	},
	["thb.quest_complete.w24.blessing.025"] = {
		"Your words go with me. I'll set them down somewhere worthy.",
		"I'll carry that out with me, carefully.",
		"Kept and carried. Thank you.",
	},
	["thb.quest_complete.w24.blessing.026"] = {
		"The blessing ended on a hum rather than a word, and the hum went on a while after the tauren's mouth had closed. I didn't know a voice could do that.",
		"There was no last word to the blessing, only a long low note that faded on its own. I waited until it was gone before I said thank you.",
	},
	["thb.quest_complete.w24.boon.001"] = {
		"This is more than I asked for. I'm told that's the point.",
		"Too much, surely. No? Then I'll stop arguing with a tauren; I know how that ends.",
	},
	["thb.quest_complete.w24.boon.002"] = {
		"is given, along with the reward, a little clay pot sealed with wax and the brief instruction to rub it into sore knees.",
		"receives an extra with the reward: a clay pot no bigger than a thumb, smelling of pine resin, offered for aching joints without further comment.",
	},
	["thb.quest_complete.w24.boon.003"] = {
		"Part of the reward wasn't in the pouch. It was being told there's a place for me at that cookfire whenever I pass.",
		"Besides what was owed, I was given a mat by that fire, for any time. I think that was the real payment.",
		"The coin was fair. The offer of a seat at their fire, any time I come by, was more than fair.",
	},
	["thb.quest_complete.w24.boon.004"] = {
		"I'll put it to good use. You'll hear of it, I promise.",
		"It won't sit in a pack gathering dust. Thank you.",
	},
	["thb.quest_complete.w24.boon.005"] = {
		"I tried to say the reward was generous. The tauren looked at it, then at me, and said it was only fair. Arguing generosity with these people is like arguing with a boulder.",
		"When I called it generous, I was corrected, gently and at length. It was fair, apparently. Generous would have been the second helping.",
	},
	["thb.quest_complete.w24.boon.006"] = {
		"is offered the reward on two flat palms, the tauren's head lowered until the horns point at {g:his|her} boots.",
		"watches the reward come forward on open palms, with a bow so deep that for a moment {g:he|she} is looking at the top of a great horned head.",
	},
	["thb.quest_complete.w24.boon.007"] = {
		"Someone had clearly thought about who I was before choosing what to give me. I've had rewards from kings' clerks with less thought in them.",
		"Whatever else, it was picked for me. I could tell by the way I was measured with a glance first.",
		"Nothing was pulled at random from a heap. It was chosen, and the choosing showed.",
	},
	["thb.quest_complete.w24.boon.008"] = {
		"The reward is enough. Keep the rest for whoever needs it more.",
		"This is plenty. Give the extra to the next one who comes asking.",
	},
	["thb.quest_complete.w24.boon.009"] = {
		"takes the reward and discovers it was handed over with tauren ease and must be carried away with considerably less.",
		"accepts the reward, which came across in one easy motion of a tauren arm, and then needs a moment to find a way to hold it.",
	},
	["thb.quest_complete.w24.boon.010"] = {
		"It's odd to be handed something by a people who lost so much on the plains and kept giving anyway. I'm not sure I'd have learned the habit.",
		"They were hunted across the plains for generations and still they give freely. The reward feels heavier when I think about that.",
	},
	["thb.quest_complete.w24.boon.011"] = {
		"Fair and then some. I'll try to spend it as slowly as you gave it.",
		"Generous. I'll make it last, the way things last up here.",
		"Thank you. I'll spend it with tauren patience, which is to say very, very gradually.",
	},
	["thb.quest_complete.w24.boon.012"] = {
		"is given the reward and, threaded on a thong beside it, a single carved bead of bone, offered with no explanation at all.",
		"finds a small bone bead tied to the reward, carved with a mark {g:he|she} does not know and is not told.",
	},
	["thb.quest_complete.w24.boon.013"] = {
		"I said I'd done it gladly and needed nothing. The reward was simply held out until my arm got tired of not taking it.",
		"Refusing a tauren's payment turns out to be a contest of patience. I lost, as anyone would.",
	},
	["thb.quest_complete.w24.boon.014"] = {
		"I'm honored to take it from your hand.",
		"From your hand, then. Thank you, truly.",
	},
	["thb.quest_complete.w24.boon.015"] = {
		"It isn't much, as rewards go. But the way it was given made it clear it had been set aside a long while, waiting for whoever would finish the job.",
		"Small, what I got. Kept for this, though, wrapped and waiting for whoever would see it through. That makes it bigger.",
		"A modest reward, unwrapped from a cloth that had plainly been folded and refolded many times while it waited.",
	},
	["thb.quest_complete.w24.boon.016"] = {
		"takes a reward that is still warm from being held so long in a great closed fist, waiting for {g:him|her}.",
		"is handed a reward warmed through by the palm that held it, as if it had been kept a good while in readiness.",
	},
	["thb.quest_complete.w24.boon.017"] = {
		"My own people paid me as if I were a guest. I'll have to have words with the elders about that, slowly, over several visits.",
		"A reward, from my own tribe, for doing what any of us would do. I'll take it, and give it back somehow at the next feast.",
	},
	["thb.quest_complete.w24.boon.018"] = {
		"Is there a word I should say when taking this? I'd rather get it right.",
		"Tell me how it's properly received here. I'll do it your way.",
	},
	["thb.quest_complete.w24.boon.019"] = {
		"has the reward placed in {g:his|her} palm and {g:his|her} fingers folded over it, one by one, by a much larger set of fingers.",
		"finds {g:his|her} hand taken, opened, filled and closed again, with all the care of someone wrapping an egg.",
		"holds still while a giant hand closes {g:his|her} fingers round the reward, finger by finger.",
	},
	["thb.quest_complete.w24.boon.020"] = {
		"Paid as the sun drops behind the far rises, the coins catching the last of the light before they vanish into my pouch.",
		"The reward came into my hands red-gold in the sunset glow. By the time I'd put it away, the fires were taking over.",
	},
	["thb.quest_complete.w24.gratitude.001"] = {
		"stands through a silence long enough to be awkward anywhere else, and is given to understand that here it is the praise.",
		"receives no words at all for a long moment, only a steady look, and slowly understands that the look is the thanks.",
		"waits out a quiet that stretches and stretches, until it becomes clear the quiet was the answer, and a good one.",
	},
	["thb.quest_complete.w24.gratitude.002"] = {
		"Two words of thanks, and then nothing, and I've been thanked longer elsewhere with half the meaning.",
		"'Well done.' That was all. I'll be carrying those two words a good while.",
	},
	["thb.quest_complete.w24.gratitude.003"] = {
		"That one word was plenty. I'll keep it.",
		"You've said it once, and that's worth more than a speech.",
	},
	["thb.quest_complete.w24.gratitude.004"] = {
		"I'm starting to read tauren quiet. A short one means 'fine'. A long one with a nod at the end means 'better than fine'. This was a long one.",
		"There are kinds of tauren silence, I've decided. The one I just got was the good kind: long, level, ending in a slow blink.",
		"If I'm reading the pause right, that was high praise. If not, I've just been politely ignored at great length.",
	},
	["thb.quest_complete.w24.gratitude.005"] = {
		"is thanked with a single word and a broad hand laid flat against the tauren's own chest, held there a moment and lowered.",
		"sees the tauren touch the center of a broad chest with the fingertips, then turn the palm toward {g:him|her}: thanks, said without words.",
	},
	["thb.quest_complete.w24.gratitude.006"] = {
		"Your thanks are received. May they come back to you.",
		"Thanks received. And mine, for being trusted with it.",
	},
	["thb.quest_complete.w24.gratitude.007"] = {
		"The elder thanked me and then said nothing for a while, looking out past me. I had the feeling someone else was being remembered in the quiet.",
		"In the pause after the thanks, the old eyes went somewhere far off. Whoever was being thought of, I didn't ask.",
	},
	["thb.quest_complete.w24.gratitude.008"] = {
		"gets thanked with a laugh so deep and slow it seems to take a moment to reach the surface.",
		"draws a rumbling laugh of approval from the tauren, the kind that starts somewhere around the hooves.",
	},
	["thb.quest_complete.w24.gratitude.009"] = {
		"My name, said slowly, all its sounds given full weight, and then 'thank you'. I've never heard it pronounced so carefully.",
		"The thanks came with my name in it, every syllable set down like a stone on a path. It sounded like a better name than usual.",
		"Being thanked by name, at tauren speed, is a strange honor: you hear every piece of yourself, one sound after the next.",
	},
	["thb.quest_complete.w24.gratitude.010"] = {
		"Then we're both glad.",
		"I'm glad it mattered.",
	},
	["thb.quest_complete.w24.gratitude.011"] = {
		"I'm better at being shouted at than thanked. A tauren's quiet thanks left me not knowing where to put my hands.",
		"Gratitude this calm is hard to stand in front of. I nodded too many times.",
	},
	["thb.quest_complete.w24.gratitude.012"] = {
		"is thanked with a slow dip of horns, low enough to be a bow and short enough to stay friendly.",
		"gets a bow of the great horned head, unhurried, which comes up again only when it is sure {g:he|she} has seen it.",
		"follows the slow fall and rise of the tauren's horns, one long movement, a thanks that needs no voice.",
	},
	["thb.quest_complete.w24.gratitude.013"] = {
		"Thanked as one of the Horde, with the slow weight of an old promise in it. Thrall would have liked to see it.",
		"The thanks had the whole Horde folded into it: orc and tauren, the old debt both ways. I just happened to be standing where it landed.",
	},
	["thb.quest_complete.w24.gratitude.014"] = {
		"I'll take that silence as a yes.",
		"That look means I did well, doesn't it? I'll take it.",
	},
	["thb.quest_complete.w24.gratitude.015"] = {
		"has {g:his|her} hand held a moment longer than the reward needed, then let go with care, as if it had been lent.",
		"keeps {g:his|her} hand in a large, warm grip a beat longer than the thanks required.",
	},
	["thb.quest_complete.w24.gratitude.016"] = {
		"The tauren thanked the work before thanking me, looking at what I'd done as if it deserved its own word. Then I got mine.",
		"First the deed got its thanks, spoken to it almost; then I got mine. I didn't mind waiting my turn.",
		"I was second in line for the gratitude. The task itself was thanked first, quietly, and I think rightly.",
	},
	["thb.quest_complete.w24.gratitude.017"] = {
		"Thanks among the tribe are a small thing. Keep yours for the strangers who help us.",
		"No thanks needed between children of the Earth Mother. I'd have done it unasked.",
	},
	["thb.quest_complete.w24.gratitude.018"] = {
		"Thanked in the fog, two voices and a shape I could barely see. Somehow the words carried better for it.",
		"The fog had swallowed the far rises, and the thanks came out of it low and close, as if the bluff itself were speaking.",
	},
	["thb.quest_complete.w24.gratitude.019"] = {
		"is waved to the mat beside the tauren after the thanks, and the two of them sit a while without speaking, which seems to be the rest of the thanks.",
		"is invited, by a slow gesture, to sit; the silence that follows is shared, comfortable and apparently part of the payment.",
	},
	["thb.quest_complete.w24.gratitude.020"] = {
		"Twice I was thanked. Up here that's practically weeping. I'm a little worried.",
		"Two thank-yous in a row, from a tauren. I didn't know it was allowed. I may have done something important by accident.",
	},
	["thb.quest_complete.w24.handover.001"] = {
		"waits, motionless, while the tauren takes a long look from boots to brow, and only then, as if some quiet sum had come out right, brings out the reward.",
		"is looked over slowly and thoroughly before anything changes hands, the way a trader looks over a hide before naming a price.",
		"stands under a calm, unhurried gaze for a good while, and the reward arrives at the end of it like the last word of a sentence.",
	},
	["thb.quest_complete.w24.handover.002"] = {
		"Tauren don't hand a reward across. They set it down in front of you and wait for you to pick it up, as if taking it had to be your own choice.",
		"No pressing it into my hands here. The reward is laid on the blanket between us and left there until I decide to want it.",
	},
	["thb.quest_complete.w24.handover.003"] = {
		"watches a huge hand fold what is owed into a square of soft leather, tie it with a thong, test the knot twice, and only then hold it out.",
		"is kept waiting while the reward is wrapped in leather and knotted with great care, the bundle plainly finer than anything a hurried giver would bother with.",
	},
	["thb.quest_complete.w24.handover.004"] = {
		"The tauren listened to the whole account without once looking away. I've never been heard so completely by someone who said so little back.",
		"I gave my report and got silence, then a slow nod. Somewhere in that silence every word I'd said was weighed and kept.",
		"Every word of my account was taken in and none of it was answered at once. Up here you're allowed to finish.",
	},
	["thb.quest_complete.w24.handover.005"] = {
		"Gladly taken. And the handshake, if I can have my hand back afterward.",
		"Thank you. That's a grip I'll feel all the way across the city.",
	},
	["thb.quest_complete.w24.handover.006"] = {
		"waits while an old tauren gets up from the mat by stages, one knee, a hand on the pole, then the other, because a reward is not given sitting down.",
		"watches an elder rise from the fireside in slow stages, refusing every offered hand, so that the reward can be given standing.",
		"is made to wait for an old tauren to stand, which takes a while and is plainly not up for discussion: thanks are given on the hooves.",
	},
	["thb.quest_complete.w24.handover.007"] = {
		"The hunter who paid me did it the way hunters here do everything: no wasted motion, and a long look at my hands, as if they told the story better than I would.",
		"Paid by a hunter, which up here means quietly, briskly for a tauren, and with an eye on my hands the whole time, reading them like tracks.",
	},
	["thb.quest_complete.w24.handover.008"] = {
		"is given the reward by a shaman who first touches it to the ground, then to a small stone hung at the throat, and only then lets it go.",
		"watches a shaman hold the reward low, close to the earth, for a moment of silence before passing it up into {g:his|her} hands.",
	},
	["thb.quest_complete.w24.handover.009"] = {
		"A leatherworker set down the awl to pay me, then wiped both hands on an apron before touching mine. Clean hands for a clean debt, I suppose.",
		"The crafter finished the stitch first. Then the needle was parked in a sleeve, the work turned face-down, and I had full attention and my reward.",
		"I was paid between two stitches, by someone who did not drop the thread to do it and did not make me feel any less thanked.",
	},
	["thb.quest_complete.w24.handover.010"] = {
		"gets the reward from a brave who stays at attention throughout, then breaks it for one short, almost shy grin before turning back to the post.",
		"is paid by a brave with a spear tucked in the crook of one arm and the reward held out in the other, the whole business done without leaving the post.",
	},
	["thb.quest_complete.w24.handover.011"] = {
		"The pouch I was handed was sized for a tauren palm. In mine it looks like a pillow.",
		"A reward, given by a hand that could hold four of mine. Somehow even the coins look bigger coming out of it.",
	},
	["thb.quest_complete.w24.handover.012"] = {
		"sees a single knot tied in a cord of many knots hanging from a lodge pole before the payment, as though the deed now had to be counted somewhere.",
		"sees a new knot added to a long knotted cord at the giver's belt before the reward comes, and is not told what the knot means.",
	},
	["thb.quest_complete.w24.handover.013"] = {
		"Stay seated, please. I'll come round to you.",
		"No, don't rise for me. I can bend.",
	},
	["thb.quest_complete.w24.handover.014"] = {
		"I watched the tauren search a long time for the right word of thanks, and settle at last on a short one. It was the right one.",
		"There was a long pause while the thanks were chosen. What came out was three words, and none of them could have been swapped.",
	},
	["thb.quest_complete.w24.handover.015"] = {
		"watches the reward lifted out of a woven basket from under a layer of dried grass, as if it had been put to bed there for safekeeping.",
		"waits while a lid of plaited reeds comes off a basket and a big hand rummages, unhurried, until it finds what was set aside.",
		"is handed something that has plainly been waiting in a basket under the eaves, a few stalks of dry grass still clinging to it.",
	},
	["thb.quest_complete.w24.handover.016"] = {
		"I expected a little haggling over what I was owed. The tauren just named it, paid it, and seemed puzzled that I'd braced for more.",
		"No counting out loud, no 'that's what we agreed'. The full sum was set in my hand as if the question had never been open.",
	},
	["thb.quest_complete.w24.handover.017"] = {
		"watches a young tauren sent at a trot to fetch the reward come back at a much more careful walk, holding it out in both hands as instructed.",
		"is brought the reward by a calf who has clearly been told to be solemn about it and manages, almost, until the very end.",
	},
	["thb.quest_complete.w24.handover.018"] = {
		"In Orgrimmar someone would have written it down. Here the tauren just looked at me for a long moment, and I suspect that's the same thing, only harder to lose.",
		"No ledger, no mark on a slate. The tauren just learned my face, slowly, the way you'd learn a trail.",
	},
	["thb.quest_complete.w24.handover.019"] = {
		"is paid by a tauren stirring a pot with one hand and holding out the reward with the other, neither task interrupting the other.",
		"takes the reward from a hand that reaches out from the cookfire without the rest of the cook turning around.",
	},
	["thb.quest_complete.w24.handover.020"] = {
		"The thong that tied my reward was old, and the tauren told me whose it had been, and whose before that. Even the string here has ancestors.",
		"Three owners, all named, all remembered: that was the history of the leather cord around the reward, as it was told to me. I'll be careful with it.",
		"Even the tie around my reward came with a story, told slowly, one owner after another.",
	},
	["thb.quest_complete.w24.handover.021"] = {
		"No, I won't check it. I watched how carefully it was made ready.",
		"I'll not look it over in front of you. Not after watching it put together so carefully.",
	},
	["thb.quest_complete.w24.handover.022"] = {
		"A hand set on my shoulder for the thanks, and I felt it settle like a heavy blanket: not pushing, just there.",
		"A palm the size of a door rested on my shoulder for a moment. It weighed more than the reward and said more, too.",
		"One great hand on my shoulder, held there for the length of a slow word. My knees noticed before I did.",
	},
	["thb.quest_complete.w24.jest.001"] = {
		"I nearly said 'quick, then'. I can tell that word doesn't live up here.",
		"Sorry, I'm rushing the thanks. Let me start them over, at your pace.",
	},
	["thb.quest_complete.w24.jest.002"] = {
		"Thank... you. There. I think that's the right speed for this city.",
		"Let me try that once more, slower. Grateful. Very. Grateful.",
	},
	["thb.quest_complete.w24.jest.003"] = {
		"Don't hurry on my account. Then again, nobody here hurries on any account.",
		"Take your time. I'm learning that's the only thing anyone takes around here.",
	},
	["thb.quest_complete.w24.jest.004"] = {
		"Finish the thanks on my next visit. I can see you're only halfway.",
		"Keep the rest of that sentence for me. I'll come by for it later.",
	},
	["thb.quest_complete.w24.jest.005"] = {
		"I'll go now. Slowly, of course. I wouldn't want to cause a scandal.",
		"Off I go, at a stroll. Running would only frighten the neighbors.",
	},
	["thb.quest_complete.w24.jest.006"] = {
		"Anywhere else I'd haggle a little over this. Here the haggling would outlast us both.",
		"I was going to argue for more. Then I pictured the argument at tauren speed and gave up.",
	},
	["thb.quest_complete.w24.jest.007"] = {
		"Pleasure doing business. Slow, thorough, honest business.",
		"A fine trade. Unhurried, but fine.",
	},
	["thb.quest_complete.w24.jest.008"] = {
		"Is this the part where we both stand here quietly for a while? I can do that. Watch me.",
		"So now we just stand in silence together? Fine. I'm good at that. Mostly.",
	},
	["thb.quest_complete.w24.jest.009"] = {
		"I almost said 'I'll hurry back'. Up here I'd better say 'I'll wander back, eventually'.",
		"Back soon? No, wrong city. Back eventually, unhurried, at a respectable amble.",
	},
	["thb.quest_complete.w24.jest.010"] = {
		"Tell me plainly when the thanks are over. Honestly, here I can't tell where they end.",
		"Is that the end of the thanks, or just a pause? With you lot I never know.",
	},
	["thb.quest_complete.w24.jest.011"] = {
		"You thank people slower than I do the work. I'll call that a compliment to us both.",
		"Your thanks took longer than some errands I've run. I'm not complaining. Much.",
	},
	["thb.quest_complete.w24.jest.012"] = {
		"If I dash off now, will somebody write it down? I feel somebody would write it down.",
		"Don't let me run. People here would talk about it for a year.",
	},
	["thb.quest_complete.w24.jest.013"] = {
		"Everyone here listens to the whole of a sentence. I've had to start finishing mine.",
		"You let me get to the end of what I was saying. I'd forgotten how it ended.",
	},
	["thb.quest_complete.w24.jest.014"] = {
		"Careful with that grip. I'd like my hand back in working order.",
		"A firm handshake. I'll count my fingers later, gratefully.",
	},
	["thb.quest_complete.w24.jest.015"] = {
		"Somewhere a goblin is paying three times this for the same job, and shouting about it.",
		"In Ratchet I'd have been handed a contract and a bill. This is much nicer.",
	},
	["thb.quest_complete.w24.jest.016"] = {
		"You ask so politely that I'd say yes before you'd finished. Lucky for me, you never finish quickly.",
		"With manners like that you could ask me for anything. Please don't test it just yet.",
	},
	["thb.quest_complete.w24.jest.017"] = {
		"Shall I say 'you're welcome' now, or wait the customary half hour?",
		"Is there a polite interval before I say 'my pleasure'? I'd hate to jump in early.",
	},
	["thb.quest_complete.w24.jest.018"] = {
		"Finished, and I didn't even run. You see? This city is rubbing off on me.",
		"Look at me, standing still and nodding. Give me a season here and I'll be wearing beads.",
	},
	["thb.quest_complete.w24.jest.019"] = {
		"Even 'you're welcome' takes the scenic route in this city.",
		"Here a farewell is a journey with stops along the way.",
	},
	["thb.quest_complete.w24.jest.020"] = {
		"I rushed my thanks, and the reply came back as if I'd said them slowly. Maybe they simply hear everyone at their own speed.",
		"I gabbled. The answer arrived calm and whole, as though I'd spoken at an easy pace. Patience like that must hear the words under the rush.",
	},
	["thb.quest_complete.w24.jest.021"] = {
		"tries to leave briskly, and is overtaken, very gently, by a farewell that takes its time.",
		"makes for the bridge at a clip, then slows to a stroll after a few steps, as if remembering the manners of the place.",
	},
	["thb.quest_complete.w24.jest.022"] = {
		"For the road? Kind. And no, I won't eat it walking. I'll sit down like a civilized person.",
		"I'll eat it sitting, I promise. Nobody here walks and chews.",
	},
	["thb.quest_complete.w24.jest.023"] = {
		"I caught myself talking twice as fast as the one I was thanking. Next time I'll count to three between sentences.",
		"Halfway through my thanks I realized I'd been gabbling. The tauren waited patiently for the words to catch up with me.",
	},
	["thb.quest_complete.w24.jest.024"] = {
		"Grateful, truly. Shall we finish the courtesies under a hide? You're patient, but the rain isn't.",
		"Lovely thanks. Let's have the rest of them somewhere less wet.",
	},
	["thb.quest_complete.w24.jest.025"] = {
		"I'd bow, honestly, but I'd rather not explain to the plain below why I'm arriving early.",
		"I'd do a proper bow, if this rise came with a little more rise and a little less drop.",
	},
	["thb.quest_complete.w24.jest.026"] = {
		"You've thanked me so slowly I've had time to think of a reply. Rare luxury.",
		"Thanks this unhurried give a person time to come up with a decent answer. Here it is: you're welcome.",
	},
	["thb.quest_complete.w24.jest.027"] = {
		"Goodbye. That's goodbye, by the way, not a pause. I'm leaving now. Gently.",
		"I'm going now, I promise. This is me going. Any moment.",
	},
	["thb.quest_complete.w24.nod.001"] = {
		"answers the low words of thanks with a nod, then a second one, slower, to match.",
		"nods once, deeply, and takes {g:his|her} time raising {g:his|her} head again.",
	},
	["thb.quest_complete.w24.nod.002"] = {
		"answers in a low voice, without noticing {g:he|she} has dropped it to match the city.",
		"replies more softly than usual, the bluff's quiet having crept into {g:his|her} voice.",
	},
	["thb.quest_complete.w24.nod.003"] = {
		"starts to turn away too soon, catches {g:himself|herself}, and stays for the rest of the thanks.",
		"half turns to go, realizes the thanks are far from over, and turns back with a sheepish smile.",
	},
	["thb.quest_complete.w24.nod.004"] = {
		"clears {g:his|her} throat for a speech, thinks better of it, and simply nods.",
		"opens {g:his|her} mouth to say something grand, closes it, and settles for a plain 'thank you'.",
	},
	["thb.quest_complete.w24.nod.005"] = {
		"grins up at the one doing the thanking, plainly pleased and making no effort to hide it.",
		"smiles broadly through the whole of the thanks, which, given the pace, is quite a feat.",
	},
	["thb.quest_complete.w24.nod.006"] = {
		"bows from the waist, a careful bow, mindful of the edge of the planks behind {g:him|her}.",
		"offers a small bow and keeps it small, with an eye on how close the edge is.",
	},
	["thb.quest_complete.w24.nod.007"] = {
		"taps the strap of {g:his|her} pack twice, a promise without words to come back if called.",
		"pats {g:his|her} pack and tips {g:his|her} head toward the bridges: if there's more, {g:he|she} knows the way.",
	},
	["thb.quest_complete.w24.nod.008"] = {
		"shakes the offered hand and then waits, politely, to be given {g:his|her} own back.",
		"disappears up to the wrist in a handshake and comes out of it flexing {g:his|her} fingers.",
	},
	["thb.quest_complete.w24.nod.009"] = {
		"inclines {g:his|her} head and says nothing more, letting the silence finish the courtesy.",
		"keeps quiet after the last word of thanks, and the quiet seems to be the right answer.",
	},
	["thb.quest_complete.w24.nod.010"] = {
		"rubs the back of {g:his|her} neck, a little awkward under so much slow gratitude.",
		"shifts from foot to foot while the thanks go on, unused to being praised at such length.",
	},
	["thb.quest_complete.w24.nod.011"] = {
		"repeats the parting words carefully back, as if the shape of the courtesy mattered as much as its meaning.",
		"echoes the farewell word for word, slowly, taking care to get each one right.",
	},
	["thb.quest_complete.w24.nod.012"] = {
		"laughs at something said in reply, a laugh that turns heads on the next rise over.",
		"lets out a short laugh, then lowers it hastily when a few faces across the way look up.",
	},
	["thb.quest_complete.w24.nod.013"] = {
		"steps back a pace before answering, the better to meet the eyes of the one thanking {g:him|her}.",
		"tilts {g:his|her} head well back to answer face to face, and holds the look without fuss.",
	},
	["thb.quest_complete.w24.nod.014"] = {
		"rests a hand briefly on the offered forearm, a thank-you that needs no words.",
		"returns the grip with both hands, and lets go only when the other does.",
	},
	["thb.quest_complete.w24.nod.015"] = {
		"says something plain and courteous, and a deep rumble answers that sounds very much like agreement.",
		"offers a few polite words and gets a low hum in return, which seems to settle everything.",
	},
	["thb.quest_complete.w24.nod.016"] = {
		"touches the planks at {g:his|her} feet before standing to go, a small gesture the onlookers seem to approve of.",
		"crouches to lay a palm on the ground for a moment after the thanks, and a nearby elder gives a slow nod.",
	},
	["thb.quest_complete.w24.nod.017"] = {
		"waits out a long pause, unsure whether it is the end of the thanks or the middle, and guesses wrong.",
		"starts to answer during a pause that turns out not to be one, and stops with a polite cough.",
	},
	["thb.quest_complete.w24.nod.018"] = {
		"stows what was given without counting or checking, as if counting would be rude here.",
		"puts the thanks away along with everything else, neatly, with no show of looking it over.",
	},
	["thb.quest_complete.w24.nod.019"] = {
		"smiles in a way that stays on {g:his|her} face long after the words have finished.",
		"keeps the smile from the hand-over all the way to the end of the rise.",
	},
	["thb.quest_complete.w24.nod.020"] = {
		"asks a short question about the city in parting, and listens to the whole of the long answer.",
		"lingers to ask the name of a carving nearby, and is given its story, slowly, from the beginning.",
	},
	["thb.quest_complete.w24.nod.021"] = {
		"accepts the thanks with a modest shrug that fools nobody.",
		"waves the praise away with one hand, and keeps the other firmly on what was given.",
	},
	["thb.quest_complete.w24.nod.022"] = {
		"nods the thanks away by the light of a cookfire, the faces around it lit gold and patient.",
		"answers with a quiet word, the shadows of the lodge poles long across the planks in the firelight.",
	},
	["thb.quest_complete.w24.nod.023"] = {
		"answers a slow question with a quick reply, then adds a second, slower one to keep the peace.",
		"realizes {g:he|she} has answered before the question was quite finished, and apologizes at length.",
	},
	["thb.quest_complete.w24.nod.024"] = {
		"presses a fist to {g:his|her} chest in thanks, holding the gesture a beat longer than {g:he|she} would elsewhere.",
		"lays a hand flat over {g:his|her} chest and keeps it there while the last words of thanks are said.",
	},
	["thb.quest_complete.w24.onward.001"] = {
		"Bank first, then a meal, then whatever comes looking for me. A good order for a quiet city.",
		"Purse to the bank, then food. Past that, I'll let the city decide.",
		"First the purse goes somewhere safe, then I go somewhere warm. Plans don't need to be grander than that.",
	},
	["thb.quest_complete.w24.onward.002"] = {
		"stands a moment where the paths split between the rises, choosing none of them in particular.",
		"stops where three ways part across the mesa and lets {g:his|her} feet pick, which they do slowly.",
	},
	["thb.quest_complete.w24.onward.003"] = {
		"Anyone need anything else carried, found or frowned at? No? Good. I'm off.",
		"Last call for errands. Nothing? Then I'm off to sit down somewhere large.",
		"Nothing else? Then I'll take my leave, and my purse.",
	},
	["thb.quest_complete.w24.onward.004"] = {
		"I don't know yet where my feet are headed. Up here, not knowing feels less like being lost and more like being free to choose.",
		"No next step planned. On this bluff that seems allowed.",
		"Nothing waiting, nothing promised. For once the next move is entirely mine, and I'm in no hurry to spend it.",
	},
	["thb.quest_complete.w24.onward.005"] = {
		"pulls a folded map from {g:his|her} pack, frowns at it, and decides that for the moment the most important place marked on it is the inn.",
		"unfolds a worn map once the business is closed, studies it gravely, then folds it up again and simply walks.",
	},
	["thb.quest_complete.w24.onward.006"] = {
		"Out there another problem is waiting for someone exactly my size. It can wait a little longer.",
		"There's always another job. There isn't always a tauren cook within twenty paces. Priorities.",
	},
	["thb.quest_complete.w24.onward.007"] = {
		"Finished here. I'll take the long way round for once; there's no reason not to.",
		"I'm in no hurry for once. Let's see where the rises take me.",
		"Nothing pressing. I think I'll wander and let my feet choose.",
	},
	["thb.quest_complete.w24.onward.008"] = {
		"is halfway to the next errand before noticing there is no next errand, and stops, a little surprised, in the middle of the path.",
		"heads off briskly, then slows and halts, realizing there is nowhere in particular to be.",
	},
	["thb.quest_complete.w24.onward.009"] = {
		"I feel ready for something larger. A tauren would tell me to sit with that feeling a while first. They might be right.",
		"There's an itch in my feet for something bigger. A tauren would say let it ripen. I'll try.",
	},
	["thb.quest_complete.w24.onward.010"] = {
		"Where next? Somewhere with chairs my size, ideally.",
		"Off to find a seat that fits me. Wish me luck.",
		"Next: somewhere I can be slow without having to try.",
	},
	["thb.quest_complete.w24.onward.011"] = {
		"asks a passing Bluffwatcher for the way to a trainer and gets, after a thoughtful pause, directions so thorough they include which planks are loose.",
		"asks the way to the bank and receives careful, unhurried directions, each landmark offered as if it were a small gift.",
	},
	["thb.quest_complete.w24.onward.012"] = {
		"The next thing I do is sit down, and I mean to do it very well.",
		"Next task: a bench. It has my full attention.",
		"One job left on my list: a long sit. I'm the right one for it.",
	},
	["thb.quest_complete.w24.onward.013"] = {
		"For generations the tauren followed the herds with no fixed place. Walking off with no plan, I understand them a little.",
		"No plan for what's next. The tauren wandered for generations with less, and built this city at the end of it.",
	},
	["thb.quest_complete.w24.onward.014"] = {
		"I'll stop by again before I leave the city.",
		"I'll look in on you before I go. Don't get up.",
		"I'll pass this way before I leave. Keep me a seat.",
	},
	["thb.quest_complete.w24.onward.015"] = {
		"turns to go and is halted by a polite cough: there is, it seems, one more small thing, and it will be explained slowly.",
		"is almost away when a deep voice adds, at leisure, that there might be something else, sometime, if it is no trouble.",
	},
	["thb.quest_complete.w24.onward.016"] = {
		"Whatever's next, I'll go to it a little steadier. This city lends you its pace for a while after you leave a task in it.",
		"I'll carry the slowness of this place into whatever comes next. It's a good thing to borrow.",
	},
	["thb.quest_complete.w24.onward.017"] = {
		"Wherever my feet take me next, the bluff stays where it is. Knowing that is what makes it easy to go.",
		"I can wander off now with a light step. The mesas aren't going anywhere, and neither is my place on them.",
	},
	["thb.quest_complete.w24.onward.018"] = {
		"Done. Now I'll go and do what the tauren do best: nothing at all, for as long as it takes.",
		"That's finished. I'm off to stand somewhere and be patient. I hear it's the local sport.",
		"Finished. I'm going to practice standing still. Apparently there's an art to it.",
	},
	["thb.quest_complete.w24.onward.019"] = {
		"glances toward the inn, then toward the bank, then toward the far rises, and settles the matter by following a good smell.",
		"weighs the inn against the bank for a moment and lets {g:his|her} nose cast the deciding vote.",
	},
	["thb.quest_complete.w24.onward.020"] = {
		"steps away as the fires are lit one by one across the rises, and decides the next thing can wait until the light comes back.",
		"leaves the business behind as dusk pulls the color out of the plain below, in no hurry at all to find another.",
	},
	["thb.quest_complete.w24.onward.021"] = {
		"pauses to retie a bootlace on the planks, and by the time it is knotted the next errand has chosen itself.",
		"crouches to fix a loose boot strap and stands with the next move decided, as though the knot had settled it.",
	},
	["thb.quest_complete.w24.onward.022"] = {
		"There's nothing I have to do now. I keep turning that over like a found coin.",
		"A moment with nothing owed to anyone. It feels like finding a coin in an old pocket.",
	},
	["thb.quest_complete.w24.reckon.001"] = {
		"The tauren still speak of the orcs who stood with them against the centaur. A people who remember help that long will remember this too, in its small way.",
		"If they still honor a debt to Thrall's orcs from the hard years, my little favor has found a careful keeper.",
	},
	["thb.quest_complete.w24.reckon.002"] = {
		"is told, gravely, that this will not be forgotten, and the words carry the weight of a promise rather than a pleasantry.",
		"hears that the help will be remembered, said plainly and once, in the voice of someone who keeps such accounts for life.",
	},
	["thb.quest_complete.w24.reckon.003"] = {
		"Somewhere on this bluff there's now someone who owes me a favor and will absolutely remember it. Possibly at a very inconvenient moment.",
		"I'm owed by a tauren now. I'm told they repay in full, usually once you've forgotten.",
	},
	["thb.quest_complete.w24.reckon.004"] = {
		"A small, clean feeling, like a knot tied properly. Nobody will ever check it, and that's fine.",
		"It's a little thing, a job finished right. The satisfaction is the size of a pebble and sits nicely in the pocket.",
		"Nobody cheers. Nobody needs to. A thing done properly hums on its own for a while.",
	},
	["thb.quest_complete.w24.reckon.005"] = {
		"No debt between us. Or if there is, let it run the other way someday.",
		"You owe me nothing. Remember it anyway; I may need a friend up here.",
		"Call it even. Or call it a start; I'd like that better.",
	},
	["thb.quest_complete.w24.reckon.006"] = {
		"notices a tauren scoring a mark with a thumbnail on a strip of hide, and wonders whether help, up here, is counted that way too.",
		"sees a fresh notch on a tally stick hanging beside a doorway, and finds {g:himself|herself} wondering what it counts.",
	},
	["thb.quest_complete.w24.reckon.007"] = {
		"My good deed is now a tauren memory. It will outlast me, my boots and probably my reputation.",
		"In a mind slower and longer than mine, I'm being filed away. Gently.",
	},
	["thb.quest_complete.w24.reckon.008"] = {
		"Now the city owes me a little, and I owe it a little, and neither of us is keeping close count. That's how friendship starts, I think.",
		"A small debt each way. Neither side counting. I'd call that the beginning of something.",
	},
	["thb.quest_complete.w24.reckon.009"] = {
		"sits on an upturned basket for a moment, turning the reward over in {g:his|her} fingers, quietly pleased with nothing in particular.",
		"allows {g:himself|herself} a small, private smile once nobody is looking.",
	},
	["thb.quest_complete.w24.reckon.010"] = {
		"The tauren hold that a kindness is never lost, only buried, like a seed in the Earth Mother's keeping. Theirs to say; I like hearing it.",
		"I'm told the tauren believe the Earth Mother keeps every kindness the way soil keeps a seed. It's a gentle way to think about a ledger.",
	},
	["thb.quest_complete.w24.reckon.011"] = {
		"Good. That's one thing in the world tidier than it was.",
		"There. The world's a hair more in order.",
		"Done and dusted. One less loose thread.",
	},
	["thb.quest_complete.w24.reckon.012"] = {
		"I've heard the tauren keep their debts even to the dead. I hope nobody ever has to keep mine that way.",
		"I hear the tauren settle accounts even with the ancestors. I'd rather collect mine in person.",
	},
	["thb.quest_complete.w24.reckon.013"] = {
		"is urged, on the way off, to remember a lodge and the way to it, should {g:he|she} ever need anything at all.",
		"is shown which lodge to come to if ever in need, and the offer is made with the plain seriousness of a debt being recorded.",
	},
	["thb.quest_complete.w24.reckon.014"] = {
		"When the Horde needs a hand, remember mine. I'll remember yours.",
		"Horde helps Horde. Call on me, and I'll call on you.",
		"The Horde keeps its accounts. Count me in yours.",
	},
	["thb.quest_complete.w24.reckon.015"] = {
		"Tauren gratitude is like tauren bread: slow to make, very heavy, and it keeps for weeks.",
		"Being owed a favor by a tauren is like being owed a mountain. It won't move, and it's enormous.",
	},
	["thb.quest_complete.w24.reckon.016"] = {
		"Nobody up here will make a story of this. Good. Some work is better left to rest quietly in the people who needed it.",
		"There'll be no tale of it, and that suits me. It goes where the tauren keep things: in their long, quiet memory.",
	},
	["thb.quest_complete.w24.reckon.017"] = {
		"Don't mention it. Actually, do. Once, slowly. I've come to enjoy it.",
		"No thanks needed. But if you insist, take your time. Everyone else does.",
		"No need for thanks. Well, a little need. Go on.",
	},
	["thb.quest_complete.w24.reckon.018"] = {
		"A debt between tauren isn't a weight. It's a rope strung between two lodges. I've tied one more.",
		"Among our people a favor is a thread, not a chain. Mine now runs to one more hearth.",
	},
	["thb.quest_complete.w24.reckon.019"] = {
		"counts the coins of the reward once, out of habit, and then a second time, out of something closer to pleasure.",
		"tallies the reward with a thumb, out of habit, then stops and simply holds it a moment, satisfied.",
	},
	["thb.quest_complete.w24.reckon.020"] = {
		"Tauren memories are long. Some elder on this bluff will still recall this when I'm gone. A strange comfort, but a comfort.",
		"I'll be forgotten in most places. Here, I suspect, some patient mind will keep this small thing well past my time.",
	},
	["thb.quest_complete.w24.reckon.021"] = {
		"Glad it's done. Glad it was for you.",
		"I'm glad it was this city I did it for.",
		"It was good to do this for you.",
	},
	["thb.quest_complete.w24.reckon.022"] = {
		"I'll probably forget this before they do. That seems unfair to them, and very generous of them.",
		"They'll remember this longer than I will. I find that oddly touching.",
	},
	["thb.quest_complete.w24.reckon.023"] = {
		"If you ever need it done twice, you know who to ask.",
		"Same again, any time. I don't charge extra for repeats.",
	},
	["thb.quest_complete.w24.spoken.001"] = {
		"Thank you for hearing me out. I talk fast, and you listened to every word anyway.",
		"You let me finish every sentence. That alone was worth the work.",
	},
	["thb.quest_complete.w24.spoken.002"] = {
		"It's an honor to be trusted with it. I mean that.",
		"With all the folk on this bluff to choose from, you asked me. I won't forget it.",
	},
	["thb.quest_complete.w24.spoken.003"] = {
		"That means more than you'd think.",
		"Kind of you to say so. I'll keep those words longer than anything in my pack.",
		"Those few words were plenty. Truly.",
	},
	["thb.quest_complete.w24.spoken.004"] = {
		"Done as asked: nothing added, nothing missing.",
		"All of it, the way you wanted. Look it over if you like; I'll wait.",
	},
	["thb.quest_complete.w24.spoken.005"] = {
		"May the ground under this city stay steady for a long while yet.",
		"Good earth under your feet, and under every rise of this place.",
	},
	["thb.quest_complete.w24.spoken.006"] = {
		"No speech needed. Between us, a nod will do.",
		"Save the long thanks for someone who needs them. I'm content with a nod.",
	},
	["thb.quest_complete.w24.spoken.007"] = {
		"If more needs doing, tell me yourself. I'd rather hear it from you than from gossip.",
		"Should you need willing hands again, ask for mine before anyone's.",
	},
	["thb.quest_complete.w24.spoken.008"] = {
		"Glad to help. Honestly glad, not the polite kind.",
		"I'm pleased it fell to me. Some work you're happy to have been asked.",
	},
	["thb.quest_complete.w24.spoken.009"] = {
		"Thanks. And thank you for not rushing me, either.",
		"You've a way of making a person feel they have all the time in the world. I'll miss that elsewhere.",
	},
	["thb.quest_complete.w24.spoken.010"] = {
		"I'll take it gladly, and the hand that gives it gladder still.",
		"I'm grateful. It's the giving I'll remember, more than the gift.",
	},
	["thb.quest_complete.w24.spoken.011"] = {
		"You say 'well done' as if the words weighed a stone each. I'll carry them that way.",
		"Two words of praise from you sound like ten from anyone else. I'll take them.",
	},
	["thb.quest_complete.w24.spoken.012"] = {
		"It was nothing. No, that's not true. It was something, and I'm glad you noticed.",
		"I'd like to say it was easy. It wasn't, quite. Thank you for seeing that.",
	},
	["thb.quest_complete.w24.spoken.013"] = {
		"That's fair, and fairly given. I've no complaint to make.",
		"Fair. More than fair, if I'm honest, and I try to be.",
	},
	["thb.quest_complete.w24.spoken.014"] = {
		"Your thanks are heard, and returned.",
		"I hear your thanks. Hear mine in turn, for the trust.",
	},
	["thb.quest_complete.w24.spoken.015"] = {
		"You looked at me the whole time you spoke. People in a hurry never do that.",
		"Nobody's looked me in the eye that long in a while. It's a good kind of strange.",
	},
	["thb.quest_complete.w24.spoken.016"] = {
		"There. It's in your hands now.",
		"Yours to keep. My part ends here, yours begins.",
	},
	["thb.quest_complete.w24.spoken.017"] = {
		"Peace on your lodge, and on whoever keeps its fire.",
		"May your fire never want for fuel, nor your door for friends.",
	},
	["thb.quest_complete.w24.spoken.018"] = {
		"I learned something doing it, so really, I should be thanking you.",
		"Funny thing: I'm walking away knowing more than I did. Call it a second reward.",
	},
	["thb.quest_complete.w24.spoken.019"] = {
		"If anyone else on this rise needs help, point them my way.",
		"Know someone else with a job going spare? Send them over.",
	},
	["thb.quest_complete.w24.spoken.020"] = {
		"You speak so low I nearly leaned in. I'm glad I did.",
		"That quiet voice of yours carries further than a shout. I heard every word.",
	},
	["thb.quest_complete.w24.spoken.021"] = {
		"Walk lightly, and may the spirits you honor keep you well.",
		"Your ancestors would be pleased with the way you thank a stranger. I'm sure of it.",
	},
	["thb.quest_complete.w24.spoken.022"] = {
		"Please, a nod back is enough. You don't have to match me word for word.",
		"I've said thanks four times now. You've said it once. I think you're winning.",
	},
	["thb.quest_complete.w24.spoken.023"] = {
		"I thanked them the old way, the way the elders taught it. It came out without my thinking.",
		"The old words of thanks came to me on their own. Up on our own bluff, they always do.",
	},
	["thb.quest_complete.w24.spoken.024"] = {
		"Your chieftain spoke for my people when few would. An errand like this is the least I owe.",
		"Not many doors open for one like me. I don't forget the ones that did.",
	},
	["thb.quest_complete.w24.spoken.025"] = {
		"When my people came to Kalimdor, yours showed us the way. This was small change against that debt.",
		"Orcs remember who stood with them on this side of the sea. Thank me less; let me do more.",
	},
	["thb.quest_complete.w24.spoken.026"] = {
		"I said thank you three times. The tauren said it once, and theirs outweighed all three of mine.",
		"My thanks came out in a rush, a pile of small words. The reply was one word, and it was heavier.",
	},
	["thb.quest_complete.w24.spoken.027"] = {
		"I had a whole speech ready. The nod I got made it unnecessary, so I kept it for myself.",
		"There was a fine little speech in me. It turned out nobody needed it, me included.",
	},
	["thb.quest_complete.w24.spoken.028"] = {
		"I lower my voice here without meaning to. Nobody shouts on the bluff, so somehow neither do I.",
		"My voice has gone quiet by itself. The city does that; it never raises its own.",
	},
	["thb.quest_complete.w24.spoken.029"] = {
		"I meant to say something clever at the hand-over. What came out was 'thank you', and it was the right thing.",
		"I reached for a witty answer and found only plain thanks. Plain was better.",
	},
	["thb.quest_complete.w24.spoken.030"] = {
		"The courtesy here is slow enough to notice. I noticed I liked it, which surprised me.",
		"Everywhere else, thanks are over before you feel them. Here I had time to feel them.",
	},
	["thb.quest_complete.w24.spoken.031"] = {
		"Much obliged. Go back to your fire; it's no hour to stand about thanking people.",
		"My thanks, and good night. I won't keep you from your blankets any longer.",
	},
	["thb.quest_complete.w24.spoken.032"] = {
		"Good. That's one weight off your mind and none on mine.",
		"Settled, then, and nobody worse off for it.",
	},
	["thb.quest_complete.w24.spoken.033"] = {
		"You smiled. On a face that patient, a smile reads like a whole sentence.",
		"That's the biggest smile I've earned in a long while. Worth more than the pay.",
	},
	["thb.quest_complete.w24.spoken.034"] = {
		"Be well. And mind your step on the bridges, though I suppose you never need telling.",
		"Stay well, friend of mine. That's all the farewell I've got, and I mean all of it.",
	},
	["thb.quest_complete.w24.spoken.035"] = {
		"No need to walk me anywhere. I know the way, more or less. Mostly less.",
		"I'll find my own way off this rise. If I don't, you'll hear about it.",
	},
	["thb.quest_complete.w24.spoken.036"] = {
		"Thank you for the quiet, too. I didn't know I'd been missing it.",
		"The thanks were kind. The stillness after them, kinder.",
	},
	["thb.quest_complete.w24.spoken.037"] = {
		"They tell me the Earth Mother sees honest work. If she saw this, I hope it pleased her.",
		"The shamans say small deeds are noticed by those who watch the earth. Then let this one be noticed kindly.",
	},
	["thb.quest_complete.w24.vow.001"] = {
		"Call, and I'll come. You won't have to ask twice.",
		"Send word when there's more. I'll answer it before the messenger sits down.",
	},
	["thb.quest_complete.w24.vow.002"] = {
		"Keep my name somewhere handy. I mean to be useful in this city.",
		"Remember my face, would you? I plan to be back with it.",
	},
	["thb.quest_complete.w24.vow.003"] = {
		"You have my word, for whatever a word from me weighs up here.",
		"My word on it. It's lighter than yours, maybe, but it holds.",
	},
	["thb.quest_complete.w24.vow.004"] = {
		"Save me the next hard thing. The one nobody else will touch.",
		"Next time, give me something worth a song. I'll see it through.",
	},
	["thb.quest_complete.w24.vow.005"] = {
		"Whatever else this city asks of me, I'm listening.",
		"Ask again whenever you like. I'll be the one who says yes.",
	},
	["thb.quest_complete.w24.vow.006"] = {
		"I told them to send for me. I meant it more than I usually do.",
		"'Call on me any time,' I said. Most places, that's a pleasantry. Here I'd be ashamed not to mean it.",
	},
	["thb.quest_complete.w24.vow.007"] = {
		"I offered more help without being asked. Something about this place pulls promises out of a person.",
		"Twice now I've volunteered for work no one mentioned. These people don't ask; they just wait, and I fill the silence.",
	},
	["thb.quest_complete.w24.vow.008"] = {
		"If the trouble ever comes back, you won't face it alone. That's a promise.",
		"Whatever this was about, if it starts again, don't wait. Find me.",
	},
	["thb.quest_complete.w24.vow.009"] = {
		"My hands are yours when you need them. Just say the word.",
		"There's more work in these hands. Spend it when you like.",
	},
	["thb.quest_complete.w24.vow.010"] = {
		"I don't leave things half done. If it needs finishing later, that's mine too.",
		"Anything left loose, I'll tie it off. That's how I work.",
	},
	["thb.quest_complete.w24.vow.011"] = {
		"For the tribe, any time. You never need to thank me for that.",
		"No thanks between kin. I'd have done it twice over.",
	},
	["thb.quest_complete.w24.vow.012"] = {
		"The Horde keeps faith with its friends. Call, and I'll answer.",
		"One task for an ally, and I'd do a dozen more. That's what the Horde is for.",
	},
	["thb.quest_complete.w24.vow.013"] = {
		"I promised to come back if needed. Saying it aloud made it a little heavier, which is how it should be.",
		"A promise spoken in front of a tauren feels like one carved into a post. I'd better keep it.",
	},
	["thb.quest_complete.w24.vow.014"] = {
		"When I'm next on the bluff, I'll look for you first.",
		"I'll stop by your fire when I'm passing. Not for work. Just to sit.",
	},
	["thb.quest_complete.w24.worth.001"] = {
		"The tauren don't measure a task by how big it was, only by whether it holds. I hope mine holds.",
		"Up here, I think, they ask one thing of any work: will it last? Not how grand. Not how quick. Will it last.",
		"Whether a job was large matters little on this bluff. Whether it will still be sound in ten winters, that matters.",
	},
	["thb.quest_complete.w24.worth.002"] = {
		"A people who waited generations for a home don't think much of hurry. Whatever I did, they'll weigh it over years.",
		"To folk who wandered for generations before they raised these lodges, a good deed is something judged slowly, over seasons.",
	},
	["thb.quest_complete.w24.worth.003"] = {
		"I'd ask what it was worth to you, but I suspect the answer takes a season.",
		"Worth it? Ask me next year. Apparently that's how it works up here.",
		"Was it any good? Don't answer yet. I know you'll want to sleep on it. Several times.",
	},
	["thb.quest_complete.w24.worth.004"] = {
		"receives a long, careful nod for the work, the kind given to something meant to last.",
		"sees the work taken in not with excitement but with care, considered slowly, as if it had a long life ahead of it.",
	},
	["thb.quest_complete.w24.worth.005"] = {
		"Nobody here will remember the coin they paid. They'll remember whether I kept my word. That's a better ledger to be in.",
		"What they keep on this bluff isn't the price, it's the promise. I kept mine, and somewhere on this rise that's been noted.",
	},
	["thb.quest_complete.w24.worth.006"] = {
		"Gold spends anywhere. A tauren's good opinion only spends here, but it never runs out.",
		"The coin will be gone soon enough. The goodwill stays on the bluff, earning interest at tauren speed.",
	},
	["thb.quest_complete.w24.worth.007"] = {
		"notices the hands that gave the reward, broad and seamed with old work, and the thought settles that hands like those ask nothing lightly.",
		"glances at the hands that paid, cracked and enormous, hands that have plainly never asked for anything they did not need.",
	},
	["thb.quest_complete.w24.worth.008"] = {
		"Small thing, really. But I'm told small things are the ones you keep here.",
		"It wasn't much. Still, I hear this city has a long memory for not much.",
		"Nothing worth a song. Worth a nod, maybe.",
	},
	["thb.quest_complete.w24.worth.009"] = {
		"People who lost so much on the open plains don't waste help. Whatever I did, someone here will stretch it further than I'd know how.",
		"A people who once had to carry everything they owned learned to throw nothing away. Not even a helping hand.",
	},
	["thb.quest_complete.w24.worth.010"] = {
		"One slow nod and a single word. I've heard whole speeches that said less.",
		"A nod, a word, finished. Some heralds could learn from that.",
		"Three words of thanks. In some cities that would be a whole ceremony.",
	},
	["thb.quest_complete.w24.worth.011"] = {
		"looks back once from a few paces off and sees the matter already being put to use, unhurried, as though it had always been part of the plan.",
		"turns for a single look back: the business just settled is already being folded into the slow work of the place.",
	},
	["thb.quest_complete.w24.worth.012"] = {
		"For my own people the thanks are almost beside the point. The work goes into the city like grain into the common store.",
		"It's worth more done here, for us. Not more coin; more of something the coin can't count.",
	},
	["thb.quest_complete.w24.worth.013"] = {
		"May it serve you as long as you need it.",
		"Make good use of it, and long.",
		"Let it be useful for many seasons.",
	},
	["thb.quest_complete.w24.worth.014"] = {
		"A tauren told me once that the grass doesn't hurry and still covers the whole plain. I think that's what a small job is worth here.",
		"They have a saying here, or so a hunter told me: the grass is slow and the grass wins. My bit of work is one blade of it.",
	},
	["thb.quest_complete.w24.worth.015"] = {
		"weighs the reward in one palm and the long, deliberate thanks in the other, and seems unsure which was heavier.",
		"jingles the purse once, then thinks of the slow words that came with it, and for a moment the coins seem the lighter part.",
	},
	["thb.quest_complete.w24.worth.016"] = {
		"A people who count their years in herds and seasons don't judge help on the spot. They wait to see what grows.",
		"They'll judge this the way they judge a new calf or a planted field: later, patiently, by what it becomes.",
	},
	["thb.quest_complete.w24.worth.017"] = {
		"Take your time deciding whether it was any good. I know you will.",
		"No rush to say it was well done. Clearly.",
		"Judge it whenever you like. Next spring is fine.",
	},
	["thb.quest_complete.w24.worth.018"] = {
		"The pay is fair. Better, I suspect that the next time I pass this lodge, the flap will be held open a little longer.",
		"Coin's fine. The real reward here is quieter: a nod that will come a beat sooner, the next time.",
	},
	["thb.quest_complete.w24.worth.019"] = {
		"is told, almost as an afterthought, that there is a place by this fire whenever {g:he|she} likes, and the tone makes plain this is the real payment.",
		"hears, in passing, that there will always be room at this hearth, and understands from the voice that nothing else given was worth as much.",
	},
	["thb.quest_complete.w24.worth.020"] = {
		"I think the worth of this, to them, isn't in what was done but in who chose to do it. A willing pair of hands counts for a lot here.",
		"To the tauren the gift is the stepping forward. What exactly I did matters less than that I answered when asked.",
	},
	["thb.quest_complete.w24.worth.021"] = {
		"Odd to be paid by people who seem to think the payment is the least interesting part.",
		"They handed over the reward the way you'd pass the salt. Over the thanks, though, they took their time.",
	},
]==])
